export type Role = "General Manager" | "IT Manager" | "Coordinator" | "Boss" | "CFO" | string;

export interface LogEntry {
  id: string;
  timestamp: string;
  user: string;
  action: string;
  details: string;
}

export interface ExtraItem {
  id: string;
  name: string;
  quantity: number;
}

export interface Transaction {
  id: string;
  productSetName: string;
  supplierName: string;
  department: string;
  usageLocation: string;
  requesterName: string;
  requestDateTime: string;
  packageContent?: string;
