import React from 'react';
import { 
  TrendingUp, 
  Clock, 
  AlertCircle, 
  Wallet,
  ArrowUpRight,
  ArrowDownRight
} from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend } from 'recharts';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction }) => {
  const totalSpending = transactions
    .filter(t => t.status === 'Approved')
    .reduce((sum, t) => sum + t.totalAmount, 0);

  const pendingCount = transactions.filter(t => t.status === 'Pending').length;
  const holdCount = transactions.filter(t => t.status === 'On Hold').length;

  const departmentSpending = transactions.reduce((acc: any[], t) => {
    const existing = acc.find(item => item.name === t.department);
    if (existing) {
      existing.value += t.totalAmount;
    } else {
      acc.push({ name: t.department, value: t.totalAmount });
    }
    return acc;
  }, []);

  const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Hoş Geldiniz 👋</h2>
        <p className="text-slate-500">İşte satın alma süreçlerinizdeki son durum.</p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-4 bg-indigo-50 text-indigo-600 rounded-xl">
            <Wallet size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">Toplam Onaylı Harcama</p>
            <h3 className="text-2xl font-bold text-slate-800">₺{totalSpending.toLocaleString('tr-TR')}</h3>
            <div className="flex items-center text-emerald-500 text-xs mt-1 font-semibold">
              <ArrowUpRight size={14} className="mr-1" />
              <span>Geçen aya göre %12.5 artış</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-4 bg-amber-50 text-amber-600 rounded-xl">
            <Clock size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">Bekleyen Talepler</p>
            <h3 className="text-2xl font-bold text-slate-800">{pendingCount} Adet</h3>
            <div className="flex items-center text-slate-400 text-xs mt-1 font-semibold">
              <Clock size={14} className="mr-1" />
              <span>Sıradaki onaylar bekliyor</span>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex items-center space-x-4">
          <div className="p-4 bg-slate-50 text-slate-600 rounded-xl">
            <AlertCircle size={24} />
          </div>
          <div>
            <p className="text-sm text-slate-500 font-medium">Askıdaki İşlemler</p>
            <h3 className="text-2xl font-bold text-slate-800">{holdCount} Adet</h3>
            <div className="flex items-center text-slate-400 text-xs mt-1 font-semibold">
              <span>Bütçe revizyonu gerekebilir</span>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Pie Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Departman Bazlı Dağılım</h3>
            <TrendingUp size={20} className="text-slate-400" />
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={departmentSpending}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {departmentSpending.map((entry: any, index: number) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                  formatter={(value: number) => `₺${value.toLocaleString('tr-TR')}`}
                />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Pending List */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Onay Bekleyen İşlemler</h3>
            <button className="text-sm text-indigo-600 font-semibold hover:underline">Tümünü Gör</button>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto max-h-[300px] pr-2">
            {transactions.filter(t => t.status === 'Pending').map((t) => (
              <div 
                key={t.id} 
                onClick={() => onSelectTransaction(t.id)}
                className="group flex items-center justify-between p-4 rounded-xl hover:bg-slate-50 border border-transparent hover:border-slate-200 transition-all cursor-pointer"
              >
                <div className="flex items-center space-x-4">
                  <div className="w-10 h-10 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold">
                    {t.requesterName.charAt(0)}
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{t.productSetName}</h4>
                    <p className="text-xs text-slate-500">{t.department} • {t.requesterName}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-bold text-slate-800">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                  <p className="text-[10px] text-slate-400 font-medium">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                </div>
              </div>
            ))}
            {transactions.filter(t => t.status === 'Pending').length === 0 && (
              <div className="flex flex-col items-center justify-center h-full text-slate-400 py-10">
                <Clock size={32} className="mb-2 opacity-20" />
                <p>Bekleyen işlem bulunamadı.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Send, Plus, Trash2, Camera, Info, Sparkles } from 'lucide-react';
import { ExtraItem, Transaction } from '../types';
import { analyzeJustification } from '../services/geminiService';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    newDepartment: '',
    usageLocation: '',
    requesterName: '',
    packageContent: '',
    quantity: 1,
    unitPriceTl: 0,
    description: '',
    justification: '',
    microCode: ''
  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  const addExtraItem = () => {
    if (extraItems.length >= 4) return;
    setExtraItems([...extraItems, { id: Date.now().toString(), name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, field: keyof ExtraItem, value: string | number) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleAiCheck = async () => {
    if (!formData.description || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.description, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let finalDept = formData.department;
    if (formData.department === 'OTHER' && formData.newDepartment) {
      onAddDepartment(formData.newDepartment);
      finalDept = formData.newDepartment;
    }

    onSave({
      ...formData,
      department: finalDept,
      totalAmount: formData.quantity * formData.unitPriceTl,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      logs: [{ id: 'l1', timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Created', details: 'Form submitted' }]
    });
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Yeni Satın Alma Talebi</h2>
          <p className="text-slate-500">Formu eksiksiz doldurarak süreci başlatın.</p>
        </div>
        <div className="px-4 py-2 bg-indigo-50 rounded-full flex items-center space-x-2 text-indigo-700 font-medium text-sm">
          <Info size={16} />
          <span>Talep No: OTOMATİK</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Ürün / Set Adı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
                onChange={e => setFormData({...formData, productSetName: e.target.value})}
                placeholder="Örn: Yazılım Ekibi Donanım Paketi"
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Tedarikçi Firma *</label>
              <input 
                required
                type="text" 
                value={formData.supplierName}
                onChange={e => setFormData({...formData, supplierName: e.target.value})}
                placeholder="Örn: Teknoloji Ltd. Şti."
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold text-slate-700">Departman</label>
              <select 
                value={formData.department}
                onChange={e => setFormData({...formData, department: e.target.value})}
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              >
                {departments.map(d => <option key={d} value={d}>{d}</option>)}
                <option value="OTHER">Diğer (Yeni Ekle)</option>
              </select>
              {formData.department === 'OTHER' && (
                <input 
                  type="text" 
                  value={formData.newDepartment}
                  onChange={e => setFormData({...formData, newDepartment: e.target.value})}
                  placeholder="Departman Adı Yazın"
