        <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center space-x-4">
            <button type="button" className="p-3 border border-slate-200 rounded-xl text-slate-500 hover:bg-slate-50 transition-colors flex items-center space-x-2">
