import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, Role, User } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);

  // Persistence check (Mock)
  useEffect(() => {
    const saved = localStorage.getItem('purchasing_app_state');
    if (saved) {
      // For demo, we might want to reload state, but here we just keep it fresh for the UI
    }
  }, []);

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 10000)}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Anonim',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      totalAmount: (request.quantity || 1) * (request.unitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: [
        { role: 'IT Manager', status: 'Pending' },
        { role: 'CFO', status: 'Pending' }
      ]
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    setActiveTab('dashboard');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Status Update',
            details: `Status changed to ${newStatus}`
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    setSelectedTransactionId(null);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
    }
  };

  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-6">
              <div className="flex items-center justify-between">
                <h2 className="text-2xl font-bold text-slate-800">Tüm İşlemler</h2>
                <div className="flex space-x-2">
                  <span className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-xs font-bold text-slate-500">TÜMÜ</span>
                  <span className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-xs font-bold text-amber-600">BEKLEYEN</span>
                  <span className="px-3 py-1 bg-white border border-slate-200 rounded-lg text-xs font-bold text-emerald-600">ONAYLANMIŞ</span>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {state.transactions.map((t) => (
                  <div 
                    key={t.id}
                    onClick={() => setSelectedTransactionId(t.id)}
                    className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 hover:border-indigo-500 transition-all cursor-pointer group"
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div className="w-12 h-12 bg-slate-50 text-indigo-600 flex items-center justify-center rounded-xl group-hover:bg-indigo-600 group-hover:text-white transition-all">
                        <span className="font-bold">{t.requesterName.charAt(0)}</span>
                      </div>
                      <span className={`px-2 py-1 rounded-md text-[10px] font-black uppercase ${
                        t.status === 'Pending' ? 'bg-amber-100 text-amber-700' : 
                        t.status === 'Approved' ? 'bg-emerald-100 text-emerald-700' : 
                        t.status === 'Rejected' ? 'bg-red-100 text-red-700' : 
                        'bg-slate-100 text-slate-700'
                      }`}>
                        {t.status}
                      </span>
                    </div>
                    <h3 className="font-bold text-slate-800 truncate mb-1">{t.productSetName}</h3>
                    <p className="text-xs text-slate-500 mb-4">{t.department} • {t.supplierName}</p>
                    <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                      <div>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">Toplam</p>
                        <p className="text-lg font-black text-indigo-600">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                      </div>
                      <p className="text-[10px] text-slate-400 font-medium">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={(roles) => setState(prev => ({ ...prev, roles }))} 
              departments={state.departments}
              setDepartments={(departments) => setState(prev => ({ ...prev, departments }))}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

