            <h3 className="text-3xl font-black text-white neon-text">{pendingCount} <span className="text-sm font-bold opacity-40">DOSYA</span></h3>
          </div>
        </div>

        <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-pink-500/30 transition-all group relative overflow-hidden">
          <div className="p-5 bg-pink-500/10 text-pink-400 rounded-2xl border border-pink-500/20 group-hover:bg-pink-600 group-hover:text-white transition-all">
            <AlertCircle size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Askıdaki İşlemler</p>
            <h3 className="text-3xl font-black text-white neon-text">{holdCount} <span className="text-sm font-bold opacity-40">BİRİM</span></h3>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
