          </div>
          <div className="flex-1 space-y-5 overflow-y-auto max-h-[340px] pr-4 custom-scroll">
            {transactions.filter(t => t.status === 'Pending').map((t) => (
              <div 
                key={t.id} 
                onClick={() => onSelectTransaction(t.id)}
                className="group flex items-center justify-between p-5 rounded-3xl bg-indigo-950/20 border border-indigo-500/5 hover:border-indigo-500/30 transition-all cursor-pointer hover:bg-indigo-900/30"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-2xl bg-indigo-500/10 text-indigo-400 flex items-center justify-center font-black border border-indigo-500/20 group-hover:bg-indigo-500 group-hover:text-white transition-all">
                    {t.requesterName.charAt(0)}
                  </div>
                  <div>
                    <h4 className="text-sm font-bold text-white group-hover:text-indigo-400 transition-colors">{t.productSetName}</h4>
                    <p className="text-[10px] text-indigo-400/60 font-black uppercase tracking-widest mt-0.5">{t.department}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-black text-white tracking-tight">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                  <p className="text-[9px] text-indigo-400/40 font-bold uppercase mt-1">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Lock, User as UserIcon, Loader2, ShieldCheck } from 'lucide-react';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      onLogin({
        username,
        role: 'General Manager',
        name: 'Hasan Demir'
      });
      setLoading(false);
    }, 1200);
  };

  return (
    <div className="min-h-screen bg-[#070912] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Background Neon Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-600/10 rounded-full blur-[120px] animate-pulse"></div>

      <div className="w-full max-w-md glass-panel rounded-[40px] border border-indigo-500/20 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-700 relative z-10">
        <div className="p-12">
          <div className="text-center mb-12">
            <div className="inline-flex items-center justify-center w-20 h-20 neon-gradient text-white rounded-3xl shadow-[0_0_30px_rgba(99,102,241,0.4)] mb-8 transform hover:rotate-6 transition-transform">
              <ShieldCheck size={40} />
            </div>
            <h1 className="text-4xl font-black text-white neon-text tracking-tighter">SAPRO NEON</h1>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px] mt-2 opacity-70">Geleceğin Satın Alma Sistemi</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Kullanıcı Kimliği</label>
              <div className="relative">
                <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50" size={18} />
                <input 
                  required
                  type="text" 
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  placeholder="admin"
                  className="w-full bg-indigo-950/40 border border-indigo-500/20 rounded-[20px] py-4 pl-12 pr-4 text-sm text-white focus:ring-1 focus:ring-indigo-400 outline-none transition-all placeholder:text-indigo-900"
                />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Güvenlik Parolası</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50" size={18} />
                <input 
                  required
                  type="password" 
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full bg-indigo-950/40 border border-indigo-500/20 rounded-[20px] py-4 pl-12 pr-4 text-sm text-white focus:ring-1 focus:ring-indigo-400 outline-none transition-all placeholder:text-indigo-900"
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full py-5 neon-gradient text-white rounded-[24px] font-black uppercase tracking-widest text-sm shadow-[0_0_25px_rgba(99,102,241,0.3)] hover:shadow-[0_0_35px_rgba(168,85,247,0.5)] active:scale-95 transition-all flex items-center justify-center space-x-3 mt-10"
            >
              {loading ? <Loader2 className="animate-spin" size={20} /> : <span>SİSTEME GİRİŞ YAP</span>}
            </button>
          </form>

          <div className="mt-12 text-center">
            <p className="text-[10px] text-indigo-900 font-bold uppercase tracking-tighter">Tüm veriler 256-bit SSL ile korunmaktadır</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, Role, User } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Hasan Demir',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      totalAmount: (request.quantity || 1) * (request.unitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: [
        { role: 'IT Manager', status: 'Pending' },
        { role: 'CFO', status: 'Pending' }
      ]
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    setActiveTab('dashboard');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi (Islak İmza Alındı)' : `Durum Güncellendi: ${newStatus}`;
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Arşiv Güncelleme',
            details: actionText
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    setSelectedTransactionId(null);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
    }
  };

  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black text-white neon-text tracking-tighter">Dijital Arşiv</h2>
                    <p className="text-indigo-400 font-bold text-xs uppercase tracking-widest mt-1">Tüm Geçmiş ve Aktif Dosyalar</p>
                </div>
                <div className="flex space-x-3 bg-indigo-950/30 p-1.5 rounded-2xl border border-indigo-500/10">
                  <button className="px-4 py-2 bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">TÜMÜ</button>
                  <button className="px-4 py-2 hover:bg-indigo-500/10 text-indigo-400 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">BEKLEYEN</button>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                {state.transactions.map((t) => (
                  <div 
                    key={t.id}
                    onClick={() => setSelectedTransactionId(t.id)}
                    className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 hover:border-indigo-500/40 transition-all cursor-pointer group hover:scale-[1.02] shadow-xl"
                  >
                    <div className="flex items-start justify-between mb-6">
                      <div className="w-14 h-14 bg-indigo-500/10 text-indigo-400 flex items-center justify-center rounded-2xl group-hover:neon-gradient group-hover:text-white transition-all border border-indigo-500/20 shadow-inner">
                        <span className="font-black text-lg">{t.requesterName.charAt(0)}</span>
                      </div>
                      <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${
                        t.status === 'Pending' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 
                        t.status === 'Approved' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 
                        'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
                      }`}>
                        {t.status}
                      </span>
                    </div>
                    <h3 className="font-black text-white text-lg truncate mb-1 group-hover:text-indigo-400 transition-colors">{t.productSetName}</h3>
                    <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mb-6 opacity-60">{t.department} • {t.supplierName}</p>
                    <div className="flex items-center justify-between pt-6 border-t border-indigo-500/10">
                      <div>
                        <p className="text-[9px] text-indigo-500/40 font-black uppercase tracking-[0.2em]">Dosya Bedeli</p>
                        <p className="text-xl font-black text-white neon-text">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                      </div>
                      <div className="text-right">
                          <p className="text-[9px] text-indigo-500/40 font-bold uppercase">Kayıt No</p>
                          <p className="text-xs font-mono text-indigo-300">#{t.id}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={(roles) => setState(prev => ({ ...prev, roles }))} 
              departments={state.departments}
              setDepartments={(departments) => setState(prev => ({ ...prev, departments }))}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

export type Role = "General Manager" | "IT Manager" | "Coordinator" | "Boss" | "CFO" | string;

export interface LogEntry {
  id: string;
  timestamp: string;
  user: string;
  action: string;
  details: string;
}

export interface ExtraItem {
  id: string;
  name: string;
  quantity: number;
}

export interface Transaction {
  id: string;
  productSetName: string;
  supplierName: string;
  department: string;
  usageLocation: string;
  requesterName: string;
  requestDateTime: string;
  packageContent?: string;
  quantity: number;
  unitPriceTl: number;
  totalAmount: number;
  description: string;
  justification: string;
  microCode: string;
  status: 'Pending' | 'Approved' | 'Rejected' | 'On Hold';
  extraItems: ExtraItem[];
  photoUrl?: string;
  logs: LogEntry[];
  approvalFlow: {
    role: Role;
    status: 'Pending' | 'Approved' | 'Rejected';
    approverName?: string;
    date?: string;
    proofUrl?: string; // Islak imza fotoğrafı için
  }[];
}

export interface User {
  username: string;
  role: Role;
  name: string;
}

export interface AppState {
  user: User | null;
  transactions: Transaction[];
  roles: Role[];
  departments: string[];
}

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Image as ImageIcon,
  Upload
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Gerçek bir uygulamada burada dosya yükleme servisi olurdu.
      // Demo için base64 simülasyonu yapıyoruz.
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { ...f, proofUrl: reader.result as string, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Hasan Demir',
            action: 'İmza Kanıtı',
            details: `${role} için ıslak imza fotoğrafı yüklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const manualApproveRole = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { ...f, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Hasan Demir',
        action: 'Manuel Onay',
        details: `${role} imzası manuel olarak onaylandı.`
      }, ...transaction.logs]
    });
  };

  return (
    <div className="animate-in fade-in zoom-in-95 duration-700 flex flex-col lg:flex-row gap-10 pb-20">
      {/* Main Info */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between">
          <button 
            onClick={onBack}
            className="flex items-center space-x-2 text-indigo-400 hover:text-white transition-all font-bold text-xs uppercase tracking-widest"
          >
            <ArrowLeft size={18} />
            <span>ARŞİV LİSTESİNE DÖN</span>
          </button>

          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <>
                <button 
                  onClick={() => setIsEditing(true)}
                  className="px-5 py-2 glass-panel rounded-xl text-xs font-black uppercase text-indigo-400 border-indigo-500/20 hover:border-indigo-500/50 transition-all"
                >
                  DÜZENLE
                </button>
                <button 
                  onClick={() => { if(confirm('Bu kaydı arşivden silmek istediğinize emin misiniz?')) onDelete(transaction.id); }}
                  className="px-5 py-2 glass-panel rounded-xl text-xs font-black uppercase text-red-500 border-red-500/20 hover:bg-red-500/10 transition-all"
                >
                  <Trash2 size={18} />
                </button>
              </>
            ) : (
              <button 
                onClick={handleSave}
                className="px-6 py-2 neon-gradient text-white rounded-xl text-xs font-black uppercase shadow-lg shadow-indigo-500/20 flex items-center space-x-2"
              >
                <Save size={18} />
                <span>KAYDET</span>
              </button>
            )}
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-indigo-500/10 overflow-hidden shadow-2xl">
          <div className="p-10 border-b border-indigo-500/10 flex items-center justify-between bg-indigo-950/20">
            <div>
              <div className="flex items-center space-x-4 mb-3">
                <h2 className="text-3xl font-black text-white neon-text tracking-tight">
                  {isEditing ? (
                    <input 
                      className="bg-transparent border-b border-indigo-500 outline-none px-2 py-1 w-full"
                      value={editForm.productSetName}
                      onChange={e => setEditForm({...editForm, productSetName: e.target.value})}
                    />
                  ) : transaction.productSetName}
                </h2>
                <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                  {transaction.status}
                </span>
              </div>
              <p className="text-indigo-400/60 text-xs font-bold uppercase tracking-widest">DOSYA ID: <span className="text-indigo-300">{transaction.id}</span> • {new Date(transaction.requestDateTime).toLocaleString('tr-TR')}</p>
            </div>
            <div className="text-right">
              <p className="text-[10px] text-indigo-400/40 font-black uppercase tracking-[0.3em] mb-1">Maliyet Detayı</p>
              <h3 className="text-4xl font-black text-white neon-text">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>

          <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-x-16 gap-y-10">
            <div className="space-y-8">
              <div>
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-indigo-500 pl-3">Talep Özeti</h4>
                <div className="space-y-4">
                  <div className="flex justify-between items-center bg-indigo-950/20 p-3 rounded-2xl">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Tedarikçi</span>
                    <span className="text-sm font-bold text-white">{transaction.supplierName}</span>
                  </div>
                  <div className="flex justify-between items-center bg-indigo-950/20 p-3 rounded-2xl">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Departman</span>
                    <span className="text-sm font-bold text-white">{transaction.department}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Birim Fiyat</span>
                    <span className="text-sm font-black text-indigo-400">₺{transaction.unitPriceTl.toLocaleString('tr-TR')}</span>
                  </div>
                </div>
              </div>

              <div>
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-indigo-500 pl-3">Sözlü Açıklama</h4>
                <div className="p-5 bg-indigo-950/40 rounded-3xl border border-indigo-500/10 text-indigo-200 text-sm leading-relaxed italic">
                  "{transaction.justification}"
                </div>
              </div>
            </div>

            <div className="space-y-8">
                <div>
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-pink-500 pl-3">Islak İmza & Fiziksel Takip</h4>
                    <div className="grid grid-cols-1 gap-4">
                        {transaction.approvalFlow.map((flow, i) => (
                            <div key={i} className={`flex flex-col p-4 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-indigo-500/10 border-indigo-500/30' : 'bg-slate-900/40 border-slate-800'}`}>
                                <div className="flex items-center justify-between mb-3">
                                    <div className="flex items-center space-x-3">
                                        <div className={`p-2 rounded-xl ${flow.status === 'Approved' ? 'bg-indigo-500 text-white shadow-[0_0_15px_rgba(99,102,241,0.5)]' : 'bg-slate-800 text-slate-500'}`}>
                                            <ShieldCheck size={18} />
                                        </div>
                                        <div>
                                            <span className={`text-xs font-black uppercase tracking-wide ${flow.status === 'Approved' ? 'text-white' : 'text-slate-500'}`}>{flow.role} İmzası</span>
                                            {flow.date && <p className="text-[9px] text-indigo-400 font-bold uppercase mt-0.5">{flow.date}</p>}
                                        </div>
                                    </div>

                                    {flow.status !== 'Approved' ? (
                                        <div className="flex items-center space-x-2">
                                            <input 
                                                type="file" 
                                                accept="image/*"
                                                className="hidden" 
                                                ref={el => fileInputRefs.current[flow.role] = el}
                                                onChange={(e) => handleSignatureProof(flow.role, e)}
                                            />
                                            <button 
                                                onClick={() => fileInputRefs.current[flow.role]?.click()}
                                                className="p-2 bg-indigo-500/20 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all"
                                                title="İmza Fotoğrafı Yükle"
                                            >
                                                <Camera size={16} />
                                            </button>
                                            <button 
                                                onClick={() => manualApproveRole(flow.role)}
                                                className="p-2 bg-emerald-500/20 text-emerald-500 rounded-lg hover:bg-emerald-500 hover:text-white transition-all"
                                                title="Manuel Onayla"
                                            >
                                                <CheckCircle2 size={16} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="flex items-center space-x-2">
                                            {flow.proofUrl && (
                                                <button 
                                                    onClick={() => window.open(flow.proofUrl)}
                                                    className="p-2 bg-indigo-500/40 text-white rounded-lg hover:bg-indigo-500 transition-all"
                                                >
                                                    <ImageIcon size={16} />
                                                </button>
                                            )}
                                            <CheckCircle2 size={20} className="text-indigo-400 shadow-[0_0_10px_rgba(99,102,241,0.4)]" />
                                        </div>
                                    )}
                                </div>
                                {flow.proofUrl && (
                                    <div className="mt-2 h-16 w-full rounded-xl overflow-hidden border border-indigo-500/20 relative group">
