        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 flex flex-col">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center">
              <Users size={20} className="mr-3 text-pink-500" />
              Tedarikçi Analizi
            </h3>
            <span className="text-[10px] text-indigo-400 font-black uppercase">Onaylı Ödemeler</span>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto max-h-[340px] pr-4 custom-scroll">
            {monthlyAnalysis.map((monthData: any) => (
              <div key={monthData.month} className="space-y-3">
                <div className="flex items-center space-x-2">
                  <span className="px-3 py-1 bg-indigo-500/20 text-indigo-400 rounded-lg text-[10px] font-black uppercase">{monthData.month}</span>
                  <div className="h-px flex-1 bg-indigo-500/10"></div>
                  <span className="text-xs font-black text-white">₺{monthData.total.toLocaleString('tr-TR')}</span>
                </div>
                <div className="grid gap-2 pl-4">
                  {Object.entries(monthData.suppliers).map(([name, amount]: [any, any]) => (
                    <div key={name} className="flex justify-between items-center p-3 bg-indigo-950/20 rounded-xl border border-indigo-500/5">
                      <span className="text-[11px] font-bold text-slate-300">{name}</span>
                      <span className="text-[11px] font-black text-indigo-400">₺{amount.toLocaleString('tr-TR')}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

