import React, { useMemo } from 'react';
import { 
  TrendingUp, 
  Clock, 
  AlertCircle, 
  Wallet,
  ArrowUpRight,
  Target,
  BarChart as BarChartIcon,
  Users,
  ChevronRight
} from 'lucide-react';
import { 
  PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Legend, 
  BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const totalSpending = transactions
    .filter(t => t.status === 'Approved')
    .reduce((sum, t) => sum + t.totalAmount, 0);

  const pendingCount = transactions.filter(t => t.status === 'Pending').length;
  const holdCount = transactions.filter(t => t.status === 'On Hold').length;

  // Aylık Bazda Harcama Analizi
  const monthlyAnalysis = useMemo(() => {
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const currentMonth = new Date().getMonth();

    // Son 12 ayın boş listesini oluştur (veya sadece verisi olanları göster)
    const analysis: any = {};

    transactions.filter(t => t.status === 'Approved').forEach(t => {
      const date = new Date(t.requestDateTime);
      const monthLabel = months[date.getMonth()];

      if (!analysis[monthLabel]) {
        analysis[monthLabel] = { month: monthLabel, monthIndex: date.getMonth(), total: 0, suppliers: {} };
      }

      analysis[monthLabel].total += t.totalAmount;
      if (!analysis[monthLabel].suppliers[t.supplierName]) {
        analysis[monthLabel].suppliers[t.supplierName] = 0;
      }
      analysis[monthLabel].suppliers[t.supplierName] += t.totalAmount;
    });

    return Object.values(analysis).sort((a: any, b: any) => a.monthIndex - b.monthIndex);
  }, [transactions]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-black text-white neon-text tracking-tighter">Sistem Özeti</h2>
          <p className="text-indigo-400 font-bold text-sm mt-1">Metriklere tıklayarak detaylı arşive ulaşabilirsiniz</p>
        </div>
        <div className="flex items-center space-x-2 bg-indigo-950/30 px-4 py-2 rounded-full border border-indigo-500/10">
            <Target size={16} className="text-pink-500" />
            <span className="text-[10px] font-black text-white uppercase tracking-widest">Veri Analiz Merkezi</span>
        </div>
      </div>

      {/* Stats Grid - Clickable */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <button 
          onClick={() => onFilterClick('Approved')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-indigo-500/30 transition-all group relative overflow-hidden text-left"
        >
          <div className="absolute -right-4 -top-4 w-24 h-24 bg-indigo-500/5 rounded-full blur-2xl group-hover:bg-indigo-500/10 transition-all"></div>
          <div className="p-5 bg-indigo-500/10 text-indigo-400 rounded-2xl border border-indigo-500/20 group-hover:neon-gradient group-hover:text-white transition-all shadow-lg">
            <Wallet size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Onaylı Harcama</p>
            <h3 className="text-3xl font-black text-white neon-text">₺{totalSpending.toLocaleString('tr-TR')}</h3>
            <span className="text-[8px] text-indigo-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">Dosyaları İncele &raquo;</span>
          </div>
        </button>

        <button 
          onClick={() => onFilterClick('Pending')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-purple-500/30 transition-all group relative overflow-hidden text-left"
        >
          <div className="p-5 bg-purple-500/10 text-purple-400 rounded-2xl border border-purple-500/20 group-hover:bg-purple-600 group-hover:text-white transition-all">
            <Clock size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Bekleyen Arşiv</p>
            <h3 className="text-3xl font-black text-white neon-text">{pendingCount} <span className="text-sm font-bold opacity-40">DOSYA</span></h3>
            <span className="text-[8px] text-purple-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">Süreci Yönet &raquo;</span>
          </div>
        </button>

        <button 
          onClick={() => onFilterClick('On Hold')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-pink-500/30 transition-all group relative overflow-hidden text-left"
        >
          <div className="p-5 bg-pink-500/10 text-pink-400 rounded-2xl border border-pink-500/20 group-hover:bg-pink-600 group-hover:text-white transition-all">
            <AlertCircle size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Askıdaki İşlemler</p>
            <h3 className="text-3xl font-black text-white neon-text">{holdCount} <span className="text-sm font-bold opacity-40">DOSYA</span></h3>
            <span className="text-[8px] text-pink-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">Arşive Git &raquo;</span>
          </div>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        {/* Aylık Harcama Trendi (Bar Chart) */}
        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 shadow-2xl">
          <div className="flex items-center justify-between mb-10">
            <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center">
              <BarChartIcon size={20} className="mr-3 text-indigo-400" />
              Aylık Harcama Trendi
            </h3>
          </div>
          <div className="h-[340px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyAnalysis}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e1b4b" vertical={false} />
                <XAxis dataKey="month" stroke="#4338ca" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#4338ca" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => `₺${val/1000}k`} />
                <Tooltip 
                  cursor={{fill: 'rgba(99, 102, 241, 0.1)'}}
                  contentStyle={{ 
                    backgroundColor: '#0a0f1e', 
                    borderRadius: '16px', 
                    border: '1px solid rgba(99,102,241,0.2)',
                    boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
                  }}
                  itemStyle={{ color: '#fff' }}
                  labelStyle={{ color: '#6366f1', fontWeight: 'bold' }}
                  formatter={(value: number) => `₺${value.toLocaleString('tr-TR')}`}
                />
                <Bar dataKey="total" fill="url(#barGradient)" radius={[6, 6, 0, 0]} />
                <defs>
                  <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#6366f1" />
                    <stop offset="100%" stopColor="#a855f7" />
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Aylık Detay Listesi (Kim Ne Kadar Aldı) */}
        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 flex flex-col shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center">
              <Users size={20} className="mr-3 text-pink-500" />
              Harcama & Tedarikçi Detayı
            </h3>
            <span className="text-[10px] text-indigo-400 font-black uppercase bg-indigo-500/10 px-3 py-1 rounded-full border border-indigo-500/20">Arşiv Analizi</span>
          </div>
          <div className="flex-1 space-y-6 overflow-y-auto max-h-[340px] pr-4 custom-scroll">
            {monthlyAnalysis.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-30">
                    <Clock size={40} className="mb-2" />
                    <p className="text-xs font-bold uppercase tracking-widest">Veri Bulunmuyor</p>
                </div>
            )}
            {monthlyAnalysis.slice().reverse().map((monthData: any) => (
              <div key={monthData.month} className="space-y-4 group">
                <div className="flex items-center space-x-3">
                  <span className="px-4 py-1.5 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-indigo-600/20">{monthData.month} Toplamı</span>
                  <div className="h-px flex-1 bg-indigo-500/20"></div>
                  <span className="text-sm font-black text-indigo-400">₺{monthData.total.toLocaleString('tr-TR')}</span>
                </div>
                <div className="grid gap-3 pl-4">
                  {Object.entries(monthData.suppliers).map(([name, amount]: [any, any]) => (
                    <div 
                      key={name} 
                      onClick={() => onFilterClick('Approved')}
                      className="flex justify-between items-center p-4 bg-indigo-950/20 rounded-[20px] border border-indigo-500/5 hover:border-indigo-500/30 hover:bg-indigo-950/40 transition-all cursor-pointer"
                    >
                      <div className="flex items-center space-x-3">
                        <div className="w-2 h-2 rounded-full bg-pink-500 shadow-[0_0_5px_#ec4899]"></div>
                        <span className="text-xs font-bold text-slate-200">{name}</span>
                      </div>
                      <div className="flex items-center space-x-3">
                        <span className="text-xs font-black text-white">₺{amount.toLocaleString('tr-TR')}</span>
                        <ChevronRight size={14} className="text-indigo-800" />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

