import React, { useState, useRef } from 'react';
import { Send, Plus, Trash2, Camera, Info, Sparkles, FileText, CheckCircle, X } from 'lucide-react';
import { ExtraItem, Transaction } from '../types';
import { analyzeJustification } from '../services/geminiService';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    newDepartment: '',
    usageLocation: '',
    requesterName: 'Hasan Demir', // Simüle edilen kullanıcı
    packageContent: '',
    quantity: 1,
    unitPriceTl: 0,
    description: '',
    justification: '',
    microCode: '',
    photoUrl: ''
  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const inputClass = "w-full px-4 py-3 rounded-xl bg-indigo-900/60 border border-indigo-500/20 text-slate-200 focus:border-indigo-400 focus:ring-1 focus:ring-indigo-400/30 outline-none transition-all placeholder:text-indigo-700/60";

  const addExtraItem = () => {
    if (extraItems.length >= 4) return;
    setExtraItems([...extraItems, { id: Date.now().toString(), name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, field: keyof ExtraItem, value: string | number) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, photoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAiCheck = async () => {
    if (!formData.description || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.description, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      totalAmount: formData.quantity * formData.unitPriceTl,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Süreç Başlatıldı', details: 'Sözlü onay sonrası dijital kayıt oluşturuldu.' }]
    });
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-700 pb-20">
      <div className="flex items-center justify-between mb-10">
        <div>
          <h2 className="text-3xl font-black text-white neon-text tracking-tight">Yeni Satın Alma Kaydı</h2>
          <div className="flex items-center space-x-2 mt-2">
            <span className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></span>
            <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest">Sözlü Onay Alınmış İşlemler İçin</p>
          </div>
        </div>
        <div className="px-5 py-2 glass-panel rounded-full border border-indigo-500/30 flex items-center space-x-3 text-indigo-400 font-bold text-xs">
          <FileText size={16} />
          <span>KLASÖR NO: OTOMATİK</span>
        </div>
      </div>

      {/* Süreç Bilgi Kartı */}
      <div className="glass-panel p-6 rounded-3xl border border-indigo-500/20 mb-8 flex items-center justify-between">
        <div className="flex items-center space-x-4">
            <div className="p-3 bg-indigo-500/10 rounded-2xl border border-indigo-500/20">
                <CheckCircle className="text-indigo-400" size={24} />
            </div>
            <div>
                <p className="text-white font-bold text-sm">Süreç Hatırlatması</p>
                <p className="text-indigo-400 text-xs mt-0.5">Yöneticilerle görüşülüp onay alındıysa, detayları buraya girerek dijital arşive ekleyin.</p>
            </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Ürün / Set Adı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
                onChange={e => setFormData({...formData, productSetName: e.target.value})}
                placeholder="Örn: Ofis Malzemeleri Paketi"
                className={inputClass}
              />
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Tedarikçi Firma *</label>
