          <button 
            onClick={onBack}
            className="flex items-center space-x-2 text-indigo-400 hover:text-white transition-all font-bold text-xs uppercase tracking-widest"
          >
            <ArrowLeft size={18} />
            <span>ARŞİV LİSTESİNE DÖN</span>
