import React, { useMemo, useState } from 'react';
import { 
  TrendingUp, 
  Clock, 
  AlertCircle, 
  Wallet,
  Target,
  BarChart as BarChartIcon,
  Users,
  ChevronRight,
  Building2
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer 
} from 'recharts';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const [analysisType, setAnalysisType] = useState<'suppliers' | 'departments'>('suppliers');

  const totalSpending = transactions
    .filter(t => t.status === 'Approved')
    .reduce((sum, t) => sum + t.totalAmount, 0);

  const pendingCount = transactions.filter(t => t.status === 'Pending').length;
  const holdCount = transactions.filter(t => t.status === 'On Hold').length;

  // Gelişmiş Aylık Analiz (Tedarikçi + Departman)
  const monthlyAnalysis = useMemo(() => {
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const analysis: any = {};

    transactions.filter(t => t.status === 'Approved').forEach(t => {
      const date = new Date(t.requestDateTime);
      const monthLabel = months[date.getMonth()];

      if (!analysis[monthLabel]) {
        analysis[monthLabel] = { 
          month: monthLabel, 
          monthIndex: date.getMonth(), 
          total: 0, 
          suppliers: {}, 
          departments: {} 
        };
      }

      analysis[monthLabel].total += t.totalAmount;

      // Tedarikçi bazlı toplama
      if (!analysis[monthLabel].suppliers[t.supplierName]) {
        analysis[monthLabel].suppliers[t.supplierName] = 0;
      }
      analysis[monthLabel].suppliers[t.supplierName] += t.totalAmount;

      // Departman bazlı toplama
      if (!analysis[monthLabel].departments[t.department]) {
        analysis[monthLabel].departments[t.department] = 0;
      }
      analysis[monthLabel].departments[t.department] += t.totalAmount;
    });

    return Object.values(analysis).sort((a: any, b: any) => a.monthIndex - b.monthIndex);
  }, [transactions]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">Yönetim Paneli</h2>
          <p className="text-indigo-400 font-bold text-sm mt-1">Sistem genelindeki tüm finansal hareketlerin özeti</p>
        </div>
        <div className="flex items-center space-x-2 bg-indigo-950/30 px-4 py-2 rounded-full border border-indigo-500/10">
            <Target size={16} className="text-pink-500" />
            <span className="text-[10px] font-black text-white uppercase tracking-widest">Canlı Finansal Analiz</span>
        </div>
      </div>

      {/* Tıklanabilir Metrik Kartları */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <button 
          onClick={() => onFilterClick('Approved')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-indigo-500/40 transition-all group relative overflow-hidden text-left"
        >
          <div className="absolute -right-4 -top-4 w-24 h-24 bg-indigo-500/5 rounded-full blur-2xl group-hover:bg-indigo-500/10 transition-all"></div>
          <div className="p-5 bg-indigo-500/10 text-indigo-400 rounded-2xl border border-indigo-500/20 group-hover:neon-gradient group-hover:text-white transition-all shadow-lg">
            <Wallet size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Toplam Harcama</p>
            <h3 className="text-3xl font-black text-white neon-text">₺{totalSpending.toLocaleString('tr-TR')}</h3>
            <span className="text-[8px] text-indigo-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              ARŞİVE GİT <ChevronRight size={10} className="ml-1" />
            </span>
          </div>
        </button>

        <button 
          onClick={() => onFilterClick('Pending')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-purple-500/40 transition-all group relative overflow-hidden text-left"
        >
          <div className="p-5 bg-purple-500/10 text-purple-400 rounded-2xl border border-purple-500/20 group-hover:bg-purple-600 group-hover:text-white transition-all">
            <Clock size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Bekleyen İşlemler</p>
            <h3 className="text-3xl font-black text-white neon-text">{pendingCount} <span className="text-sm font-bold opacity-40 uppercase">Kayıt</span></h3>
            <span className="text-[8px] text-purple-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              LİSTEYE GİT <ChevronRight size={10} className="ml-1" />
            </span>
          </div>
        </button>

        <button 
          onClick={() => onFilterClick('On Hold')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-pink-500/40 transition-all group relative overflow-hidden text-left"
        >
          <div className="p-5 bg-pink-500/10 text-pink-400 rounded-2xl border border-pink-500/20 group-hover:bg-pink-600 group-hover:text-white transition-all">
            <AlertCircle size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Askıdaki Dosyalar</p>
            <h3 className="text-3xl font-black text-white neon-text">{holdCount} <span className="text-sm font-bold opacity-40 uppercase">Birim</span></h3>
            <span className="text-[8px] text-pink-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              DETAYLARA BAK <ChevronRight size={10} className="ml-1" />
            </span>
          </div>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        {/* Aylık Harcama Grafiği */}
        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5">
            <BarChartIcon size={120} />
          </div>
          <div className="flex items-center justify-between mb-10 relative z-10">
            <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center">
              <TrendingUp size={20} className="mr-3 text-indigo-400" />
              Aylık Harcama Trendi
            </h3>
            <span className="text-[9px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-500/5 px-3 py-1 rounded-full border border-indigo-500/10">Son 12 Ay</span>
          </div>
          <div className="h-[340px] relative z-10">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyAnalysis}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e1b4b" vertical={false} />
                <XAxis dataKey="month" stroke="#4338ca" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#4338ca" fontSize={10} tickLine={false} axisLine={false} tickFormatter={(val) => `₺${val/1000}k`} />
                <Tooltip 
                  cursor={{fill: 'rgba(99, 102, 241, 0.05)'}}
                  contentStyle={{ 
                    backgroundColor: '#0a0f1e', 
                    borderRadius: '16px', 
                    border: '1px solid rgba(99,102,241,0.2)',
                    boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
                  }}
                  itemStyle={{ color: '#fff' }}
                  labelStyle={{ color: '#6366f1', fontWeight: 'bold' }}
                  formatter={(value: number) => `₺${value.toLocaleString('tr-TR')}`}
                />
                <Bar dataKey="total" fill="url(#barGradient)" radius={[6, 6, 0, 0]} />
                <defs>
                  <linearGradient id="barGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor="#6366f1" />
                    <stop offset="100%" stopColor="#a855f7" />
                  </linearGradient>
                </defs>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Aylık Detay Listesi */}
        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 flex flex-col shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center">
              <Users size={20} className="mr-3 text-pink-500" />
              Harcama Dökümü
            </h3>

            <div className="flex bg-indigo-900/20 p-1 rounded-xl border border-indigo-500/10">
                <button 
                  onClick={() => setAnalysisType('suppliers')}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${analysisType === 'suppliers' ? 'bg-indigo-500 text-white shadow-lg' : 'text-indigo-400 hover:text-white'}`}
                >
                    Tedarikçi
                </button>
                <button 
                  onClick={() => setAnalysisType('departments')}
                  className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${analysisType === 'departments' ? 'bg-indigo-500 text-white shadow-lg' : 'text-indigo-400 hover:text-white'}`}
                >
                    Departman
                </button>
            </div>
          </div>

          <div className="flex-1 space-y-8 overflow-y-auto max-h-[340px] pr-4 custom-scroll">
            {monthlyAnalysis.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-30 mt-10">
                    <AlertCircle size={40} className="mb-2" />
                    <p className="text-xs font-bold uppercase tracking-widest">Henüz onaylı veri bulunmuyor</p>
                </div>
            )}
            {monthlyAnalysis.slice().reverse().map((monthData: any) => (
              <div key={monthData.month} className="space-y-4 animate-in slide-in-from-right-4 duration-500">
                <div className="flex items-center space-x-3">
                  <span className="px-4 py-1.5 bg-indigo-900/60 text-white rounded-xl text-[10px] font-black uppercase border border-indigo-500/20">{monthData.month} Analizi</span>
                  <div className="h-px flex-1 bg-indigo-500/10"></div>
                  <span className="text-sm font-black text-indigo-400">₺{monthData.total.toLocaleString('tr-TR')}</span>
                </div>

                <div className="grid gap-2 pl-2">
                  {Object.entries(analysisType === 'suppliers' ? monthData.suppliers : monthData.departments).map(([name, amount]: [any, any]) => (
                    <div 
                      key={name} 
                      className="flex justify-between items-center p-3 bg-indigo-950/20 rounded-2xl border border-indigo-500/5 hover:border-indigo-500/20 transition-all"
                    >
                      <div className="flex items-center space-x-3">
                        <div className={`w-1.5 h-1.5 rounded-full ${analysisType === 'suppliers' ? 'bg-pink-500 shadow-[0_0_8px_#ec4899]' : 'bg-indigo-400 shadow-[0_0_8px_#818cf8]'}`}></div>
                        <span className="text-[11px] font-bold text-slate-300">{name}</span>
                      </div>
                      <span className="text-[11px] font-black text-white">₺{amount.toLocaleString('tr-TR')}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

