import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, Role, User } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  // Hooks must be called unconditionally at the top level
  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Hasan Demir',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      totalAmount: (request.quantity || 1) * (request.unitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: [
        { role: 'IT Manager', status: 'Pending' },
        { role: 'CFO', status: 'Pending' }
      ]
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    setActiveTab('dashboard');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi (Islak İmza Alındı)' : `Durum Güncellendi: ${newStatus}`;
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Arşiv Güncelleme',
            details: actionText
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    setSelectedTransactionId(null);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
    }
  };

  const handleMetricClick = (status: string | null) => {
    setStatusFilter(status);
    setActiveTab('transactions');
  };

  // Conditional return must happen after all hooks
  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
        if (tab !== 'transactions') setStatusFilter(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
              onFilterClick={handleMetricClick}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black text-white neon-text tracking-tighter">Dijital Arşiv</h2>
                    <p className="text-indigo-400 font-bold text-xs uppercase tracking-widest mt-1">
                      {statusFilter ? `${statusFilter} Filtreli Sonuçlar` : 'Tüm Geçmiş ve Aktif Dosyalar'}
                    </p>
                </div>
                <div className="flex space-x-3 bg-indigo-950/30 p-1.5 rounded-2xl border border-indigo-500/10">
                  <button 
                    onClick={() => setStatusFilter(null)}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-indigo-500/10 text-indigo-400'}`}
                  >
                    TÜMÜ
                  </button>
                  <button 
                    onClick={() => setStatusFilter('Pending')}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-indigo-500/10 text-indigo-400'}`}
                  >
                    BEKLEYEN
                  </button>
                  <button 
                    onClick={() => setStatusFilter('Approved')}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-indigo-500/10 text-indigo-400'}`}
                  >
                    ONAYLI
                  </button>
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="glass-panel p-20 rounded-[40px] border border-indigo-500/10 text-center">
                  <p className="text-indigo-400 font-bold uppercase tracking-widest">Bu kriterlere uygun dosya bulunamadı.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id}
                      onClick={() => setSelectedTransactionId(t.id)}
                      className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 hover:border-indigo-500/40 transition-all cursor-pointer group hover:scale-[1.02] shadow-xl"
                    >
                      <div className="flex items-start justify-between mb-6">
                        <div className="w-14 h-14 bg-indigo-500/10 text-indigo-400 flex items-center justify-center rounded-2xl group-hover:neon-gradient group-hover:text-white transition-all border border-indigo-500/20 shadow-inner">
                          <span className="font-black text-lg">{t.requesterName.charAt(0)}</span>
                        </div>
                        <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${
                          t.status === 'Pending' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 
                          t.status === 'Approved' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 
                          'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
                        }`}>
                          {t.status}
                        </span>
                      </div>
                      <h3 className="font-black text-white text-lg truncate mb-1 group-hover:text-indigo-400 transition-colors">{t.productSetName}</h3>
                      <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mb-6 opacity-60">{t.department} • {t.supplierName}</p>
                      <div className="flex items-center justify-between pt-6 border-t border-indigo-500/10">
                        <div>
                          <p className="text-[9px] text-indigo-500/40 font-black uppercase tracking-[0.2em]">Dosya Bedeli</p>
                          <p className="text-xl font-black text-white neon-text">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[9px] text-indigo-500/40 font-bold uppercase">Kayıt No</p>
                            <p className="text-xs font-mono text-indigo-300">#{t.id}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={(roles) => setState(prev => ({ ...prev, roles }))} 
              departments={state.departments}
              setDepartments={(departments) => setState(prev => ({ ...prev, departments }))}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

