                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-indigo-500/10 text-indigo-400'}`}
                  >
                    BEKLEYEN
                  </button>
                  <button 
                    onClick={() => setStatusFilter('Approved')}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-indigo-500 text-white shadow-lg' : 'hover:bg-indigo-500/10 text-indigo-400'}`}
                  >
                    ONAYLI
                  </button>
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="glass-panel p-20 rounded-[40px] border border-indigo-500/10 text-center">
                  <p className="text-indigo-400 font-bold uppercase tracking-widest">Bu kriterlere uygun dosya bulunamadı.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id}
                      onClick={() => setSelectedTransactionId(t.id)}
                      className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 hover:border-indigo-500/40 transition-all cursor-pointer group hover:scale-[1.02] shadow-xl"
                    >
                      <div className="flex items-start justify-between mb-6">
                        <div className="w-14 h-14 bg-indigo-500/10 text-indigo-400 flex items-center justify-center rounded-2xl group-hover:neon-gradient group-hover:text-white transition-all border border-indigo-500/20 shadow-inner">
                          <span className="font-black text-lg">{t.requesterName.charAt(0)}</span>
                        </div>
                        <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${
                          t.status === 'Pending' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 
                          t.status === 'Approved' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 
                          'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
                        }`}>
                          {t.status}
                        </span>
                      </div>
                      <h3 className="font-black text-white text-lg truncate mb-1 group-hover:text-indigo-400 transition-colors">{t.productSetName}</h3>
                      <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mb-6 opacity-60">{t.department} • {t.supplierName}</p>
                      <div className="flex items-center justify-between pt-6 border-t border-indigo-500/10">
                        <div>
                          <p className="text-[9px] text-indigo-500/40 font-black uppercase tracking-[0.2em]">Dosya Bedeli</p>
                          <p className="text-xl font-black text-white neon-text">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[9px] text-indigo-500/40 font-bold uppercase">Kayıt No</p>
                            <p className="text-xs font-mono text-indigo-300">#{t.id}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={(roles) => setState(prev => ({ ...prev, roles }))} 
              departments={state.departments}
              setDepartments={(departments) => setState(prev => ({ ...prev, departments }))}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Image as ImageIcon,
  Upload,
  X,
  Maximize2
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleDeleteClick = () => {
    // Bazı tarayıcılar için confirm penceresini garantiliyoruz
    const confirmed = window.confirm(`${transaction.productSetName} isimli kaydı arşivden tamamen silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`);
    if (confirmed) {
      onDelete(transaction.id);
    }
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { ...f, proofUrl: reader.result as string, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Hasan Demir',
            action: 'İmza Kanıtı',
            details: `${role} için ıslak imza fotoğrafı yüklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const manualApproveRole = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { ...f, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Hasan Demir',
        action: 'Manuel Onay',
        details: `${role} imzası manuel olarak onaylandı.`
      }, ...transaction.logs]
    });
  };

  return (
    <div className="animate-in fade-in zoom-in-95 duration-700 flex flex-col lg:flex-row gap-10 pb-20 relative">
      {/* Image Viewer Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300">
          <button 
            onClick={() => setSelectedImage(null)}
            className="absolute top-8 right-8 p-3 bg-white/10 hover:bg-white/20 text-white rounded-full transition-all"
          >
            <X size={24} />
          </button>
          <img 
            src={selectedImage} 
            className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-2xl border border-white/10 animate-in zoom-in-95 duration-300" 
            alt="Belge Önizleme" 
          />
        </div>
      )}

      {/* Main Info */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between">
          <button 
            onClick={onBack}
            className="flex items-center space-x-2 text-indigo-400 hover:text-white transition-all font-bold text-xs uppercase tracking-widest"
          >
            <ArrowLeft size={18} />
            <span>ARŞİV LİSTESİNE DÖN</span>
          </button>

          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <>
                <button 
                  onClick={() => setIsEditing(true)}
                  className="px-5 py-2 glass-panel rounded-xl text-xs font-black uppercase text-indigo-400 border-indigo-500/20 hover:border-indigo-500/50 transition-all"
                >
                  DÜZENLE
                </button>
                <button 
                  onClick={handleDeleteClick}
                  className="px-4 py-2 glass-panel rounded-xl text-xs font-black uppercase text-red-500 border-red-500/20 hover:bg-red-500/10 transition-all flex items-center space-x-2 group"
                  title="Kaydı Sil"
                >
                  <Trash2 size={16} className="group-hover:scale-110 transition-transform" />
                  <span>SİL</span>
                </button>
              </>
            ) : (
              <button 
                onClick={handleSave}
                className="px-6 py-2 neon-gradient text-white rounded-xl text-xs font-black uppercase shadow-lg shadow-indigo-500/20 flex items-center space-x-2"
              >
                <Save size={18} />
                <span>KAYDET</span>
              </button>
            )}
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-indigo-500/10 overflow-hidden shadow-2xl">
          <div className="p-10 border-b border-indigo-500/10 flex items-center justify-between bg-indigo-950/20">
            <div>
              <div className="flex items-center space-x-4 mb-3">
                <h2 className="text-3xl font-black text-white neon-text tracking-tight">
                  {isEditing ? (
                    <input 
                      className="bg-indigo-900/60 border-b border-indigo-500 outline-none px-4 py-2 rounded-xl w-full text-white"
                      value={editForm.productSetName}
                      onChange={e => setEditForm({...editForm, productSetName: e.target.value})}
                    />
                  ) : transaction.productSetName}
                </h2>
                <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                  {transaction.status}
                </span>
              </div>
              <p className="text-indigo-400/60 text-xs font-bold uppercase tracking-widest">DOSYA ID: <span className="text-indigo-300">{transaction.id}</span> • {new Date(transaction.requestDateTime).toLocaleString('tr-TR')}</p>
            </div>
            <div className="text-right">
              <p className="text-[10px] text-indigo-400/40 font-black uppercase tracking-[0.3em] mb-1">Maliyet Detayı</p>
              <h3 className="text-4xl font-black text-white neon-text">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>

          <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-x-16 gap-y-10">
            <div className="space-y-8">
              <div>
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-indigo-500 pl-3">Talep Özeti</h4>
                <div className="space-y-4">
                  <div className="flex justify-between items-center bg-indigo-950/20 p-3 rounded-2xl">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Tedarikçi</span>
                    <span className="text-sm font-bold text-white">{transaction.supplierName}</span>
                  </div>
                  <div className="flex justify-between items-center bg-indigo-950/20 p-3 rounded-2xl">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Departman</span>
                    <span className="text-sm font-bold text-white">{transaction.department}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-xs font-bold text-indigo-400/60 uppercase">Birim Fiyat</span>
                    <span className="text-sm font-black text-indigo-400">₺{transaction.unitPriceTl.toLocaleString('tr-TR')}</span>
                  </div>
                </div>
              </div>

              {transaction.photoUrl && (
                <div>
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-indigo-500 pl-3">Ekli Belge</h4>
                    <div 
                      onClick={() => setSelectedImage(transaction.photoUrl || null)}
                      className="group relative h-48 w-full rounded-3xl overflow-hidden border border-indigo-500/10 cursor-pointer shadow-lg"
                    >
                        <img src={transaction.photoUrl} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt="Ana Belge" />
                        <div className="absolute inset-0 bg-indigo-900/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <Maximize2 size={32} className="text-white drop-shadow-lg" />
                        </div>
                    </div>
                </div>
              )}
            </div>

            <div className="space-y-8">
                <div>
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-pink-500 pl-3">Islak İmza & Fiziksel Takip</h4>
                    <div className="grid grid-cols-1 gap-4">
                        {transaction.approvalFlow.map((flow, i) => (
                            <div key={i} className={`flex flex-col p-4 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-indigo-500/10 border-indigo-500/30' : 'bg-slate-900/40 border-slate-800'}`}>
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center space-x-3">
                                        <div className={`p-2 rounded-xl ${flow.status === 'Approved' ? 'bg-indigo-500 text-white shadow-[0_0_15px_rgba(99,102,241,0.5)]' : 'bg-slate-800 text-slate-500'}`}>
                                            <ShieldCheck size={18} />
                                        </div>
                                        <div>
                                            <span className={`text-xs font-black uppercase tracking-wide ${flow.status === 'Approved' ? 'text-white' : 'text-slate-500'}`}>{flow.role} İmzası</span>
                                            {flow.date && <p className="text-[9px] text-indigo-400 font-bold uppercase mt-0.5">{flow.date}</p>}
                                        </div>
                                    </div>

                                    <div className="flex items-center space-x-2">
                                        {flow.status !== 'Approved' ? (
                                            <>
                                                <input 
                                                    type="file" 
                                                    accept="image/*"
                                                    className="hidden" 
                                                    ref={el => fileInputRefs.current[flow.role] = el}
                                                    onChange={(e) => handleSignatureProof(flow.role, e)}
                                                />
                                                <button 
                                                    onClick={() => fileInputRefs.current[flow.role]?.click()}
                                                    className="p-2 bg-indigo-500/20 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all"
                                                    title="İmza Fotoğrafı Yükle"
                                                >
                                                    <Camera size={16} />
                                                </button>
                                                <button 
                                                    onClick={() => manualApproveRole(flow.role)}
                                                    className="p-2 bg-emerald-500/20 text-emerald-500 rounded-lg hover:bg-emerald-500 hover:text-white transition-all"
                                                    title="Manuel Onayla"
                                                >
                                                    <CheckCircle2 size={16} />
                                                </button>
                                            </>
                                        ) : (
                                            <>
                                                {flow.proofUrl && (
                                                    <button 
                                                        onClick={() => setSelectedImage(flow.proofUrl || null)}
                                                        className="p-2 bg-indigo-500/40 text-white rounded-lg hover:bg-indigo-500 transition-all"
                                                        title="Görüntüle"
                                                    >
                                                        <Maximize2 size={16} />
                                                    </button>
                                                )}
                                                <CheckCircle2 size={20} className="text-indigo-400 shadow-[0_0_10px_rgba(99,102,241,0.4)]" />
                                            </>
                                        )}
                                    </div>
                                </div>
                                {flow.proofUrl && (
                                    <div 
                                      onClick={() => setSelectedImage(flow.proofUrl || null)}
                                      className="mt-3 h-16 w-full rounded-xl overflow-hidden border border-indigo-500/20 relative group cursor-pointer"
                                    >
                                        <img src={flow.proofUrl} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-opacity" alt="İmza Kanıtı" />
                                        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                                            <span className="text-[9px] font-black text-white uppercase tracking-widest">Tam Boyut</span>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>

                <div>
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] mb-4 border-l-2 border-indigo-500 pl-3">Sözlü Açıklama</h4>
                    <div className="p-5 bg-indigo-950/40 rounded-3xl border border-indigo-500/10 text-indigo-200 text-sm leading-relaxed italic">
                        "{transaction.justification}"
                    </div>
                </div>
            </div>
          </div>

          <div className="bg-indigo-950/40 p-10 border-t border-indigo-500/10 flex items-center justify-center space-x-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved'}
              className={`px-10 py-4 neon-gradient text-white rounded-[20px] font-black text-xs uppercase tracking-[0.2em] flex items-center space-x-3 shadow-lg hover:scale-105 active:scale-95 transition-all ${
                transaction.approvalFlow.every(f => f.status === 'Approved') ? 'opacity-100' : 'opacity-30 cursor-not-allowed'
              }`}
            >
              <Archive size={20} />
              <span>{transaction.status === 'Approved' ? 'ARŞİVLENDİ' : 'SÜRECİ TAMAMLA & ARŞİVLE'}</span>
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="px-10 py-4 bg-red-600/10 border border-red-600/20 text-red-500 rounded-[20px] font-black text-xs uppercase tracking-[0.2em] flex items-center space-x-3 hover:bg-red-600/20 transition-all"
            >
              <XCircle size={20} />
              <span>SÜRECİ İPTAL ET</span>
            </button>
          </div>
        </div>
      </div>

      {/* Side Panel: Günlük */}
      <div className="w-full lg:w-80 space-y-8">
        <div className="glass-panel rounded-3xl border border-indigo-500/10 overflow-hidden shadow-xl">
          <div className="p-5 border-b border-indigo-500/10 bg-indigo-950 flex items-center space-x-3">
            <History size={18} className="text-pink-500" />
            <h3 className="font-black text-[10px] uppercase tracking-widest text-white">İşlem Geçmişi</h3>
          </div>
          <div className="p-6 space-y-6 max-h-[500px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[10px]">
                <div className="flex items-center justify-between mb-2">
                  <span className="font-black text-indigo-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-slate-600 font-bold">{new Date(log.timestamp).toLocaleTimeString('tr-TR', {hour:'2-digit', minute:'2-digit'})}</span>
                </div>
                <div className="p-3 bg-indigo-950/40 rounded-xl border border-indigo-500/5 text-indigo-300 leading-relaxed">
                   <span className="font-bold text-white mr-1 uppercase">{log.action}:</span>
                   {log.details}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-indigo-600 p-8 rounded-[32px] shadow-lg shadow-indigo-500/20 text-white relative overflow-hidden group">
            <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-white/10 rounded-full blur-3xl group-hover:bg-white/20 transition-all"></div>
            <h4 className="font-black text-sm uppercase tracking-widest mb-4 flex items-center">
                <FileText size={18} className="mr-2" />
                Hızlı Not
            </h4>
            <textarea 
                className="w-full bg-indigo-900/60 border border-white/10 rounded-2xl p-4 text-xs text-white placeholder:text-indigo-300 focus:ring-1 focus:ring-white outline-none resize-none"
                placeholder="Bu dosya için ek not bırakın..."
                rows={3}
            ></textarea>
            <button className="w-full mt-4 py-3 bg-white text-indigo-600 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-indigo-50 transition-all">
                NOTU KAYDET
            </button>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState } from 'react';
import { Lock, User as UserIcon, Loader2, ShieldCheck } from 'lucide-react';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (loading) return;

    setLoading(true);

    // Küçük bir bekleme ekleyerek UI tepkisini güçlendiriyoruz
    setTimeout(() => {
      try {
        onLogin({
          username: username || 'admin',
          role: 'General Manager',
          name: 'Hasan Demir'
        });
      } catch (error) {
        console.error("Giriş hatası:", error);
        setLoading(false);
      }
    }, 500);
  };

  return (
    <div className="min-h-screen bg-[#070912] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Background Neon Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600/10 rounded-full blur-[120px] animate-pulse"></div>
      <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-600/10 rounded-full blur-[120px] animate-pulse"></div>

      <div className="w-full max-w-md glass-panel rounded-[40px] border border-indigo-500/20 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-700 relative z-10">
        <div className="p-12">
          <div className="text-center mb-12">
            <div className="inline-flex items-center justify-center w-20 h-20 neon-gradient text-white rounded-3xl shadow-[0_0_30px_rgba(99,102,241,0.4)] mb-8 transform hover:rotate-6 transition-transform">
              <ShieldCheck size={40} />
            </div>
            <h1 className="text-4xl font-black text-white neon-text tracking-tighter">SAPRO NEON</h1>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px] mt-2 opacity-70">Giriş Yapın</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Kullanıcı Adı</label>
              <div className="relative">
                <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50" size={18} />
                <input 
                  required
                  type="text" 
                  autoComplete="username"
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  placeholder="Kullanıcı adınız"
                  className="w-full rounded-[20px] py-4 pl-12 pr-4 text-sm text-white gradient-neon-input placeholder:text-indigo-700/60"
                />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Parola</label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-indigo-500/50" size={18} />
                <input 
                  required
                  type="password" 
                  autoComplete="current-password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full rounded-[20px] py-4 pl-12 pr-4 text-sm text-white gradient-neon-input placeholder:text-indigo-700/60"
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
