import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Image as ImageIcon,
  Upload,
  X,
  Maximize2
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleDeleteClick = () => {
    // Bazı tarayıcılar için confirm penceresini garantiliyoruz
    const confirmed = window.confirm(`${transaction.productSetName} isimli kaydı arşivden tamamen silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`);
    if (confirmed) {
      onDelete(transaction.id);
    }
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { ...f, proofUrl: reader.result as string, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Hasan Demir',
            action: 'İmza Kanıtı',
            details: `${role} için ıslak imza fotoğrafı yüklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const manualApproveRole = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { ...f, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Hasan Demir',
        action: 'Manuel Onay',
        details: `${role} imzası manuel olarak onaylandı.`
      }, ...transaction.logs]
    });
  };

  return (
    <div className="animate-in fade-in zoom-in-95 duration-700 flex flex-col lg:flex-row gap-10 pb-20 relative">
      {/* Image Viewer Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300">
          <button 
            onClick={() => setSelectedImage(null)}
            className="absolute top-8 right-8 p-3 bg-white/10 hover:bg-white/20 text-white rounded-full transition-all"
          >
            <X size={24} />
          </button>
          <img 
            src={selectedImage} 
            className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-2xl border border-white/10 animate-in zoom-in-95 duration-300" 
            alt="Belge Önizleme" 
          />
        </div>
      )}

      {/* Main Info */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between">
          <button 
            onClick={onBack}
            className="flex items-center space-x-2 text-indigo-400 hover:text-white transition-all font-bold text-xs uppercase tracking-widest"
          >
            <ArrowLeft size={18} />
            <span>ARŞİV LİSTESİNE DÖN</span>
          </button>

          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <>
                <button 
                  onClick={() => setIsEditing(true)}
                  className="px-5 py-2 glass-panel rounded-xl text-xs font-black uppercase text-indigo-400 border-indigo-500/20 hover:border-indigo-500/50 transition-all"
                >
                  DÜZENLE
                </button>
                <button 
                  onClick={handleDeleteClick}
                  className="px-4 py-2 glass-panel rounded-xl text-xs font-black uppercase text-red-500 border-red-500/20 hover:bg-red-500/10 transition-all flex items-center space-x-2 group"
