  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const inputClass = "w-full px-4 py-3 rounded-xl gradient-neon-input text-slate-200 outline-none transition-all placeholder:text-indigo-700/60 text-sm";

  const addExtraItem = () => {
    if (extraItems.length >= 4) return;
    setExtraItems([...extraItems, { id: Date.now().toString(), name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, field: keyof ExtraItem, value: string | number) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAiCheck = async () => {
    if (!formData.productSetName || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.productSetName, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const totalAmount = (formData.packageQuantity * formData.packageUnitPriceTl) + (formData.quantity * formData.unitPriceTl);

    onSave({
      ...formData,
      totalAmount,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Süreç Başlatıldı', details: 'Mobil kayıt oluşturuldu.' }]
    });
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      <div className="flex items-center justify-between mb-6 lg:mb-10 px-2">
        <h2 className="text-2xl lg:text-3xl font-black text-white neon-text tracking-tight uppercase">Talep Girişi</h2>
        <div className="hidden lg:flex px-4 py-2 glass-panel rounded-full border border-indigo-500/30 items-center space-x-2 text-indigo-400 font-bold text-xs uppercase tracking-widest">
          <FileText size={14} />
          <span>Yeni Dosya</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 lg:space-y-8">
        {/* Temel Bilgiler */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Harcama Tanımı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
                onChange={e => setFormData({...formData, productSetName: e.target.value})}
                placeholder="Ürün veya Set Adı"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Tedarikçi *</label>
              <input 
                required
                type="text" 
                value={formData.supplierName}
                onChange={e => setFormData({...formData, supplierName: e.target.value})}
                placeholder="Firma Adı"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Departman</label>
              <select 
                value={formData.department}
                onChange={e => setFormData({...formData, department: e.target.value})}
                className={inputClass}
              >
                {departments.map(d => <option key={d} value={d} className="bg-[#1e1b4b]">{d}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Micro Kodu (Opsiyonel)</label>
              <input 
                type="text" 
                value={formData.microCode}
                onChange={e => setFormData({...formData, microCode: e.target.value})}
                placeholder="Örn: STOK-001"
                className={inputClass}
              />
            </div>
          </div>
        </div>

        {/* Paket ve Maliyet - Mantık Gereği Eklendi */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="flex items-center space-x-2 mb-6">
            <Package size={18} className="text-indigo-400" />
            <h3 className="text-sm lg:text-base font-black text-white uppercase tracking-tight">Maliyet Detayı</h3>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase">Paket Adet</label>
              <input 
                type="number" 
                value={formData.packageQuantity}
                onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase">Paket Fiyat (TL)</label>
              <input 
                type="number" 
                value={formData.packageUnitPriceTl}
                onChange={e => setFormData({...formData, packageUnitPriceTl: parseFloat(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="col-span-2 bg-[#1e293b]/50 p-4 rounded-xl border border-indigo-500/20 flex flex-col justify-center">
              <p className="text-[9px] text-indigo-400 font-black uppercase">Ara Toplam</p>
              <p className="text-xl font-black text-white neon-text">₺{(formData.packageQuantity * formData.packageUnitPriceTl).toLocaleString('tr-TR')}</p>
            </div>
          </div>
        </div>

        {/* Ek Ürünler - Max 4 Sınırı ile Mobil Uyumlu */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="flex items-center justify-between mb-4 lg:mb-6">
            <h3 className="text-sm font-black text-white uppercase tracking-tight">Set İçeriği / Ek Ürünler</h3>
            {extraItems.length < 4 && (
              <button 
                type="button" 
                onClick={addExtraItem}
                className="p-2 bg-indigo-500/10 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all"
              >
                <Plus size={16} />
              </button>
            )}
          </div>

          <div className="space-y-3">
            {extraItems.map((item) => (
              <div key={item.id} className="flex items-center space-x-3 bg-indigo-950/20 p-3 rounded-2xl border border-indigo-500/5 animate-in slide-in-from-right-4">
                <input 
                  type="text" 
                  value={item.name}
                  onChange={e => updateExtraItem(item.id, 'name', e.target.value)}
                  placeholder="Ürün Adı"
                  className="flex-1 bg-transparent border-b border-indigo-500/20 outline-none text-xs text-white p-1"
                />
                <input 
                  type="number" 
                  value={item.quantity}
                  onChange={e => updateExtraItem(item.id, 'quantity', parseInt(e.target.value) || 1)}
                  className="w-12 bg-transparent border-b border-indigo-500/20 outline-none text-xs text-center text-white p-1"
                />
                <button onClick={() => removeExtraItem(item.id)} className="text-red-500/60 hover:text-red-500">
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
            {extraItems.length === 0 && (
              <p className="text-[10px] text-indigo-400/40 font-bold uppercase text-center py-4">Sadece ana kalem mevcut</p>
            )}
          </div>
        </div>

        {/* Gerekçe ve AI */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] border border-indigo-500/10">
          <div className="flex items-center justify-between mb-4">
            <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Talep Gerekçesi *</label>
            <button 
              type="button" 
              onClick={handleAiCheck}
              disabled={analyzing}
              className="text-[10px] font-black text-pink-500 uppercase flex items-center space-x-1"
            >
              <Sparkles size={12} />
              <span>{analyzing ? 'Analiz...' : 'AI Analiz'}</span>
            </button>
          </div>
          <textarea 
            required
            rows={4}
            value={formData.justification}
            onChange={e => setFormData({...formData, justification: e.target.value})}
            className={`${inputClass} resize-none mb-4`}
            placeholder="Neden bu ürüne ihtiyaç duyuldu?"
          />
          {aiAnalysis && (
            <div className="p-4 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl text-[11px] text-indigo-300 leading-relaxed italic animate-in fade-in">
               <span className="font-black text-indigo-400 uppercase tracking-tighter mr-2">AI Notu:</span>
               {aiAnalysis}
            </div>
          )}
        </div>

        {/* Gönderim Butonu */}
        <div className="flex flex-col lg:flex-row items-center gap-4">
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()}
            className="w-full lg:w-auto p-4 glass-panel rounded-2xl text-indigo-400 flex items-center justify-center space-x-3 hover:text-white transition-all"
          >
            {formData.photoUrl ? <CheckCircle size={20} className="text-emerald-500" /> : <Camera size={20} />}
            <span className="text-[10px] font-black uppercase tracking-widest">{formData.photoUrl ? 'BELGE EKLENDİ' : 'BELGE / FOTOĞRAF'}</span>
          </button>
          <button 
            type="submit"
            className="w-full flex-1 py-5 neon-gradient text-white rounded-[24px] font-black shadow-lg flex items-center justify-center space-x-3 uppercase tracking-widest text-sm active:scale-95 transition-all"
          >
            <Send size={18} />
            <span>KAYDI ONAYA SUN</span>
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewRequest;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { ...f, proofUrl: reader.result as string, status: 'Approved' as const, date: new Date().toLocaleDateString('tr-TR') } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'İmza Kanıtı',
            details: `${role} için ıslak imza fotoğrafı eklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24">
      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-indigo-400"><Maximize2 size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-2xl" alt="Önizleme" />
        </div>
      )}

      {/* Ana Bilgi Paneli */}
      <div className="flex-1 space-y-6 lg:space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-2 text-indigo-400 font-bold text-xs uppercase tracking-widest">
            <ArrowLeft size={16} /> <span>GERİ DÖN</span>
          </button>

          <div className="flex items-center space-x-2">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-4 py-2 glass-panel rounded-xl text-[10px] font-black text-indigo-400 uppercase tracking-widest border-indigo-500/20">DÜZENLE</button>
            ) : (
              <button onClick={handleSave} className="px-6 py-2 neon-gradient text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Dosyayı tamamen silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-2 text-red-500/60 hover:text-red-500 transition-colors">
              <Trash2 size={18} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[32px] border border-indigo-500/10 overflow-hidden shadow-2xl">
          <div className="p-6 lg:p-10 border-b border-indigo-500/10 bg-indigo-950/20">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
              <div>
                <div className="flex items-center space-x-3 mb-2">
                  <h2 className="text-xl lg:text-3xl font-black text-white neon-text uppercase leading-none">
                    {isEditing ? (
                      <input className="gradient-neon-input outline-none px-3 py-1 rounded-lg w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} />
                    ) : transaction.productSetName}
                  </h2>
                  <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter border ${statusColors[transaction.status]}`}>
                    {transaction.status}
                  </span>
                </div>
                <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest opacity-60">ID: #{transaction.id} • {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[9px] text-indigo-500/40 font-black uppercase tracking-[0.2em] mb-1">Toplam Maliyet</p>
                <h3 className="text-3xl lg:text-5xl font-black text-white neon-text">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-6 lg:p-10 space-y-10">
            {/* Maliyet & Micro Kartı */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="p-6 bg-indigo-950/30 rounded-3xl border border-indigo-500/10 space-y-4">
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest flex items-center">
                        <Package size={14} className="mr-2" /> Maliyet Kırılımı
                    </h4>
                    <div className="space-y-2">
                        <div className="flex justify-between text-xs">
                            <span className="text-slate-500 uppercase font-bold">Paket ({transaction.packageQuantity || 0} Adet):</span>
                            <span className="text-white font-black">₺{(transaction.packageQuantity || 0) * (transaction.packageUnitPriceTl || 0)}</span>
                        </div>
                        <div className="flex justify-between text-xs">
                            <span className="text-slate-500 uppercase font-bold">Birim ({transaction.quantity || 0} Adet):</span>
                            <span className="text-white font-black">₺{(transaction.quantity || 0) * (transaction.unitPriceTl || 0)}</span>
                        </div>
                    </div>
                </div>

                <div className="p-6 bg-slate-900/40 rounded-3xl border border-indigo-500/10 flex flex-col justify-center space-y-3">
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Micro Entegrasyon Kodu</h4>
                    <div className="flex items-center justify-between bg-black/30 p-3 rounded-xl border border-indigo-500/20">
                        <span className="font-mono text-xs text-indigo-300">{transaction.microCode || 'TANIMSIZ'}</span>
                        <button onClick={copyMicroCode} className="text-indigo-500 hover:text-white transition-all">
                            {copied ? <Check size={16} /> : <Copy size={16} />}
                        </button>
                    </div>
                </div>
            </div>

            {/* Set İçeriği / Ek Ürünler */}
            {transaction.extraItems.length > 0 && (
                <div>
                    <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4 flex items-center">
                        <Plus size={14} className="mr-2" /> Ek Ürün Listesi
                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        {transaction.extraItems.map(item => (
                            <div key={item.id} className="p-4 bg-indigo-950/20 rounded-2xl border border-indigo-500/5 flex justify-between items-center">
                                <span className="text-xs font-bold text-white uppercase">{item.name}</span>
                                <span className="px-3 py-1 bg-indigo-500/10 rounded-lg text-[10px] font-black text-indigo-400">x{item.quantity}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Onay Akışı - Mobil Kart Tasarımı */}
            <div>
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-4 flex items-center">
                    <ShieldCheck size={14} className="mr-2" /> Islak İmza & Takip Durumu
                </h4>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className={`p-4 rounded-3xl border ${flow.status === 'Approved' ? 'bg-indigo-500/5 border-indigo-500/30 shadow-[0_0_20px_rgba(99,102,241,0.1)]' : 'bg-slate-900/40 border-slate-800'} transition-all`}>
                            <div className="flex items-center justify-between mb-3">
                                <div className="flex items-center space-x-3">
                                    <div className={`p-2 rounded-xl ${flow.status === 'Approved' ? 'bg-indigo-500 text-white shadow-lg' : 'bg-slate-800 text-slate-600'}`}>
                                        <ShieldCheck size={16} />
