                                    <span className={`text-[11px] font-black uppercase tracking-tight ${flow.status === 'Approved' ? 'text-white' : 'text-slate-500'}`}>{flow.role}</span>
                                </div>
                                {flow.status === 'Approved' ? (
                                    <CheckCircle2 size={20} className="text-emerald-500" />
