                                    <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-2 bg-indigo-500/20 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all">
                                        <Camera size={14} />
                                    </button>
                                )}
                                <input type="file" accept="image/*" className="hidden" ref={el => fileInputRefs.current[flow.role] = el} onChange={(e) => handleSignatureProof(flow.role, e)} />
                            </div>

                            {flow.proofUrl && (
                                <div onClick={() => setSelectedImage(flow.proofUrl || null)} className="h-20 w-full rounded-xl overflow-hidden cursor-pointer border border-indigo-500/10 relative group">
                                    <img src={flow.proofUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform" alt="İmza" />
                                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                        <Maximize2 size={16} className="text-white" />
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* Gerekçe Metni */}
            <div>
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-3">Talep Gerekçesi</h4>
                <div className="p-5 bg-indigo-950/40 rounded-3xl border border-indigo-500/10 text-indigo-200 text-xs lg:text-sm leading-relaxed italic">
                    "{transaction.justification}"
                </div>
            </div>
          </div>

          {/* Onay Butonları - Sabit Alt Bar Etkisi */}
          <div className="bg-indigo-950/40 p-6 lg:p-10 border-t border-indigo-500/10 flex flex-col sm:flex-row items-center justify-center gap-4">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved'}
              className={`w-full sm:w-auto px-10 py-4 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-3 shadow-lg active:scale-95 transition-all ${
                transaction.approvalFlow.every(f => f.status === 'Approved') ? 'opacity-100' : 'opacity-30 cursor-not-allowed'
              }`}
            >
              <Archive size={20} />
              <span>SÜRECİ TAMAMLA</span>
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="w-full sm:w-auto px-10 py-4 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-3 hover:bg-red-600/20 transition-all"
            >
              <XCircle size={20} />
              <span>İPTAL ET</span>
            </button>
          </div>
        </div>
      </div>

      {/* Sağ Panel - Geçmiş Günlüğü - Mobilde Alta Geçer */}
      <div className="w-full lg:w-80 space-y-6">
        <div className="glass-panel rounded-[24px] border border-indigo-500/10 overflow-hidden shadow-xl">
          <div className="p-4 border-b border-indigo-500/10 bg-indigo-950 flex items-center space-x-3">
            <History size={16} className="text-pink-500" />
            <h3 className="font-black text-[10px] uppercase tracking-widest text-white">İşlem Günlüğü</h3>
          </div>
          <div className="p-5 space-y-5 max-h-[400px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[10px] relative pl-4 border-l border-indigo-500/20">
                <div className="absolute left-[-4px] top-0 w-2 h-2 rounded-full bg-indigo-500"></div>
                <div className="flex items-center justify-between mb-1">
