          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'İmza Kanıtı',
            details: `${role} için ıslak imza fotoğrafı eklendi.`
