import { GoogleGenAI } from "@google/genai";

// Initialize the Gemini API client using the required named parameter and environment variable.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeJustification = async (description: string, justification: string) => {
  try {
    // Generate content by specifying the model and prompt within a single call.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analiz et ve bir onaylayıcı gibi geri bildirim ver.
      Talep Açıklaması: ${description}
      Gerekçe: ${justification}

      Lütfen bu talebin mantıklı olup olmadığını, kritik bir eksiklik olup olmadığını ve bütçe verimliliği açısından kısa bir özet (max 2 cümle) ver. Türkçe yanıtla.`,
    });
    // Correctly access the text output from the 'text' property.
    return response.text || "Analiz sonucu alınamadı.";
  } catch (error) {
    console.error("Gemini analysis failed:", error);
    return "Analiz şu an yapılamıyor.";
  }
};

import React, { useMemo, useState, useEffect } from 'react';
import { 
  TrendingUp, 
  Clock, 
  AlertCircle, 
  Wallet,
  Target,
  BarChart as BarChartIcon,
  Users,
  ChevronRight,
  Building2,
