        <div className="glass-panel p-8 rounded-[40px] border border-indigo-500/10 shadow-2xl relative overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-4">
            <div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center">
                <TrendingUp size={24} className="mr-3 text-indigo-400" />
                Aylık Harcama Trendi
              </h3>
              <p className="text-indigo-400 text-xs font-bold uppercase tracking-widest mt-1 opacity-60">Grafik üzerinden ay seçimi yapabilirsiniz</p>
            </div>
            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-2 bg-indigo-500/10 px-4 py-2 rounded-2xl border border-indigo-500/20">
