  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell
} from 'recharts';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);

  const totalSpending = transactions
    .filter(t => t.status === 'Approved')
    .reduce((sum, t) => sum + t.totalAmount, 0);

  const pendingCount = transactions.filter(t => t.status === 'Pending').length;
  const holdCount = transactions.filter(t => t.status === 'On Hold').length;

  // Monthly Analysis Calculation
  const monthlyAnalysis = useMemo(() => {
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const analysis: Record<string, any> = {};

    transactions.filter(t => t.status === 'Approved').forEach(t => {
      const date = new Date(t.requestDateTime);
      const monthLabel = months[date.getMonth()];

      if (!analysis[monthLabel]) {
        analysis[monthLabel] = { 
          month: monthLabel, 
          monthIndex: date.getMonth(), 
          total: 0, 
          count: 0,
          suppliers: {} as Record<string, number>, 
          departments: {} as Record<string, number> 
        };
      }

      analysis[monthLabel].total += t.totalAmount;
      analysis[monthLabel].count += 1;

      // Supplier Aggregation
      if (!analysis[monthLabel].suppliers[t.supplierName]) {
        analysis[monthLabel].suppliers[t.supplierName] = 0;
      }
      analysis[monthLabel].suppliers[t.supplierName] += t.totalAmount;

      // Department Aggregation
      if (!analysis[monthLabel].departments[t.department]) {
        analysis[monthLabel].departments[t.department] = 0;
      }
      analysis[monthLabel].departments[t.department] += t.totalAmount;
    });

    return Object.values(analysis).sort((a: any, b: any) => a.monthIndex - b.monthIndex);
  }, [transactions]);

  // Set default selected month to the latest one with data
  useEffect(() => {
    if (monthlyAnalysis.length > 0 && !selectedMonth) {
      setSelectedMonth(monthlyAnalysis[monthlyAnalysis.length - 1].month);
    }
  }, [monthlyAnalysis, selectedMonth]);

  const selectedMonthData = useMemo(() => {
    return monthlyAnalysis.find(m => m.month === selectedMonth) || null;
  }, [monthlyAnalysis, selectedMonth]);

  const sortedSuppliers = useMemo(() => {
    if (!selectedMonthData) return [];
    return Object.entries(selectedMonthData.suppliers)
      .sort(([, a], [, b]) => (b as number) - (a as number))
      .slice(0, 5);
  }, [selectedMonthData]);

  const sortedDepartments = useMemo(() => {
    if (!selectedMonthData) return [];
    return Object.entries(selectedMonthData.departments)
      .sort(([, a], [, b]) => (b as number) - (a as number))
      .slice(0, 5);
  }, [selectedMonthData]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">Yönetim Paneli</h2>
          <p className="text-indigo-400 font-bold text-sm mt-1">Süreç analitiği ve harcama projeksiyonu</p>
        </div>
        <div className="flex items-center space-x-2 bg-indigo-950/30 px-4 py-2 rounded-full border border-indigo-500/10 shadow-lg">
            <Target size={16} className="text-pink-500" />
            <span className="text-[10px] font-black text-white uppercase tracking-widest">Veri Odaklı Karar Mekanizması</span>
        </div>
      </div>

      {/* Top Level Metric Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <button 
          onClick={() => onFilterClick('Approved')}
          className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 flex items-center space-x-6 hover:border-indigo-500/40 transition-all group relative overflow-hidden text-left"
        >
          <div className="absolute -right-4 -top-4 w-24 h-24 bg-indigo-500/5 rounded-full blur-2xl group-hover:bg-indigo-500/10 transition-all"></div>
          <div className="p-5 bg-indigo-500/10 text-indigo-400 rounded-2xl border border-indigo-500/20 group-hover:neon-gradient group-hover:text-white transition-all shadow-lg">
            <Wallet size={28} />
          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">Kümülatif Harcama</p>
            <h3 className="text-3xl font-black text-white neon-text">₺{totalSpending.toLocaleString('tr-TR')}</h3>
            <span className="text-[8px] text-indigo-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              ARŞİVE GİT <ChevronRight size={10} className="ml-1" />
