          </div>
          <div>
            <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1 opacity-70">İnceleme Gereken</p>
            <h3 className="text-3xl font-black text-white neon-text">{holdCount} <span className="text-sm font-bold opacity-40 uppercase">Dosya</span></h3>
            <span className="text-[8px] text-pink-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity flex items-center">
              DETAYLARA BAK <ChevronRight size={10} className="ml-1" />
            </span>
          </div>
        </button>
      </div>

      {/* Main Analysis Visualizations */}
      <div className="space-y-8">
        {/* Expenditure Trend Chart */}
        <div className="glass-panel p-8 lg:p-10 rounded-[48px] border border-indigo-500/10 shadow-2xl relative overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between mb-12 gap-6">
            <div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center">
                <TrendingUp size={24} className="mr-3 text-indigo-400" />
