import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Uygulama başarıyla yüklendi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Yönetici girişi yapıldı: ${user.username}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı sistemden ayrıldı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    // Akışı sistemdeki yetkililerden çekerek oluştur
    const approvalFlow = state.roles.slice(0, 2).map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      totalAmount: (request.quantity || 1) * (request.unitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow.length > 0 ? approvalFlow : [
        { role: 'IT Manager', status: 'Pending', approverName: 'Murat Bilgin' },
        { role: 'CFO', status: 'Pending', approverName: 'Selin Aksoy' }
      ]
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    addSystemLog('PURCHASE', 'Yeni Talep', `${newTransaction.productSetName} için ${newTransaction.totalAmount} TL bedelli talep oluşturuldu.`);
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi' : `Durum: ${newStatus}`;
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Statü Güncelleme',
            details: actionText
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Değişikliği', `Kayıt #${id} yeni durumuna getirildi: ${newStatus}`);
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} veritabanından kalıcı olarak kaldırıldı.`);
    setSelectedTransactionId(null);
    setActiveTab('transactions');
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
    addSystemLog('PURCHASE', 'Kayıt Güncellendi', `Kayıt #${id} içeriği manuel olarak düzenlendi.`);
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
      addSystemLog('DEPTS', 'Departman Eklendi', `Yeni departman sisteme tanımlandı: ${name}`);
    }
  };

  const handleSetRoles = (roles: RoleDefinition[]) => {
    setState(prev => ({ ...prev, roles }));
    addSystemLog('ROLES', 'Yetkili Listesi Güncellendi', `Onay yetkilileri ve atanan isimler güncellendi.`);
  };

  const handleSetDepartments = (departments: string[]) => {
    setState(prev => ({ ...prev, departments }));
    addSystemLog('DEPTS', 'Departman Listesi Güncellendi', `Sistemdeki departman yapılandırması güncellendi.`);
  };

  const handleUpdateUser = (name: string) => {
    if (state.user) {
      const oldName = state.user.name;
      setState(prev => ({ ...prev, user: { ...prev.user!, name } }));
      addSystemLog('PROFILE', 'Profil Güncellendi', `Kullanıcı adı '${oldName}' değerinden '${name}' değerine değiştirildi.`);
    }
  };

  const handleMetricClick = (status: string | null) => {
    setStatusFilter(status);
    setActiveTab('transactions');
  };

  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
        if (tab !== 'transactions') setStatusFilter(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
              onFilterClick={handleMetricClick}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">DİJİTAL ARŞİV</h2>
                    <p className="text-emerald-400 font-bold text-xs uppercase tracking-widest mt-1">
                      {statusFilter ? `${statusFilter} Filtreli Sonuçlar` : 'Tüm Geçmiş ve Aktif Dosyalar'}
                    </p>
                </div>
                <div className="flex space-x-3 bg-emerald-950/30 p-1.5 rounded-2xl border border-emerald-500/10">
                  <button onClick={() => setStatusFilter(null)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>ONAYLI</button>
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="glass-panel p-20 rounded-[40px] border border-emerald-500/10 text-center">
                  <p className="text-emerald-400 font-bold uppercase tracking-widest">Bu kriterlere uygun dosya bulunamadı.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id}
                      onClick={() => setSelectedTransactionId(t.id)}
                      className="glass-panel p-8 rounded-[32px] border border-emerald-500/10 hover:border-emerald-500/40 transition-all cursor-pointer group hover:scale-[1.02] shadow-xl"
                    >
                      <div className="flex items-start justify-between mb-6">
                        <div className="w-14 h-14 bg-emerald-500/10 text-emerald-400 flex items-center justify-center rounded-2xl group-hover:neon-gradient group-hover:text-white transition-all border border-emerald-500/20 shadow-inner">
                          <span className="font-black text-lg">{t.requesterName.charAt(0)}</span>
                        </div>
                        <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${
                          t.status === 'Pending' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 
                          t.status === 'Approved' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 
                          'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                        }`}>
                          {t.status}
                        </span>
                      </div>
                      <h3 className="font-black text-white text-lg truncate mb-1 group-hover:text-emerald-400 transition-colors">{t.productSetName}</h3>
                      <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest mb-6 opacity-60">{t.department} • {t.supplierName}</p>
                      <div className="flex items-center justify-between pt-6 border-t border-emerald-500/10">
                        <div>
                          <p className="text-[9px] text-emerald-500/40 font-black uppercase tracking-[0.2em]">Dosya Bedeli</p>
                          <p className="text-xl font-black text-white neon-text">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[9px] text-emerald-500/40 font-bold uppercase">Kayıt No</p>
                            <p className="text-xs font-mono text-emerald-300">#{t.id}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={handleSetRoles} 
              departments={state.departments}
              setDepartments={handleSetDepartments}
              user={state.user}
              onUpdateUser={handleUpdateUser}
              systemLogs={state.systemLogs}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

export interface RoleDefinition {
  id: string;
  roleName: string;
  assignedName: string;
}

export type Role = string; 

export interface LogEntry {
  id: string;
  timestamp: string;
  user: string;
  action: string;
  details: string;
}

export interface ExtraItem {
  id: string;
  name: string;
  quantity: number;
}

export interface Transaction {
  id: string;
  productSetName: string;
  supplierName: string;
  department: string;
  usageLocation: string;
  requesterName: string;
  requestDateTime: string;
  packageContent?: string;
  quantity: number;
  packageQuantity?: number;
  unitPriceTl: number;
  packageUnitPriceTl?: number;
  totalAmount: number;
  description: string;
  justification: string;
  microCode: string;
  status: 'Pending' | 'Approved' | 'Rejected' | 'On Hold';
  extraItems: ExtraItem[];
  photoUrl?: string;
  logs: LogEntry[];
  approvalFlow: {
    role: string;
    status: 'Pending' | 'Approved' | 'Rejected';
    approverName?: string;
    date?: string;
    proofUrl?: string;
    decisionNote?: string;
  }[];
}

export interface User {
  username: string;
  role: string;
  name: string;
}

export interface SystemLog {
  id: string;
  timestamp: string;
  user: string;
  module: 'AUTH' | 'PURCHASE' | 'ROLES' | 'DEPTS' | 'PROFILE';
  action: string;
  details: string;
}

export interface AppState {
  user: User | null;
  transactions: Transaction[];
  roles: RoleDefinition[];
  departments: string[];
  systemLogs: SystemLog[];
}

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const flowStatusColors = {
    'Pending': 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    'Approved': 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    'Rejected': 'bg-red-500/20 text-red-400 border-red-500/30'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: new Date().toLocaleDateString('tr-TR'),
            decisionNote: decisionNote || 'İşlem onaylandı.'
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Onay Güncelleme',
            details: `${role} onayı ve görsel kanıtı başarıyla kaydedildi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReject = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Rejected' as const, 
        date: new Date().toLocaleDateString('tr-TR'),
        decisionNote: decisionNote || 'Talep uygun görülmedi.'
      } : f
    );
    onUpdate(transaction.id, { 
      status: 'Rejected',
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Ret Kararı',
        details: `${role} tarafından işlem reddedildi: ${decisionNote}`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24 px-1 lg:px-0">

      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-emerald-400 bg-emerald-500/10 rounded-full transition-all">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-[0_0_100px_rgba(16,185,129,0.3)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 rounded-[40px] border border-emerald-500/20 shadow-2xl relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-2 text-emerald-400 hover:bg-emerald-500/10 rounded-xl transition-all">
              <X size={24} />
            </button>
            <div className="flex items-center space-x-4 mb-8">
                <div className="w-16 h-16 neon-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <UserCheck size={32} />
                </div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-emerald-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-6">
                <div className="bg-emerald-950/20 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Tarihi & Durum</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekliyor...'}</span>
                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border ${flowStatusColors[transaction.approvalFlow[selectedFlowDetail].status]}`}>
                            {transaction.approvalFlow[selectedFlowDetail].status}
                        </span>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Notu</p>
                    <p className="text-xs text-slate-300 italic leading-relaxed">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'Henüz not eklenmedi.'}"
                    </p>
                </div>

                {transaction.approvalFlow[selectedFlowDetail].proofUrl && (
                    <div>
                        <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-3">İmzalı Belge / Kanıt</p>
                        <div 
                          onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}
                          className="w-full h-48 rounded-[30px] overflow-hidden border border-emerald-500/20 cursor-pointer group relative shadow-inner"
                        >
                            <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Maximize2 className="text-white" size={24} />
                            </div>
                        </div>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}

      {/* Ana Bilgi Paneli */}
      <div className="flex-1 space-y-6 lg:space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-2 text-emerald-400 font-bold text-[11px] uppercase tracking-widest group">
            <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> <span>GERİ DÖN</span>
          </button>

          <div className="flex items-center space-x-2">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-5 py-2 glass-panel rounded-xl text-[10px] font-black text-emerald-400 uppercase tracking-widest border-emerald-500/20 hover:border-emerald-500/40 transition-all">DÜZENLE</button>
            ) : (
              <button onClick={handleSave} className="px-6 py-2 neon-gradient text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Bu dosyayı tamamen sistemden silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-2.5 text-red-500/40 hover:text-red-500 hover:bg-red-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-emerald-500/10 overflow-hidden shadow-[0_30px_60px_rgba(0,0,0,0.4)]">
          <div className="p-8 lg:p-12 border-b border-emerald-500/10 bg-emerald-950/20 relative overflow-hidden">
            <div className="absolute -right-20 -top-20 w-64 h-64 bg-emerald-500/5 rounded-full blur-[80px]"></div>
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-3">
                  <h2 className="text-2xl lg:text-4xl font-black text-white neon-text uppercase leading-tight tracking-tighter">
                    {isEditing ? (
                      <input className="gradient-neon-input outline-none px-4 py-2 rounded-2xl w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} />
                    ) : transaction.productSetName}
                  </h2>
                  <span className={`px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                    {transaction.status}
                  </span>
                </div>
                <p className="text-[11px] text-emerald-500 font-bold uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • TALEP EDEN: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-emerald-600 font-black uppercase tracking-[0.2em] mb-1">DOSYA TOPLAM BEDELİ</p>
                <h3 className="text-4xl lg:text-6xl font-black text-white neon-text drop-shadow-[0_0_15px_rgba(16,185,129,0.2)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-8 lg:p-12 space-y-12">
            {/* Maliyet & Micro Kartı */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="p-8 bg-emerald-950/30 rounded-[32px] border border-emerald-500/10 space-y-6 shadow-inner relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><Archive size={80} /></div>
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> Maliyet Analizi
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Set / Paket Adedi:</span>
                            <span className="text-white font-black">{transaction.packageQuantity || 0}</span>
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Paket Birim Fiyat:</span>
                            <span className="text-white font-black">₺{(transaction.packageUnitPriceTl || 0).toLocaleString('tr-TR')}</span>
                        </div>
                        <div className="flex justify-between items-center text-sm pt-4 border-t border-emerald-500/10">
                            <span className="text-emerald-800 uppercase font-black tracking-tight text-xs">Tekil Birim Fiyat:</span>
                            <span className="text-white font-black">₺{(transaction.unitPriceTl || 0).toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>

                <div className="p-8 bg-slate-900/40 rounded-[32px] border border-emerald-500/10 flex flex-col justify-center space-y-4 shadow-inner">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> Micro ERP Kodu</h4>
                    <div className="flex items-center justify-between bg-black/40 p-5 rounded-2xl border border-emerald-500/10 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-emerald-300 tracking-wider">{transaction.microCode || 'TANIMSİZ'}</span>
                        <div className="text-emerald-500 group-hover:text-white transition-all">
                            {copied ? <Check size={20} className="text-emerald-400" /> : <Copy size={20} />}
                        </div>
                    </div>
                    {copied && <p className="text-[9px] text-emerald-500 font-black uppercase text-center animate-bounce">KOD KOPYALANDI!</p>}
                </div>
            </div>

            {/* Onay Akış Süreci - Geliştirilmiş Tasarım */}
            <div className="space-y-8">
                <div className="flex items-center justify-between px-2">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <ShieldCheck size={18} className="mr-3" /> Dijital Onay Zinciri
                    </h4>
                    <span className="text-[9px] text-emerald-900 font-black uppercase tracking-widest">Tüm adımlar zorunludur</span>
                </div>

                <div className="relative pl-12 lg:pl-16 space-y-10">
                    <div className="absolute left-6 lg:left-8 top-4 bottom-4 w-0.5 bg-emerald-500/10"></div>

                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[32px] lg:-left-[44px] top-1.5 w-9 h-9 lg:w-11 lg:h-11 rounded-full flex items-center justify-center border-2 z-10 transition-all duration-700 ${
                                flow.status === 'Approved' ? 'bg-emerald-500 border-emerald-500 text-white shadow-[0_0_25px_rgba(16,185,129,0.4)]' :
                                flow.status === 'Rejected' ? 'bg-red-500 border-red-500 text-white shadow-[0_0_25px_rgba(239,68,68,0.4)]' :
                                'bg-indigo-950 border-emerald-500/20 text-emerald-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={18} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={18} /> : 
                                 <span className="text-xs font-black">{i + 1}</span>}
                            </div>

                            <div className={`p-6 lg:p-8 rounded-[36px] border transition-all duration-500 group relative ${
                                flow.status === 'Approved' ? 'bg-emerald-500/5 border-emerald-500/15' : 
                                flow.status === 'Rejected' ? 'bg-red-500/5 border-red-500/15' : 
                                'bg-emerald-950/10 border-emerald-500/5'
                            }`}>
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                    <div className="space-y-3 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                        <div className="flex items-center space-x-4">
                                            <h5 className="font-black text-white uppercase tracking-tight text-base group-hover:text-emerald-400 transition-colors">{flow.role}</h5>
                                            <span className={`px-2.5 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-colors ${flowStatusColors[flow.status]}`}>
                                                {flow.status === 'Approved' ? 'ONAYLANDI' : flow.status === 'Rejected' ? 'REDDEDİLDİ' : 'İŞLEM BEKLİYOR'}
                                            </span>
                                        </div>

                                        <div className="flex flex-wrap gap-x-8 gap-y-2">
                                            <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                <UserCheck size={16} className="text-emerald-600" />
                                                <span className="tracking-tight">{flow.approverName || 'Yetkili Atanmadı'}</span>
                                            </div>
                                            {flow.date && (
                                                <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                    <CalendarDays size={16} className="text-emerald-600" />
                                                    <span className="tracking-tight">{flow.date}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex items-center space-x-4">
                                        {flow.proofUrl ? (
                                            <div 
                                                onClick={() => setSelectedImage(flow.proofUrl!)}
                                                className="w-14 h-14 rounded-2xl overflow-hidden cursor-pointer border-2 border-emerald-500/20 hover:border-emerald-400 transition-all shadow-xl group-hover:scale-110 active:scale-95"
                                            >
                                                <img src={flow.proofUrl} className="w-full h-full object-cover" alt="İmza/Kanıt" />
                                            </div>
                                        ) : flow.status === 'Pending' ? (
                                            <div className="flex flex-col space-y-3 w-full md:w-auto">
                                                <input 
                                                    type="text" 
                                                    placeholder="Karar notu yazın..."
                                                    value={decisionNote}
                                                    onChange={(e) => setDecisionNote(e.target.value)}
                                                    className="px-4 py-2 bg-black/20 border border-emerald-500/10 rounded-xl text-xs text-white outline-none focus:border-emerald-500/40 transition-all"
                                                />
                                                <div className="flex space-x-2">
                                                    <button 
                                                        onClick={() => fileInputRefs.current[flow.role]?.click()}
                                                        className="flex-1 md:flex-none p-3 bg-emerald-500/10 text-emerald-400 rounded-xl hover:bg-emerald-500 hover:text-white transition-all border border-emerald-500/20 flex items-center justify-center space-x-2"
                                                        title="Belge Yükle ve Onayla"
                                                    >
                                                        <Camera size={18} />
                                                        <span className="text-[10px] font-black uppercase">ONAY BELGESİ YÜKLE</span>
                                                    </button>
                                                    <button 
                                                        onClick={() => handleReject(flow.role)}
                                                        className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all border border-red-500/20"
                                                        title="Reddet"
                                                    >
                                                        <XCircle size={18} />
                                                    </button>
                                                </div>
                                                <input 
                                                    type="file" 
                                                    accept="image/*" 
                                                    className="hidden" 
                                                    ref={el => fileInputRefs.current[flow.role] = el} 
                                                    onChange={(e) => handleSignatureProof(flow.role, e)} 
                                                />
                                            </div>
                                        ) : null}
                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-emerald-900 hover:text-emerald-400 bg-emerald-500/5 rounded-xl transition-all">
                                            <Info size={20} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Gerekçe Metni */}
            <div className="space-y-4">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest px-2">TALEP GEREKÇESİ VE AÇIKLAMA</h4>
                <div className="p-8 lg:p-10 bg-emerald-950/40 rounded-[32px] border border-emerald-500/10 text-emerald-100 text-sm lg:text-base leading-relaxed italic relative">
                    <div className="absolute top-4 right-8 opacity-10"><MessageSquare size={40} /></div>
                    "{transaction.justification}"
                    <div className="mt-4 pt-4 border-t border-emerald-500/5 text-[10px] text-emerald-700 font-black uppercase tracking-widest">
                        DOSYA AÇIKLAMASI: {transaction.description || 'Ek açıklama belirtilmemiş.'}
                    </div>
                </div>
            </div>
          </div>

          {/* Onay Butonları - Sabit Alt Bar Etkisi */}
          <div className="bg-emerald-950/40 p-10 lg:p-12 border-t border-emerald-500/10 flex flex-col sm:flex-row items-center justify-center gap-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved' || !transaction.approvalFlow.every(f => f.status === 'Approved')}
              className={`w-full sm:w-auto px-12 py-5 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 shadow-[0_20px_50px_rgba(0,0,0,0.3)] active:scale-95 transition-all ${
                transaction.approvalFlow.every(f => f.status === 'Approved') ? 'opacity-100 shadow-[0_0_30px_rgba(16,185,129,0.4)]' : 'opacity-20 cursor-not-allowed grayscale'
              }`}
            >
              <Archive size={22} />
              <span>ARŞİVE GÖNDER (ONAYLA)</span>
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="w-full sm:w-auto px-12 py-5 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 hover:bg-red-600/20 transition-all active:scale-95"
            >
              <XCircle size={22} />
              <span>DOSYAYI İPTAL ET</span>
            </button>
          </div>
        </div>
      </div>

      {/* Sağ Panel - Geçmiş Günlüğü (Desktop Only Fixed Position Like) */}
      <div className="w-full lg:w-96 space-y-8">
        <div className="glass-panel rounded-[32px] border border-emerald-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-6 border-b border-emerald-500/10 bg-emerald-950/40 flex items-center space-x-4">
            <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><History size={20} /></div>
            <div>
                <h3 className="font-black text-[11px] uppercase tracking-widest text-white">SİSTEM LOGLARI</h3>
                <p className="text-[8px] font-bold text-emerald-700 uppercase tracking-widest">Kayıt Tarihçesi</p>
            </div>
          </div>
          <div className="p-6 space-y-6 max-h-[750px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[11px] relative pl-6 border-l border-emerald-500/10 pb-6 last:pb-0 group">
                <div className="absolute left-[-5px] top-0 w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)] transition-all group-hover:scale-125"></div>
                <div className="flex items-center justify-between mb-2">
                  <span className="font-black text-emerald-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-slate-600 font-bold bg-black/20 px-2 py-0.5 rounded-md font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR', {hour:'2-digit', minute:'2-digit'})}</span>
                </div>
                <div className="text-slate-400 leading-relaxed font-medium">
                   <span className="font-black text-white bg-emerald-500/5 px-1.5 py-0.5 rounded border border-emerald-500/10 mr-1">{log.action}:</span> {log.details}
                </div>
                <div className="mt-2 text-[9px] text-slate-700 font-bold uppercase tracking-widest">{new Date(log.timestamp).toLocaleDateString('tr-TR')}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const flowStatusColors = {
    'Pending': 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    'Approved': 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    'Rejected': 'bg-red-500/20 text-red-400 border-red-500/30'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: new Date().toLocaleDateString('tr-TR'),
            decisionNote: decisionNote || 'İşlem onaylandı.'
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Onay Güncelleme',
            details: `${role} onayı ve görsel kanıtı başarıyla kaydedildi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReject = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Rejected' as const, 
        date: new Date().toLocaleDateString('tr-TR'),
        decisionNote: decisionNote || 'Talep uygun görülmedi.'
      } : f
    );
    onUpdate(transaction.id, { 
      status: 'Rejected',
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Ret Kararı',
        details: `${role} tarafından işlem reddedildi: ${decisionNote}`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24 px-1 lg:px-0">

      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-emerald-400 bg-emerald-500/10 rounded-full transition-all">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-[0_0_100px_rgba(16,185,129,0.3)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 rounded-[40px] border border-emerald-500/20 shadow-2xl relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-2 text-emerald-400 hover:bg-emerald-500/10 rounded-xl transition-all">
              <X size={24} />
            </button>
            <div className="flex items-center space-x-4 mb-8">
                <div className="w-16 h-16 neon-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <UserCheck size={32} />
                </div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-emerald-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-6">
                <div className="bg-emerald-950/20 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Tarihi & Durum</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekliyor...'}</span>
                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border ${flowStatusColors[transaction.approvalFlow[selectedFlowDetail].status]}`}>
                            {transaction.approvalFlow[selectedFlowDetail].status}
                        </span>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Notu</p>
                    <p className="text-xs text-slate-300 italic leading-relaxed">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'Henüz not eklenmedi.'}"
                    </p>
                </div>

                {transaction.approvalFlow[selectedFlowDetail].proofUrl && (
                    <div>
                        <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-3">İmzalı Belge / Kanıt</p>
                        <div 
                          onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}
                          className="w-full h-48 rounded-[30px] overflow-hidden border border-emerald-500/20 cursor-pointer group relative shadow-inner"
                        >
                            <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Maximize2 className="text-white" size={24} />
                            </div>
                        </div>
                    </div>
                )}
            </div>
          </div>
        </div>
      )}

      {/* Ana Bilgi Paneli */}
      <div className="flex-1 space-y-6 lg:space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-2 text-emerald-400 font-bold text-[11px] uppercase tracking-widest group">
            <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> <span>GERİ DÖN</span>
          </button>

          <div className="flex items-center space-x-2">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-5 py-2 glass-panel rounded-xl text-[10px] font-black text-emerald-400 uppercase tracking-widest border-emerald-500/20 hover:border-emerald-500/40 transition-all">DÜZENLE</button>
            ) : (
              <button onClick={handleSave} className="px-6 py-2 neon-gradient text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Bu dosyayı tamamen sistemden silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-2.5 text-red-500/40 hover:text-red-500 hover:bg-red-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-emerald-500/10 overflow-hidden shadow-[0_30px_60px_rgba(0,0,0,0.4)]">
          <div className="p-8 lg:p-12 border-b border-emerald-500/10 bg-emerald-950/20 relative overflow-hidden">
            <div className="absolute -right-20 -top-20 w-64 h-64 bg-emerald-500/5 rounded-full blur-[80px]"></div>
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-3">
                  <h2 className="text-2xl lg:text-4xl font-black text-white neon-text uppercase leading-tight tracking-tighter">
                    {isEditing ? (
                      <input className="gradient-neon-input outline-none px-4 py-2 rounded-2xl w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} />
                    ) : transaction.productSetName}
                  </h2>
                  <span className={`px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                    {transaction.status}
                  </span>
                </div>
                <p className="text-[11px] text-emerald-500 font-bold uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • TALEP EDEN: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-emerald-600 font-black uppercase tracking-[0.2em] mb-1">DOSYA TOPLAM BEDELİ</p>
                <h3 className="text-4xl lg:text-6xl font-black text-white neon-text drop-shadow-[0_0_15px_rgba(16,185,129,0.2)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-8 lg:p-12 space-y-12">
            {/* Maliyet & Micro Kartı */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="p-8 bg-emerald-950/30 rounded-[32px] border border-emerald-500/10 space-y-6 shadow-inner relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><Archive size={80} /></div>
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> Maliyet Analizi
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Set / Paket Adedi:</span>
                            <span className="text-white font-black">{transaction.packageQuantity || 0}</span>
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Paket Birim Fiyat:</span>
                            <span className="text-white font-black">₺{(transaction.packageUnitPriceTl || 0).toLocaleString('tr-TR')}</span>
                        </div>
                        <div className="flex justify-between items-center text-sm pt-4 border-t border-emerald-500/10">
                            <span className="text-emerald-800 uppercase font-black tracking-tight text-xs">Tekil Birim Fiyat:</span>
                            <span className="text-white font-black">₺{(transaction.unitPriceTl || 0).toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>

                <div className="p-8 bg-slate-900/40 rounded-[32px] border border-emerald-500/10 flex flex-col justify-center space-y-4 shadow-inner">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> Micro ERP Kodu</h4>
                    <div className="flex items-center justify-between bg-black/40 p-5 rounded-2xl border border-emerald-500/10 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-emerald-300 tracking-wider">{transaction.microCode || 'TANIMSİZ'}</span>
                        <div className="text-emerald-500 group-hover:text-white transition-all">
                            {copied ? <Check size={20} className="text-emerald-400" /> : <Copy size={20} />}
                        </div>
                    </div>
                    {copied && <p className="text-[9px] text-emerald-500 font-black uppercase text-center animate-bounce">KOD KOPYALANDI!</p>}
                </div>
            </div>

            {/* Onay Akış Süreci - Geliştirilmiş Tasarım */}
            <div className="space-y-8">
                <div className="flex items-center justify-between px-2">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <ShieldCheck size={18} className="mr-3" /> Dijital Onay Zinciri
                    </h4>
                    <span className="text-[9px] text-emerald-900 font-black uppercase tracking-widest">Tüm adımlar zorunludur</span>
                </div>

                <div className="relative pl-12 lg:pl-16 space-y-10">
                    <div className="absolute left-6 lg:left-8 top-4 bottom-4 w-0.5 bg-emerald-500/10"></div>

                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[32px] lg:-left-[44px] top-1.5 w-9 h-9 lg:w-11 lg:h-11 rounded-full flex items-center justify-center border-2 z-10 transition-all duration-700 ${
                                flow.status === 'Approved' ? 'bg-emerald-500 border-emerald-500 text-white shadow-[0_0_25px_rgba(16,185,129,0.4)]' :
                                flow.status === 'Rejected' ? 'bg-red-500 border-red-500 text-white shadow-[0_0_25px_rgba(239,68,68,0.4)]' :
                                'bg-indigo-950 border-emerald-500/20 text-emerald-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={18} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={18} /> : 
                                 <span className="text-xs font-black">{i + 1}</span>}
                            </div>

                            <div className={`p-6 lg:p-8 rounded-[36px] border transition-all duration-500 group relative ${
                                flow.status === 'Approved' ? 'bg-emerald-500/5 border-emerald-500/15' : 
                                flow.status === 'Rejected' ? 'bg-red-500/5 border-red-500/15' : 
                                'bg-emerald-950/10 border-emerald-500/5'
                            }`}>
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                    <div className="space-y-3 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                        <div className="flex items-center space-x-4">
                                            <h5 className="font-black text-white uppercase tracking-tight text-base group-hover:text-emerald-400 transition-colors">{flow.role}</h5>
                                            <span className={`px-2.5 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-colors ${flowStatusColors[flow.status]}`}>
                                                {flow.status === 'Approved' ? 'ONAYLANDI' : flow.status === 'Rejected' ? 'REDDEDİLDİ' : 'İŞLEM BEKLİYOR'}
                                            </span>
                                        </div>

                                        <div className="flex flex-wrap gap-x-8 gap-y-2">
                                            <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                <UserCheck size={16} className="text-emerald-600" />
                                                <span className="tracking-tight">{flow.approverName || 'Yetkili Atanmadı'}</span>
                                            </div>
                                            {flow.date && (
                                                <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                    <CalendarDays size={16} className="text-emerald-600" />
                                                    <span className="tracking-tight">{flow.date}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex items-center space-x-4">
                                        {flow.proofUrl ? (
                                            <div 
                                                onClick={() => setSelectedImage(flow.proofUrl!)}
                                                className="w-14 h-14 rounded-2xl overflow-hidden cursor-pointer border-2 border-emerald-500/20 hover:border-emerald-400 transition-all shadow-xl group-hover:scale-110 active:scale-95"
                                            >
                                                <img src={flow.proofUrl} className="w-full h-full object-cover" alt="İmza/Kanıt" />
                                            </div>
                                        ) : flow.status === 'Pending' ? (
                                            <div className="flex flex-col space-y-3 w-full md:w-auto">
                                                <input 
                                                    type="text" 
                                                    placeholder="Karar notu yazın..."
                                                    value={decisionNote}
                                                    onChange={(e) => setDecisionNote(e.target.value)}
                                                    className="px-4 py-2 bg-black/20 border border-emerald-500/10 rounded-xl text-xs text-white outline-none focus:border-emerald-500/40 transition-all"
                                                />
                                                <div className="flex space-x-2">
                                                    <button 
                                                        onClick={() => fileInputRefs.current[flow.role]?.click()}
                                                        className="flex-1 md:flex-none p-3 bg-emerald-500/10 text-emerald-400 rounded-xl hover:bg-emerald-500 hover:text-white transition-all border border-emerald-500/20 flex items-center justify-center space-x-2"
                                                        title="Belge Yükle ve Onayla"
                                                    >
                                                        <Camera size={18} />
                                                        <span className="text-[10px] font-black uppercase">ONAY BELGESİ YÜKLE</span>
                                                    </button>
                                                    <button 
                                                        onClick={() => handleReject(flow.role)}
                                                        className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all border border-red-500/20"
                                                        title="Reddet"
                                                    >
                                                        <XCircle size={18} />
                                                    </button>
                                                </div>
                                                <input 
                                                    type="file" 
                                                    accept="image/*" 
                                                    className="hidden" 
                                                    ref={el => fileInputRefs.current[flow.role] = el} 
                                                    onChange={(e) => handleSignatureProof(flow.role, e)} 
                                                />
                                            </div>
                                        ) : null}
                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-emerald-900 hover:text-emerald-400 bg-emerald-500/5 rounded-xl transition-all">
                                            <Info size={20} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Gerekçe Metni */}
            <div className="space-y-4">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest px-2">TALEP GEREKÇESİ VE AÇIKLAMA</h4>
                <div className="p-8 lg:p-10 bg-emerald-950/40 rounded-[32px] border border-emerald-500/10 text-emerald-100 text-sm lg:text-base leading-relaxed italic relative">
                    <div className="absolute top-4 right-8 opacity-10"><MessageSquare size={40} /></div>
                    "{transaction.justification}"
                    <div className="mt-4 pt-4 border-t border-emerald-500/5 text-[10px] text-emerald-700 font-black uppercase tracking-widest">
                        DOSYA AÇIKLAMASI: {transaction.description || 'Ek açıklama belirtilmemiş.'}
                    </div>
                </div>
            </div>
          </div>

          {/* Onay Butonları - Sabit Alt Bar Etkisi */}
          <div className="bg-emerald-950/40 p-10 lg:p-12 border-t border-emerald-500/10 flex flex-col sm:flex-row items-center justify-center gap-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved' || !transaction.approvalFlow.every(f => f.status === 'Approved')}
              className={`w-full sm:w-auto px-12 py-5 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 shadow-[0_20px_50px_rgba(0,0,0,0.3)] active:scale-95 transition-all ${
                transaction.approvalFlow.every(f => f.status === 'Approved') ? 'opacity-100 shadow-[0_0_30px_rgba(16,185,129,0.4)]' : 'opacity-20 cursor-not-allowed grayscale'
              }`}
            >
              <Archive size={22} />
              <span>ARŞİVE GÖNDER (ONAYLA)</span>
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="w-full sm:w-auto px-12 py-5 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 hover:bg-red-600/20 transition-all active:scale-95"
            >
              <XCircle size={22} />
              <span>DOSYAYI İPTAL ET</span>
            </button>
          </div>
        </div>
      </div>

      {/* Sağ Panel - Geçmiş Günlüğü (Desktop Only Fixed Position Like) */}
      <div className="w-full lg:w-96 space-y-8">
        <div className="glass-panel rounded-[32px] border border-emerald-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-6 border-b border-emerald-500/10 bg-emerald-950/40 flex items-center space-x-4">
            <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><History size={20} /></div>
            <div>
                <h3 className="font-black text-[11px] uppercase tracking-widest text-white">SİSTEM LOGLARI</h3>
                <p className="text-[8px] font-bold text-emerald-700 uppercase tracking-widest">Kayıt Tarihçesi</p>
            </div>
          </div>
          <div className="p-6 space-y-6 max-h-[750px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[11px] relative pl-6 border-l border-emerald-500/10 pb-6 last:pb-0 group">
                <div className="absolute left-[-5px] top-0 w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)] transition-all group-hover:scale-125"></div>
                <div className="flex items-center justify-between mb-2">
                  <span className="font-black text-emerald-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-slate-600 font-bold bg-black/20 px-2 py-0.5 rounded-md font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR', {hour:'2-digit', minute:'2-digit'})}</span>
                </div>
                <div className="text-slate-400 leading-relaxed font-medium">
                   <span className="font-black text-white bg-emerald-500/5 px-1.5 py-0.5 rounded border border-emerald-500/10 mr-1">{log.action}:</span> {log.details}
                </div>
                <div className="mt-2 text-[9px] text-slate-700 font-bold uppercase tracking-widest">{new Date(log.timestamp).toLocaleDateString('tr-TR')}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  // ESC tuşu ile geri dönme desteği
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack]);

  // Düzenleme sırasında toplam bedeli anlık güncelle
  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const flowStatusColors = {
    'Pending': 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    'Approved': 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    'Rejected': 'bg-red-500/20 text-red-400 border-red-500/30'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Dijital onay verildi (Hızlı Onay).'
      } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Hızlı Onay',
        details: `${role} adımı belgesiz olarak onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: new Date().toLocaleString('tr-TR'),
            decisionNote: decisionNote || 'Belge eşliğinde onaylandı.'
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belgeli Onay',
            details: `${role} onayı ve görsel kanıtı kaydedildi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReject = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Rejected' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Talep uygun görülmedi.'
      } : f
    );
    onUpdate(transaction.id, { 
      status: 'Rejected',
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Ret Kararı',
        details: `${role} tarafından işlem reddedildi: ${decisionNote}`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24 px-1 lg:px-0">

      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-emerald-400 bg-emerald-500/10 rounded-full transition-all">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-[0_0_100px_rgba(16,185,129,0.3)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 rounded-[40px] border border-emerald-500/20 shadow-2xl relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-2 text-emerald-400 hover:bg-emerald-500/10 rounded-xl transition-all">
              <X size={24} />
            </button>
            <div className="flex items-center space-x-4 mb-8">
                <div className="w-16 h-16 neon-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <UserCheck size={32} />
                </div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-emerald-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-6">
                <div className="bg-emerald-950/20 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Zamanı & Durum</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekliyor...'}</span>
                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border ${flowStatusColors[transaction.approvalFlow[selectedFlowDetail].status]}`}>
                            {transaction.approvalFlow[selectedFlowDetail].status}
                        </span>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Karar Notu</p>
                    <p className="text-xs text-slate-300 italic leading-relaxed">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'Henüz not eklenmedi.'}"
                    </p>
                </div>

                {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div>
                        <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-3">İmzalı Belge / Kanıt</p>
                        <div 
                          onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}
                          className="w-full h-48 rounded-[30px] overflow-hidden border border-emerald-500/20 cursor-pointer group relative shadow-inner"
                        >
                            <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Maximize2 className="text-white" size={24} />
                            </div>
                        </div>
                    </div>
                ) : (
                  <div className="flex items-center space-x-3 text-emerald-500/40 py-4 justify-center border border-dashed border-emerald-500/20 rounded-2xl">
                    <Zap size={16} />
                    <span className="text-[10px] font-black uppercase tracking-widest">Belgesiz Dijital Onay</span>
                  </div>
                )}
            </div>
          </div>
        </div>
      )}

      {/* Ana Bilgi Paneli */}
      <div className="flex-1 space-y-6 lg:space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-2 text-emerald-400 font-bold text-[11px] uppercase tracking-widest group">
            <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> <span>ARŞİVE DÖN <span className="text-[8px] opacity-40 ml-1">(ESC)</span></span>
          </button>

          <div className="flex items-center space-x-2">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-5 py-2 glass-panel rounded-xl text-[10px] font-black text-emerald-400 uppercase tracking-widest border-emerald-500/20 hover:border-emerald-500/40 transition-all">DÜZENLE</button>
            ) : (
              <button onClick={handleSave} className="px-6 py-2 neon-gradient text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">DEĞİŞİKLİKLERİ KAYDET</button>
            )}
            <button onClick={() => window.confirm('Bu dosyayı tamamen sistemden silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-2.5 text-red-500/40 hover:text-red-500 hover:bg-red-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-emerald-500/10 overflow-hidden shadow-[0_30px_60px_rgba(0,0,0,0.4)]">
          <div className="p-8 lg:p-12 border-b border-emerald-500/10 bg-emerald-950/20 relative overflow-hidden">
            <div className="absolute -right-20 -top-20 w-64 h-64 bg-emerald-500/5 rounded-full blur-[80px]"></div>
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-3">
                  <h2 className="text-2xl lg:text-4xl font-black text-white neon-text uppercase leading-tight tracking-tighter">
                    {isEditing ? (
                      <input className="gradient-neon-input outline-none px-4 py-2 rounded-2xl w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} />
                    ) : transaction.productSetName}
                  </h2>
                  <span className={`px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                    {transaction.status}
                  </span>
                </div>
                <p className="text-[11px] text-emerald-500 font-bold uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • TALEP EDEN: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-emerald-600 font-black uppercase tracking-[0.2em] mb-1">GÜNCEL TOPLAM BEDEL</p>
                <h3 className="text-4xl lg:text-6xl font-black text-white neon-text drop-shadow-[0_0_15px_rgba(16,185,129,0.2)]">
                  ₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}
                </h3>
              </div>
            </div>
          </div>

          <div className="p-8 lg:p-12 space-y-12">
            {/* Maliyet & Micro Kartı */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="p-8 bg-emerald-950/30 rounded-[32px] border border-emerald-500/10 space-y-6 shadow-inner relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-5"><Archive size={80} /></div>
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> Maliyet Analizi
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Set / Paket Adedi:</span>
                            {isEditing ? (
                              <input type="number" className="w-20 bg-black/40 text-white rounded-lg px-2 py-1 outline-none text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} />
                            ) : <span className="text-white font-black">{transaction.packageQuantity || 0}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Paket Birim Fiyat:</span>
                            {isEditing ? (
                              <input type="number" className="w-24 bg-black/40 text-white rounded-lg px-2 py-1 outline-none text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} />
                            ) : <span className="text-white font-black">₺{(transaction.packageUnitPriceTl || 0).toLocaleString('tr-TR')}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm pt-4 border-t border-emerald-500/10">
                            <span className="text-emerald-800 uppercase font-black tracking-tight text-xs">Tekil Birim Fiyat:</span>
                            <span className="text-white font-black">₺{(transaction.unitPriceTl || 0).toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>

                <div className="p-8 bg-slate-900/40 rounded-[32px] border border-emerald-500/10 flex flex-col justify-center space-y-4 shadow-inner">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> Micro ERP Kodu</h4>
                    <div className="flex items-center justify-between bg-black/40 p-5 rounded-2xl border border-emerald-500/10 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-emerald-300 tracking-wider">
                          {isEditing ? (
                            <input className="bg-transparent outline-none w-full" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} />
                          ) : transaction.microCode || 'TANIMSIZ'}
                        </span>
                        {!isEditing && (
                          <div className="text-emerald-500 group-hover:text-white transition-all">
                              {copied ? <Check size={20} className="text-emerald-400" /> : <Copy size={20} />}
                          </div>
                        )}
                    </div>
                    {copied && <p className="text-[9px] text-emerald-500 font-black uppercase text-center animate-bounce">KOD KOPYALANDI!</p>}
                </div>
            </div>

            {/* Onay Akış Süreci */}
            <div className="space-y-8">
                <div className="flex items-center justify-between px-2">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <ShieldCheck size={18} className="mr-3" /> Dijital Onay Zinciri
                    </h4>
                    <span className="text-[9px] text-emerald-900 font-black uppercase tracking-widest">Adımları sırayla veya hızlıca tamamlayın</span>
                </div>

                <div className="relative pl-12 lg:pl-16 space-y-10">
                    <div className="absolute left-6 lg:left-8 top-4 bottom-4 w-0.5 bg-emerald-500/10"></div>

                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[32px] lg:-left-[44px] top-1.5 w-9 h-9 lg:w-11 lg:h-11 rounded-full flex items-center justify-center border-2 z-10 transition-all duration-700 ${
                                flow.status === 'Approved' ? 'bg-emerald-500 border-emerald-500 text-white shadow-[0_0_25px_rgba(16,185,129,0.4)]' :
                                flow.status === 'Rejected' ? 'bg-red-500 border-red-500 text-white shadow-[0_0_25px_rgba(239,68,68,0.4)]' :
                                'bg-indigo-950 border-emerald-500/20 text-emerald-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={18} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={18} /> : 
                                 <span className="text-xs font-black">{i + 1}</span>}
                            </div>

                            <div className={`p-6 lg:p-8 rounded-[36px] border transition-all duration-500 group relative ${
                                flow.status === 'Approved' ? 'bg-emerald-500/5 border-emerald-500/15' : 
                                flow.status === 'Rejected' ? 'bg-red-500/5 border-red-500/15' : 
                                'bg-emerald-950/10 border-emerald-500/5'
                            }`}>
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                    <div className="space-y-3 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                        <div className="flex items-center space-x-4">
                                            <h5 className="font-black text-white uppercase tracking-tight text-base group-hover:text-emerald-400 transition-colors">{flow.role}</h5>
                                            <span className={`px-2.5 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-colors ${flowStatusColors[flow.status]}`}>
                                                {flow.status === 'Approved' ? 'ONAYLANDI' : flow.status === 'Rejected' ? 'REDDEDİLDİ' : 'BEKLİYOR'}
                                            </span>
                                        </div>

                                        <div className="flex flex-wrap gap-x-8 gap-y-2">
                                            <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                <UserCheck size={16} className="text-emerald-600" />
                                                <span className="tracking-tight">{flow.approverName || 'Yetkili Atanmadı'}</span>
                                            </div>
                                            {flow.date && (
                                                <div className="flex items-center space-x-2.5 text-[11px] text-slate-400 font-bold uppercase">
                                                    <CalendarDays size={16} className="text-emerald-600" />
                                                    <span className="tracking-tight">{flow.date}</span>
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex items-center space-x-4">
                                        {flow.status === 'Pending' ? (
                                            <div className="flex flex-col space-y-3 w-full md:w-auto">
                                                <input 
                                                    type="text" 
                                                    placeholder="Karar notu (Opsiyonel)"
                                                    value={decisionNote}
                                                    onChange={(e) => setDecisionNote(e.target.value)}
                                                    className="px-4 py-2 bg-black/20 border border-emerald-500/10 rounded-xl text-xs text-white outline-none focus:border-emerald-500/40 transition-all"
                                                />
                                                <div className="flex flex-wrap gap-2">
                                                    <button 
                                                        onClick={() => handleQuickApprove(flow.role)}
                                                        className="flex-1 md:flex-none px-4 py-3 bg-indigo-500/10 text-indigo-400 rounded-xl hover:bg-indigo-500 hover:text-white transition-all border border-indigo-500/20 flex items-center justify-center space-x-2"
                                                    >
                                                        <Zap size={16} />
                                                        <span className="text-[10px] font-black uppercase">Hızlı Onay</span>
                                                    </button>
                                                    <button 
                                                        onClick={() => fileInputRefs.current[flow.role]?.click()}
                                                        className="flex-1 md:flex-none p-3 bg-emerald-500/10 text-emerald-400 rounded-xl hover:bg-emerald-500 hover:text-white transition-all border border-emerald-500/20 flex items-center justify-center space-x-2"
                                                        title="Belge Yükle ve Onayla"
                                                    >
                                                        <Camera size={18} />
                                                        <span className="text-[10px] font-black uppercase">Belge İle</span>
                                                    </button>
                                                    <button 
                                                        onClick={() => handleReject(flow.role)}
                                                        className="p-3 bg-red-500/10 text-red-500 rounded-xl hover:bg-red-500 hover:text-white transition-all border border-red-500/20"
                                                        title="Reddet"
                                                    >
                                                        <XCircle size={18} />
                                                    </button>
                                                </div>
                                                <input 
                                                    type="file" 
                                                    accept="image/*" 
                                                    className="hidden" 
                                                    ref={el => fileInputRefs.current[flow.role] = el} 
                                                    onChange={(e) => handleSignatureProof(flow.role, e)} 
                                                />
                                            </div>
                                        ) : flow.proofUrl ? (
                                            <div 
                                                onClick={() => setSelectedImage(flow.proofUrl!)}
                                                className="w-14 h-14 rounded-2xl overflow-hidden cursor-pointer border-2 border-emerald-500/20 hover:border-emerald-400 transition-all shadow-xl group-hover:scale-110 active:scale-95"
                                            >
                                                <img src={flow.proofUrl} className="w-full h-full object-cover" alt="İmza/Kanıt" />
                                            </div>
                                        ) : (
                                          <div className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl border border-emerald-500/20">
                                            <Zap size={18} />
                                          </div>
                                        )}
                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-emerald-900 hover:text-emerald-400 bg-emerald-500/5 rounded-xl transition-all">
                                            <Info size={20} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Gerekçe Metni */}
            <div className="space-y-4">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest px-2">TALEP GEREKÇESİ VE AÇIKLAMA</h4>
                <div className="p-8 lg:p-10 bg-emerald-950/40 rounded-[32px] border border-emerald-500/10 text-emerald-100 text-sm lg:text-base leading-relaxed italic relative">
                    <div className="absolute top-4 right-8 opacity-10"><MessageSquare size={40} /></div>
                    "{isEditing ? (
                      <textarea className="w-full bg-transparent outline-none border-b border-emerald-500/20 py-2" rows={3} value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} />
                    ) : transaction.justification}"
                    <div className="mt-4 pt-4 border-t border-emerald-500/5 text-[10px] text-emerald-700 font-black uppercase tracking-widest">
                        DOSYA AÇIKLAMASI: {isEditing ? (
                          <input className="bg-transparent outline-none border-b border-emerald-500/20 w-full" value={editForm.description} onChange={e => setEditForm({...editForm, description: e.target.value})} />
                        ) : transaction.description || 'Ek açıklama belirtilmemiş.'}
                    </div>
                </div>
            </div>
          </div>

          {/* Onay Butonları */}
          <div className="bg-emerald-950/40 p-10 lg:p-12 border-t border-emerald-500/10 flex flex-col sm:flex-row items-center justify-center gap-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved' || !transaction.approvalFlow.every(f => f.status === 'Approved')}
              className={`w-full sm:w-auto px-12 py-5 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 shadow-[0_20px_50px_rgba(0,0,0,0.3)] active:scale-95 transition-all ${
                transaction.approvalFlow.every(f => f.status === 'Approved') ? 'opacity-100 shadow-[0_0_30px_rgba(16,185,129,0.4)]' : 'opacity-20 cursor-not-allowed grayscale'
              }`}
            >
              <Archive size={22} />
              <span>DOSYAYI TAMAMLA VE ARŞİVLE</span>
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="w-full sm:w-auto px-12 py-5 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-4 hover:bg-red-600/20 transition-all active:scale-95"
            >
              <XCircle size={22} />
              <span>SÜRECİ İPTAL ET</span>
            </button>
          </div>
        </div>
      </div>

      {/* Sağ Panel - Geçmiş Günlüğü */}
      <div className="w-full lg:w-96 space-y-8">
        <div className="glass-panel rounded-[32px] border border-emerald-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-6 border-b border-emerald-500/10 bg-emerald-950/40 flex items-center space-x-4">
            <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><History size={20} /></div>
            <div>
                <h3 className="font-black text-[11px] uppercase tracking-widest text-white">İŞLEM GEÇMİŞİ</h3>
                <p className="text-[8px] font-bold text-emerald-700 uppercase tracking-widest">Sistem Logları</p>
            </div>
          </div>
          <div className="p-6 space-y-6 max-h-[750px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[11px] relative pl-6 border-l border-emerald-500/10 pb-6 last:pb-0 group">
                <div className="absolute left-[-5px] top-0 w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)] transition-all group-hover:scale-125"></div>
                <div className="flex items-center justify-between mb-2">
                  <span className="font-black text-emerald-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-slate-600 font-bold bg-black/20 px-2 py-0.5 rounded-md font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <div className="text-slate-400 leading-relaxed font-medium">
                   <span className="font-black text-white bg-emerald-500/5 px-1.5 py-0.5 rounded border border-emerald-500/10 mr-1">{log.action}:</span> {log.details}
                </div>
                <div className="mt-2 text-[9px] text-slate-700 font-bold uppercase tracking-widest">{new Date(log.timestamp).toLocaleDateString('tr-TR')}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Plus, Trash2, Camera, Info, Sparkles, FileText, CheckCircle, X, Package } from 'lucide-react';
import { ExtraItem, Transaction } from '../types';
import { analyzeJustification } from '../services/geminiService';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    usageLocation: '',
    requesterName: 'Hasan Demir',
    packageQuantity: 1,
    packageUnitPriceTl: 0,
    quantity: 1,
    unitPriceTl: 0,
    justification: '',
    microCode: '',
    photoUrl: '',
    totalAmount: 0
  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Toplam Bedel Real-time Hesaplama
  useEffect(() => {
    const total = (formData.packageQuantity * formData.packageUnitPriceTl) + (formData.quantity * formData.unitPriceTl);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, formData.packageUnitPriceTl, formData.quantity, formData.unitPriceTl]);

  const inputClass = "w-full px-4 py-3 rounded-xl gradient-neon-input text-slate-200 outline-none transition-all placeholder:text-indigo-700/60 text-sm";

  const addExtraItem = () => {
    if (extraItems.length >= 4) return;
    setExtraItems([...extraItems, { id: Date.now().toString(), name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, field: keyof ExtraItem, value: string | number) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAiCheck = async () => {
    if (!formData.productSetName || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.productSetName, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Süreç Başlatıldı', details: 'Yeni dijital talep girişi yapıldı.' }]
    });
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
      <div className="flex items-center justify-between mb-6 lg:mb-10 px-2">
        <div>
          <h2 className="text-2xl lg:text-3xl font-black text-white neon-text tracking-tight uppercase">Yeni Talep Girişi</h2>
          <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mt-1">2025 Finansal Dönem Kaydı</p>
        </div>
        <div className="hidden lg:flex px-4 py-2 glass-panel rounded-full border border-indigo-500/30 items-center space-x-2 text-indigo-400 font-bold text-xs uppercase tracking-widest">
          <FileText size={14} />
          <span>Form No: {Math.floor(Math.random() * 10000)}</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 lg:space-y-8">
        {/* Temel Bilgiler */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Satın Alma Tanımı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
                onChange={e => setFormData({...formData, productSetName: e.target.value})}
                placeholder="Örn: Macbook Pro Ofis Paketi"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Tedarikçi Firma *</label>
              <input 
                required
                type="text" 
                value={formData.supplierName}
                onChange={e => setFormData({...formData, supplierName: e.target.value})}
                placeholder="Firma veya Şahıs Adı"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">İlgili Departman</label>
              <select 
                value={formData.department}
                onChange={e => setFormData({...formData, department: e.target.value})}
                className={inputClass}
              >
                {departments.map(d => <option key={d} value={d} className="bg-[#1e1b4b]">{d}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">ERP / Micro Kodu</label>
              <input 
                type="text" 
                value={formData.microCode}
                onChange={e => setFormData({...formData, microCode: e.target.value})}
                placeholder="ERP referansı (Varsa)"
                className={inputClass}
              />
            </div>
          </div>
        </div>

        {/* Maliyet Detayı - Dinamik Toplam */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5"><Package size={120} /></div>
          <div className="flex items-center space-x-2 mb-6">
            <Package size={18} className="text-indigo-400" />
            <h3 className="text-sm lg:text-base font-black text-white uppercase tracking-tight">Harcama ve Maliyet Detayı</h3>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 relative z-10">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Adet</label>
              <input 
                type="number" 
                value={formData.packageQuantity}
                onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Fiyat (TL)</label>
              <input 
                type="number" 
                value={formData.packageUnitPriceTl}
                onChange={e => setFormData({...formData, packageUnitPriceTl: parseFloat(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="col-span-2 bg-[#1e293b]/50 p-5 rounded-2xl border border-indigo-500/20 flex flex-col justify-center text-right">
              <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1">Hesaplanan Toplam Bedel</p>
              <p className="text-3xl font-black text-white neon-text">₺{formData.totalAmount.toLocaleString('tr-TR')}</p>
            </div>
          </div>
        </div>

        {/* Ek Kalemler */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="flex items-center justify-between mb-4 lg:mb-6">
            <h3 className="text-sm font-black text-white uppercase tracking-tight">Paket İçeriği / Yan Ürünler</h3>
            {extraItems.length < 4 && (
              <button 
                type="button" 
                onClick={addExtraItem}
                className="p-2 bg-indigo-500/10 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all flex items-center space-x-2"
              >
                <Plus size={16} />
                <span className="text-[8px] font-black uppercase">Yeni Kalem</span>
              </button>
            )}
          </div>

          <div className="space-y-3">
            {extraItems.map((item) => (
              <div key={item.id} className="flex items-center space-x-3 bg-indigo-950/20 p-3 rounded-2xl border border-indigo-500/5 animate-in slide-in-from-right-4">
                <input 
                  type="text" 
                  value={item.name}
                  onChange={e => updateExtraItem(item.id, 'name', e.target.value)}
                  placeholder="Ürün Adı"
                  className="flex-1 bg-transparent border-b border-indigo-500/20 outline-none text-xs text-white p-1"
                />
                <input 
                  type="number" 
                  value={item.quantity}
                  onChange={e => updateExtraItem(item.id, 'quantity', parseInt(e.target.value) || 1)}
                  className="w-12 bg-transparent border-b border-indigo-500/20 outline-none text-xs text-center text-white p-1"
                />
                <button onClick={() => removeExtraItem(item.id)} className="text-red-500/60 hover:text-red-500 p-1">
                  <Trash2 size={16} />
                </button>
              </div>
            ))}
            {extraItems.length === 0 && (
              <p className="text-[10px] text-indigo-400/40 font-bold uppercase text-center py-4">Ek yan ürün bulunmuyor</p>
            )}
          </div>
        </div>

        {/* Gerekçe ve AI Analiz */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] border border-indigo-500/10">
          <div className="flex items-center justify-between mb-4">
            <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Talep Gerekçesi ve Notlar *</label>
            <button 
              type="button" 
              onClick={handleAiCheck}
              disabled={analyzing}
              className="px-3 py-1 bg-pink-500/10 text-pink-500 rounded-lg text-[9px] font-black uppercase flex items-center space-x-2 border border-pink-500/20 hover:bg-pink-500 hover:text-white transition-all"
            >
              <Sparkles size={12} />
              <span>{analyzing ? 'Analiz Yapılıyor...' : 'AI Karar Destek'}</span>
            </button>
          </div>
          <textarea 
            required
            rows={4}
            value={formData.justification}
            onChange={e => setFormData({...formData, justification: e.target.value})}
            className={`${inputClass} resize-none mb-4`}
            placeholder="Bu harcamanın şirkete sağlayacağı faydayı belirtiniz..."
          />
          {aiAnalysis && (
