        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 lg:space-y-8">
        {/* Temel Bilgiler */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Satın Alma Tanımı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
