                placeholder="Örn: Macbook Pro Ofis Paketi"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Tedarikçi Firma *</label>
              <input 
                required
