              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Adet</label>
              <input 
                type="number" 
                value={formData.packageQuantity}
                onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Fiyat (TL)</label>
              <input 
                type="number" 
                value={formData.packageUnitPriceTl}
                onChange={e => setFormData({...formData, packageUnitPriceTl: parseFloat(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="col-span-2 bg-[#1e293b]/50 p-5 rounded-2xl border border-indigo-500/20 flex flex-col justify-center text-right">
              <p className="text-[10px] text-indigo-400 font-black uppercase tracking-widest mb-1">Hesaplanan Toplam Bedel</p>
              <p className="text-3xl font-black text-white neon-text">₺{formData.totalAmount.toLocaleString('tr-TR')}</p>
            </div>
          </div>
        </div>

        {/* Ek Kalemler */}
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="flex items-center justify-between mb-4 lg:mb-6">
            <h3 className="text-sm font-black text-white uppercase tracking-tight">Paket İçeriği / Detaylı Liste</h3>
            <button 
              type="button" 
              onClick={addExtraItem}
              className="p-2 bg-indigo-500/10 text-indigo-400 rounded-lg hover:bg-indigo-500 hover:text-white transition-all flex items-center space-x-2"
            >
              <Plus size={16} />
              <span className="text-[8px] font-black uppercase">Ürün Ekle</span>
