            placeholder="Neden bu alım yapılmalı?"
          />
          {aiAnalysis && (
            <div className="p-5 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl text-[11px] text-indigo-300 leading-relaxed italic animate-in zoom-in-95">
               <div className="flex items-center space-x-2 mb-2">
                 <Sparkles size={14} className="text-pink-500" />
                 <span className="font-black text-indigo-400 uppercase tracking-tighter">AI Karar Destek</span>
