import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  // ESC tuşu ile geri dönme desteği
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  // Düzenleme sırasında toplam bedeli anlık güncelle
  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const flowStatusColors = {
    'Pending': 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    'Approved': 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    'Rejected': 'bg-red-500/20 text-red-400 border-red-500/30'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Dijital onay verildi (Hızlı Onay).'
      } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Hızlı Onay',
        details: `${role} adımı belgesiz olarak onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR'),
            decisionNote: f.decisionNote || decisionNote || 'Belge sisteme yüklendi.'
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belge Yükleme',
            details: `${role} adımı için görsel kanıt/belge eklendi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReject = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Rejected' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Talep uygun görülmedi.'
      } : f
    );
    onUpdate(transaction.id, { 
      status: 'Rejected',
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Ret Kararı',
        details: `${role} tarafından işlem reddedildi: ${decisionNote}`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24 px-1 lg:px-0">

      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-emerald-400 bg-emerald-500/10 rounded-full transition-all">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-[0_0_100px_rgba(16,185,129,0.3)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 rounded-[40px] border border-emerald-500/20 shadow-2xl relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-2 text-emerald-400 hover:bg-emerald-500/10 rounded-xl transition-all">
              <X size={24} />
            </button>
            <div className="flex items-center space-x-4 mb-8">
                <div className="w-16 h-16 neon-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <UserCheck size={32} />
                </div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-emerald-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-6">
                <div className="bg-emerald-950/20 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">İşlem Detayı & Statü</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Henüz Onaylanmadı'}</span>
                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border ${flowStatusColors[transaction.approvalFlow[selectedFlowDetail].status]}`}>
                            {transaction.approvalFlow[selectedFlowDetail].status}
                        </span>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">Onay Notu</p>
                    <p className="text-xs text-slate-300 italic leading-relaxed">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'Ek not bulunmuyor.'}"
                    </p>
                </div>

                {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div>
                        <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-3">Yüklenen Belge</p>
                        <div 
                          onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}
                          className="w-full h-48 rounded-[30px] overflow-hidden border border-emerald-500/20 cursor-pointer group relative shadow-inner"
                        >
                            <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                <Maximize2 className="text-white" size={24} />
                            </div>
                        </div>
                        <button 
                          onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail].role]?.click()}
                          className="w-full mt-4 py-2 border border-emerald-500/20 rounded-xl text-[10px] font-black text-emerald-400 hover:bg-emerald-500/10 transition-all uppercase"
                        >
                          BELGEYİ GÜNCELLE
                        </button>
                    </div>
                ) : (
                  <div className="space-y-4">
                    <div className="flex items-center space-x-3 text-emerald-500/40 py-8 justify-center border border-dashed border-emerald-500/20 rounded-2xl">
                      <FileText size={24} />
                      <span className="text-[10px] font-black uppercase tracking-widest">Henüz belge yüklenmedi</span>
                    </div>
                    {transaction.approvalFlow[selectedFlowDetail].status === 'Approved' && (
                       <button 
                        onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail].role]?.click()}
                        className="w-full py-3 bg-emerald-500/10 text-emerald-400 rounded-xl border border-emerald-500/20 font-black text-[10px] uppercase hover:bg-emerald-500 hover:text-white transition-all"
                      >
                        SONRADAN BELGE EKLE
                      </button>
                    )}
                  </div>
                )}
            </div>
          </div>
        </div>
      )}

      {/* Ana Detay Kartı */}
      <div className="flex-1 space-y-6 lg:space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-2 text-emerald-400 font-bold text-[11px] uppercase tracking-widest group">
            <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> 
            <span>LİSTEYE DÖN <span className="text-[8px] opacity-40 ml-1">(ESC)</span></span>
          </button>

          <div className="flex items-center space-x-2">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-5 py-2 glass-panel rounded-xl text-[10px] font-black text-emerald-400 uppercase tracking-widest border-emerald-500/20 hover:border-emerald-500/40 transition-all flex items-center">
                <Edit3 size={14} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-6 py-2 neon-gradient text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">GÜNCELLE</button>
            )}
            <button onClick={() => window.confirm('Bu kaydı tamamen silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-2.5 text-red-500/40 hover:text-red-500 hover:bg-red-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[40px] border border-emerald-500/10 overflow-hidden shadow-2xl">
          <div className="p-8 lg:p-12 border-b border-emerald-500/10 bg-emerald-950/20 relative">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-3">
                  <h2 className="text-2xl lg:text-4xl font-black text-white neon-text uppercase leading-tight tracking-tighter">
                    {isEditing ? (
                      <input className="gradient-neon-input outline-none px-4 py-2 rounded-2xl w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} />
                    ) : transaction.productSetName}
                  </h2>
                  <span className={`px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase tracking-widest border ${statusColors[transaction.status]}`}>
                    {transaction.status}
                  </span>
                </div>
                <p className="text-[11px] text-emerald-500 font-bold uppercase tracking-[0.3em] opacity-60">FİŞ NO: #{transaction.id} • SORUMLU: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-emerald-600 font-black uppercase tracking-[0.2em] mb-1">TOPLAM TUTAR (KDV DAHİL)</p>
                <h3 className="text-4xl lg:text-6xl font-black text-white neon-text">
                  ₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}
                </h3>
              </div>
            </div>
          </div>

          <div className="p-8 lg:p-12 space-y-12">
            {/* Maliyet Paneli */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="p-8 bg-emerald-950/30 rounded-[32px] border border-emerald-500/10 space-y-6">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> Fiyatlandırma
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Adet/Paket:</span>
                            {isEditing ? (
                              <input type="number" className="w-20 bg-black/40 text-white rounded-lg px-2 py-1 outline-none text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} />
                            ) : <span className="text-white font-black">{transaction.packageQuantity || 0}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-emerald-800 uppercase font-black tracking-tight">Birim Fiyat:</span>
                            {isEditing ? (
                              <input type="number" className="w-24 bg-black/40 text-white rounded-lg px-2 py-1 outline-none text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} />
                            ) : <span className="text-white font-black">₺{(transaction.packageUnitPriceTl || 0).toLocaleString('tr-TR')}</span>}
                        </div>
                    </div>
                </div>

                <div className="p-8 bg-slate-900/40 rounded-[32px] border border-emerald-500/10 flex flex-col justify-center space-y-4">
                    <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> Micro Kayıt Kodu</h4>
                    <div className="flex items-center justify-between bg-black/40 p-5 rounded-2xl border border-emerald-500/10 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-emerald-300">
                          {isEditing ? (
                            <input className="bg-transparent outline-none w-full" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} />
                          ) : transaction.microCode || 'TANIMSİZ'}
                        </span>
                        {!isEditing && <Copy size={16} className="text-emerald-500 opacity-40 group-hover:opacity-100 transition-opacity" />}
                    </div>
                    {copied && <p className="text-[9px] text-emerald-500 font-black uppercase text-center animate-pulse">KOPYALANDI</p>}
                </div>
            </div>

            {/* Onay Akışı */}
            <div className="space-y-8">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest flex items-center px-2">
                  <ShieldCheck size={18} className="mr-3" /> Onay Durumu ve Belgeler
                </h4>

                <div className="relative pl-12 lg:pl-16 space-y-10">
                    <div className="absolute left-6 lg:left-8 top-4 bottom-4 w-px bg-emerald-500/10"></div>

                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[32px] lg:-left-[44px] top-1.5 w-9 h-9 lg:w-11 lg:h-11 rounded-full flex items-center justify-center border-2 z-10 ${
                                flow.status === 'Approved' ? 'bg-emerald-500 border-emerald-500 text-white' :
                                flow.status === 'Rejected' ? 'bg-red-500 border-red-500 text-white' :
                                'bg-indigo-950 border-emerald-500/20 text-emerald-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={18} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={18} /> : 
                                 <span className="text-xs font-black">{i + 1}</span>}
                            </div>

                            <div className="p-6 lg:p-8 rounded-[36px] border bg-emerald-950/10 border-emerald-500/5 group hover:border-emerald-500/20 transition-all">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                    <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                        <div className="flex items-center space-x-4">
                                            <h5 className="font-black text-white uppercase tracking-tight">{flow.role}</h5>
                                            <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest border ${flowStatusColors[flow.status]}`}>
                                                {flow.status}
                                            </span>
                                        </div>
                                        <p className="text-[11px] text-slate-400 font-bold uppercase">{flow.approverName}</p>
                                        <p className="text-[9px] text-slate-600">{flow.date}</p>
                                    </div>

                                    <div className="flex items-center space-x-3">
                                        <input 
                                            type="file" 
                                            accept="image/*" 
                                            className="hidden" 
                                            ref={el => fileInputRefs.current[flow.role] = el} 
                                            onChange={(e) => handleSignatureProof(flow.role, e)} 
                                        />

                                        {flow.status === 'Pending' ? (
                                            <div className="flex flex-col space-y-2 w-full md:w-auto">
                                                <input 
                                                    type="text" 
                                                    placeholder="Opsiyonel Not"
                                                    value={decisionNote}
                                                    onChange={(e) => setDecisionNote(e.target.value)}
                                                    className="px-3 py-2 bg-black/20 border border-emerald-500/10 rounded-xl text-[10px] text-white outline-none"
                                                />
                                                <div className="flex gap-2">
                                                    <button onClick={() => handleQuickApprove(flow.role)} className="flex-1 px-4 py-2 bg-indigo-500/10 text-indigo-400 rounded-xl border border-indigo-500/20 text-[10px] font-black uppercase">HIZLI ONAY</button>
                                                    <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-2 bg-emerald-500/10 text-emerald-400 rounded-xl border border-emerald-500/20"><Camera size={16} /></button>
                                                    <button onClick={() => handleReject(flow.role)} className="p-2 bg-red-500/10 text-red-500 rounded-xl border border-red-500/20"><XCircle size={16} /></button>
                                                </div>
                                            </div>
                                        ) : (
                                          <div className="flex items-center space-x-2">
                                            {flow.proofUrl ? (
                                                <div 
                                                    onClick={() => setSelectedImage(flow.proofUrl!)}
                                                    className="w-12 h-12 rounded-xl overflow-hidden cursor-pointer border-2 border-emerald-500/10 hover:border-emerald-500/40 transition-all"
                                                >
                                                    <img src={flow.proofUrl} className="w-full h-full object-cover" alt="Belge" />
                                                </div>
                                            ) : (
                                                <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-3 bg-emerald-500/5 text-emerald-500/40 rounded-xl border border-dashed border-emerald-500/20 hover:text-emerald-400 hover:border-emerald-500/40 transition-all" title="Sonradan Belge Ekle">
                                                    <Plus size={18} />
                                                </button>
                                            )}
                                            <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-emerald-900 hover:text-emerald-400 bg-emerald-500/5 rounded-xl transition-all">
                                                <Info size={18} />
                                            </button>
                                          </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Açıklama Paneli */}
            <div className="space-y-4">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest px-2">Talep Gerekçesi</h4>
                <div className="p-8 bg-emerald-950/40 rounded-[32px] border border-emerald-500/10 text-emerald-100 text-sm leading-relaxed italic">
                    {isEditing ? (
                      <textarea className="w-full bg-transparent outline-none border-b border-emerald-500/20 py-2" rows={3} value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} />
                    ) : transaction.justification}
                </div>
            </div>
          </div>

          <div className="bg-emerald-950/40 p-10 border-t border-emerald-500/10 flex flex-col sm:flex-row items-center justify-center gap-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')}
              disabled={transaction.status === 'Approved' || !allApproved}
              className={`w-full sm:w-auto px-12 py-5 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-4 shadow-xl active:scale-95 transition-all ${
                allApproved ? 'opacity-100' : 'opacity-20 cursor-not-allowed'
              }`}
            >
              <Archive size={20} />
              <span>DOSYAYI TAMAMLA VE ARŞİVLE</span>
            </button>
            {transaction.status !== 'Rejected' && (
              <button 
                onClick={() => onStatusChange(transaction.id, 'Rejected')}
                className="w-full sm:w-auto px-12 py-5 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-4 hover:bg-red-600/20 transition-all active:scale-95"
              >
                <XCircle size={20} />
                <span>DOSYAYI İPTAL ET</span>
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-8">
        <div className="glass-panel rounded-[32px] border border-emerald-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-6 border-b border-emerald-500/10 bg-emerald-950/40 flex items-center space-x-4">
            <History size={18} className="text-emerald-500" />
            <h3 className="font-black text-[11px] uppercase tracking-widest text-white">İşlem Günlüğü</h3>
          </div>
          <div className="p-6 space-y-6 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[10px] relative pl-6 border-l border-emerald-500/10 pb-6 last:pb-0 group">
                <div className="absolute left-[-5px] top-0 w-2.5 h-2.5 rounded-full bg-emerald-500"></div>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-black text-emerald-400 uppercase">{log.user}</span>
                  <span className="text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <div className="text-slate-400 leading-tight">
                   <span className="text-white font-bold">{log.action}:</span> {log.details}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  // ESC tuşu ile geri dönme ve modal kapatma desteği
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) {
          setSelectedImage(null);
        } else if (selectedFlowDetail !== null) {
          setSelectedFlowDetail(null);
        } else {
          onBack();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  // Düzenleme sırasında toplam bedeli anlık güncelle
  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const statusColors = {
    'Pending': 'bg-amber-500/10 text-amber-500 border-amber-500/20',
    'Approved': 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20',
    'Rejected': 'bg-red-500/10 text-red-500 border-red-500/20',
    'On Hold': 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'
  };

  const flowStatusColors = {
    'Pending': 'bg-amber-500/20 text-amber-400 border-amber-500/30',
    'Approved': 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
    'Rejected': 'bg-red-500/20 text-red-400 border-red-500/30'
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Dijital onay verildi (Hızlı Onay).'
      } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Hızlı Onay',
        details: `${role} adımı belgesiz olarak onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR'),
            decisionNote: f.decisionNote || decisionNote || 'Belge sisteme yüklendi.'
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belge Yükleme',
            details: `${role} adımı için görsel kanıt/belge eklendi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReject = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Rejected' as const, 
        date: new Date().toLocaleString('tr-TR'),
        decisionNote: decisionNote || 'Talep uygun görülmedi.'
      } : f
    );
    onUpdate(transaction.id, { 
      status: 'Rejected',
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Ret Kararı',
        details: `${role} tarafından işlem reddedildi: ${decisionNote}`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleFinalize = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack(); // Arşivle deyince listeye geri döner
  };

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-500 flex flex-col lg:flex-row gap-6 lg:gap-10 pb-24 px-1 lg:px-0">

      {/* Resim Önizleme Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-6 right-6 p-4 text-white hover:text-emerald-400 bg-emerald-500/10 rounded-full transition-all">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] object-contain rounded-2xl shadow-[0_0_100px_rgba(16,185,129,0.3)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[90] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 rounded-[40px] border border-emerald-500/20 shadow-2xl relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-2 text-emerald-400 hover:bg-emerald-500/10 rounded-xl transition-all">
              <X size={24} />
            </button>
            <div className="flex items-center space-x-4 mb-8">
                <div className="w-16 h-16 neon-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                    <UserCheck size={32} />
                </div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-emerald-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-6">
                <div className="bg-emerald-950/20 p-5 rounded-3xl border border-emerald-500/10">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest mb-2">İşlem Detayı & Statü</p>
                    <div className="flex justify-between items-center">
