                <div className="relative pl-12 lg:pl-16 space-y-10">
                    <div className="absolute left-6 lg:left-8 top-4 bottom-4 w-px bg-emerald-500/10"></div>

                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[32px] lg:-left-[44px] top-1.5 w-9 h-9 lg:w-11 lg:h-11 rounded-full flex items-center justify-center border-2 z-10 ${
                                flow.status === 'Approved' ? 'bg-emerald-500 border-emerald-500 text-white' :
                                flow.status === 'Rejected' ? 'bg-red-500 border-red-500 text-white' :
                                'bg-indigo-950 border-emerald-500/20 text-emerald-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={18} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={18} /> : 
                                 <span className="text-xs font-black">{i + 1}</span>}
                            </div>

                            <div className="p-6 lg:p-8 rounded-[36px] border bg-emerald-950/10 border-emerald-500/5 group hover:border-emerald-500/20 transition-all">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                                    <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                        <div className="flex items-center space-x-4">
                                            <h5 className="font-black text-white uppercase tracking-tight">{flow.role}</h5>
                                            <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase tracking-widest border ${flowStatusColors[flow.status]}`}>
                                                {flow.status}
                                            </span>
                                        </div>
                                        <p className="text-[11px] text-slate-400 font-bold uppercase">{flow.approverName}</p>
                                        <p className="text-[9px] text-slate-600">{flow.date}</p>
                                    </div>

                                    <div className="flex items-center space-x-3">
                                        <input 
                                            type="file" 
                                            accept="image/*" 
                                            className="hidden" 
                                            ref={el => fileInputRefs.current[flow.role] = el} 
                                            onChange={(e) => handleSignatureProof(flow.role, e)} 
                                        />

                                        {flow.status === 'Pending' ? (
                                            <div className="flex flex-col space-y-2 w-full md:w-auto">
                                                <input 
                                                    type="text" 
                                                    placeholder="Opsiyonel Not"
                                                    value={decisionNote}
                                                    onChange={(e) => setDecisionNote(e.target.value)}
                                                    className="px-3 py-2 bg-black/20 border border-emerald-500/10 rounded-xl text-[10px] text-white outline-none"
                                                />
                                                <div className="flex gap-2">
                                                    <button onClick={() => handleQuickApprove(flow.role)} className="flex-1 px-4 py-2 bg-indigo-500/10 text-indigo-400 rounded-xl border border-indigo-500/20 text-[10px] font-black uppercase">HIZLI ONAY</button>
                                                    <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-2 bg-emerald-500/10 text-emerald-400 rounded-xl border border-emerald-500/20"><Camera size={16} /></button>
                                                    <button onClick={() => handleReject(flow.role)} className="p-2 bg-red-500/10 text-red-500 rounded-xl border border-red-500/20"><XCircle size={16} /></button>
                                                </div>
                                            </div>
                                        ) : (
                                          <div className="flex items-center space-x-2">
                                            {flow.proofUrl ? (
                                                <div 
                                                    onClick={() => setSelectedImage(flow.proofUrl!)}
                                                    className="w-12 h-12 rounded-xl overflow-hidden cursor-pointer border-2 border-emerald-500/10 hover:border-emerald-500/40 transition-all"
                                                >
                                                    <img src={flow.proofUrl} className="w-full h-full object-cover" alt="Belge" />
                                                </div>
                                            ) : (
                                                <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-3 bg-emerald-500/5 text-emerald-500/40 rounded-xl border border-dashed border-emerald-500/20 hover:text-emerald-400 hover:border-emerald-500/40 transition-all" title="Sonradan Belge Ekle">
                                                    <Plus size={18} />
                                                </button>
                                            )}
                                            <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-emerald-900 hover:text-emerald-400 bg-emerald-500/5 rounded-xl transition-all">
                                                <Info size={18} />
                                            </button>
                                          </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Açıklama Paneli */}
            <div className="space-y-4">
                <h4 className="text-[11px] font-black text-emerald-400 uppercase tracking-widest px-2">Talep Gerekçesi</h4>
                <div className="p-8 bg-emerald-950/40 rounded-[32px] border border-emerald-500/10 text-emerald-100 text-sm leading-relaxed italic">
                    {isEditing ? (
                      <textarea className="w-full bg-transparent outline-none border-b border-emerald-500/20 py-2" rows={3} value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} />
                    ) : transaction.justification}
                </div>
            </div>
          </div>

          <div className="bg-emerald-950/40 p-10 border-t border-emerald-500/10 flex flex-col sm:flex-row items-center justify-center gap-6">
            <button 
              onClick={handleFinalize}
              disabled={transaction.status === 'Approved' || !allApproved}
              className={`w-full sm:w-auto px-12 py-5 neon-gradient text-white rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-4 shadow-xl active:scale-95 transition-all ${
                allApproved ? 'opacity-100' : 'opacity-20 cursor-not-allowed'
              }`}
            >
              <Archive size={20} />
              <span>DOSYAYI TAMAMLA VE ARŞİVLE</span>
            </button>
            {transaction.status !== 'Rejected' && (
              <button 
                onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }}
                className="w-full sm:w-auto px-12 py-5 bg-red-600/10 border border-red-600/20 text-red-500 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-4 hover:bg-red-600/20 transition-all active:scale-95"
              >
                <XCircle size={20} />
                <span>DOSYAYI İPTAL ET</span>
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-8">
        <div className="glass-panel rounded-[32px] border border-emerald-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-6 border-b border-emerald-500/10 bg-emerald-950/40 flex items-center space-x-4">
            <History size={18} className="text-emerald-500" />
            <h3 className="font-black text-[11px] uppercase tracking-widest text-white">İşlem Günlüğü</h3>
          </div>
          <div className="p-6 space-y-6 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="text-[10px] relative pl-6 border-l border-emerald-500/10 pb-6 last:pb-0 group">
                <div className="absolute left-[-5px] top-0 w-2.5 h-2.5 rounded-full bg-emerald-500"></div>
                <div className="flex items-center justify-between mb-1">
                  <span className="font-black text-emerald-400 uppercase">{log.user}</span>
                  <span className="text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <div className="text-slate-400 leading-tight">
                   <span className="text-white font-bold">{log.action}:</span> {log.details}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Uygulama başarıyla yüklendi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Yönetici girişi yapıldı: ${user.username}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı sistemden ayrıldı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.slice(0, 2).map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPriceTl: request.packageUnitPriceTl || 0,
      totalAmount: (request.packageQuantity || 1) * (request.packageUnitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow.length > 0 ? approvalFlow : [
        { role: 'IT Manager', status: 'Pending', approverName: 'Murat Bilgin' },
        { role: 'CFO', status: 'Pending', approverName: 'Selin Aksoy' }
      ]
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    addSystemLog('PURCHASE', 'Yeni Talep', `${newTransaction.productSetName} için ${newTransaction.totalAmount} TL bedelli talep oluşturuldu.`);
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi' : `Durum: ${newStatus}`;
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Statü Güncelleme',
            details: actionText
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Değişikliği', `Kayıt #${id} yeni durumuna getirildi: ${newStatus}`);
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} veritabanından kalıcı olarak kaldırıldı.`);
    setSelectedTransactionId(null);
    setActiveTab('transactions');
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          // Otomatik toplam tutar hesaplama senkronizasyonu
          if (updates.packageQuantity !== undefined || updates.packageUnitPriceTl !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPriceTl || 0);
          }
          return updated;
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Kayıt Güncellendi', `Kayıt #${id} içeriği manuel olarak düzenlendi.`);
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
      addSystemLog('DEPTS', 'Departman Eklendi', `Yeni departman sisteme tanımlandı: ${name}`);
    }
  };

  const handleSetRoles = (roles: RoleDefinition[]) => {
    setState(prev => ({ ...prev, roles }));
    addSystemLog('ROLES', 'Yetkili Listesi Güncellendi', `Onay yetkilileri ve atanan isimler güncellendi.`);
  };

  const handleSetDepartments = (departments: string[]) => {
    setState(prev => ({ ...prev, departments }));
    addSystemLog('DEPTS', 'Departman Listesi Güncellendi', `Sistemdeki departman yapılandırması güncellendi.`);
  };

  const handleUpdateUser = (name: string) => {
    if (state.user) {
      const oldName = state.user.name;
      setState(prev => ({ ...prev, user: { ...prev.user!, name } }));
      addSystemLog('PROFILE', 'Profil Güncellendi', `Kullanıcı adı '${oldName}' değerinden '${name}' değerine değiştirildi.`);
    }
  };

  const handleMetricClick = (status: string | null) => {
    setStatusFilter(status);
    setActiveTab('transactions');
  };

  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
        if (tab !== 'transactions') setStatusFilter(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
              onFilterClick={handleMetricClick}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">DİJİTAL ARŞİV</h2>
                    <p className="text-emerald-400 font-bold text-xs uppercase tracking-widest mt-1">
                      {statusFilter ? `${statusFilter} Filtreli Sonuçlar` : 'Tüm Geçmiş ve Aktif Dosyalar'}
                    </p>
                </div>
                <div className="flex space-x-3 bg-emerald-950/30 p-1.5 rounded-2xl border border-emerald-500/10">
                  <button onClick={() => setStatusFilter(null)} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-emerald-600 text-white shadow-lg' : 'hover:bg-emerald-500/10 text-emerald-400'}`}>ONAYLI</button>
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="glass-panel p-20 rounded-[40px] border border-emerald-500/10 text-center">
                  <p className="text-emerald-400 font-bold uppercase tracking-widest">Bu kriterlere uygun dosya bulunamadı.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id}
                      onClick={() => setSelectedTransactionId(t.id)}
                      className="glass-panel p-8 rounded-[32px] border border-emerald-500/10 hover:border-emerald-500/40 transition-all cursor-pointer group hover:scale-[1.02] shadow-xl"
                    >
                      <div className="flex items-start justify-between mb-6">
                        <div className="w-14 h-14 bg-emerald-500/10 text-emerald-400 flex items-center justify-center rounded-2xl group-hover:neon-gradient group-hover:text-white transition-all border border-emerald-500/20 shadow-inner">
                          <span className="font-black text-lg">{t.requesterName.charAt(0)}</span>
                        </div>
                        <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border ${
                          t.status === 'Pending' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' : 
                          t.status === 'Approved' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' : 
                          'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                        }`}>
                          {t.status}
                        </span>
                      </div>
                      <h3 className="font-black text-white text-lg truncate mb-1 group-hover:text-emerald-400 transition-colors">{t.productSetName}</h3>
                      <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-widest mb-6 opacity-60">{t.department} • {t.supplierName}</p>
                      <div className="flex items-center justify-between pt-6 border-t border-emerald-500/10">
                        <div>
                          <p className="text-[9px] text-emerald-500/40 font-black uppercase tracking-[0.2em]">Dosya Bedeli</p>
                          <p className="text-xl font-black text-white neon-text">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                        </div>
                        <div className="text-right">
                            <p className="text-[9px] text-emerald-500/40 font-bold uppercase">Kayıt No</p>
                            <p className="text-xs font-mono text-emerald-300">#{t.id}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'settings' && (
            <Settings 
              roles={state.roles} 
              setRoles={handleSetRoles} 
              departments={state.departments}
              setDepartments={handleSetDepartments}
              user={state.user}
              onUpdateUser={handleUpdateUser}
              systemLogs={state.systemLogs}
            />
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Shield, Plus, X, Users, Lock, ChevronRight, User as UserIcon, History, Terminal, UserCheck } from 'lucide-react';
