interface SettingsProps {
  roles: RoleDefinition[];
  setRoles: (roles: RoleDefinition[]) => void;
  departments: string[];
  setDepartments: (depts: string[]) => void;
  user: User;
  onUpdateUser: (name: string) => void;
  systemLogs: SystemLog[];
  onBack?: () => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  roles, setRoles, departments, setDepartments, user, onUpdateUser, systemLogs, onBack 
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'profile' | 'security'>('profile');
  const [newRoleName, setNewRoleName] = useState('');
  const [newAssignedName, setNewAssignedName] = useState('');
  const [userName, setUserName] = useState(user.name);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && onBack) onBack();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack]);

  const addRole = () => {
    if (newRoleName && newAssignedName) {
      const isDuplicate = roles.some(r => r.roleName.toLowerCase() === newRoleName.toLowerCase());
      if (isDuplicate) {
        alert('Bu rol zaten tanımlı.');
        return;
      }
      setRoles([...roles, { 
        id: Date.now().toString(), 
        roleName: newRoleName, 
        assignedName: newAssignedName 
      }]);
      setNewRoleName('');
      setNewAssignedName('');
    } else {
      alert('Lütfen hem rol adını hem de yetkili ismini giriniz.');
    }
  };

  const removeRole = (id: string) => {
    setRoles(roles.filter(r => r.id !== id));
  };

