import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Uygulama başarıyla yüklendi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Yönetici girişi yapıldı: ${user.username}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı sistemden ayrıldı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPriceTl: request.packageUnitPriceTl || 0,
      totalAmount: (request.packageQuantity || 1) * (request.packageUnitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow
    };

    setState(prev => ({
      ...prev,
      transactions: [newTransaction, ...prev.transactions]
    }));
    addSystemLog('PURCHASE', 'Yeni Talep', `${newTransaction.productSetName} için ${newTransaction.totalAmount} TL bedelli talep oluşturuldu.`);
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi' : `Durum: ${newStatus}`;
          const newLog = {
            id: `log-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Admin',
            action: 'Statü Güncelleme',
            details: actionText
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Değişikliği', `Kayıt #${id} yeni durumuna getirildi: ${newStatus}`);
  };

  const handleDelete = (id: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.filter(t => t.id !== id)
    }));
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} veritabanından kalıcı olarak kaldırıldı.`);
    setSelectedTransactionId(null);
    setActiveTab('transactions');
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (updates.packageQuantity !== undefined || updates.packageUnitPriceTl !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPriceTl || 0);
          }
          return updated;
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Kayıt Güncellendi', `Kayıt #${id} içeriği manuel olarak düzenlendi.`);
  };

  const handleAddDepartment = (name: string) => {
    if (!state.departments.includes(name)) {
      setState(prev => ({ ...prev, departments: [...prev.departments, name] }));
      addSystemLog('DEPTS', 'Departman Eklendi', `Yeni departman sisteme tanımlandı: ${name}`);
    }
  };

  const handleSetRoles = (roles: RoleDefinition[]) => {
    setState(prev => ({ ...prev, roles }));
    addSystemLog('ROLES', 'Yetkili Listesi Güncellendi', `Onay yetkilileri ve atanan isimler güncellendi.`);
  };

  const handleSetDepartments = (departments: string[]) => {
    setState(prev => ({ ...prev, departments }));
    addSystemLog('DEPTS', 'Departman Listesi Güncellendi', `Sistemdeki departman yapılandırması güncellendi.`);
  };

  const handleUpdateUser = (name: string) => {
    if (state.user) {
      const oldName = state.user.name;
      setState(prev => ({ ...prev, user: { ...prev.user!, name } }));
      addSystemLog('PROFILE', 'Profil Güncellendi', `Kullanıcı adı '${oldName}' değerinden '${name}' değerine değiştirildi.`);
    }
  };

  const handleMetricClick = (status: string | null) => {
    setStatusFilter(status);
    setActiveTab('transactions');
  };

  if (!state.user) {
    return <Login onLogin={handleLogin} />;
  }

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setSelectedTransactionId(null);
        if (tab !== 'transactions') setStatusFilter(null);
      }} 
      user={state.user}
      onLogout={handleLogout}
    >
      {selectedTransaction ? (
        <TransactionDetail 
          transaction={selectedTransaction}
          onBack={() => setSelectedTransactionId(null)}
          onStatusChange={handleStatusChange}
          onDelete={handleDelete}
          onUpdate={handleUpdate}
          currentUserRole={state.user.role}
        />
      ) : (
        <>
          {activeTab === 'dashboard' && (
            <Dashboard 
              transactions={state.transactions} 
              onSelectTransaction={(id) => setSelectedTransactionId(id)}
              onFilterClick={handleMetricClick}
            />
          )}
          {activeTab === 'new-request' && (
            <NewRequest 
              onSave={handleNewRequest} 
              departments={state.departments}
              onAddDepartment={handleAddDepartment}
              onBack={() => setActiveTab('dashboard')}
            />
          )}
          {activeTab === 'transactions' && (
            <div className="space-y-10 animate-in fade-in duration-700">
              <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">DİJİTAL ARŞİV</h2>
