import React, { useState, useRef, useEffect } from 'react';
import { Send, Plus, Trash2, Camera, Info, Sparkles, FileText, CheckCircle, X, Package } from 'lucide-react';
import { ExtraItem, Transaction } from '../types';
import { analyzeJustification } from '../services/geminiService';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    usageLocation: '',
    requesterName: 'Hasan Demir',
    packageQuantity: 1,
    packageUnitPriceTl: 0,
    quantity: 0,
    unitPriceTl: 0,
    justification: '',
    microCode: '',
    photoUrl: '',
    totalAmount: 0
  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [isOtherDept, setIsOtherDept] = useState(false);
  const [newDeptName, setNewDeptName] = useState('');
  const [analyzing, setAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ESC tuşu ile geri dönme desteği
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && onBack) onBack();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack]);

  // Toplam Bedel Real-time Hesaplama
  useEffect(() => {
    const total = (formData.packageQuantity * formData.packageUnitPriceTl) + (formData.quantity * formData.unitPriceTl);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, formData.packageUnitPriceTl, formData.quantity, formData.unitPriceTl]);

  const inputClass = "w-full px-4 py-3 rounded-xl gradient-neon-input text-slate-200 outline-none transition-all placeholder:text-indigo-700/60 text-sm";

  const addExtraItem = () => {
    setExtraItems([...extraItems, { id: Date.now().toString() + Math.random(), name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, field: keyof ExtraItem, value: string | number) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAiCheck = async () => {
    if (!formData.productSetName || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.productSetName, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleDeptChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'OTHER') {
      setIsOtherDept(true);
      setFormData({ ...formData, department: '' });
    } else {
      setIsOtherDept(false);
      setFormData({ ...formData, department: val });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalDept = isOtherDept ? newDeptName : formData.department;

    if (!finalDept) {
      alert("Lütfen bir departman belirtiniz.");
      return;
    }

    if (isOtherDept) {
      onAddDepartment(newDeptName);
    }

    onSave({
      ...formData,
      department: finalDept,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Süreç Başlatıldı', details: 'Yeni dijital talep girişi yapıldı.' }]
    });
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex items-center justify-between mb-6 lg:mb-10 px-2">
        <div>
          <h2 className="text-2xl lg:text-3xl font-black text-white neon-text tracking-tight uppercase">Yeni Talep Girişi</h2>
          <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mt-1">2025 Finansal Dönem Kaydı</p>
        </div>
        <div className="hidden lg:flex px-4 py-2 glass-panel rounded-full border border-indigo-500/30 items-center space-x-2 text-indigo-400 font-bold text-xs uppercase tracking-widest">
          <FileText size={14} />
          <span>Form No: {Math.floor(Math.random() * 10000)}</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6 lg:space-y-8">
        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-8">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Satın Alma Tanımı *</label>
              <input 
                required
                type="text" 
                value={formData.productSetName}
                onChange={e => setFormData({...formData, productSetName: e.target.value})}
                placeholder="Örn: Macbook Pro Ofis Paketi"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Tedarikçi Firma *</label>
              <input 
                required
                type="text" 
                value={formData.supplierName}
                onChange={e => setFormData({...formData, supplierName: e.target.value})}
                placeholder="Firma veya Şahıs Adı"
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">İlgili Departman</label>
              <div className="space-y-2">
                <select 
                  onChange={handleDeptChange}
                  className={inputClass}
                  value={isOtherDept ? 'OTHER' : formData.department}
                >
                  {departments.map(d => <option key={d} value={d} className="bg-[#1e1b4b]">{d}</option>)}
                  <option value="OTHER" className="bg-[#1e1b4b] font-bold text-emerald-400">DİĞER...</option>
                </select>
                {isOtherDept && (
                  <input 
                    type="text" 
                    required
                    value={newDeptName}
                    onChange={e => setNewDeptName(e.target.value)}
                    placeholder="Yeni Departman Adını Yazın"
                    className={`${inputClass} animate-in fade-in slide-in-from-top-2 border-emerald-500/30`}
                  />
                )}
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">ERP / Micro Kodu</label>
              <input 
                type="text" 
                value={formData.microCode}
                onChange={e => setFormData({...formData, microCode: e.target.value})}
                placeholder="ERP referansı (Varsa)"
                className={inputClass}
              />
            </div>
          </div>
        </div>

        <div className="glass-panel p-6 lg:p-8 rounded-[24px] lg:rounded-[32px] border border-indigo-500/10 shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-8 opacity-5"><Package size={120} /></div>
          <div className="flex items-center space-x-2 mb-6">
            <Package size={18} className="text-indigo-400" />
            <h3 className="text-sm lg:text-base font-black text-white uppercase tracking-tight">Harcama ve Maliyet Detayı</h3>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 relative z-10">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Adet</label>
              <input 
                type="number" 
                value={formData.packageQuantity}
                onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})}
                className={inputClass}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Fiyat (TL)</label>
              <input 
                type="number" 
