              type="button" 
              onClick={handleAiCheck}
              disabled={analyzing}
              className="px-3 py-1 bg-pink-500/10 text-pink-500 rounded-lg text-[9px] font-black uppercase flex items-center space-x-2 border border-pink-500/20 hover:bg-pink-500 hover:text-white transition-all"
            >
              <Sparkles size={12} />
              <span>{analyzing ? 'Analiz Ediliyor...' : 'Gemini AI Kontrolü'}</span>
            </button>
          </div>
          <textarea 
            required
            rows={4}
            value={formData.justification}
            onChange={e => setFormData({...formData, justification: e.target.value})}
            className={`${inputClass} resize-none mb-4`}
            placeholder="Neden bu alım yapılmalı?"
          />
          {aiAnalysis && (
            <div className="p-5 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl text-[11px] text-indigo-300 leading-relaxed italic animate-in zoom-in-95">
