        </div>

        <div className="flex flex-col lg:flex-row items-center gap-4">
          <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
          <button 
            type="button" 
            onClick={() => fileInputRef.current?.click()}
            className="w-full lg:w-auto px-8 py-5 glass-panel rounded-2xl text-indigo-400 flex items-center justify-center space-x-3 hover:text-white transition-all border border-indigo-500/20"
          >
            {formData.photoUrl ? <CheckCircle size={20} className="text-emerald-500" /> : <Camera size={20} />}
