          </button>
          <button 
            type="submit"
            className="w-full flex-1 py-5 neon-gradient text-white rounded-[24px] font-black shadow-[0_20px_40px_rgba(16,185,129,0.2)] flex items-center justify-center space-x-3 uppercase tracking-widest text-sm active:scale-95 transition-all"
