import React, { useState, useEffect, useMemo } from 'react';
import { 
  Shield, 
  Plus, 
  X, 
  Users, 
  Lock, 
  ChevronRight, 
  User as UserIcon, 
  History, 
  Terminal, 
  UserCheck,
  CheckCircle2,
  XCircle,
  FileText,
  Search,
  ArrowRight,
  TrendingUp,
  CreditCard
} from 'lucide-react';
import { RoleDefinition, User, SystemLog, Transaction } from '../types';

interface SettingsProps {
  roles: RoleDefinition[];
  setRoles: (roles: RoleDefinition[]) => void;
  departments: string[];
  setDepartments: (depts: string[]) => void;
  user: User;
  onUpdateUser: (name: string) => void;
  systemLogs: SystemLog[];
  transactions: Transaction[];
  onBack?: () => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  roles, setRoles, departments, setDepartments, user, onUpdateUser, systemLogs, transactions, onBack 
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'profile' | 'security'>('profile');
  const [newRoleName, setNewRoleName] = useState('');
  const [newAssignedName, setNewAssignedName] = useState('');
  const [userName, setUserName] = useState(user.name);
  const [selectedApproverHistory, setSelectedApproverHistory] = useState<string | null>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedApproverHistory) {
          setSelectedApproverHistory(null);
        } else if (onBack) {
          onBack();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedApproverHistory]);

  const addRole = () => {
    if (newRoleName && newAssignedName) {
      const isDuplicate = roles.some(r => r.roleName.toLowerCase() === newRoleName.toLowerCase());
      if (isDuplicate) return;
      setRoles([...roles, { id: Date.now().toString(), roleName: newRoleName, assignedName: newAssignedName }]);
      setNewRoleName('');
      setNewAssignedName('');
    }
  };

  const removeRole = (id: string) => setRoles(roles.filter(r => r.id !== id));

  const handleUpdateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateUser(userName);
  };

  const approverHistory = useMemo(() => {
    if (!selectedApproverHistory) return [];
    return transactions.filter(t => 
      t.approvalFlow.some(f => f.approverName === selectedApproverHistory && f.status !== 'Pending')
    ).map(t => {
      const flowStep = t.approvalFlow.find(f => f.approverName === selectedApproverHistory);
      return {
        id: t.id,
        name: t.productSetName,
        amount: t.totalAmount,
        status: flowStep?.status,
        date: flowStep?.date || 'Belirtilmedi',
        note: flowStep?.decisionNote
      };
    });
  }, [selectedApproverHistory, transactions]);

  return (
    <div className="max-w-6xl mx-auto space-y-10 animate-in fade-in duration-500 pb-20">

      {/* Yetkili Onay Geçmişi Modalı (Neon Işıklarla Güncellendi) */}
      {selectedApproverHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-2xl animate-in fade-in">
          <div className="w-full max-w-2xl glass-panel p-10 lg:p-14 rounded-[50px] border border-violet-500/30 shadow-[0_0_100px_rgba(139,92,246,0.2)] relative">
            <button onClick={() => setSelectedApproverHistory(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-violet-500/10 rounded-2xl transition-all">
              <X size={28} />
            </button>

            <div className="flex items-center space-x-6 mb-12">
              <div className="w-20 h-20 neon-gradient-premium rounded-[32px] flex items-center justify-center text-white shadow-[0_0_30px_rgba(139,92,246,0.5)]">
                <UserCheck size={40} />
              </div>
              <div>
                <h3 className="text-3xl font-black text-white uppercase tracking-tighter neon-text-premium">{selectedApproverHistory}</h3>
                <p className="text-sm font-black text-violet-500 uppercase tracking-widest opacity-60">Sistem Karar Logları</p>
              </div>
            </div>

            <div className="space-y-6 max-h-[500px] overflow-y-auto custom-scroll pr-4">
              {approverHistory.length > 0 ? approverHistory.map((item) => (
                <div key={item.id} className={`p-6 rounded-[30px] border transition-all duration-500 flex items-center justify-between group ${
                  item.status === 'Approved' 
                  ? 'bg-green-500/5 border-green-500/30 neon-glow-green' 
                  : 'bg-rose-500/5 border-rose-500/30 neon-glow-rose'
                }`}>
                   <div className="space-y-2">
                      <div className="flex items-center space-x-3">
                         <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">#{item.id}</span>
                         <p className="text-sm font-black text-white uppercase tracking-tight">{item.name}</p>
                      </div>
                      <div className="flex items-center space-x-4">
                         <div className="flex items-center space-x-1 text-slate-400 text-[10px] font-bold">
                            <History size={12} />
                            <span>{item.date}</span>
                         </div>
                         <div className="flex items-center space-x-1 text-violet-400 text-[11px] font-black">
                            <CreditCard size={12} />
                            <span>₺{item.amount.toLocaleString('tr-TR')}</span>
                         </div>
                      </div>
                      {item.note && <p className="text-[10px] text-slate-500 italic mt-1 bg-black/20 p-2 rounded-lg">"{item.note}"</p>}
                   </div>
                   <div className="flex flex-col items-center">
                     {item.status === 'Approved' ? (
                       <div className="flex flex-col items-center text-green-400">
                          <CheckCircle2 size={32} className="mb-1" />
                          <span className="text-[8px] font-black uppercase tracking-widest">UYGUN GÖRÜLDÜ</span>
                       </div>
                     ) : (
                       <div className="flex flex-col items-center text-rose-500">
                          <XCircle size={32} className="mb-1" />
                          <span className="text-[8px] font-black uppercase tracking-widest">UYGUN GÖRÜLMEDİ</span>
                       </div>
                     )}
                   </div>
                </div>
              )) : (
                <div className="text-center py-24 opacity-30">
                   <Terminal size={64} className="mx-auto text-violet-950 mb-6" />
                   <p className="text-xs font-black text-violet-500 uppercase tracking-widest">Henüz bir karar kaydı işlenmemiş</p>
                </div>
              )}
            </div>

            <div className="mt-12 pt-8 border-t border-violet-500/10 flex justify-between items-center">
              <span className="text-[9px] font-black text-violet-900 uppercase tracking-widest flex items-center">
                <Lock size={12} className="mr-2" /> Güvenli Denetim Modu
              </span>
              <button onClick={() => setSelectedApproverHistory(null)} className="px-12 py-4 neon-gradient-premium text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl">GEÇMİŞİ KAPAT</button>
            </div>
          </div>
        </div>
      )}

      <div>
        <h2 className="text-5xl font-black text-white neon-text-premium uppercase tracking-tighter">SİSTEM AYARLARI</h2>
        <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-1">Konfigürasyon ve Yetki Yönetim Merkezi</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
        <div className="space-y-4">
          <button onClick={() => setActiveSubTab('profile')} className={`w-full p-8 rounded-[32px] border transition-all flex items-center space-x-5 ${activeSubTab === 'profile' ? 'bg-violet-600 border-violet-400 text-white shadow-xl neon-glow-violet' : 'glass-panel border-violet-500/10 text-violet-400/60'}`}>
            <UserIcon size={24} />
            <span className="text-xs font-black uppercase tracking-widest">PROFİL & YETKİ</span>
          </button>
          <button onClick={() => setActiveSubTab('security')} className={`w-full p-8 rounded-[32px] border transition-all flex items-center space-x-5 ${activeSubTab === 'security' ? 'bg-cyan-600 border-cyan-400 text-white shadow-xl neon-glow-cyan' : 'glass-panel border-cyan-500/10 text-cyan-400/60'}`}>
            <Shield size={24} />
            <span className="text-xs font-black uppercase tracking-widest">LOG DENETİMİ</span>
          </button>
        </div>

        <div className="lg:col-span-3">
          {activeSubTab === 'profile' ? (
            <div className="space-y-10">
              <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-violet-500/10">
                <div className="flex items-center space-x-5 mb-12">
                    <UserIcon size={28} className="text-violet-400" />
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">KULLANICI PROFİLİ</h3>
                </div>
                <form onSubmit={handleUpdateProfile} className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-4">
                        <label className="text-[10px] font-black text-violet-400 uppercase tracking-widest ml-1">AD SOYAD GÜNCELLE</label>
                        <input type="text" value={userName} onChange={e => setUserName(e.target.value)} className="w-full px-6 py-5 rounded-2xl outline-none" />
                    </div>
                    <div className="space-y-4">
                        <label className="text-[10px] font-black text-violet-400 uppercase tracking-widest ml-1">SİSTEM ROLÜ</label>
                        <input type="text" disabled value={user.role} className="w-full px-6 py-5 rounded-2xl bg-black/40 border-none text-slate-500 font-black uppercase cursor-not-allowed" />
                    </div>
                    <div className="md:col-span-2">
                        <button type="submit" className="px-14 py-5 neon-gradient-premium text-white rounded-2xl text-[11px] font-black uppercase tracking-widest">DEĞİŞİKLİKLERİ KAYDET</button>
                    </div>
                </form>
              </div>

              <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-violet-500/10">
                <div className="flex items-center space-x-5 mb-12">
                    <Users size={28} className="text-violet-400" />
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">ONAY YETKİLİLERİ</h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                    <input type="text" value={newRoleName} onChange={e => setNewRoleName(e.target.value)} placeholder="Rol (Örn: CEO)" className="px-6 py-5 rounded-2xl" />
                    <input type="text" value={newAssignedName} onChange={e => setNewAssignedName(e.target.value)} placeholder="İsim Soyisim" className="px-6 py-5 rounded-2xl" />
                    <button onClick={addRole} className="h-full bg-white text-black rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-violet-400 transition-all">YETKİLİ EKLE</button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {roles.map((role) => (
                    <div key={role.id} onClick={() => setSelectedApproverHistory(role.assignedName)} className="cyber-card p-8 bg-violet-950/20 rounded-[40px] border border-violet-500/10 flex items-center justify-between cursor-pointer group">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest group-hover:text-violet-300 transition-colors">{role.roleName}</p>
                        <p className="text-lg font-black text-white uppercase group-hover:neon-text-premium transition-all">{role.assignedName}</p>
                      </div>
                      <X size={20} className="text-violet-900 group-hover:text-rose-500 transition-colors" onClick={(e) => { e.stopPropagation(); removeRole(role.id); }} />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-cyan-500/10 space-y-10">
                <div className="flex items-center justify-between">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center">
                        <Terminal size={28} className="text-cyan-400 mr-4" /> DENETİM KAYITLARI
                    </h3>
                    <span className="px-5 py-2 bg-cyan-500/10 text-cyan-400 text-[10px] font-black rounded-full border border-cyan-500/20">{systemLogs.length} LOG</span>
                </div>
                <div className="space-y-4 max-h-[600px] overflow-y-auto custom-scroll pr-4">
                    {systemLogs.map((log) => (
                        <div key={log.id} className="p-6 bg-slate-900/40 rounded-3xl border border-cyan-500/5 hover:border-cyan-500/20 transition-all">
                            <div className="flex justify-between mb-2">
                                <span className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">{log.action}</span>
                                <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                            </div>
                            <p className="text-xs text-slate-300 italic">"{log.details}"</p>
                        </div>
                    ))}
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

