  Zap,
  Edit3,
  CreditCard
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const handleFinalize = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { ...f, status: 'Approved' as const, date: new Date().toLocaleString('tr-TR'), decisionNote: decisionNote || 'Hızlı Dijital Onay' } : f
    );
    onUpdate(transaction.id, { approvalFlow: updatedFlow });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { ...f, proofUrl: reader.result as string, status: 'Approved' as const, date: new Date().toLocaleString('tr-TR') } : f
        );
        onUpdate(transaction.id, { approvalFlow: updatedFlow });
      };
      reader.readAsDataURL(file);
    }
  };

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Resim Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-violet-400 bg-white/5 rounded-full hover:bg-white/10 transition-all"><X size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[80vh] rounded-3xl neon-glow-violet shadow-[0_0_100px_rgba(139,92,246,0.4)]" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-12 rounded-[50px] border border-violet-500/20 relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-10">
                <div className="w-20 h-20 neon-gradient-premium rounded-[30px] flex items-center justify-center text-white"><UserCheck size={40} /></div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-violet-500 uppercase tracking-widest">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>
            <div className="space-y-6">
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">KARAR STATÜSÜ</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status}</span>
                    </div>
                </div>
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">ONAYLAYICI NOTU</p>
                    <p className="text-xs text-slate-400 italic leading-relaxed">"{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'İşlem notu bırakılmamış.'}"</p>
                </div>
                {transaction.approvalFlow[selectedFlowDetail].proofUrl && (
                  <div className="w-full h-48 rounded-[30px] overflow-hidden border border-violet-500/20 cursor-pointer" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                    <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover" />
                  </div>
                )}
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>GERİ DÖN <span className="opacity-30 ml-2">(ESC)</span></span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">GÜNCELLE</button>
            )}
            <button onClick={() => window.confirm('Kaydı silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative">
          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border ${
                    transaction.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 shadow-[0_0_20px_rgba(34,197,94,0.1)]' : 'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>{transaction.status}</span>
                </div>
                <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • SORUMLU: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="p-10 bg-violet-950/30 rounded-[40px] border border-violet-500/10 space-y-8">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={20} className="mr-4" /> MİKTAR & FİYAT ANALİZİ
                    </h4>
                    <div className="space-y-6">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Adet / Birim:</span>
                            {isEditing ? <input type="number" className="w-24 px-3 py-1 rounded-lg text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">{transaction.packageQuantity}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Birim Fiyat (₺):</span>
                            {isEditing ? <input type="number" className="w-32 px-3 py-1 rounded-lg text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">{transaction.packageUnitPriceTl?.toLocaleString('tr-TR')}</span>}
                        </div>
                    </div>
                </div>
                <div className="p-10 bg-black/40 rounded-[40px] border border-violet-500/10 flex flex-col justify-center space-y-5">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={20} className="mr-4" /> ERP / MICRO REFERANS</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-6 rounded-3xl border border-violet-500/20 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-lg text-violet-300 tracking-wider">{isEditing ? <input className="bg-transparent border-none outline-none" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} /> : transaction.microCode || 'TANIMSİZ'}</span>
                        <Copy size={20} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />
                    </div>
                    {copied && <p className="text-[10px] text-violet-500 font-black uppercase text-center animate-pulse">KOD KOPYALANDI!</p>}
                </div>
            </div>

            <div className="space-y-10">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center px-4"><ShieldCheck size={22} className="mr-4" /> DİJİTAL ONAY SÜRECİ</h4>
                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 ${flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-[0_0_20px_rgba(34,197,94,0.4)]' : 'bg-black border-violet-500/30 text-violet-800'}`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                    <div className="flex items-center space-x-4">
                                        <h5 className="font-black text-white text-lg uppercase tracking-tight">{flow.role}</h5>
                                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase border ${flow.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-slate-500/10 text-slate-500 border-slate-500/20'}`}>{flow.status}</span>
                                    </div>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600">{flow.date}</p>
                                </div>
                                <div className="flex items-center space-x-4">
                                    {flow.status === 'Pending' ? (
                                        <div className="flex items-center space-x-2">
                                            <input type="text" placeholder="Karar Notu" className="px-4 py-2 rounded-xl text-xs w-48" value={decisionNote} onChange={e => setDecisionNote(e.target.value)} />
                                            <button onClick={() => handleQuickApprove(flow.role)} className="p-3 bg-violet-600 text-white rounded-xl shadow-lg"><Zap size={20} /></button>
                                            <button onClick={() => fileInputRefs.current[flow.role]?.click()} className="p-3 bg-white text-black rounded-xl"><Camera size={20} /></button>
                                            <input type="file" ref={el => fileInputRefs.current[flow.role] = el} className="hidden" onChange={e => handleSignatureProof(flow.role, e)} />
                                        </div>
                                    ) : (
                                        <div className="flex items-center space-x-3">
                                            {flow.proofUrl && <div className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-violet-500/20 cursor-pointer" onClick={() => setSelectedImage(flow.proofUrl!)}><img src={flow.proofUrl} className="w-full h-full object-cover" /></div>}
                                            <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-violet-400 hover:bg-violet-500/10 rounded-xl transition-all"><Info size={24} /></button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="space-y-6">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest px-4">TALEP GEREKÇESİ</h4>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
            </div>
          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-col sm:flex-row items-center justify-center gap-8">
            <button onClick={handleFinalize} disabled={transaction.status === 'Approved' || !allApproved} className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${allApproved ? 'opacity-100 neon-glow-violet' : 'opacity-20 cursor-not-allowed'}`}>
              <Archive size={24} className="inline mr-4" /> DOSYAYI TAMAMLA VE ARŞİVLE
            </button>
            {transaction.status !== 'Rejected' && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-16 py-6 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all">
                <XCircle size={24} className="inline mr-4" /> DOSYAYI İPTAL ET
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">İŞLEM GÜNLÜĞÜ</h3>
          </div>
          <div className="p-8 space-y-8 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="relative pl-8 border-l border-violet-500/20 pb-8 last:pb-0">
                <div className="absolute left-[-6px] top-0 w-3 h-3 rounded-full bg-violet-500 shadow-[0_0_10px_rgba(139,92,246,0.8)]"></div>
                <div className="flex justify-between items-center mb-1">
                  <span className="font-black text-[10px] text-violet-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <p className="text-xs text-slate-400 leading-snug"><span className="text-white font-bold">{log.action}:</span> {log.details}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Cyber Premium UI başarıyla yüklendi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !selectedTransactionId && activeTab !== 'dashboard') {
        setActiveTab('dashboard');
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Yönetici girişi yapıldı: ${user.username}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı sistemden ayrıldı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `KL-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPriceTl: request.packageUnitPriceTl || 0,
      totalAmount: (request.packageQuantity || 1) * (request.packageUnitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Yeni Talep', `${newTransaction.productSetName} için ${newTransaction.totalAmount} TL bedelli talep oluşturuldu.`);
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Approved' ? 'Dosya Arşivlendi' : `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Admin', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Değişikliği', `Kayıt #${id} statüsü değiştirildi: ${newStatus}`);

    if (newStatus === 'Approved') {
        setStatusFilter('Approved');
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (updates.packageQuantity !== undefined || updates.packageUnitPriceTl !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPriceTl || 0);
          }
          return updated;
        }
        return t;
      })
    }));
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); if (tab !== 'transactions') setStatusFilter(null); }} user={state.user} onLogout={handleLogout}>
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={(id) => { setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) })); setSelectedTransactionId(null); setActiveTab('transactions'); }} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">DİJİTAL ARŞİV</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Filtreli Veriler` : 'Tüm Kayıtların Merkezi Deposu'}</p>
                </div>
                <div className="flex bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10">
                  <button onClick={() => setStatusFilter(null)} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-6 py-3 rounded-xl text-[11px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>ONAYLI</button>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.map((t) => (
                  <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                    <div className="flex justify-between items-start mb-8 relative z-10">
                      <div className="w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl">{t.requesterName.charAt(0)}</div>
                      <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${t.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-violet-500/10 text-violet-400 border-violet-500/20'}`}>{t.status}</span>
                    </div>
                    <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                    <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-10">{t.department} • {t.supplierName}</p>
                    <div className="flex justify-between items-end border-t border-violet-500/10 pt-8">
                       <div>
                          <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Tutarı</p>
                          <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       </div>
                       <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} departments={state.departments} setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} user={state.user} onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} systemLogs={state.systemLogs} transactions={state.transactions} onBack={() => setActiveTab('dashboard')} />}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3,
  CreditCard,
  ImagePlus
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const handleFinalize = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Sözlü Onay Verildi (Dijital Kayıt)' 
      } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Onay Güncelleme',
        details: `${role} adımı dijital olarak onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: f.status === 'Pending' ? 'Approved' as const : f.status, 
            date: f.date || new Date().toLocaleString('tr-TR') 
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belge Ekleme',
            details: `${role} adımı için görsel kanıt sisteme eklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Resim Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-violet-400 bg-white/5 rounded-full hover:bg-white/10 transition-all"><X size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[80vh] rounded-3xl neon-glow-violet shadow-[0_0_100px_rgba(139,92,246,0.4)]" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-12 rounded-[50px] border border-violet-500/20 relative">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-10">
                <div className="w-20 h-20 neon-gradient-premium rounded-[30px] flex items-center justify-center text-white shadow-lg"><UserCheck size={40} /></div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>
            <div className="space-y-6">
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">KARAR STATÜSÜ</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status}</span>
                    </div>
                </div>
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">ONAYLAYICI NOTU</p>
                    <p className="text-xs text-slate-400 italic leading-relaxed">"{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'İşlem notu bırakılmamış.'}"</p>
                </div>

                <div className="space-y-4">
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">GÖRSEL KANIT / BELGE</p>
                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div className="w-full h-48 rounded-[30px] overflow-hidden border border-violet-500/20 cursor-pointer relative group" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Maximize2 className="text-white" size={24} />
                      </div>
                    </div>
                  ) : (
                    <div className="w-full py-10 border border-dashed border-violet-500/20 rounded-[30px] flex flex-col items-center justify-center text-slate-500">
                      <ImagePlus size={32} className="mb-2 opacity-20" />
                      <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Henüz belge yüklenmedi</span>
                    </div>
                  )}

                  <button 
                    onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()}
                    className="w-full py-4 bg-violet-600/10 text-violet-400 rounded-2xl border border-violet-500/20 font-black text-[10px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-lg"
                  >
                    {transaction.approvalFlow[selectedFlowDetail].proofUrl ? 'BELGEYİ GÜNCELLE' : 'BELGE / RESİM EKLE'}
                  </button>
                  <input 
                    type="file" 
                    ref={el => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role] = el} 
                    className="hidden" 
                    onChange={e => handleSignatureProof(transaction.approvalFlow[selectedFlowDetail!].role, e)} 
                    accept="image/*"
                  />
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>LİSTEYE DÖN <span className="opacity-30 ml-2">(ESC)</span></span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">GÜNCELLE</button>
            )}
            <button onClick={() => window.confirm('Kaydı silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative shadow-2xl">
          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-violet-500/5 rounded-full blur-[100px]"></div>
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 
                    transaction.status === 'Rejected' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose' :
                    'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>{transaction.status === 'Approved' ? 'ARŞİVLENDİ' : transaction.status}</span>
                </div>
                <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • SORUMLU: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL (KDV DAHİL)</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            {/* Maliyet Analizi Paneli */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="p-10 bg-violet-950/30 rounded-[40px] border border-violet-500/10 space-y-8 shadow-inner">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={20} className="mr-4" /> MİKTAR & FİYAT ANALİZİ
                    </h4>
                    <div className="space-y-6">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Adet / Birim:</span>
                            {isEditing ? <input type="number" className="w-24 px-3 py-1 rounded-lg text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">{transaction.packageQuantity}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Birim Fiyat:</span>
                            {isEditing ? <input type="number" className="w-32 px-3 py-1 rounded-lg text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">₺{transaction.packageUnitPriceTl?.toLocaleString('tr-TR')}</span>}
                        </div>
                    </div>
                </div>
                <div className="p-10 bg-black/40 rounded-[40px] border border-violet-500/10 flex flex-col justify-center space-y-5">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={20} className="mr-4" /> ERP / MICRO KAYDI</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-6 rounded-3xl border border-violet-500/20 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-lg text-violet-300 tracking-wider uppercase">{isEditing ? <input className="bg-transparent border-none outline-none w-full" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} /> : transaction.microCode || 'TANIMSİZ'}</span>
                        <Copy size={20} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />
                    </div>
                    {copied && <p className="text-[10px] text-violet-500 font-black uppercase text-center animate-pulse">PANEYE KOPYALANDI!</p>}
                </div>
            </div>

            {/* Onay Akış Paneli */}
            <div className="space-y-10">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center px-4"><ShieldCheck size={22} className="mr-4" /> DİJİTAL ONAY SİSTEMİ</h4>
                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 transition-all duration-500 ${
                                flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-[0_0_25px_rgba(34,197,94,0.5)]' : 
                                flow.status === 'Rejected' ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_25px_rgba(244,63,94,0.5)]' :
                                'bg-black border-violet-500/30 text-violet-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={24} /> :
                                 <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                    <div className="flex items-center space-x-4">
                                        <h5 className="font-black text-white text-lg uppercase tracking-tight group-hover:text-violet-400 transition-colors">{flow.role}</h5>
                                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase border ${
                                          flow.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 shadow-sm' : 
                                          flow.status === 'Rejected' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20 shadow-sm' :
                                          'bg-slate-500/10 text-slate-500 border-slate-500/20'
                                        }`}>{flow.status}</span>
                                    </div>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono">{flow.date || 'Bekliyor'}</p>
                                </div>
                                <div className="flex items-center space-x-4">
                                    <div className="flex items-center space-x-2">
                                        {flow.status === 'Pending' && (
                                          <>
                                            <input 
                                                type="text" 
                                                placeholder="İşlem Notu..." 
                                                className="px-4 py-3 rounded-xl text-xs w-48 bg-black/40 border border-violet-500/20 focus:border-violet-500 outline-none" 
                                                value={decisionNote} 
                                                onChange={e => setDecisionNote(e.target.value)} 
                                            />
                                            <button onClick={() => handleQuickApprove(flow.role)} className="p-3 bg-violet-600 text-white rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all" title="Hızlı Onay"><Zap size={20} /></button>
                                          </>
                                        )}

                                        {/* Arşivli dahi olsa resim eklemeye izin veren buton */}
                                        <button 
                                          onClick={() => fileInputRefs.current[flow.role]?.click()} 
                                          className={`p-3 rounded-xl transition-all shadow-lg hover:scale-105 active:scale-95 ${
                                            flow.proofUrl ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-white text-black'
                                          }`}
                                          title={flow.proofUrl ? 'Resmi Güncelle' : 'Resim Ekle'}
                                        >
                                          {flow.proofUrl ? <ImagePlus size={20} /> : <Camera size={20} />}
                                        </button>
                                        <input 
                                          type="file" 
                                          ref={el => fileInputRefs.current[flow.role] = el} 
                                          className="hidden" 
                                          onChange={e => handleSignatureProof(flow.role, e)} 
                                          accept="image/*"
                                        />

                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-violet-400 hover:bg-violet-500/10 rounded-xl transition-all"><Info size={24} /></button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="space-y-6">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest px-4">TALEP GEREKÇESİ</h4>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
            </div>
          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-col sm:flex-row items-center justify-center gap-8">
            <button 
              onClick={handleFinalize} 
              disabled={transaction.status === 'Approved' || !allApproved} 
              className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${
                allApproved && transaction.status !== 'Approved' ? 'opacity-100 neon-glow-violet' : 'opacity-20 cursor-not-allowed'
              }`}
            >
              <Archive size={24} className="inline mr-4" /> DOSYAYI TAMAMLA VE ARŞİVLE
            </button>
            {transaction.status !== 'Rejected' && transaction.status !== 'Approved' && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-16 py-6 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all shadow-lg active:scale-95">
                <XCircle size={24} className="inline mr-4" /> DOSYAYI İPTAL ET
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">İŞLEM GÜNLÜĞÜ</h3>
          </div>
          <div className="p-8 space-y-8 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="relative pl-8 border-l border-violet-500/20 pb-8 last:pb-0">
                <div className="absolute left-[-6px] top-0 w-3 h-3 rounded-full bg-violet-500 shadow-[0_0_15px_rgba(139,92,246,0.8)]"></div>
                <div className="flex justify-between items-center mb-1">
                  <span className="font-black text-[10px] text-violet-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <p className="text-xs text-slate-400 leading-snug"><span className="text-white font-bold">{log.action}:</span> {log.details}</p>
              </div>
            ))}
            {transaction.logs.length === 0 && <p className="text-center py-10 text-[10px] text-slate-500 font-black uppercase tracking-widest">Kayıt bulunmuyor</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3,
  CreditCard,
  ImagePlus,
  PauseCircle,
  PlayCircle
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const handleFinalize = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const handleSuspend = () => {
    // Mevcut değişiklikleri kaydet ve statüyü "On Hold" yap
    onUpdate(transaction.id, { 
      status: 'On Hold',
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Dosya Askıya Alındı',
        details: 'Kısmi onaylar kaydedildi ve süreç donduruldu.'
      }, ...transaction.logs]
    });
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Dijital Onay (Münferit)' 
      } : f
    );
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Kısmi Onay',
        details: `${role} adımı onaylandı. Süreç devam ediyor.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR') 
          } : f
        );
        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belge/Resim Ekleme',
            details: `${role} için görsel kanıt sisteme işlendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');
  const someApproved = transaction.approvalFlow.some(f => f.status === 'Approved');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Resim Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-violet-400 bg-white/5 rounded-full hover:bg-white/10 transition-all"><X size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[80vh] rounded-3xl shadow-[0_0_100px_rgba(139,92,246,0.4)] border border-violet-500/20" alt="Önizleme" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-12 rounded-[50px] border border-violet-500/20 relative shadow-[0_0_100px_rgba(0,0,0,0.8)]">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-10">
                <div className="w-20 h-20 neon-gradient-premium rounded-[30px] flex items-center justify-center text-white shadow-lg"><UserCheck size={40} /></div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>
            <div className="space-y-6">
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">KARAR STATÜSÜ</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status}</span>
                    </div>
                </div>
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">ONAYLAYICI NOTU</p>
                    <p className="text-xs text-slate-400 italic leading-relaxed">"{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'İşlem notu bırakılmamış.'}"</p>
                </div>

                <div className="space-y-4">
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">GÖRSEL KANIT / BELGE</p>
                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div className="w-full h-48 rounded-[30px] overflow-hidden border border-violet-500/20 cursor-pointer relative group" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Proof" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Maximize2 className="text-white" size={24} />
                      </div>
                    </div>
                  ) : (
                    <div className="w-full py-10 border border-dashed border-violet-500/20 rounded-[30px] flex flex-col items-center justify-center text-slate-500">
                      <ImagePlus size={32} className="mb-2 opacity-20" />
                      <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Henüz belge yüklenmedi</span>
                    </div>
                  )}

                  <button 
                    onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()}
                    className="w-full py-4 bg-violet-600/10 text-violet-400 rounded-2xl border border-violet-500/20 font-black text-[10px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-lg"
                  >
                    {transaction.approvalFlow[selectedFlowDetail].proofUrl ? 'BELGEYİ GÜNCELLE' : 'RESİM / BELGE YÜKLE'}
                  </button>
                  <input 
                    type="file" 
                    ref={el => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role] = el} 
                    className="hidden" 
                    onChange={e => handleSignatureProof(transaction.approvalFlow[selectedFlowDetail!].role, e)} 
                    accept="image/*"
                  />
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>LİSTEYE DÖN <span className="opacity-30 ml-2">(ESC)</span></span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">GÜNCELLE</button>
            )}
            <button onClick={() => window.confirm('Kaydı silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative shadow-2xl">
          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-64 h-64 bg-violet-500/5 rounded-full blur-[100px]"></div>
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 
                    transaction.status === 'On Hold' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20 neon-glow-cyan' :
                    transaction.status === 'Rejected' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose' :
                    'bg-violet-500/10 text-violet-400 border-violet-500/20'
                  }`}>{
                    transaction.status === 'Approved' ? 'ARŞİVLENDİ' : 
                    transaction.status === 'On Hold' ? 'ASKIDA / İŞLEMDE' : 
                    transaction.status
                  }</span>
                </div>
                <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">DOSYA NO: #{transaction.id} • SORUMLU: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL (KDV DAHİL)</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="p-10 bg-violet-950/30 rounded-[40px] border border-violet-500/10 space-y-8 shadow-inner">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={20} className="mr-4" /> MİKTAR & FİYAT ANALİZİ
                    </h4>
                    <div className="space-y-6">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Adet / Birim:</span>
                            {isEditing ? <input type="number" className="w-24 px-3 py-1 rounded-lg text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">{transaction.packageQuantity}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Birim Fiyat:</span>
                            {isEditing ? <input type="number" className="w-32 px-3 py-1 rounded-lg text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">₺{transaction.packageUnitPriceTl?.toLocaleString('tr-TR')}</span>}
                        </div>
                    </div>
                </div>
                <div className="p-10 bg-black/40 rounded-[40px] border border-violet-500/10 flex flex-col justify-center space-y-5">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={20} className="mr-4" /> ERP / MICRO KAYDI</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-6 rounded-3xl border border-violet-500/20 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-lg text-violet-300 tracking-wider uppercase">{isEditing ? <input className="bg-transparent border-none outline-none w-full" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} /> : transaction.microCode || 'TANIMSİZ'}</span>
                        <Copy size={20} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />
                    </div>
                    {copied && <p className="text-[10px] text-violet-500 font-black uppercase text-center animate-pulse">PANEYE KOPYALANDI!</p>}
                </div>
            </div>

            <div className="space-y-10">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><ShieldCheck size={22} className="mr-4" /> DİJİTAL ONAY SİSTEMİ</h4>
                  <div className="flex items-center space-x-2 text-[10px] font-black text-cyan-400 animate-pulse">
                    <Clock size={14} />
                    <span>SIRALI ONAY GEREKMEZ</span>
                  </div>
                </div>
                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 transition-all duration-500 ${
                                flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-[0_0_25px_rgba(34,197,94,0.5)]' : 
                                flow.status === 'Rejected' ? 'bg-rose-500 border-rose-400 text-white shadow-[0_0_25px_rgba(244,63,94,0.5)]' :
                                'bg-black border-violet-500/30 text-violet-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : 
                                 flow.status === 'Rejected' ? <XCircle size={24} /> :
                                 <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                    <div className="flex items-center space-x-4">
                                        <h5 className="font-black text-white text-lg uppercase tracking-tight group-hover:text-violet-400 transition-colors">{flow.role}</h5>
                                        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase border ${
                                          flow.status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 shadow-sm' : 
                                          flow.status === 'Rejected' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20 shadow-sm' :
                                          'bg-slate-500/10 text-slate-500 border-slate-500/20'
                                        }`}>{flow.status}</span>
                                    </div>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono">{flow.date || 'Karar Bekliyor'}</p>
                                </div>
                                <div className="flex items-center space-x-4">
                                    <div className="flex items-center space-x-2">
                                        {flow.status === 'Pending' && (
                                          <>
                                            <input 
                                                type="text" 
                                                placeholder="Karar Notu..." 
                                                className="px-4 py-3 rounded-xl text-xs w-48 bg-black/40 border border-violet-500/20 focus:border-violet-500 outline-none" 
                                                value={decisionNote} 
                                                onChange={e => setDecisionNote(e.target.value)} 
                                            />
                                            <button onClick={() => handleQuickApprove(flow.role)} className="p-3 bg-violet-600 text-white rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all" title="Hızlı Onay"><Zap size={20} /></button>
                                          </>
                                        )}

                                        <button 
                                          onClick={() => fileInputRefs.current[flow.role]?.click()} 
                                          className={`p-3 rounded-xl transition-all shadow-lg hover:scale-105 active:scale-95 ${
                                            flow.proofUrl ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-white text-black'
                                          }`}
                                          title={flow.proofUrl ? 'Resmi Güncelle' : 'Resim/Belge Ekle'}
                                        >
                                          {flow.proofUrl ? <ImagePlus size={20} /> : <Camera size={20} />}
                                        </button>
                                        <input 
                                          type="file" 
                                          ref={el => fileInputRefs.current[flow.role] = el} 
                                          className="hidden" 
                                          onChange={e => handleSignatureProof(flow.role, e)} 
                                          accept="image/*"
                                        />

                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-violet-400 hover:bg-violet-500/10 rounded-xl transition-all"><Info size={24} /></button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="space-y-6">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest px-4">TALEP GEREKÇESİ</h4>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
            </div>
          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-col sm:flex-row items-center justify-center gap-8">
            <button 
              onClick={handleSuspend} 
              disabled={transaction.status === 'Approved'}
              className="px-12 py-6 bg-cyan-600/10 border border-cyan-600/20 text-cyan-400 rounded-3xl font-black text-sm uppercase tracking-widest hover:bg-cyan-600 hover:text-white transition-all shadow-lg active:scale-95 flex items-center group"
            >
              <PauseCircle size={24} className="mr-4 group-hover:animate-pulse" />
              HAREKETİ KAYDET VE ASKIYA AL
            </button>

            <button 
              onClick={handleFinalize} 
              disabled={transaction.status === 'Approved' || !allApproved} 
              className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${
                allApproved && transaction.status !== 'Approved' ? 'opacity-100 neon-glow-violet' : 'opacity-20 cursor-not-allowed'
              }`}
            >
              <Archive size={24} className="inline mr-4" /> DOSYAYI ARŞİVLE
            </button>
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">İŞLEM GÜNLÜĞÜ</h3>
          </div>
          <div className="p-8 space-y-8 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="relative pl-8 border-l border-violet-500/20 pb-8 last:pb-0">
                <div className="absolute left-[-6px] top-0 w-3 h-3 rounded-full bg-violet-500 shadow-[0_0_15px_rgba(139,92,246,0.8)]"></div>
                <div className="flex justify-between items-center mb-1">
                  <span className="font-black text-[10px] text-violet-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <p className="text-xs text-slate-400 leading-snug"><span className="text-white font-bold">{log.action}:</span> {log.details}</p>
              </div>
            ))}
            {transaction.logs.length === 0 && <p className="text-center py-10 text-[10px] text-slate-500 font-black uppercase tracking-widest">Kayıt bulunmuyor</p>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

export interface RoleDefinition {
  id: string;
  roleName: string;
  assignedName: string;
}

export type Role = string; 

export interface LogEntry {
  id: string;
  timestamp: string;
  user: string;
  action: string;
  details: string;
}

export interface ExtraItem {
  id: string;
  name: string;
  quantity: number;
}

export interface Transaction {
  id: string;
  productSetName: string;
  supplierName: string;
  department: string;
  usageLocation: string;
  requesterName: string;
  requestDateTime: string;
  packageContent?: string;
  quantity: number;
  packageQuantity?: number;
  unitPriceTl: number;
  packageUnitPriceTl?: number;
  totalAmount: number;
  description: string;
  justification: string;
  microCode: string;
  status: 'Pending' | 'Approved' | 'Purchased' | 'Rejected' | 'On Hold';
  extraItems: ExtraItem[];
  photoUrl?: string;
  logs: LogEntry[];
  approvalFlow: {
    role: string;
    status: 'Pending' | 'Approved' | 'Rejected';
    approverName?: string;
    date?: string;
    proofUrl?: string;
    decisionNote?: string;
  }[];
}

export interface User {
  username: string;
  role: string;
  name: string;
}

export interface SystemLog {
  id: string;
  timestamp: string;
  user: string;
  module: 'AUTH' | 'PURCHASE' | 'ROLES' | 'DEPTS' | 'PROFILE';
  action: string;
  details: string;
}

export interface AppState {
  user: User | null;
  transactions: Transaction[];
  roles: RoleDefinition[];
  departments: string[];
  systemLogs: SystemLog[];
}

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3,
  CreditCard,
  ImagePlus,
  PauseCircle,
  PlayCircle,
  ShoppingBag
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPriceTl || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPriceTl, isEditing]);

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  const handleApprove = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const handlePurchase = () => {
    onStatusChange(transaction.id, 'Purchased');
    onBack();
  };

  const handleSuspend = () => {
    onUpdate(transaction.id, { 
      status: 'On Hold',
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Askıya Alındı',
        details: 'Talep geçici olarak beklemeye alındı.'
      }, ...transaction.logs]
    });
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, editForm);
    setIsEditing(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Dijital Onay Verildi' 
      } : f
    );

    // Check if this was the last signature
    const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      status: isNowFullyApproved ? 'Approved' : transaction.status,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Kısmi Onay',
        details: `${role} adımı onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR') 
          } : f
        );

        const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          status: isNowFullyApproved ? 'Approved' : transaction.status,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Sistem',
            action: 'Belge Eklendi',
            details: `${role} için görsel kanıt yüklendi.`
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Resim Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-violet-400 bg-white/5 rounded-full hover:bg-white/10 transition-all"><X size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[80vh] rounded-3xl shadow-[0_0_100px_rgba(139,92,246,0.4)] border border-violet-500/20" alt="Belge" />
        </div>
      )}

      {/* Akış Detay Modal */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-12 rounded-[50px] border border-violet-500/20 relative shadow-2xl">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-10">
                <div className="w-20 h-20 neon-gradient-premium rounded-[30px] flex items-center justify-center text-white"><UserCheck size={40} /></div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-xs font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>
            <div className="space-y-6">
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">ONAY DURUMU</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekliyor'}</span>
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status}</span>
                    </div>
                </div>
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">NOTLAR</p>
                    <p className="text-xs text-slate-400 italic">"{transaction.approvalFlow[selectedFlowDetail].decisionNote || 'Not yok.'}"</p>
                </div>

                <div className="space-y-4">
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">DİJİTAL KANIT</p>
                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div className="w-full h-48 rounded-[30px] overflow-hidden border border-violet-500/20 cursor-pointer relative group" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover" alt="Proof" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center"><Maximize2 className="text-white" size={24} /></div>
                    </div>
                  ) : (
                    <div className="w-full py-10 border border-dashed border-violet-500/20 rounded-[30px] flex flex-col items-center justify-center text-slate-500">
                      <ImagePlus size={32} className="mb-2 opacity-20" />
                      <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Görsel kanıt yok</span>
                    </div>
                  )}

                  <button onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()} className="w-full py-4 bg-violet-600/10 text-violet-400 rounded-2xl border border-violet-500/20 font-black text-[10px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-lg">GÖRSEL EKLE / GÜNCELLE</button>
                  <input type="file" ref={el => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role] = el} className="hidden" onChange={e => handleSignatureProof(transaction.approvalFlow[selectedFlowDetail!].role, e)} accept="image/*" />
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>LİSTEYE DÖN</span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Talebi silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all"><Trash2 size={20} /></button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative shadow-2xl">
          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20 relative">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div>
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20 neon-glow-green' : 
                    transaction.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20 neon-glow-cyan' :
                    transaction.status === 'Rejected' ? 'bg-rose-500/10 text-rose-400 border-rose-500/20 neon-glow-rose' :
                    'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>
                    {transaction.status === 'Pending' ? 'BEKLEYEN' : 
                     transaction.status === 'Approved' ? 'ONAYLI' : 
                     transaction.status === 'Purchased' ? 'SATIN ALINDI' : 
                     transaction.status === 'On Hold' ? 'ASKIDA' : 'İPTAL'}
                  </span>
                </div>
                <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">İŞLEM: #{transaction.id} • SORUMLU: {transaction.requesterName}</p>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM TUTAR</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="p-10 bg-violet-950/30 rounded-[40px] border border-violet-500/10 space-y-8">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={20} className="mr-4" /> BİRİM ANALİZİ
                    </h4>
                    <div className="space-y-6">
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Birim Adedi:</span>
                            {isEditing ? <input type="number" className="w-24 px-3 py-1 rounded-lg text-right" value={editForm.packageQuantity} onChange={e => setEditForm({...editForm, packageQuantity: parseInt(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">{transaction.packageQuantity}</span>}
                        </div>
                        <div className="flex justify-between items-center text-sm">
                            <span className="text-violet-800 uppercase font-black">Birim Fiyatı:</span>
                            {isEditing ? <input type="number" className="w-32 px-3 py-1 rounded-lg text-right" value={editForm.packageUnitPriceTl} onChange={e => setEditForm({...editForm, packageUnitPriceTl: parseFloat(e.target.value) || 0})} /> : <span className="text-white font-black text-lg">₺{transaction.packageUnitPriceTl?.toLocaleString('tr-TR')}</span>}
                        </div>
                    </div>
                </div>
                <div className="p-10 bg-black/40 rounded-[40px] border border-violet-500/10 flex flex-col justify-center space-y-5">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={20} className="mr-4" /> ERP / MICRO KODU</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-6 rounded-3xl border border-violet-500/20 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-lg text-violet-300 tracking-wider uppercase">{isEditing ? <input className="bg-transparent border-none outline-none w-full" value={editForm.microCode} onChange={e => setEditForm({...editForm, microCode: e.target.value})} /> : transaction.microCode || 'BELİRTİLMEDİ'}</span>
                        <Copy size={20} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />
                    </div>
                    {copied && <p className="text-[10px] text-violet-500 font-black uppercase text-center animate-pulse">PANEYE KOPYALANDI!</p>}
                </div>
            </div>

            <div className="space-y-10">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><ShieldCheck size={22} className="mr-4" /> DİJİTAL ONAY SİSTEMİ</h4>
                </div>
                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 transition-all duration-500 ${
                                flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-lg' : 
                                'bg-black border-violet-500/30 text-violet-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                    <h5 className="font-black text-white text-lg uppercase tracking-tight group-hover:text-violet-400 transition-colors">{flow.role}</h5>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono">{flow.date || 'Bekliyor'}</p>
                                </div>
                                <div className="flex items-center space-x-4">
                                    <div className="flex items-center space-x-2">
                                        {flow.status === 'Pending' && (
                                          <>
                                            <input 
                                                type="text" 
                                                placeholder="Karar Notu..." 
                                                className="px-4 py-3 rounded-xl text-xs w-48 bg-black/40 border border-violet-500/20 outline-none focus:border-violet-500 transition-colors" 
                                                value={decisionNote} 
                                                onChange={e => setDecisionNote(e.target.value)} 
                                            />
                                            <button onClick={() => handleQuickApprove(flow.role)} className="p-3 bg-violet-600 text-white rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all"><Zap size={20} /></button>
                                          </>
                                        )}
                                        <button onClick={() => fileInputRefs.current[flow.role]?.click()} className={`p-3 rounded-xl transition-all shadow-lg ${flow.proofUrl ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-white text-black'}`}>
                                          {flow.proofUrl ? <ImagePlus size={20} /> : <Camera size={20} />}
                                        </button>
                                        <input type="file" ref={el => fileInputRefs.current[flow.role] = el} className="hidden" onChange={e => handleSignatureProof(flow.role, e)} accept="image/*" />
                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-violet-400 hover:bg-violet-500/10 rounded-xl transition-all"><Info size={24} /></button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="space-y-6">
                <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest px-4">SATIN ALMA GEREKÇESİ</h4>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
            </div>
          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-wrap items-center justify-center gap-6 lg:gap-10">
            {transaction.status !== 'Purchased' && transaction.status !== 'Approved' && (
              <button onClick={handleSuspend} className="px-10 py-5 bg-amber-600/10 border border-amber-600/20 text-amber-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-amber-600 hover:text-white transition-all shadow-lg active:scale-95 flex items-center group">
                <PauseCircle size={20} className="mr-3" /> ASKIYA AL / KAYDET
              </button>
            )}

            {transaction.status === 'Approved' ? (
              <button onClick={handlePurchase} className="px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all neon-glow-green flex items-center">
                <ShoppingBag size={24} className="mr-4" /> SATIN ALINDI OLARAK İŞARETLE
              </button>
            ) : transaction.status !== 'Purchased' ? (
              <button 
                onClick={handleApprove} 
                disabled={!allApproved} 
                className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${
                  allApproved ? 'opacity-100 neon-glow-cyan' : 'opacity-20 cursor-not-allowed'
                } flex items-center`}
              >
                <CheckCircle2 size={24} className="mr-4" /> ONAYLA VE BÜTÇEYİ BAĞLA
              </button>
            ) : null}

            {(transaction.status === 'Pending' || transaction.status === 'On Hold') && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-10 py-5 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all shadow-lg active:scale-95 flex items-center">
                <XCircle size={20} className="mr-3" /> TALEBİ İPTAL ET
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">SİSTEM KAYITLARI</h3>
          </div>
          <div className="p-8 space-y-8 max-h-[600px] overflow-y-auto custom-scroll">
            {transaction.logs.map((log) => (
              <div key={log.id} className="relative pl-8 border-l border-violet-500/20 pb-8 last:pb-0">
                <div className="absolute left-[-6px] top-0 w-3 h-3 rounded-full bg-violet-500 shadow-[0_0_15px_rgba(139,92,246,0.8)]"></div>
                <div className="flex justify-between items-center mb-1">
                  <span className="font-black text-[10px] text-violet-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                </div>
                <p className="text-xs text-slate-400 leading-snug"><span className="text-white font-bold">{log.action}:</span> {log.details}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useMemo, useState, useEffect } from 'react';
import { 
  TrendingUp, 
  Clock, 
  AlertCircle, 
  Wallet,
  Target,
  ChevronRight,
  Building2,
  Calendar,
  Layers,
  ShoppingBag,
  Hash,
  ArrowUpRight,
  PieChart as PieChartIcon,
  CheckCircle2
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell
} from 'recharts';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);

  // Use 'Purchased' for actual spending metrics
  const totalSpending = transactions
    .filter(t => t.status === 'Purchased')
    .reduce((sum, t) => sum + t.totalAmount, 0);

  const pendingCount = transactions.filter(t => t.status === 'Pending').length;
  const approvedCount = transactions.filter(t => t.status === 'Approved').length;

  const monthlyAnalysis = useMemo(() => {
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const analysis: Record<string, any> = {};

    transactions.filter(t => t.status === 'Purchased').forEach(t => {
      const date = new Date(t.requestDateTime);
      const monthLabel = months[date.getMonth()];

      if (!analysis[monthLabel]) {
        analysis[monthLabel] = { 
          month: monthLabel, 
          monthIndex: date.getMonth(), 
          total: 0, 
          count: 0,
          suppliers: {} as Record<string, number>, 
          departments: {} as Record<string, number> 
        };
      }

      analysis[monthLabel].total += t.totalAmount;
      analysis[monthLabel].count += 1;

      if (!analysis[monthLabel].suppliers[t.supplierName]) analysis[monthLabel].suppliers[t.supplierName] = 0;
      analysis[monthLabel].suppliers[t.supplierName] += t.totalAmount;

      if (!analysis[monthLabel].departments[t.department]) analysis[monthLabel].departments[t.department] = 0;
      analysis[monthLabel].departments[t.department] += t.totalAmount;
    });

    return Object.values(analysis).sort((a: any, b: any) => a.monthIndex - b.monthIndex);
  }, [transactions]);

  useEffect(() => {
    if (monthlyAnalysis.length > 0 && !selectedMonth) {
      setSelectedMonth(monthlyAnalysis[monthlyAnalysis.length - 1].month);
    }
  }, [monthlyAnalysis, selectedMonth]);

  const selectedMonthData = useMemo(() => {
    return monthlyAnalysis.find(m => m.month === selectedMonth) || null;
  }, [monthlyAnalysis, selectedMonth]);

  const sortedSuppliers = useMemo(() => {
    if (!selectedMonthData) return [];
    return Object.entries(selectedMonthData.suppliers)
      .sort(([, a], [, b]) => (b as number) - (a as number))
      .slice(0, 5);
  }, [selectedMonthData]);

  const sortedDepartments = useMemo(() => {
    if (!selectedMonthData) return [];
    return Object.entries(selectedMonthData.departments)
      .sort(([, a], [, b]) => (b as number) - (a as number))
      .slice(0, 5);
  }, [selectedMonthData]);

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-4xl font-black text-white neon-text tracking-tighter uppercase">SÜREÇ ANALİTİĞİ</h2>
          <p className="text-violet-400 font-bold text-sm mt-1">Harcanan bütçe ve onay akış projeksiyonu</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <button onClick={() => onFilterClick('Purchased')} className="cyber-card glass-panel p-8 rounded-[40px] border border-violet-500/10 flex items-center space-x-6 hover:border-violet-500/40 transition-all text-left relative overflow-hidden group">
          <div className="p-5 bg-green-500/10 text-green-400 rounded-2xl border border-green-500/20 group-hover:neon-glow-green transition-all shadow-lg">
            <ShoppingBag size={28} />
          </div>
          <div>
            <p className="text-[10px] text-violet-400 font-black uppercase tracking-widest mb-1 opacity-70">TOPLAM HARCAMA</p>
            <h3 className="text-3xl font-black text-white neon-text-premium">₺{totalSpending.toLocaleString('tr-TR')}</h3>
            <span className="text-[8px] text-green-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">ÖDENEN TALEPLER</span>
          </div>
        </button>

        <button onClick={() => onFilterClick('Pending')} className="cyber-card glass-panel p-8 rounded-[40px] border border-violet-500/10 flex items-center space-x-6 hover:border-amber-500/40 transition-all text-left relative overflow-hidden group">
          <div className="p-5 bg-amber-500/10 text-amber-500 rounded-2xl border border-amber-500/20 group-hover:bg-amber-600 group-hover:text-white transition-all">
            <Clock size={28} />
          </div>
          <div>
            <p className="text-[10px] text-violet-400 font-black uppercase tracking-widest mb-1 opacity-70">BEKLEYEN ONAY</p>
            <h3 className="text-3xl font-black text-white neon-text">{pendingCount} <span className="text-sm font-bold opacity-40">DOSYA</span></h3>
            <span className="text-[8px] text-amber-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">İMZA SÜRECİNDE</span>
          </div>
        </button>

        <button onClick={() => onFilterClick('Approved')} className="cyber-card glass-panel p-8 rounded-[40px] border border-violet-500/10 flex items-center space-x-6 hover:border-cyan-500/40 transition-all text-left relative overflow-hidden group">
          <div className="p-5 bg-cyan-500/10 text-cyan-400 rounded-2xl border border-cyan-500/20 group-hover:neon-glow-cyan transition-all">
            <CheckCircle2 size={28} />
          </div>
          <div>
            <p className="text-[10px] text-violet-400 font-black uppercase tracking-widest mb-1 opacity-70">ONAYLI / SATIN ALIM BEKLEYEN</p>
            <h3 className="text-3xl font-black text-white neon-text">{approvedCount} <span className="text-sm font-bold opacity-40">DOSYA</span></h3>
            <span className="text-[8px] text-cyan-500 font-bold uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">BÜTÇE AYRILDI</span>
          </div>
        </button>
      </div>

      <div className="space-y-8">
        <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-violet-500/10 shadow-2xl relative overflow-hidden">
          <div className="flex flex-col md:flex-row md:items-center justify-between mb-12 gap-6 relative z-10">
            <div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center">
                <TrendingUp size={24} className="mr-3 text-violet-400" /> HARCAMA PERFORMANSI
              </h3>
              <p className="text-violet-400 text-[10px] font-black uppercase tracking-widest mt-1 opacity-60">Aylık bazda gerçekleşen satın alımlar</p>
            </div>
          </div>

          <div className="h-[400px] w-full relative z-10">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyAnalysis} onClick={(data) => data && data.activeLabel && setSelectedMonth(data.activeLabel)}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e1b4b" vertical={false} opacity={0.3} />
                <XAxis dataKey="month" stroke="#8b5cf6" fontSize={11} fontWeight="bold" tickLine={false} axisLine={false} dy={10} />
                <YAxis stroke="#8b5cf6" fontSize={10} fontWeight="bold" tickLine={false} axisLine={false} tickFormatter={(val) => `₺${val >= 1000 ? (val/1000).toFixed(0) + 'k' : val}`} />
                <Tooltip 
                  cursor={{fill: 'rgba(139, 92, 246, 0.08)'}}
                  contentStyle={{ backgroundColor: '#020617', borderRadius: '30px', border: '1px solid rgba(139,92,246,0.3)', boxShadow: '0 20px 50px rgba(0,0,0,0.8)' }}
                  itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                  labelStyle={{ color: '#8b5cf6', fontWeight: '900', textTransform: 'uppercase', fontSize: '14px', marginBottom: '8px' }}
                />
                <Bar dataKey="total" radius={[12, 12, 4, 4]}>
                  {monthlyAnalysis.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.month === selectedMonth ? '#ec4899' : '#8b5cf6'} className="cursor-pointer transition-all duration-500" />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {selectedMonthData ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in slide-in-from-top-4">
            <div className="glass-panel p-10 rounded-[45px] border border-violet-500/10">
              <h4 className="text-xl font-black text-white uppercase mb-8 flex items-center"><ShoppingBag size={20} className="mr-4 text-violet-400" /> TEDARİKÇİ DAĞILIMI</h4>
              <div className="space-y-6">
                {sortedSuppliers.map(([name, amount]) => (
                  <div key={name} className="space-y-2">
                    <div className="flex justify-between text-xs font-black uppercase"><span className="text-slate-200">{name}</span><span className="text-violet-400">₺{amount.toLocaleString('tr-TR')}</span></div>
                    <div className="h-2 bg-black/40 rounded-full overflow-hidden border border-violet-500/10">
                      <div className="h-full neon-gradient-premium shadow-lg" style={{ width: `${(amount / selectedMonthData.total) * 100}%` }} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div className="glass-panel p-10 rounded-[45px] border border-violet-500/10">
              <h4 className="text-xl font-black text-white uppercase mb-8 flex items-center"><Building2 size={20} className="mr-4 text-pink-500" /> DEPARTMAN HARCAMALARI</h4>
              <div className="space-y-6">
                {sortedDepartments.map(([name, amount]) => (
                  <div key={name} className="space-y-2">
                    <div className="flex justify-between text-xs font-black uppercase"><span className="text-slate-200">{name}</span><span className="text-pink-500">₺{amount.toLocaleString('tr-TR')}</span></div>
                    <div className="h-2 bg-black/40 rounded-full overflow-hidden border border-violet-500/10">
                      <div className="h-full bg-pink-500 shadow-lg" style={{ width: `${(amount / selectedMonthData.total) * 100}%` }} />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !selectedTransactionId && activeTab !== 'dashboard') {
        setActiveTab('dashboard');
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    if (!statusFilter) return state.transactions;
    return state.transactions.filter(t => t.status === statusFilter);
  }, [state.transactions, statusFilter]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      quantity: request.quantity || 1,
      unitPriceTl: request.unitPriceTl || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPriceTl: request.packageUnitPriceTl || 0,
      totalAmount: (request.packageQuantity || 1) * (request.packageUnitPriceTl || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} kodlu yeni talep oluşturuldu.`);
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Purchased' ? 'Satın Alındı' : newStatus === 'Approved' ? 'Bütçe Onaylandı' : `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Güncelleme', `Kayıt #${id} yeni statüsü: ${newStatus}`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (updates.packageQuantity !== undefined || updates.packageUnitPriceTl !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPriceTl || 0);
          }
          return updated;
        }
        return t;
      })
    }));
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    setActiveTab('transactions');
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} sistemden kaldırıldı.`);
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); if (tab !== 'transactions') setStatusFilter(null); }} user={state.user} onLogout={handleLogout}>
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                </div>
                <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                  <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                  <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.map((t) => (
                  <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                    <div className="flex justify-between items-start mb-8 relative z-10">
                      <div className="w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl">{t.requesterName.charAt(0)}</div>
                      <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${
                        t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                        t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                        'bg-violet-500/10 text-violet-400 border-violet-500/20'
                      }`}>{
                        t.status === 'Pending' ? 'BEKLEYEN' : 
                        t.status === 'Approved' ? 'ONAYLI' : 
                        t.status === 'Purchased' ? 'ALINDI' : t.status
                      }</span>
                    </div>
                    <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                    <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-10">{t.department} • {t.supplierName}</p>
                    <div className="flex justify-between items-end border-t border-violet-500/10 pt-8">
                       <div>
                          <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                          <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       </div>
                       <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                    </div>
                  </div>
                ))}
              </div>
              {filteredTransactions.length === 0 && (
                <div className="text-center py-40 glass-panel rounded-[50px] border border-violet-500/10">
                   <p className="text-xs font-black text-violet-900 uppercase tracking-widest">Bu kategoride dosya bulunamadı</p>
                </div>
              )}
            </div>
          )}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} departments={state.departments} setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} user={state.user} onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} systemLogs={state.systemLogs} transactions={state.transactions} onBack={() => setActiveTab('dashboard')} />}
        </>
      )}
    </Layout>
  );
};

export default App;

