import React, { useMemo, useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, PieChart, Pie, Cell, LineChart, Line, Legend
} from 'recharts';
import { 
  FileDown, TrendingUp, TrendingDown, Target, Building2, 
  ShoppingBag, Calendar, Users, Sparkles, Filter, 
  ArrowUpRight, Printer, Zap, Award, Briefcase
} from 'lucide-react';
import { Transaction } from '../types';
import { GoogleGenAI } from "@google/genai";

interface ReportsProps {
  transactions: Transaction[];
}

const COLORS = ['#8b5cf6', '#06b6d4', '#f43f5e', '#10b981', '#f59e0b', '#ec4899'];

const Reports: React.FC<ReportsProps> = ({ transactions }) => {
  const [aiAnalysis, setAiAnalysis] = useState<string>("");
  const [loadingAi, setLoadingAi] = useState(false);

  // Veri Agregasyonu
  const stats = useMemo(() => {
    const purchased = transactions.filter(t => t.status === 'Purchased');
    const total = purchased.reduce((sum, t) => sum + t.totalAmount, 0);
    const avg = purchased.length > 0 ? total / purchased.length : 0;

    // Aylık Veri
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const monthlyMap: Record<string, { month: string, total: number, count: number }> = {};

    // Departman Verisi
    const deptMap: Record<string, number> = {};

    // En Çok Alınan Ürün Grubu
    const productMap: Record<string, number> = {};

    purchased.forEach(t => {
      const date = new Date(t.requestDateTime);
      const mLabel = months[date.getMonth()];
      if (!monthlyMap[mLabel]) monthlyMap[mLabel] = { month: mLabel, total: 0, count: 0 };
      monthlyMap[mLabel].total += t.totalAmount;
      monthlyMap[mLabel].count += 1;

      deptMap[t.department] = (deptMap[t.department] || 0) + t.totalAmount;
      productMap[t.productSetName] = (productMap[t.productSetName] || 0) + t.totalAmount;
    });

    const monthlyData = months.map(m => monthlyMap[m] || { month: m, total: 0, count: 0 });
    const deptData = Object.entries(deptMap).map(([name, value]) => ({ name, value }));
    const topProducts = Object.entries(productMap)
      .sort(([, a], [, b]) => b - a)
      .slice(0, 5)
      .map(([name, amount]) => ({ name, amount }));

    // En yoğun ay
    const peakMonth = [...monthlyData].sort((a, b) => b.total - a.total)[0];

    return { total, avg, monthlyData, deptData, topProducts, peakMonth, count: purchased.length };
  }, [transactions]);

  // Gemini AI Analizi
  useEffect(() => {
    const getAiReport = async () => {
      if (stats.count === 0) return;
      setLoadingAi(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Aşağıdaki satın alma verilerini profesyonel bir finans müdürü gibi analiz et ve üst yönetime sunulacak 3 maddelik çok kısa bir özet yaz.
        Toplam Harcama: ₺${stats.total}
        En Çok Harcama Yapılan Ay: ${stats.peakMonth.month} (₺${stats.peakMonth.total})
        En Çok Harcama Yapan Departmanlar: ${stats.deptData.map(d => `${d.name}: ₺${d.value}`).join(', ')}
        İşlem Sayısı: ${stats.count}
        Lütfen Türkçe, çarpıcı ve stratejik bir dil kullan.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
        });
        setAiAnalysis(response.text || "Veri analizi şu an yapılamıyor.");
      } catch (e) {
        setAiAnalysis("Sistem verileri başarıyla işlendi, AI özeti oluşturulamadı.");
      } finally {
        setLoadingAi(false);
      }
    };
    getAiReport();
  }, [stats]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-12 pb-20 animate-in fade-in duration-1000">

      {/* Rapor Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 print:mb-10">
        <div>
          <div className="hidden print:block mb-4">
             <h1 className="text-2xl font-black text-black uppercase">YAŞAM FATURA KURUMSAL RAPORU</h1>
             <p className="text-xs text-gray-500">{new Date().toLocaleDateString('tr-TR')} Tarihli Çıktı</p>
          </div>
          <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">FİNANSAL PROJEKSİYON</h2>
          <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2 flex items-center">
            <Zap size={14} className="mr-2" /> Stratejik Harcama ve Bütçe Analizi
          </p>
        </div>
        <div className="flex space-x-4 print:hidden">
          <button onClick={handlePrint} className="px-8 py-4 bg-white text-black rounded-2xl text-[11px] font-black uppercase tracking-widest flex items-center shadow-xl hover:bg-violet-400 transition-all">
            <Printer size={18} className="mr-3" /> SUNUM DOSYASI HAZIRLA (PDF)
          </button>
        </div>
      </div>

      {/* Üst Metrik Kartları */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        {[
          { label: 'TOPLAM HACİM', val: `₺${stats.total.toLocaleString('tr-TR')}`, icon: <TrendingUp className="text-green-400" />, sub: 'Gerçekleşen Ödemeler' },
          { label: 'ORTALAMA DOSYA', val: `₺${stats.avg.toLocaleString('tr-TR', { maximumFractionDigits: 0 })}`, icon: <Target className="text-cyan-400" />, sub: 'İşlem Başı Maliyet' },
          { label: 'ZİRVE DÖNEMİ', val: stats.peakMonth.month, icon: <Calendar className="text-violet-400" />, sub: `₺${stats.peakMonth.total.toLocaleString('tr-TR')} Hacim` },
          { label: 'İŞLEM TRAFİĞİ', val: stats.count, icon: <Briefcase className="text-pink-400" />, sub: 'Tamamlanan Dosyalar' },
        ].map((m, i) => (
          <div key={i} className="glass-panel p-8 rounded-[40px] border border-violet-500/10 relative overflow-hidden group hover:border-violet-500/30 transition-all">
