            <p className="text-[10px] text-slate-500 font-bold uppercase">{m.sub}</p>
          </div>
        ))}
      </div>

      {/* AI Özet ve Grafik Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">

