                        <Sparkles size={14} />
                      )}
                      <span>AI ANALİZİ YAP</span>
                    </button>
                  )}
                </div>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner relative overflow-hidden">
