import React, { useState, useRef, useEffect } from 'react';
import { Send, Plus, Trash2, Camera, Info, Sparkles, FileText, CheckCircle, X, Package, ShieldCheck, UserCheck, ImagePlus, Upload } from 'lucide-react';
import { ExtraItem, Transaction, RoleDefinition } from '../types';
import { analyzeJustification } from '../services/geminiService';
import { INITIAL_ROLES } from '../constants';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    usageLocation: '',
    requesterName: 'Hasan Demir',
    packageQuantity: 1,
    packageUnitPriceTl: 0,
    quantity: 0,
    unitPriceTl: 0,
    justification: '',
    generalNotes: '',
    microCode: '',
    photoUrl: '',
    totalAmount: 0
  });

  const [selectedRoles, setSelectedRoles] = useState<string[]>(INITIAL_ROLES.map(r => r.roleName));
  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [isOtherDept, setIsOtherDept] = useState(false);
  const [newDeptName, setNewDeptName] = useState('');
  const [analyzing, setAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && onBack) onBack();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack]);

  useEffect(() => {
    const total = (formData.packageQuantity * formData.packageUnitPriceTl) + (formData.quantity * formData.unitPriceTl);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, formData.packageUnitPriceTl, formData.quantity, formData.unitPriceTl]);

  const inputClass = "w-full px-4 py-3 rounded-xl gradient-neon-input text-slate-200 outline-none transition-all placeholder:text-indigo-700/60 text-sm";

  const toggleRole = (roleName: string) => {
    setSelectedRoles(prev => 
      prev.includes(roleName) 
        ? prev.filter(r => r !== roleName) 
        : [...prev, roleName]
    );
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Dosya boyutu kontrolü (Mobil performans için 5MB limit önerilir)
      if (file.size > 5 * 1024 * 1024) {
        alert("Dosya boyutu çok büyük (Max 5MB). Lütfen daha düşük çözünürlüklü bir fotoğraf çekin.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleAiCheck = async () => {
    if (!formData.productSetName || !formData.justification) return;
    setAnalyzing(true);
    const result = await analyzeJustification(formData.productSetName, formData.justification);
    setAiAnalysis(result);
    setAnalyzing(false);
  };

  const handleDeptChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val === 'OTHER') {
      setIsOtherDept(true);
      setFormData({ ...formData, department: '' });
    } else {
      setIsOtherDept(false);
      setFormData({ ...formData, department: val });
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalDept = isOtherDept ? newDeptName : formData.department;

    if (selectedRoles.length === 0) {
      alert("En az bir onaylayıcı seçmelisiniz.");
      return;
    }

    if (isOtherDept) onAddDepartment(newDeptName);

    const approvalFlow = INITIAL_ROLES
      .filter(r => selectedRoles.includes(r.roleName))
      .map(r => ({
        role: r.roleName,
        status: 'Pending' as const,
        approverName: r.assignedName
      }));

    onSave({
      ...formData,
      department: finalDept,
      requestDateTime: new Date().toISOString(),
      extraItems,
      status: 'Pending',
      approvalFlow,
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: formData.requesterName, action: 'Süreç Başlatıldı', details: `Yeni talep oluşturuldu. Onay akışı: ${selectedRoles.join(', ')}` }]
    });
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex items-center justify-between mb-10 px-2">
        <div>
          <h2 className="text-3xl font-black text-white neon-text tracking-tight uppercase">Yeni Talep Girişi</h2>
          <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest mt-1">Saha & Mobil Uyumlu Kayıt Ekranı</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Sol Sütun: Form Detayları */}
        <div className="lg:col-span-2 space-y-8">

          {/* Mobil Görsel Yükleme Altyapısı */}
          <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 shadow-xl overflow-hidden relative group">
            <div className="flex flex-col md:flex-row gap-8 items-center">
              <div className="relative w-full md:w-56 aspect-square rounded-[30px] overflow-hidden bg-black/40 border border-indigo-500/20 flex flex-col items-center justify-center cursor-pointer transition-all hover:border-indigo-500/50 shadow-inner group-hover:scale-[1.02]" onClick={() => fileInputRef.current?.click()}>
                {formData.photoUrl ? (
                  <>
                    <img src={formData.photoUrl} className="w-full h-full object-cover" alt="Ürün" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Camera className="text-white" size={32} />
                    </div>
                  </>
                ) : (
                  <div className="text-center p-6">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center mx-auto mb-4 text-indigo-400">
                      <Camera size={28} />
                    </div>
                    <p className="text-[10px] font-black text-white uppercase tracking-widest">FOTOĞRAF ÇEK</p>
                    <p className="text-[8px] text-indigo-500/60 uppercase font-bold mt-1">VEYA GALERİDEN SEÇ</p>
                  </div>
                )}
                {/* MOBİL ALTYAPI: accept ve capture özellikleri kamerayı tetikler */}
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept="image/*" 
                  capture="environment"
                  onChange={handleFileChange} 
                />
              </div>
              <div className="flex-1 space-y-6 w-full">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Satın Alma Tanımı *</label>
                  <input required type="text" value={formData.productSetName} onChange={e => setFormData({...formData, productSetName: e.target.value})} placeholder="Örn: Saha Operasyon Cihazı" className={inputClass} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Tedarikçi Firma *</label>
                  <input required type="text" value={formData.supplierName} onChange={e => setFormData({...formData, supplierName: e.target.value})} placeholder="Firma Adı" className={inputClass} />
                </div>
              </div>
            </div>
          </div>

          <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 shadow-xl space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">İlgili Departman</label>
                <select onChange={handleDeptChange} className={inputClass} value={isOtherDept ? 'OTHER' : formData.department}>
                  {departments.map(d => <option key={d} value={d} className="bg-[#1e1b4b]">{d}</option>)}
                  <option value="OTHER" className="bg-[#1e1b4b] font-bold text-emerald-400">DİĞER...</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">ERP / Micro Kodu</label>
                <input type="text" value={formData.microCode} onChange={e => setFormData({...formData, microCode: e.target.value})} placeholder="Referans No" className={inputClass} />
              </div>
            </div>
          </div>

          <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 shadow-xl space-y-6">
             <div className="flex items-center space-x-2 mb-2">
                <Package size={18} className="text-indigo-400" />
                <h3 className="text-sm font-black text-white uppercase tracking-tight">Maliyet ve Gerekçe</h3>
             </div>
             <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Adet</label>
                  <input type="number" value={formData.packageQuantity} onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})} className={inputClass} />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-indigo-500 uppercase ml-1">Birim Fiyat (TL)</label>
                  <input type="number" value={formData.packageUnitPriceTl} onChange={e => setFormData({...formData, packageUnitPriceTl: parseFloat(e.target.value) || 0})} className={inputClass} />
                </div>
                <div className="bg-indigo-500/5 p-4 rounded-2xl border border-indigo-500/20 flex flex-col justify-center text-right">
                  <p className="text-[9px] text-indigo-400 font-black uppercase mb-1">Toplam</p>
                  <p className="text-2xl font-black text-white">₺{formData.totalAmount.toLocaleString('tr-TR')}</p>
                </div>
             </div>
             <div className="space-y-2 pt-4 border-t border-indigo-500/5">
                <div className="flex items-center justify-between">
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Satın Alma Gerekçesi *</label>
                  <button type="button" onClick={handleAiCheck} disabled={analyzing} className="text-[9px] font-black text-pink-500 flex items-center space-x-1 uppercase hover:opacity-80"><Sparkles size={12}/> <span>AI ANALİZ</span></button>
                </div>
                <textarea required rows={3} value={formData.justification} onChange={e => setFormData({...formData, justification: e.target.value})} className={`${inputClass} resize-none`} placeholder="Yönetime açıklama yazın..." />
                {aiAnalysis && <div className="p-4 bg-indigo-500/5 border border-indigo-500/10 rounded-xl text-[10px] text-indigo-300 italic animate-in fade-in">"{aiAnalysis}"</div>}
             </div>
          </div>
        </div>

        {/* Sağ Sütun: Onay Akışı Özelleştirme */}
        <div className="space-y-8">
           <div className="glass-panel p-8 rounded-[32px] border border-violet-500/20 bg-violet-600/5 shadow-2xl relative overflow-hidden">
              <div className="absolute -right-4 -top-4 opacity-5"><ShieldCheck size={100} /></div>
              <h3 className="text-sm font-black text-white uppercase tracking-widest mb-8 flex items-center">
                <ShieldCheck size={20} className="mr-3 text-violet-400" /> ONAY AKIŞINI SEÇ
              </h3>
              <div className="space-y-4">
                 {INITIAL_ROLES.map((role) => (
                   <div 
                    key={role.id} 
                    onClick={() => toggleRole(role.roleName)}
                    className={`p-5 rounded-2xl border transition-all cursor-pointer flex items-center justify-between group ${
                      selectedRoles.includes(role.roleName) 
                        ? 'bg-violet-600/20 border-violet-500/40' 
                        : 'bg-black/20 border-white/5 opacity-50 grayscale hover:grayscale-0 hover:opacity-100'
                    }`}
                   >
                      <div className="flex items-center space-x-4">
                        <div className={`p-2 rounded-lg ${selectedRoles.includes(role.roleName) ? 'bg-violet-500 text-white' : 'bg-white/5 text-slate-500'}`}>
                          <UserCheck size={18} />
                        </div>
                        <div>
                          <p className="text-xs font-black text-white uppercase tracking-tight">{role.roleName}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase">{role.assignedName}</p>
                        </div>
                      </div>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                        selectedRoles.includes(role.roleName) ? 'bg-violet-500 border-violet-400' : 'border-white/10'
                      }`}>
                         {selectedRoles.includes(role.roleName) && <CheckCircle size={14} className="text-white" />}
                      </div>
                   </div>
                 ))}
              </div>
              <div className="mt-8 p-4 bg-black/40 rounded-2xl border border-violet-500/10">
                 <p className="text-[9px] text-violet-500 font-black uppercase leading-relaxed">
