                 </p>
              </div>
           </div>

           <div className="glass-panel p-8 rounded-[32px] border border-indigo-500/10 space-y-4">
              <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest ml-1">Süreç Notu / Ek Bilgi</label>
              <textarea 
                rows={3} 
                value={formData.generalNotes} 
                onChange={e => setFormData({...formData, generalNotes: e.target.value})} 
                placeholder="Dosyaya eklemek istediğiniz notlar..." 
                className={`${inputClass} resize-none`} 
              />
           </div>

           <button 
             type="submit"
             className="w-full py-6 neon-gradient-premium text-white rounded-[28px] font-black shadow-2xl flex items-center justify-center space-x-3 uppercase tracking-widest text-sm active:scale-95 transition-all"
           >
             <Send size={20} />
