        </div>
        <div className="glass-panel p-8 rounded-[35px] border border-cyan-500/10 flex flex-col justify-between">
          <p className="text-[10px] font-black text-cyan-500 uppercase tracking-widest mb-4">DIŞ TAKİP LİNKLERİ</p>
          <div className="flex items-center justify-between">
            <h3 className="text-3xl font-black text-white">AKTİF</h3>
            <Globe size={24} className="text-cyan-400" />
