        <div className="glass-panel p-8 rounded-[35px] border border-violet-500/10 flex flex-col justify-between">
          <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-4">BÜTÇE SAĞLIĞI</p>
          <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden mt-2">
            <div className="h-full bg-emerald-500 w-[72%]"></div>
          </div>
