      </div>

      <div className="glass-panel p-10 rounded-[50px] border border-violet-500/10">
        <h3 className="text-sm font-black text-white uppercase tracking-widest mb-10 flex items-center">
          <TrendingUp size={20} className="mr-4 text-violet-400" /> AKTİF SÜREÇLER
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
           {transactions.slice(0, 6).map(t => (
             <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="cyber-card p-8 glass-panel rounded-[40px] border border-violet-500/10 cursor-pointer relative overflow-hidden group">
                <div className={`absolute top-0 right-0 w-1 h-full ${t.priority === 'Critical' ? 'bg-rose-500' : 'bg-violet-500'}`}></div>
                <div className="flex justify-between items-start mb-6">
                   <span className="text-[9px] font-black text-violet-500 uppercase">#{t.id}</span>
                   <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${t.priority === 'Critical' ? 'bg-rose-500/20 text-rose-500' : 'bg-violet-500/20 text-violet-400'}`}>{t.priority}</span>
                </div>
                <h4 className="text-lg font-black text-white uppercase truncate mb-1">{t.productSetName}</h4>
                <p className="text-[10px] text-slate-500 font-bold uppercase mb-6">{t.department}</p>
                <div className="flex justify-between items-end">
                   <p className="text-xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                   <div className="p-2 bg-violet-500/10 rounded-xl text-violet-400"><Clock size={16} /></div>
