                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono">{flow.date || 'Bekliyor'}</p>
                                </div>
                                <div className="flex items-center space-x-4">
                                    <div className="flex items-center space-x-2">
                                        {flow.status === 'Pending' && (
                                          <>
                                            <input 
                                                type="text" 
                                                placeholder="Karar..." 
                                                className="px-4 py-3 rounded-xl text-xs w-32 md:w-48 bg-black/40 border border-violet-500/20 outline-none focus:border-violet-500 transition-colors" 
                                                value={decisionNote} 
                                                onChange={e => setDecisionNote(e.target.value)} 
