                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Süreç Notları Bölümü */}
            <div className="p-10 bg-violet-950/30 rounded-[45px] border border-violet-500/10 space-y-6">
                <div className="flex items-center justify-between">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Notebook size={20} className="mr-4" /> SÜREÇ NOTLARI & EKSTRA DETAYLAR
                    </h4>
                    {!isEditing && (
                        <button onClick={handleUpdateGeneralNotes} className="px-5 py-2 bg-violet-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg">NOTU GÜNCELLE</button>
                    )}
                </div>
                <textarea 
                    rows={4} 
                    value={generalNoteInput} 
                    onChange={e => setGeneralNoteInput(e.target.value)} 
                    placeholder="Onaylayıcılar veya satın alma ekibi için ek notlar..." 
                    className="w-full bg-black/40 border border-violet-500/20 rounded-3xl p-6 text-sm text-slate-300 outline-none focus:border-violet-500 transition-all resize-none"
                />
