            <div className="space-y-6">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest">SATIN ALMA GEREKÇESİ</h4>
                  {!isEditing && (
                    <button 
                      onClick={handleAiJustificationAnalysis} 
                      disabled={analyzingJustification}
                      className="text-[10px] font-black text-pink-500 flex items-center space-x-2 uppercase hover:opacity-80 transition-all disabled:opacity-50"
                    >
                      {analyzingJustification ? (
                        <Loader2 size={14} className="animate-spin" />
                      ) : (
                        <Sparkles size={14} />
                      )}
                      <span>AI ANALİZİ YAP</span>
                    </button>
                  )}
                </div>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner relative overflow-hidden">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>

                {aiJustificationResult && (
                  <div className="p-8 bg-pink-500/5 border border-pink-500/20 rounded-[35px] animate-in fade-in slide-in-from-top-2 duration-500">
                    <div className="flex items-center space-x-3 mb-3">
                      <Sparkles size={16} className="text-pink-500" />
                      <span className="text-[10px] font-black text-pink-500 uppercase tracking-widest">AI DEĞERLENDİRMESİ</span>
                    </div>
                    <p className="text-sm text-slate-300 italic leading-relaxed">"{aiJustificationResult}"</p>
                  </div>
                )}
