          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-wrap items-center justify-center gap-6 lg:gap-10">
            {transaction.status !== 'Purchased' && transaction.status !== 'Approved' && (
              <button onClick={handleSuspend} className="px-10 py-5 bg-amber-600/10 border border-amber-600/20 text-amber-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-amber-600 hover:text-white transition-all shadow-lg active:scale-95 flex items-center group">
                <PauseCircle size={20} className="mr-3" /> ASKIYA AL
              </button>
