            {(transaction.status === 'Pending' || transaction.status === 'On Hold') && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-10 py-5 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-rose-600 hover:text-white transition-all shadow-lg active:scale-95 flex items-center">
                <XCircle size={20} className="mr-3" /> İPTAL ET
