          onBack();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedApproverHistory]);

  const addRole = () => {
    if (newRoleName && newAssignedName) {
      const isDuplicate = roles.some(r => r.roleName.toLowerCase() === newRoleName.toLowerCase());
      if (isDuplicate) return;
      setRoles([...roles, { id: Date.now().toString(), roleName: newRoleName, assignedName: newAssignedName }]);
