                             <p className="text-xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                          </div>
                          <ChevronRight className="text-slate-700 group-hover:text-amber-500 group-hover:translate-x-2 transition-all" size={24} />
                       </div>
