                  )) : (
                    <div className="text-center py-32 opacity-20">
                       <Search size={64} className="mx-auto mb-6" />
                       <p className="text-sm font-black uppercase tracking-[0.3em]">Aradığınız kriterde talep bulunamadı</p>
