                    <div key={role.id} onClick={() => setSelectedApproverHistory(role.assignedName)} className="cyber-card p-8 bg-violet-950/20 rounded-[40px] border border-violet-500/10 flex items-center justify-between cursor-pointer group">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest group-hover:text-violet-300 transition-colors">{role.roleName}</p>
                        <p className="text-lg font-black text-white uppercase group-hover:neon-text-premium transition-all">{role.assignedName}</p>
                      </div>
                      <X size={20} className="text-violet-900 group-hover:text-rose-500 transition-colors" onClick={(e) => { e.stopPropagation(); removeRole(role.id); }} />
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-cyan-500/10 space-y-10">
                <div className="flex items-center justify-between">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter flex items-center">
                        <Terminal size={28} className="text-cyan-400 mr-4" /> DENETİM KAYITLARI
                    </h3>
                    <span className="px-5 py-2 bg-cyan-500/10 text-cyan-400 text-[10px] font-black rounded-full border border-cyan-500/20">{systemLogs.length} LOG</span>
                </div>
                <div className="space-y-4 max-h-[600px] overflow-y-auto custom-scroll pr-4">
                    {systemLogs.map((log) => (
                        <div key={log.id} className="p-6 bg-slate-900/40 rounded-3xl border border-cyan-500/5 hover:border-cyan-500/20 transition-all">
                            <div className="flex justify-between mb-2">
                                <span className="text-[10px] font-black text-cyan-400 uppercase tracking-widest">{log.action}</span>
                                <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                            </div>
                            <p className="text-xs text-slate-300 italic">"{log.details}"</p>
                        </div>
                    ))}
                </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useMemo } from 'react';
import { Search } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !selectedTransactionId && activeTab !== 'dashboard') {
        setActiveTab('dashboard');
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions]; // Copy to avoid mutation

    // Status filtresi
    if (statusFilter) {
      list = list.filter(t => t.status === statusFilter);
    }

    // Global Arama Filtresi (Başlık, Tedarikçi, Kod, Detay)
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q) ||
        t.justification.toLowerCase().includes(q)
      );
    }

    // KRONOLOJİK SIRALAMA: En Yeni En Üstte
    return list.sort((a, b) => 
      new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime()
    );
  }, [state.transactions, statusFilter, searchQuery]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
    setSearchQuery('');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPrice: request.packageUnitPrice || 0,
      totalAmount: (request.packageQuantity || 1) * (request.packageUnitPrice || 0),
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} kodlu yeni talep oluşturuldu.`);
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Purchased' ? 'Satın Alındı' : newStatus === 'Approved' ? 'Bütçe Onaylandı' : `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Güncelleme', `Kayıt #${id} yeni statüsü: ${newStatus}`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (updates.packageQuantity !== undefined || updates.packageUnitPrice !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPrice || 0);
          }
          return updated;
        }
        return t;
      })
    }));
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    setActiveTab('transactions');
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} sistemden kaldırıldı.`);
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => { 
        setActiveTab(tab); 
        setSelectedTransactionId(null); 
        if (tab !== 'transactions') setStatusFilter(null); 
      }} 
      user={state.user} 
      onLogout={handleLogout}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
    >
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                </div>
                <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                  <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                  <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                </div>
              </div>

              {searchQuery && (
                <div className="flex items-center space-x-2 text-violet-400 text-sm font-bold uppercase tracking-widest">
                  <Search size={16} />
                  <span>"{searchQuery}" araması için {filteredTransactions.length} sonuç bulundu</span>
                  <button onClick={() => setSearchQuery('')} className="text-[10px] bg-violet-500/10 px-2 py-1 rounded-md hover:bg-violet-500/20">TEMİZLE</button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group">
                      <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className="w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl">{t.requesterName.charAt(0)}</div>
                        <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${
                          t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                          t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                          'bg-violet-500/10 text-violet-400 border-violet-500/20'
                        }`}>{
                          t.status === 'Pending' ? 'BEKLEYEN' : 
                          t.status === 'Approved' ? 'ONAYLI' : 
                          t.status === 'Purchased' ? 'ALINDI' : t.status
                        }</span>
                      </div>
                      <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                      <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-1">{t.department} • {t.supplierName}</p>
                      <p className="text-[9px] text-slate-500 font-mono mb-10">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')} {new Date(t.requestDateTime).toLocaleTimeString('tr-TR', {hour: '2-digit', minute:'2-digit'})}</p>
                      <div className="flex justify-between items-end border-t border-violet-500/10 pt-8">
                         <div>
                            <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                            <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full py-24 text-center glass-panel rounded-[40px] border border-dashed border-violet-500/20 opacity-50">
                    <Search size={48} className="mx-auto mb-4 text-violet-900" />
                    <p className="text-sm font-black text-violet-500 uppercase tracking-widest">Kayıt Bulunamadı</p>
                    <p className="text-xs text-slate-500 mt-2 italic">Arama kriterlerinizi değiştirip tekrar deneyin.</p>
                  </div>
                )}
              </div>
            </div>
          )}
          {activeTab === 'settings' && <Settings 
            roles={state.roles} 
            setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} 
            departments={state.departments} 
            setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} 
            user={state.user} 
            onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} 
            systemLogs={state.systemLogs} 
            transactions={state.transactions} 
            searchQuery={searchQuery}
            onSelectTransaction={(id) => { setSelectedTransactionId(id); }}
            onShowAll={() => { setActiveTab('transactions'); }}
            onBack={() => setActiveTab('dashboard')} 
          />}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Shield, 
  Plus, 
  X, 
  Users, 
  Lock, 
  ChevronRight, 
  User as UserIcon, 
  History, 
  Terminal, 
  UserCheck,
  CheckCircle2,
  XCircle,
  FileText,
  Search,
  ArrowRight,
  TrendingUp,
  CreditCard,
  Calendar,
  Clock,
  ArrowRightCircle,
  Package,
  CalendarDays
} from 'lucide-react';
import { RoleDefinition, User, SystemLog, Transaction } from '../types';

interface SettingsProps {
  roles: RoleDefinition[];
  setRoles: (roles: RoleDefinition[]) => void;
  departments: string[];
  setDepartments: (depts: string[]) => void;
  user: User;
  onUpdateUser: (name: string) => void;
  systemLogs: SystemLog[];
  transactions: Transaction[];
  searchQuery?: string;
  onSelectTransaction?: (id: string) => void;
  onShowAll?: () => void;
  onBack?: () => void;
}

const Settings: React.FC<SettingsProps> = ({ 
  roles, setRoles, departments, setDepartments, user, onUpdateUser, systemLogs, transactions, searchQuery, onSelectTransaction, onShowAll, onBack 
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'profile' | 'security'>('profile');
  const [newRoleName, setNewRoleName] = useState('');
  const [newAssignedName, setNewAssignedName] = useState('');
  const [userName, setUserName] = useState(user.name);
  const [selectedApproverHistory, setSelectedApproverHistory] = useState<string | null>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedApproverHistory) {
          setSelectedApproverHistory(null);
        } else if (onBack) {
          onBack();
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedApproverHistory]);

  const addRole = () => {
    if (newRoleName && newAssignedName) {
      const isDuplicate = roles.some(r => r.roleName.toLowerCase() === newRoleName.toLowerCase());
      if (isDuplicate) return;
      setRoles([...roles, { id: Date.now().toString(), roleName: newRoleName, assignedName: newAssignedName }]);
      setNewRoleName('');
      setNewAssignedName('');
    }
  };

  const removeRole = (id: string) => setRoles(roles.filter(r => r.id !== id));

  const handleUpdateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateUser(userName);
  };

  const approverHistory = useMemo(() => {
    if (!selectedApproverHistory) return [];
    return transactions.filter(t => 
      t.approvalFlow.some(f => f.approverName === selectedApproverHistory && f.status !== 'Pending')
    ).map(t => {
      const flowStep = t.approvalFlow.find(f => f.approverName === selectedApproverHistory);
      return {
        id: t.id,
        name: t.productSetName,
        amount: t.totalAmount,
        status: flowStep?.status,
        date: flowStep?.date || 'Belirtilmedi',
        note: flowStep?.decisionNote
      };
    });
  }, [selectedApproverHistory, transactions]);

  // AKILLI ARAMA: Talepleri Filtrele ve En Yeniden En Eskiye Doğru Sırala
  const searchResults = useMemo(() => {
    if (!searchQuery) return [];
    const q = searchQuery.toLowerCase();
    return [...transactions]
      .filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.justification.toLowerCase().includes(q)
      )
      .sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [searchQuery, transactions]);

  return (
    <div className="max-w-6xl mx-auto space-y-10 animate-in fade-in duration-500 pb-20">

      {/* Yetkili Onay Geçmişi Modalı */}
      {selectedApproverHistory && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/90 backdrop-blur-2xl animate-in fade-in">
          <div className="w-full max-w-2xl glass-panel p-10 lg:p-14 rounded-[50px] border border-violet-500/30 shadow-[0_0_100px_rgba(139,92,246,0.2)] relative">
            <button onClick={() => setSelectedApproverHistory(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-violet-500/10 rounded-2xl transition-all">
              <X size={28} />
            </button>

            <div className="flex items-center space-x-6 mb-12">
              <div className="w-20 h-20 neon-gradient-premium rounded-[32px] flex items-center justify-center text-white shadow-[0_0_30px_rgba(139,92,246,0.5)]">
                <UserCheck size={40} />
              </div>
              <div>
                <h3 className="text-3xl font-black text-white uppercase tracking-tighter neon-text-premium">{selectedApproverHistory}</h3>
                <p className="text-sm font-black text-violet-500 uppercase tracking-widest opacity-60">Sistem Karar Logları</p>
              </div>
            </div>

            <div className="space-y-6 max-h-[500px] overflow-y-auto custom-scroll pr-4">
              {approverHistory.length > 0 ? approverHistory.map((item) => (
                <div key={item.id} className={`p-6 rounded-[30px] border transition-all duration-500 flex items-center justify-between group ${
                  item.status === 'Approved' 
                  ? 'bg-green-500/5 border-green-500/30 neon-glow-green' 
                  : 'bg-rose-500/5 border-rose-500/30 neon-glow-rose'
                }`}>
                   <div className="space-y-2">
                      <div className="flex items-center space-x-3">
                         <span className="text-[10px] font-black text-white/40 uppercase tracking-widest">#{item.id}</span>
                         <p className="text-sm font-black text-white uppercase tracking-tight">{item.name}</p>
                      </div>
                      <div className="flex items-center space-x-4">
                         <div className="flex items-center space-x-1 text-slate-400 text-[10px] font-bold">
                            <History size={12} />
                            <span>{item.date}</span>
                         </div>
                         <div className="flex items-center space-x-1 text-violet-400 text-[11px] font-black">
                            <CreditCard size={12} />
                            <span>₺{item.amount.toLocaleString('tr-TR')}</span>
                         </div>
                      </div>
                      {item.note && <p className="text-[10px] text-slate-500 italic mt-1 bg-black/20 p-2 rounded-lg">"{item.note}"</p>}
                   </div>
                   <div className="flex flex-col items-center">
                     {item.status === 'Approved' ? (
                       <div className="flex flex-col items-center text-green-400">
                          <CheckCircle2 size={32} className="mb-1" />
                          <span className="text-[8px] font-black uppercase tracking-widest">UYGUN GÖRÜLDÜ</span>
                       </div>
                     ) : (
                       <div className="flex flex-col items-center text-rose-500">
                          <XCircle size={32} className="mb-1" />
                          <span className="text-[8px] font-black uppercase tracking-widest">UYGUN GÖRÜLMEDİ</span>
                       </div>
                     )}
                   </div>
                </div>
              )) : (
                <div className="text-center py-24 opacity-30">
                   <Terminal size={64} className="mx-auto text-violet-950 mb-6" />
                   <p className="text-xs font-black text-violet-500 uppercase tracking-widest">Henüz bir karar kaydı işlenmemiş</p>
                </div>
              )}
            </div>

            <div className="mt-12 pt-8 border-t border-violet-500/10 flex justify-between items-center">
              <span className="text-[9px] font-black text-violet-900 uppercase tracking-widest flex items-center">
                <Lock size={12} className="mr-2" /> Güvenli Denetim Modu
              </span>
              <button onClick={() => setSelectedApproverHistory(null)} className="px-12 py-4 neon-gradient-premium text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl">GEÇMİŞİ KAPAT</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-5xl font-black text-white neon-text-premium uppercase tracking-tighter">SİSTEM AYARLARI</h2>
          <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-1">Konfigürasyon ve Yetki Yönetim Merkezi</p>
        </div>
        {searchQuery && (
          <div className="hidden md:flex items-center space-x-3 bg-amber-500/10 border border-amber-500/20 px-6 py-3 rounded-2xl animate-pulse">
            <Search size={18} className="text-amber-500" />
            <span className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Arama Aktif: "{searchQuery}"</span>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
        <div className="space-y-4">
          <button onClick={() => setActiveSubTab('profile')} className={`w-full p-8 rounded-[32px] border transition-all flex items-center space-x-5 ${activeSubTab === 'profile' && !searchQuery ? 'bg-violet-600 border-violet-400 text-white shadow-xl neon-glow-violet' : 'glass-panel border-violet-500/10 text-violet-400/60'}`}>
            <UserIcon size={24} />
            <span className="text-xs font-black uppercase tracking-widest">PROFİL & YETKİ</span>
          </button>
          <button onClick={() => setActiveSubTab('security')} className={`w-full p-8 rounded-[32px] border transition-all flex items-center space-x-5 ${activeSubTab === 'security' && !searchQuery ? 'bg-cyan-600 border-cyan-400 text-white shadow-xl neon-glow-cyan' : 'glass-panel border-cyan-500/10 text-cyan-400/60'}`}>
            <Shield size={24} />
            <span className="text-xs font-black uppercase tracking-widest">LOG DENETİMİ</span>
          </button>

          {searchQuery && (
            <div className="p-8 rounded-[32px] bg-white/5 border border-white/10 text-slate-400">
                <div className="flex items-center space-x-4 mb-4">
                    <Search size={20} className="text-amber-500" />
                    <span className="text-[10px] font-black uppercase tracking-widest text-white">BULUNAN KAYITLAR</span>
                </div>
                <div className="text-4xl font-black text-white mb-2">{searchResults.length}</div>
                <p className="text-[9px] font-bold opacity-60 uppercase tracking-widest">Eşleşen Dosya</p>
                <button 
                  onClick={onShowAll}
                  className="mt-6 w-full py-4 bg-amber-500 text-black rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-amber-400 transition-all flex items-center justify-center"
                >
                   <ArrowRightCircle size={14} className="mr-2" /> SONUÇLARI LİSTELE
                </button>
            </div>
          )}
        </div>

        <div className="lg:col-span-3">
          {searchQuery ? (
            /* AKILLI ARAMA SONUÇLARI PANELİ - CYBER DESIGN */
            <div className="glass-panel p-10 lg:p-14 rounded-[50px] border border-amber-500/20 space-y-10 animate-in slide-in-from-top-4 duration-500">
               <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-5">
                      <div className="w-14 h-14 bg-amber-500/20 rounded-[22px] flex items-center justify-center text-amber-500 shadow-[0_0_20px_rgba(245,158,11,0.2)]">
                        <Search size={28} />
                      </div>
                      <div>
                        <h3 className="text-3xl font-black text-white uppercase tracking-tighter">ARAMA SONUÇLARI</h3>
                        <p className="text-[10px] text-amber-500 font-black uppercase tracking-widest opacity-60 italic">En yeni talepten en eskiye doğru sıralandı</p>
                      </div>
                  </div>
                  <button onClick={onShowAll} className="hidden md:flex px-8 py-4 bg-white/5 border border-white/10 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-amber-500 hover:text-black transition-all items-center shadow-lg group">
                    <span>TÜMÜNÜ GÖSTER</span>
                    <ArrowRightCircle size={16} className="ml-3 group-hover:translate-x-1 transition-transform" />
                  </button>
               </div>

               <div className="space-y-4 max-h-[750px] overflow-y-auto custom-scroll pr-4">
                  {searchResults.length > 0 ? searchResults.map((t) => (
                    <div 
                      key={t.id} 
                      onClick={() => onSelectTransaction?.(t.id)}
                      className="group p-8 bg-black/40 rounded-[40px] border border-white/5 hover:border-amber-500/40 hover:bg-amber-500/[0.02] transition-all cursor-pointer flex flex-col md:flex-row md:items-center justify-between gap-8"
                    >
                       <div className="flex items-center space-x-6">
                          <div className="relative">
                            <div className="w-16 h-16 bg-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 font-black text-2xl group-hover:bg-amber-500 group-hover:text-black transition-all shadow-inner">
                              {t.productSetName.charAt(0)}
                            </div>
                            <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-amber-600 rounded-lg flex items-center justify-center text-[8px] font-black text-white border-2 border-black">
                               #{t.id.slice(-3)}
