                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest group-hover:text-violet-300 transition-colors">{role.roleName}</p>
                        <p className="text-lg font-black text-white uppercase group-hover:neon-text-premium transition-all">{role.assignedName}</p>
