            <h1 className="text-5xl font-black text-white neon-text tracking-tight uppercase leading-none">YAŞAM FATURA</h1>
            <p className="text-emerald-400 font-bold uppercase tracking-[0.3em] text-[10px] mt-4 opacity-80">Girişimci Harcama Ağı</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-7">
