                  required
                  type="text" 
                  value={username}
                  onChange={e => setUsername(e.target.value)}
                  placeholder="admin"
                  className="w-full rounded-[24px] py-5 pl-14 pr-6 text-sm text-white gradient-neon-input placeholder:text-emerald-800/50"
                />
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-[10px] font-black text-emerald-400 uppercase tracking-widest ml-2">Güvenlik Anahtarı</label>
              <div className="relative">
                <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-emerald-500/40" size={20} />
                <input 
                  required
                  type="password" 
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••"
                  className="w-full rounded-[24px] py-5 pl-14 pr-6 text-sm text-white gradient-neon-input placeholder:text-emerald-800/50"
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className={`w-full py-6 neon-gradient text-white rounded-[28px] font-black uppercase tracking-[0.2em] text-sm shadow-[0_20px_40px_rgba(16,185,129,0.2)] hover:shadow-[0_20px_60px_rgba(245,158,11,0.3)] active:scale-95 transition-all flex items-center justify-center space-x-3 mt-12 ${loading ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={22} />
                  <span>KİMLİK DOĞRULANIYOR...</span>
                </>
              ) : (
                <span>YÖNETİM PANELİNE GİRİŞ</span>
              )}
            </button>
          </form>

          <div className="mt-16 text-center space-y-2">
            <p className="text-[10px] text-emerald-900 font-bold uppercase tracking-widest">Yaşam Fatura Kurumsal Çözümler © 2025</p>
            <p className="text-[11px] text-emerald-400 font-black uppercase tracking-[0.4em] opacity-60">Design by Batuhan Yontuç</p>
          </div>
        </div>
      </div>
