import React, { useState, useEffect, useMemo } from 'react';
import { Search } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !selectedTransactionId && activeTab !== 'dashboard') {
        setActiveTab('dashboard');
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];

    // Status filtresi
    if (statusFilter) {
      list = list.filter(t => t.status === statusFilter);
    }

    // Global Arama Filtresi (Başlık, Tedarikçi, Kod, Detay)
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q) ||
        (t.justification && t.justification.toLowerCase().includes(q))
      );
    }

    // KRONOLOJİK SIRALAMA: En Yeni En Üstte
    return list.sort((a, b) => 
      new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime()
    );
  }, [state.transactions, statusFilter, searchQuery]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
    setSearchQuery('');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    // Mevcut rollerden onay akışını oluştur
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    // Eksiksiz bir Transaction objesi oluştur
    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Batuhan Yontuç',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || request.packageQuantity || 1,
      unitPrice: request.unitPrice || request.packageUnitPrice || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPrice: request.packageUnitPrice || 0,
      totalAmount: request.totalAmount || (request.packageQuantity || 1) * (request.packageUnitPrice || 0),
      description: request.description || '',
      justification: request.justification || '',
      generalNotes: request.generalNotes || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      publicTrackKey: request.publicTrackKey,
      extraItems: request.extraItems || [],
      logs: request.logs || [],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    // State güncelleme
    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));

    // Sistem logu ekle
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} kodlu yeni talep oluşturuldu.`);

    // Ekranı "Süreç" sekmesine taşı, aramayı temizle ve "Bekleyen" filtresini aktif et
    setSearchQuery(''); 
    setStatusFilter('Pending');
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = newStatus === 'Purchased' ? 'Satın Alındı' : newStatus === 'Approved' ? 'Bütçe Onaylandı' : `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Güncelleme', `Kayıt #${id} yeni statüsü: ${newStatus}`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (updates.packageQuantity !== undefined || updates.packageUnitPrice !== undefined) {
             updated.totalAmount = (updated.packageQuantity || 0) * (updated.packageUnitPrice || 0);
          }
          return updated;
        }
        return t;
      })
    }));
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    setActiveTab('transactions');
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} sistemden kaldırıldı.`);
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => { 
        setActiveTab(tab); 
        setSelectedTransactionId(null); 
        if (tab !== 'transactions') setStatusFilter(null); 
      }} 
      user={state.user} 
      onLogout={handleLogout}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
    >
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                </div>
                <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                  <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                  <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                </div>
              </div>

              {searchQuery && (
                <div className="flex items-center space-x-2 text-violet-400 text-sm font-bold uppercase tracking-widest">
                  <Search size={16} />
                  <span>"{searchQuery}" araması için {filteredTransactions.length} sonuç bulundu</span>
                  <button onClick={() => setSearchQuery('')} className="text-[10px] bg-violet-500/10 px-2 py-1 rounded-md hover:bg-violet-500/20">TEMİZLE</button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group">
                      <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className="w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl">{t.requesterName ? t.requesterName.charAt(0) : 'A'}</div>
                        <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${
                          t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                          t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                          'bg-violet-500/10 text-violet-400 border-violet-500/20'
                        }`}>{
                          t.status === 'Pending' ? 'BEKLEYEN' : 
                          t.status === 'Approved' ? 'ONAYLI' : 
                          t.status === 'Purchased' ? 'ALINDI' : t.status
                        }</span>
                      </div>
                      <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                      <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-1">{t.department} • {t.supplierName}</p>
                      <p className="text-[9px] text-slate-500 font-mono mb-10">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')} {new Date(t.requestDateTime).toLocaleTimeString('tr-TR', {hour: '2-digit', minute:'2-digit'})}</p>
                      <div className="flex justify-between items-end border-t border-violet-500/10 pt-8">
                         <div>
                            <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                            <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full py-24 text-center glass-panel rounded-[40px] border border-dashed border-violet-500/20 opacity-50">
                    <Search size={48} className="mx-auto mb-4 text-violet-900" />
                    <p className="text-sm font-black text-violet-500 uppercase tracking-widest">Kayıt Bulunamadı</p>
                    <p className="text-xs text-slate-500 mt-2 italic">Arama kriterlerinizi değiştirip tekrar deneyin.</p>
                  </div>
                )}
              </div>
            </div>
          )}
          {activeTab === 'settings' && <Settings 
            roles={state.roles} 
            setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} 
            departments={state.departments} 
            setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} 
            user={state.user} 
            onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} 
            systemLogs={state.systemLogs} 
            transactions={state.transactions} 
            searchQuery={searchQuery}
            onSelectTransaction={(id) => { setSelectedTransactionId(id); }}
            onShowAll={() => { setActiveTab('transactions'); }}
            onBack={() => setActiveTab('dashboard')} 
          />}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Camera, Sparkles, Package, ShieldCheck, UserCheck, AlertTriangle, Globe, Layers } from 'lucide-react';
import { ExtraItem, Transaction, Currency, Priority } from '../types';
import { analyzeJustification } from '../services/geminiService';
import { INITIAL_ROLES } from '../constants';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    category: 'Genel Satın Alma',
    priority: 'Medium' as Priority,
    currency: 'TRY' as Currency,
    packageQuantity: 1,
    packageUnitPrice: 0,
    justification: '',
    generalNotes: '',
    microCode: '',
    photoUrl: '',
    totalAmount: 0
  });

  const [selectedRoles, setSelectedRoles] = useState<string[]>(INITIAL_ROLES.map(r => r.roleName));
  const [analyzing, setAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const total = formData.packageQuantity * formData.packageUnitPrice;
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, formData.packageUnitPrice]);

  const inputClass = "w-full px-4 py-3 rounded-xl gradient-neon-input text-slate-200 outline-none transition-all text-sm";

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert("Max 5MB limit aşıldı.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, photoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const approvalFlow = INITIAL_ROLES
      .filter(r => selectedRoles.includes(r.roleName))
      .map(r => ({ role: r.roleName, status: 'Pending' as const, approverName: r.assignedName }));

    onSave({
      ...formData,
      requestDateTime: new Date().toISOString(),
      publicTrackKey: Math.random().toString(36).substring(7),
      approvalFlow,
      status: 'Pending',
      logs: [{ id: Date.now().toString(), timestamp: new Date().toISOString(), user: 'Batuhan Yontuç', action: 'Talep Oluşturuldu', details: 'Yeni süreç başlatıldı.' }]
    });
  };

  const currencySymbols: Record<Currency, string> = { TRY: '₺', USD: '$', EUR: '€', GBP: '£' };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24">
      <div className="mb-10 flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-black text-white neon-text-premium uppercase tracking-tighter">STRATEJİK TALEP GİRİŞİ</h2>
          <p className="text-[10px] text-violet-400 font-black uppercase tracking-[0.3em] mt-2 opacity-60">Kurumsal Kaynak ve Harcama Yönetimi</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-8">
          {/* Görsel ve Temel Bilgiler */}
          <div className="glass-panel p-8 rounded-[40px] border border-violet-500/10 flex flex-col md:flex-row gap-8 items-center">
            <div className="relative w-full md:w-48 aspect-square rounded-[30px] overflow-hidden bg-black/40 border border-violet-500/20 flex items-center justify-center cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
              {formData.photoUrl ? (
                <img src={formData.photoUrl} className="w-full h-full object-cover" alt="Önizleme" />
              ) : (
                <div className="text-center">
                  <Camera className="mx-auto text-violet-500 mb-2" size={32} />
                  <p className="text-[9px] font-black text-white uppercase tracking-widest">FOTOĞRAF</p>
                </div>
              )}
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={handleFileChange} />
            </div>
            <div className="flex-1 space-y-4 w-full">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-violet-500 uppercase tracking-widest ml-1">Para Birimi</label>
                  <select value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as Currency})} className={inputClass}>
                    <option value="TRY" className="bg-[#020617]">TRY (₺)</option>
                    <option value="USD" className="bg-[#020617]">USD ($)</option>
                    <option value="EUR" className="bg-[#020617]">EUR (€)</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-rose-500 uppercase tracking-widest ml-1">Öncelik</label>
                  <select value={formData.priority} onChange={e => setFormData({...formData, priority: e.target.value as Priority})} className={`${inputClass} !border-rose-500/20`}>
                    <option value="Low" className="bg-[#020617]">DÜŞÜK</option>
                    <option value="Medium" className="bg-[#020617]">NORMAL</option>
                    <option value="High" className="bg-[#020617]">YÜKSEK</option>
                    <option value="Critical" className="bg-[#020617]">KRİTİK</option>
                  </select>
                </div>
              </div>
              <input required type="text" value={formData.productSetName} onChange={e => setFormData({...formData, productSetName: e.target.value})} placeholder="Talep Adı (Örn: Server Alımı)" className={inputClass} />
            </div>
          </div>

          {/* Finansal Detaylar */}
          <div className="glass-panel p-10 rounded-[40px] border border-violet-500/10 space-y-8">
            <div className="flex items-center space-x-4 mb-2">
              <Globe size={20} className="text-cyan-400" />
              <h3 className="text-xs font-black text-white uppercase tracking-widest">Maliyet Dağılımı</h3>
            </div>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
              <div className="space-y-2">
                <label className="text-[9px] font-black text-violet-500 uppercase ml-1">Miktar</label>
                <input type="number" value={formData.packageQuantity} onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})} className={inputClass} />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-violet-500 uppercase ml-1">Birim Fiyat ({currencySymbols[formData.currency]})</label>
                <input type="number" value={formData.packageUnitPrice} onChange={e => setFormData({...formData, packageUnitPrice: parseFloat(e.target.value) || 0})} className={inputClass} />
              </div>
              <div className="bg-violet-500/5 p-4 rounded-2xl border border-violet-500/20 flex flex-col justify-center text-right">
                <p className="text-[9px] text-violet-400 font-black uppercase mb-1">Total</p>
                <p className="text-2xl font-black text-white">{currencySymbols[formData.currency]}{formData.totalAmount.toLocaleString('tr-TR')}</p>
              </div>
            </div>
            <div className="pt-6 border-t border-violet-500/5 space-y-4">
               <div className="flex items-center justify-between">
                 <label className="text-[10px] font-black text-violet-400 uppercase tracking-widest">Satın Alma Gerekçesi</label>
                 <button type="button" onClick={async () => {
                   setAnalyzing(true);
                   const res = await analyzeJustification(formData.productSetName, formData.justification);
                   setAiAnalysis(res);
                   setAnalyzing(false);
                 }} className="text-[9px] font-black text-cyan-400 flex items-center space-x-2"><Sparkles size={14}/> <span>AI KONTROL</span></button>
               </div>
               <textarea required rows={4} value={formData.justification} onChange={e => setFormData({...formData, justification: e.target.value})} className={`${inputClass} resize-none`} placeholder="Yönetim için detaylı bütçe gerekçesini belirtin..." />
               {aiAnalysis && <div className="p-4 bg-cyan-500/5 border border-cyan-500/20 rounded-xl text-[11px] text-cyan-300 italic animate-in fade-in">"{aiAnalysis}"</div>}
            </div>
          </div>
        </div>

        {/* Sağ Sütun */}
        <div className="space-y-8">
           <div className="glass-panel p-8 rounded-[40px] border border-violet-500/10 shadow-2xl relative overflow-hidden">
              <div className="absolute -right-4 -top-4 opacity-5"><ShieldCheck size={120} /></div>
              <h3 className="text-xs font-black text-white uppercase tracking-widest mb-8 flex items-center">
                <UserCheck size={18} className="mr-3 text-violet-400" /> ONAY MERKİLERİ
              </h3>
              <div className="space-y-3">
                 {INITIAL_ROLES.map((role) => (
                   <div key={role.id} onClick={() => setSelectedRoles(prev => prev.includes(role.roleName) ? prev.filter(r => r !== role.roleName) : [...prev, role.roleName])} className={`p-4 rounded-2xl border transition-all cursor-pointer flex items-center justify-between ${selectedRoles.includes(role.roleName) ? 'bg-violet-600/10 border-violet-500/40 opacity-100' : 'opacity-40 border-white/5'}`}>
                      <span className="text-[11px] font-black text-white uppercase tracking-tight">{role.roleName}</span>
                      <div className={`w-5 h-5 rounded-full border-2 ${selectedRoles.includes(role.roleName) ? 'bg-violet-500 border-violet-400' : 'border-white/10'}`}></div>
                   </div>
                 ))}
              </div>
           </div>

           <button type="submit" className="w-full py-6 neon-gradient-premium text-white rounded-[30px] font-black shadow-2xl flex items-center justify-center space-x-3 uppercase tracking-widest text-sm active:scale-95 transition-all">
             <Send size={20} />
             <span>SÜRECİ BAŞLAT</span>
           </button>
        </div>
      </form>
    </div>
  );
};

export default NewRequest;

