                                                value={decisionNote} 
                                                onChange={e => setDecisionNote(e.target.value)} 
                                            />
                                            <button onClick={() => handleQuickApprove(flow.role)} className="p-3 bg-violet-600 text-white rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all"><Zap size={20} /></button>
                                          </>
                                        )}
                                        <button onClick={() => setSelectedFlowDetail(i)} className={`p-3 rounded-xl transition-all shadow-lg ${flow.proofUrl ? 'bg-green-500/20 text-green-400' : 'bg-white text-black'}`}>
