                    <button onClick={handleUpdateGeneralNotes} className="px-5 py-2 bg-violet-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg">KAYDET</button>
                </div>
                <textarea 
                    rows={4} 
                    value={generalNoteInput} 
                    onChange={e => setGeneralNoteInput(e.target.value)} 
