import React, { useState, useRef, useEffect } from 'react';
import { Send, Camera, Sparkles, Package, ShieldCheck, UserCheck, AlertTriangle, Globe, Layers, Loader2, Image as ImageIcon, X } from 'lucide-react';
import { ExtraItem, Transaction, Currency, Priority } from '../types';
