                    <p className="text-[8px] text-slate-500 font-bold uppercase mt-1">Yönetim onayı için zorunludur</p>
                 </div>
                 <button 
                  type="button" 
                  disabled={analyzing || !formData.justification}
                  onClick={async () => {
                    setAnalyzing(true);
                    const res = await analyzeJustification(formData.productSetName, formData.justification);
                    setAiAnalysis(res);
                    setAnalyzing(false);
                  }} 
                  className="text-[9px] font-black text-cyan-400 flex items-center space-x-2 bg-cyan-400/5 px-4 py-2 rounded-xl border border-cyan-400/10 hover:bg-cyan-400/10 transition-all disabled:opacity-30"
                 >
                   {analyzing ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14}/>} 
                   <span>AI ANALİZİ YAP</span>
                 </button>
               </div>
               <textarea 
                required 
                rows={5} 
                value={formData.justification} 
                onChange={e => setFormData(prev => ({...prev, justification: e.target.value}))} 
                className={`${inputClass} resize-none py-4 leading-relaxed`} 
                placeholder="Bu satın alma neden gerekli? Alternatifler değerlendirildi mi? Operasyonel faydası nedir? Lütfen detaylıca açıklayın..." 
               />
               {aiAnalysis && (
                 <div className="p-6 bg-cyan-500/5 border border-cyan-500/20 rounded-[25px] text-[11px] text-cyan-200 leading-relaxed italic animate-in fade-in slide-in-from-top-2">
                   <div className="flex items-center space-x-2 mb-2 text-cyan-400 font-black uppercase tracking-widest text-[9px]">
                      <Sparkles size={12} />
                      <span>Yapay Zeka Görüşü</span>
                   </div>
                   "{aiAnalysis}"
                 </div>
               )}
            </div>
          </div>
        </div>

        {/* Sağ Sütun */}
        <div className="space-y-8">
           <div className="glass-panel p-8 rounded-[40px] border border-violet-500/10 shadow-2xl relative overflow-hidden bg-gradient-to-b from-transparent to-violet-950/10">
              <div className="absolute -right-4 -top-4 opacity-[0.03] rotate-12"><ShieldCheck size={160} /></div>
              <div className="flex items-center justify-between mb-8">
                <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                  <UserCheck size={18} className="mr-3 text-violet-400" /> ONAY MERCİLERİ
                </h3>
                <span className="text-[10px] font-black text-violet-600">{selectedRoles.length} AKTİF</span>
              </div>
              <div className="space-y-3">
                 {INITIAL_ROLES.map((role) => (
                   <div 
                    key={role.id} 
                    onClick={() => setSelectedRoles(prev => prev.includes(role.roleName) ? prev.filter(r => r !== role.roleName) : [...prev, role.roleName])} 
                    className={`p-4 rounded-2xl border transition-all cursor-pointer flex items-center justify-between group ${selectedRoles.includes(role.roleName) ? 'bg-violet-600/10 border-violet-500/40 opacity-100 shadow-inner' : 'opacity-40 border-white/5 grayscale hover:grayscale-0 hover:opacity-70'}`}
                   >
                      <div className="flex flex-col">
                        <span className="text-[11px] font-black text-white uppercase tracking-tight group-hover:text-violet-400 transition-colors">{role.roleName}</span>
                        <span className="text-[9px] font-bold text-slate-500 uppercase">{role.assignedName}</span>
                      </div>
                      <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${selectedRoles.includes(role.roleName) ? 'bg-violet-500 border-violet-400 shadow-[0_0_10px_rgba(139,92,246,0.5)]' : 'border-white/10'}`}>
                        {selectedRoles.includes(role.roleName) && <Layers size={12} className="text-white" />}
                      </div>
                   </div>
                 ))}
              </div>
              <div className="mt-8 p-4 bg-amber-500/5 border border-amber-500/20 rounded-2xl flex items-start space-x-3">
                 <AlertTriangle size={16} className="text-amber-500 mt-1 flex-shrink-0" />
                 <p className="text-[9px] text-amber-200/60 font-medium leading-relaxed uppercase">Süreci başlattıktan sonra, belirlenen mercilerin onay sırasına göre talebiniz ilerleyecektir.</p>
              </div>
           </div>

           <button 
            type="submit" 
            className="w-full py-7 neon-gradient-premium text-white rounded-[35px] font-black shadow-2xl flex items-center justify-center space-x-4 uppercase tracking-[0.2em] text-sm active:scale-95 transition-all group overflow-hidden relative"
           >
             <div className="absolute inset-0 bg-white/10 translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
             <Send size={22} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
             <span>TALEBİ SİSTEME İŞLE</span>
           </button>

           <div className="p-6 text-center">
              <p className="text-[9px] text-slate-600 font-black uppercase tracking-widest">Yaşam Fatura Güvenli Veri Ağı</p>
           </div>
        </div>
      </form>
    </div>
  );
};

