import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Save,
  MessageSquare,
  FileText,
  Camera,
  Archive,
  Maximize2,
  Package,
  Copy,
  Check,
  Plus,
  Clock,
  UserCheck,
  CalendarDays,
  AlertTriangle,
  Info,
  X,
  Hash,
  Zap,
  Edit3,
  CreditCard,
