interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const [generalNoteInput, setGeneralNoteInput] = useState(transaction.generalNotes || '');
  const [analyzingJustification, setAnalyzingJustification] = useState(false);
  const [aiJustificationResult, setAiJustificationResult] = useState<string | null>(null);
  const [showAddApprover, setShowAddApprover] = useState(false);
  const [newApprover, setNewApprover] = useState({ role: '', name: '' });

  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPrice || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPrice, isEditing]);

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  const handleApprove = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const handlePurchase = () => {
    onStatusChange(transaction.id, 'Purchased');
    onBack();
  };

  const handleSuspend = () => {
    onUpdate(transaction.id, { 
      status: 'On Hold',
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Askıya Alındı',
        details: 'Talep geçici olarak beklemeye alındı.'
      }, ...transaction.logs]
    });
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, { ...editForm, generalNotes: generalNoteInput });
    setIsEditing(false);
  };

  const handleAddApprover = () => {
    if (!newApprover.role || !newApprover.name) return;
    const updatedFlow = [...transaction.approvalFlow, {
      role: newApprover.role,
      approverName: newApprover.name,
      status: 'Pending' as const
    }];
    onUpdate(transaction.id, {
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Onay Mercii Eklendi',
        details: `${newApprover.role} (${newApprover.name}) sürece dahil edildi.`
      }, ...transaction.logs]
    });
    setNewApprover({ role: '', name: '' });
    setShowAddApprover(false);
  };

  const handleUpdateGeneralNotes = () => {
    onUpdate(transaction.id, { 
      generalNotes: generalNoteInput,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Not Güncellendi',
        details: 'Dosya genel süreç notları güncellendi.'
      }, ...transaction.logs]
    });
    alert('Süreç notları kaydedildi.');
  };

  const handleAiJustificationAnalysis = async () => {
    setAnalyzingJustification(true);
    const result = await analyzeJustification(transaction.productSetName, transaction.justification);
    setAiJustificationResult(result);
    setAnalyzingJustification(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Dijital Onay Verildi' 
      } : f
    );

    const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      status: isNowFullyApproved ? 'Approved' : transaction.status,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Kısmi Onay',
        details: `${role} adımı onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleSignatureProof = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert("Dosya çok büyük (Max 5MB).");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: reader.result as string, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR'),
            decisionNote: decisionNote || 'İmzalı Belge İle Onaylandı'
          } : f
        );

        const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          status: isNowFullyApproved ? 'Approved' : transaction.status,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'İmza Kanıtı Yüklendi',
            details: `${role} için imzalı belge kanıtı yüklendi ve onaylandı.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string],
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'Fatura Eklendi',
            details: 'Yeni mali evrak sisteme yüklendi.'
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (index: number) => {
    if (!window.confirm('Bu faturayı silmek istediğinizden emin misiniz?')) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(index, 1);
    onUpdate(transaction.id, { 
      invoices: currentInvoices,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Fatura Silindi',
        details: 'Mali evrak sistemden kaldırıldı.'
      }, ...transaction.logs]
    });
  };

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(transaction.id)}`;

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-violet-400 bg-white/5 rounded-full hover:bg-white/10 transition-all"><X size={32}/></button>
          <img src={selectedImage} className="max-w-full max-h-[80vh] rounded-3xl shadow-[0_0_100px_rgba(139,92,246,0.4)] border border-violet-500/20" alt="Görsel" />
        </div>
      )}

      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-lg glass-panel p-8 md:p-12 rounded-[50px] border border-violet-500/20 relative shadow-2xl overflow-y-auto max-h-[90vh] custom-scroll">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-6 right-6 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-10">
                <div className="w-16 h-16 neon-gradient-premium rounded-[25px] flex items-center justify-center text-white"><UserCheck size={32} /></div>
                <div>
                    <h3 className="text-xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>
            <div className="space-y-6">
                <div className="p-6 bg-black/40 rounded-3xl border border-violet-500/10">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest mb-2">KARAR GEÇMİŞİ</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekliyor...'}</span>
                        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase border ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status}</span>
                    </div>
                    {transaction.approvalFlow[selectedFlowDetail].decisionNote && (
                      <p className="text-xs text-slate-400 mt-4 italic">"{transaction.approvalFlow[selectedFlowDetail].decisionNote}"</p>
                    )}
                </div>

                <div className="space-y-4">
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">IMZA / KANIT GÖRSELİ</p>
                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div className="w-full h-48 rounded-[30px] overflow-hidden border border-violet-500/20 cursor-pointer relative group" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover" alt="Proof" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center"><Maximize2 className="text-white" size={24} /></div>
                    </div>
                  ) : (
                    <div className="w-full py-10 border border-dashed border-violet-500/20 rounded-[30px] flex flex-col items-center justify-center text-slate-500">
                      <ImagePlus size={32} className="mb-2 opacity-20" />
                      <span className="text-[10px] font-black uppercase tracking-widest opacity-40">Dosya Yüklenmemiş</span>
                    </div>
                  )}

                  <button 
                    onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()} 
                    className="w-full py-5 bg-violet-600/10 text-violet-400 rounded-2xl border border-violet-500/20 font-black text-[10px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-lg flex items-center justify-center"
                  >
                    <Camera size={16} className="mr-3" /> YENİ KANIT EKLE
                  </button>
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
