                </div>
                <textarea 
                    rows={4} 
                    value={generalNoteInput} 
                    onChange={e => setGeneralNoteInput(e.target.value)} 
                    placeholder="Eknotlar..." 
                    className="w-full bg-black/40 border border-violet-500/20 rounded-3xl p-6 text-sm text-slate-300 outline-none focus:border-violet-500 transition-all resize-none"
                />
            </div>

            <div className="space-y-6">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest">SATIN ALMA GEREKÇESİ</h4>
                  {!isEditing && (
                    <button 
                      onClick={handleAiJustificationAnalysis} 
                      disabled={analyzingJustification}
                      className="text-[10px] font-black text-pink-500 flex items-center space-x-2 uppercase disabled:opacity-50"
                    >
                      {analyzingJustification ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
