                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
                {aiJustificationResult && (
                  <div className="p-8 bg-pink-500/5 border border-pink-500/20 rounded-[35px] animate-in fade-in">
                    <p className="text-sm text-slate-300 italic leading-relaxed">"{aiAnalysis}"</p>
                  </div>
                )}
            </div>
          </div>

          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-wrap items-center justify-center gap-6">
            {transaction.status !== 'Purchased' && transaction.status !== 'Approved' && (
              <button onClick={handleSuspend} className="px-10 py-5 bg-amber-600/10 border border-amber-600/20 text-amber-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-amber-600 hover:text-white transition-all">
                <PauseCircle size={20} className="mr-3" /> ASKIYA AL
              </button>
            )}

            {transaction.status === 'Approved' ? (
              <button onClick={handlePurchase} className="px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all flex items-center">
                <ShoppingBag size={24} className="mr-4" /> SATIN ALINDI İŞARETLE
              </button>
            ) : transaction.status !== 'Purchased' ? (
              <button 
                onClick={handleApprove} 
                disabled={!allApproved} 
                className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${
                  allApproved ? 'opacity-100' : 'opacity-20 cursor-not-allowed'
                } flex items-center`}
              >
                <CheckCircle2 size={24} className="mr-4" /> BÜTÇEYİ ONAYLA
              </button>
            ) : null}

            {(transaction.status === 'Pending' || transaction.status === 'On Hold') && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-10 py-5 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-xs uppercase transition-all">
                <XCircle size={20} className="mr-3" /> İPTAL ET
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">İŞLEM LOGLARI</h3>
