                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                    transaction.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                    'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>
                    {transaction.status === 'Pending' ? 'BEKLEYEN' : 
                     transaction.status === 'Approved' ? 'ONAYLI' : 
                     transaction.status === 'Purchased' ? 'ALINDI' : transaction.status}
                  </span>
                </div>
                <div className="flex items-center space-x-4">
                   <QrCode size={20} className="text-violet-500" />
                   <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">ID: {transaction.id} • TAKİP NO: {transaction.publicTrackKey || 'ÜRETİLMEDİ'}</p>
                </div>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                <div className="p-8 bg-violet-950/30 rounded-[35px] border border-violet-500/10 space-y-6">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> MİKTAR & BİRİM
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">ADET:</span>
                            <span className="text-white font-black text-lg">{transaction.packageQuantity}</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">BİRİM FİYAT:</span>
                            <span className="text-white font-black text-lg">₺{transaction.packageUnitPrice?.toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 flex flex-col justify-center space-y-4">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> MICRO KODU</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-5 rounded-2xl border border-violet-500/20 group cursor-pointer" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-violet-300 tracking-wider uppercase">{transaction.microCode || '---'}</span>
                        <Copy size={16} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />
                    </div>
                </div>
                <div className="p-8 bg-white/5 rounded-[35px] border border-white/10 flex items-center justify-center space-x-6">
                   <div className="text-center">
                      <p className="text-[9px] font-black text-violet-400 uppercase tracking-widest mb-2">QR TAKİP</p>
                      <img src={qrUrl} className="w-20 h-20 rounded-lg shadow-xl border border-white/20" alt="QR" />
                   </div>
                   <div className="flex-1">
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-tighter leading-tight">BU KODU MOBİL CİHAZINIZLA TARATARAK DOSYA ASLINA ULAŞABİLİRSİNİZ.</p>
                   </div>
                </div>
            </div>

            <div className={`p-10 rounded-[45px] border transition-all duration-700 ${transaction.status === 'Purchased' ? 'bg-emerald-600/5 border-emerald-500/30' : 'bg-violet-950/20 border-violet-500/10'}`}>
                <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-6">
                    <div className="flex items-center space-x-5">
                        <div className={`p-4 rounded-2xl ${transaction.status === 'Purchased' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-violet-500/20 text-violet-400'}`}>
                            <ReceiptText size={28} />
                        </div>
                        <div>
                            <h4 className="text-xl font-black text-white uppercase tracking-tighter">MALİ EVRAKLAR</h4>
                            <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Muhasebe dökümanları ve ödeme kanıtları</p>
                        </div>
                    </div>
                    <button 
                        onClick={() => invoiceInputRef.current?.click()}
                        className="px-8 py-4 bg-white text-black rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-400 transition-all flex items-center shadow-lg justify-center"
                    >
                        <Camera size={18} className="mr-3" /> BELGE EKLE
                    </button>
                    <input type="file" ref={invoiceInputRef} className="hidden" onChange={handleInvoiceUpload} accept="image/*" />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6">
                    {transaction.invoices && transaction.invoices.map((inv, idx) => (
                        <div key={idx} className="group relative aspect-square rounded-[25px] overflow-hidden border border-white/10 shadow-xl">
                            <img src={inv} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Fatura" onClick={() => setSelectedImage(inv)} />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-3">
                                <button onClick={() => setSelectedImage(inv)} className="p-2 bg-white/10 rounded-full text-white"><Maximize2 size={16} /></button>
                                <button onClick={() => removeInvoice(idx)} className="p-2 bg-rose-500/20 rounded-full text-rose-500"><Trash2 size={16} /></button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            <div className="space-y-10">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><ShieldCheck size={22} className="mr-4" /> ONAY ZİNCİRİ</h4>
                  <button 
                    onClick={() => setShowAddApprover(!showAddApprover)}
                    className="flex items-center space-x-2 text-[10px] font-black text-cyan-400 uppercase tracking-widest border border-cyan-500/20 px-4 py-2 rounded-xl hover:bg-cyan-500/10 transition-all"
                  >
                    <UserPlus size={14} />
                    <span>YENİ MERCİ EKLE</span>
                  </button>
                </div>

                {showAddApprover && (
                  <div className="p-8 glass-panel rounded-[35px] border border-cyan-500/20 bg-cyan-500/5 animate-in slide-in-from-top-4 duration-500 grid grid-cols-1 md:grid-cols-3 gap-6">
                     <div className="space-y-2">
                        <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest ml-1">ROL / UNVAN</label>
                        <input type="text" value={newApprover.role} onChange={e => setNewApprover({...newApprover, role: e.target.value})} placeholder="Örn: Teknik Müdür" className="w-full px-4 py-3 rounded-xl bg-black/40 border border-white/10 text-white outline-none" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest ml-1">YETKİLİ İSMİ</label>
                        <input type="text" value={newApprover.name} onChange={e => setNewApprover({...newApprover, name: e.target.value})} placeholder="Örn: Mehmet Öz" className="w-full px-4 py-3 rounded-xl bg-black/40 border border-white/10 text-white outline-none" />
                     </div>
                     <div className="flex items-end">
                        <button onClick={handleAddApprover} className="w-full py-3.5 bg-cyan-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">AKŞA DAHİL ET</button>
                     </div>
                  </div>
                )}

                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 transition-all duration-500 ${
                                flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-lg' : 
                                'bg-black border-violet-500/30 text-violet-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer" onClick={() => setSelectedFlowDetail(i)}>
                                    <h5 className="font-black text-white text-lg uppercase tracking-tight group-hover:text-violet-400 transition-colors">{flow.role}</h5>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono">{flow.date || 'Karar bekleniyor...'}</p>
                                </div>
