                </div>
            </div>

            {/* Onay Zinciri & Kanıt Yükleme */}
            <div className="space-y-10">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center"><ShieldCheck size={22} className="mr-4" /> STRATEJİK ONAY ZİNCİRİ</h4>
                  <button 
                    onClick={() => setShowAddApprover(!showAddApprover)}
                    className="flex items-center space-x-2 text-[10px] font-black text-cyan-400 uppercase tracking-widest border border-cyan-500/20 px-4 py-2 rounded-xl hover:bg-cyan-500/10 transition-all"
                  >
                    <UserPlus size={14} />
                    <span>MANUEL MERCİ EKLE</span>
                  </button>
                </div>

                {showAddApprover && (
                  <div className="p-8 glass-panel rounded-[35px] border border-cyan-500/20 bg-cyan-500/5 animate-in slide-in-from-top-4 duration-500 grid grid-cols-1 md:grid-cols-3 gap-6">
                     <div className="space-y-2">
                        <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest ml-1">ROL / UNVAN</label>
                        <input type="text" value={newApprover.role} onChange={e => setNewApprover({...newApprover, role: e.target.value})} placeholder="Örn: Teknik Müdür" className="w-full px-4 py-3 rounded-xl bg-black/40 border border-white/10 text-white outline-none" />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest ml-1">YETKİLİ İSMİ</label>
                        <input type="text" value={newApprover.name} onChange={e => setNewApprover({...newApprover, name: e.target.value})} placeholder="Örn: Mehmet Öz" className="w-full px-4 py-3 rounded-xl bg-black/40 border border-white/10 text-white outline-none" />
                     </div>
                     <div className="flex items-end">
                        <button onClick={handleAddApprover} className="w-full py-3.5 bg-cyan-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">AKŞA DAHİL ET</button>
                     </div>
                  </div>
                )}

                <div className="relative pl-16 space-y-12">
                    <div className="absolute left-8 top-6 bottom-6 w-px bg-violet-500/20"></div>
                    {transaction.approvalFlow.map((flow, i) => (
                        <div key={i} className="relative">
                            <div className={`absolute -left-[45px] top-1 w-12 h-12 rounded-[20px] flex items-center justify-center border-2 z-10 transition-all duration-500 ${
                                flow.status === 'Approved' ? 'bg-green-500 border-green-400 text-white shadow-lg' : 
                                'bg-black border-violet-500/30 text-violet-800'
                            }`}>
                                {flow.status === 'Approved' ? <CheckCircle2 size={24} /> : <span className="text-sm font-black">{i + 1}</span>}
                            </div>
                            <div className="p-8 rounded-[40px] border bg-violet-950/10 border-violet-500/5 group hover:border-violet-500/30 transition-all flex flex-col md:flex-row md:items-center justify-between gap-8">
                                <div className="space-y-2 cursor-pointer flex-1" onClick={() => setSelectedFlowDetail(i)}>
                                    <h5 className="font-black text-white text-lg uppercase tracking-tight group-hover:text-violet-400 transition-colors">{flow.role}</h5>
                                    <p className="text-xs text-slate-400 font-black uppercase tracking-wider">{flow.approverName}</p>
                                    <p className="text-[10px] text-slate-600 font-mono italic">{flow.date || 'İşlem bekleniyor...'}</p>
                                </div>

                                <div className="flex items-center space-x-4">
                                    {flow.status === 'Pending' ? (
                                      <div className="flex flex-col md:flex-row items-center gap-3">
                                          <input 
                                              type="text" 
                                              placeholder="Opsiyonel not..." 
                                              className="px-4 py-3 rounded-xl text-xs w-full md:w-40 bg-black/40 border border-violet-500/20 outline-none" 
                                              value={decisionNote} 
                                              onChange={e => setDecisionNote(e.target.value)} 
                                          />
                                          <div className="flex items-center space-x-2">
                                            {/* Kanıt Yükleme Butonu */}
                                            <button 
                                              onClick={() => fileInputRefs.current[flow.role]?.click()}
                                              className="px-6 py-3 bg-cyan-600 text-white rounded-xl font-black text-[9px] uppercase tracking-widest hover:bg-cyan-500 transition-all shadow-xl flex items-center"
                                              title="İmzalı Belge Fotoğrafı Yükle"
                                            >
                                              <UploadCloud size={14} className="mr-2" /> KANIT YÜKLE
                                            </button>
                                            <input 
                                              type="file" 
                                              ref={el => fileInputRefs.current[flow.role] = el} 
                                              className="hidden" 
                                              accept="image/*" 
                                              onChange={e => handleProofUpload(flow.role, e)} 
                                            />
                                            {/* Hızlı Dijital Onay Butonu */}
                                            <button 
                                              onClick={() => handleQuickApprove(flow.role)} 
                                              className="p-3 bg-violet-600 text-white rounded-xl shadow-lg hover:scale-105 active:scale-95 transition-all" 
                                              title="Hızlı Dijital Onay (Belgesiz)"
                                            >
                                              <Zap size={20} />
                                            </button>
                                          </div>
                                      </div>
                                    ) : (
                                      <div className="flex items-center space-x-4">
                                        {flow.proofUrl && (
                                          <div className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-green-500/30 cursor-pointer group shadow-lg" onClick={() => setSelectedImage(flow.proofUrl!)}>
                                            <img src={flow.proofUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform" alt="Proof" />
                                            <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                                              <Maximize2 size={14} className="text-white" />
                                            </div>
                                          </div>
                                        )}
                                        <button onClick={() => setSelectedFlowDetail(i)} className="p-3 text-violet-400 hover:bg-violet-500/10 rounded-xl transition-all shadow-inner border border-violet-500/10">
                                          <Info size={24} />
                                        </button>
                                      </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Süreç Notları */}
            <div className="p-10 bg-violet-950/30 rounded-[45px] border border-violet-500/10 space-y-6">
                <div className="flex items-center justify-between">
                    <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Notebook size={20} className="mr-4" /> GENEL SÜREÇ NOTLARI
                    </h4>
                    <button onClick={handleUpdateGeneralNotes} className="px-6 py-2 bg-violet-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-violet-500 transition-all">NOTU KAYDET</button>
                </div>
                <textarea 
                    rows={4} 
                    value={generalNoteInput} 
                    onChange={e => setGeneralNoteInput(e.target.value)} 
                    placeholder="Sürece dair önemli detayları buraya ekleyebilirsiniz..." 
                    className="w-full bg-black/40 border border-violet-500/20 rounded-3xl p-6 text-sm text-slate-300 outline-none focus:border-violet-500 transition-all resize-none shadow-inner"
                />
            </div>

            {/* Gerekçe & AI Analizi */}
            <div className="space-y-6">
                <div className="flex items-center justify-between px-4">
                  <h4 className="text-xs font-black text-violet-400 uppercase tracking-widest">SATIN ALMA STRATEJİK GEREKÇESİ</h4>
                  {!isEditing && (
                    <button 
                      onClick={handleAiJustificationAnalysis} 
                      disabled={analyzingJustification}
                      className="text-[10px] font-black text-pink-500 flex items-center space-x-2 uppercase disabled:opacity-50"
                    >
                      {analyzingJustification ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                      <span>AI STRATEJİ ANALİZİ</span>
                    </button>
                  )}
                </div>
                <div className="p-10 bg-violet-950/20 rounded-[40px] border border-violet-500/10 text-slate-200 leading-relaxed italic text-lg shadow-inner">
                    {isEditing ? <textarea rows={4} className="w-full bg-transparent border-b border-violet-500 outline-none py-2 text-white" value={editForm.justification} onChange={e => setEditForm({...editForm, justification: e.target.value})} /> : `"${transaction.justification}"`}
                </div>
                {aiJustificationResult && (
                  <div className="p-8 bg-pink-500/5 border border-pink-500/20 rounded-[35px] animate-in fade-in slide-in-from-top-2">
                    <div className="flex items-center space-x-2 mb-3">
                      <Sparkles size={16} className="text-pink-500" />
                      <span className="text-[10px] font-black text-pink-500 uppercase tracking-widest">AI RAPORU</span>
                    </div>
                    <p className="text-sm text-slate-300 italic leading-relaxed">"{aiJustificationResult}"</p>
                  </div>
                )}
            </div>
          </div>

          {/* Alt Aksiyon Butonları */}
          <div className="bg-violet-950/40 p-12 border-t border-violet-500/10 flex flex-wrap items-center justify-center gap-6">
            {transaction.status !== 'Purchased' && transaction.status !== 'Approved' && (
              <button onClick={handleSuspend} className="px-10 py-5 bg-amber-600/10 border border-amber-600/20 text-amber-500 rounded-3xl font-black text-xs uppercase tracking-widest hover:bg-amber-600 hover:text-white transition-all">
                <PauseCircle size={20} className="mr-3" /> DOSYAYI ASKIYA AL
              </button>
            )}

            {transaction.status === 'Approved' ? (
              <button onClick={handlePurchase} className="px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all flex items-center group">
                <ShoppingBag size={24} className="mr-4 group-hover:scale-110 transition-transform" /> SATIN ALMA TAMAMLANDI
              </button>
            ) : transaction.status !== 'Purchased' ? (
              <button 
                onClick={handleApprove} 
                disabled={!allApproved} 
                className={`px-16 py-6 neon-gradient-premium text-white rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all ${
                  allApproved ? 'opacity-100' : 'opacity-20 cursor-not-allowed grayscale'
                } flex items-center group`}
              >
                <CheckCircle2 size={24} className="mr-4 group-hover:scale-110 transition-transform" /> TOPLAM BÜTÇEYİ ONAYLA
              </button>
            ) : null}

            {(transaction.status === 'Pending' || transaction.status === 'On Hold') && (
              <button onClick={() => { onStatusChange(transaction.id, 'Rejected'); onBack(); }} className="px-10 py-5 bg-rose-600/10 border border-rose-600/20 text-rose-500 rounded-3xl font-black text-xs uppercase hover:bg-rose-600 hover:text-white transition-all">
                <XCircle size={20} className="mr-3" /> TALEBİ REDDET
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Sağ Yan Panel: Loglar */}
      <div className="w-full lg:w-96 space-y-10">
        <div className="glass-panel rounded-[40px] border border-violet-500/10 overflow-hidden shadow-2xl sticky top-28">
          <div className="p-8 border-b border-violet-500/10 bg-violet-950/40 flex items-center space-x-4">
            <History size={24} className="text-violet-500" />
            <h3 className="font-black text-xs uppercase tracking-widest text-white">DOSYA TARİHÇESİ (LOG)</h3>
          </div>
          <div className="p-8 space-y-8 max-h-[600px] overflow-y-auto custom-scroll pr-4">
            {transaction.logs.map((log) => (
              <div key={log.id} className="relative pl-8 border-l border-violet-500/20 pb-8 last:pb-0">
                <div className="absolute left-[-6px] top-0 w-3 h-3 rounded-full bg-violet-500 shadow-[0_0_10px_rgba(139,92,246,0.5)]"></div>
                <div className="flex justify-between items-center mb-1">
                  <span className="font-black text-[10px] text-violet-400 uppercase tracking-tighter">{log.user}</span>
                  <span className="text-[10px] text-slate-600 font-mono">{new Date(log.timestamp).toLocaleTimeString('tr-TR', {hour:'2-digit', minute:'2-digit'})}</span>
                </div>
                <p className="text-xs text-slate-400 leading-snug"><span className="text-white font-bold">{log.action}:</span> {log.details}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, 
  CheckCircle2, 
  XCircle, 
  History, 
  ShieldCheck, 
  Trash2, 
  Maximize2,
  Package,
  Copy,
  UserCheck,
  Info,
  X,
  Hash,
  Zap,
  Edit3,
  ImagePlus,
  PauseCircle,
  ShoppingBag,
  ReceiptText,
  Notebook,
  Sparkles,
  Loader2,
  QrCode,
  UserPlus,
  FileSignature,
  UploadCloud,
  FileCheck,
  Camera
} from 'lucide-react';
import { Transaction, Role } from '../types';
import { analyzeJustification } from '../services/geminiService';
import { INITIAL_ROLES } from '../constants';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const [generalNoteInput, setGeneralNoteInput] = useState(transaction.generalNotes || '');
  const [analyzingJustification, setAnalyzingJustification] = useState(false);
  const [aiJustificationResult, setAiJustificationResult] = useState<string | null>(null);
  const [showAddApprover, setShowAddApprover] = useState(false);
  const [newApprover, setNewApprover] = useState({ role: '', name: '' });

  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPrice || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPrice, isEditing]);

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  const handleApprove = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const handlePurchase = () => {
    onStatusChange(transaction.id, 'Purchased');
    onBack();
  };

  const handleSuspend = () => {
    onUpdate(transaction.id, { 
      status: 'On Hold',
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Askıya Alındı',
        details: 'Talep geçici olarak beklemeye alındı.'
      }, ...transaction.logs]
    });
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, { ...editForm, generalNotes: generalNoteInput });
    setIsEditing(false);
  };

  const handleAddApprover = () => {
    if (!newApprover.role || !newApprover.name) return;
    const updatedFlow = [...transaction.approvalFlow, {
      role: newApprover.role,
      approverName: newApprover.name,
      status: 'Pending' as const
    }];
    onUpdate(transaction.id, {
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Onay Mercii Eklendi',
        details: `${newApprover.role} (${newApprover.name}) sürece dahil edildi.`
      }, ...transaction.logs]
    });
    setNewApprover({ role: '', name: '' });
    setShowAddApprover(false);
  };

  const handleUpdateGeneralNotes = () => {
    onUpdate(transaction.id, { 
      generalNotes: generalNoteInput,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Not Güncellendi',
        details: 'Dosya genel süreç notları güncellendi.'
      }, ...transaction.logs]
    });
    alert('Süreç notları kaydedildi.');
  };

  const handleAiJustificationAnalysis = async () => {
    setAnalyzingJustification(true);
    const result = await analyzeJustification(transaction.productSetName, transaction.justification);
    setAiJustificationResult(result);
    setAnalyzingJustification(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Hızlı Dijital Onay' 
      } : f
    );

    const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      status: isNowFullyApproved ? 'Approved' : transaction.status,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Dijital Onay',
        details: `${role} adımı dijital imza ile onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleProofUpload = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert("Dosya boyutu 5MB limitini aşıyor.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = reader.result as string;
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: base64Data, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR'),
            decisionNote: f.decisionNote || 'İmzalı Kanıt Belgesi Yüklendi'
          } : f
        );

        const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          status: isNowFullyApproved ? 'Approved' : transaction.status,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'Kanıt Belgesi İşlendi',
            details: `${role} için imzalı belge kanıtı sisteme yüklendi/güncellendi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string],
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'Fatura Eklendi',
            details: 'Dosyaya yeni mali evrak eklendi.'
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (index: number) => {
    if (!window.confirm('Bu faturayı silmek istediğinizden emin misiniz?')) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(index, 1);
    onUpdate(transaction.id, { 
      invoices: currentInvoices,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Fatura Silindi',
        details: 'Bir mali evrak sistemden kaldırıldı.'
      }, ...transaction.logs]
    });
  };

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(transaction.id)}`;

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Görsel Lightbox Modalı */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl animate-in fade-in">
          <button onClick={() => setSelectedImage(null)} className="absolute top-10 right-10 p-4 text-white bg-white/5 rounded-full hover:bg-white/10 transition-all shadow-2xl">
            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] rounded-3xl shadow-[0_0_100px_rgba(139,92,246,0.3)] border border-white/10" alt="Detay Görsel" />
        </div>
      )}

      {/* Onay Detay Modalı */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-xl glass-panel p-10 rounded-[50px] border border-violet-500/20 relative shadow-2xl overflow-y-auto max-h-[90vh] custom-scroll">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-12">
                <div className="w-20 h-20 neon-gradient-premium rounded-[32px] flex items-center justify-center text-white shadow-xl">
                  <UserCheck size={40} />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-[11px] font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-8">
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 space-y-4">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">ONAY DURUMU VE TARİH</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase border shadow-lg ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'ONAYLANDI' : 'BEKLEMEDE'}</span>
                    </div>
                    {transaction.approvalFlow[selectedFlowDetail].decisionNote && (
                      <div className="mt-4 p-4 bg-violet-500/5 rounded-2xl border border-violet-500/10 italic text-xs text-slate-300">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote}"
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                  <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest flex items-center">
                    <FileCheck size={16} className="mr-3" /> İMZALI KANIT BELGESİ
                  </p>
                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div className="w-full h-64 rounded-[40px] overflow-hidden border border-violet-500/20 cursor-pointer relative group" onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail].proofUrl!)}>
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover" alt="Proof" />
                      <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Maximize2 className="text-white" size={32} />
                      </div>
                    </div>
                  ) : (
                    <div className="w-full py-16 border-2 border-dashed border-violet-500/20 rounded-[40px] flex flex-col items-center justify-center text-slate-600 bg-violet-500/5">
                      <ImagePlus size={48} className="mb-4 opacity-20" />
                      <span className="text-[11px] font-black uppercase tracking-widest opacity-40">Henüz Belge Yüklenmedi</span>
                    </div>
                  )}

                  <button 
                    onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()} 
                    className="w-full py-6 bg-violet-600/10 text-violet-400 rounded-3xl border border-violet-500/20 font-black text-[11px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-xl flex items-center justify-center"
                  >
                    <UploadCloud size={18} className="mr-3" /> {transaction.approvalFlow[selectedFlowDetail].proofUrl ? 'KANIT BELGESİNİ GÜNCELLE' : 'KANIT BELGESİ SEÇ'}
                  </button>
                  <input 
                    type="file" 
                    ref={el => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role] = el} 
                    className="hidden" 
                    accept="image/*" 
                    onChange={e => handleProofUpload(transaction.approvalFlow[selectedFlowDetail!].role, e)} 
                  />
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>LİSTEYE DÖN</span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Talebi silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all"><Trash2 size={20} /></button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative shadow-2xl">
          {transaction.photoUrl && (
            <div className="w-full h-64 md:h-96 relative group cursor-pointer overflow-hidden" onClick={() => setSelectedImage(transaction.photoUrl!)}>
               <img src={transaction.photoUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-1000" alt="Ürün" />
               <div className="absolute inset-0 bg-gradient-to-t from-[#020617] to-transparent opacity-60"></div>
               <div className="absolute bottom-8 left-8 flex items-center space-x-4">
                  <div className="p-4 bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 text-white"><Maximize2 size={24} /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">ÜRÜN REFERANS GÖRSELİ</span>
               </div>
            </div>
          )}

          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20 relative">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div className="flex-1">
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                    transaction.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                    'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>
                    {transaction.status === 'Pending' ? 'BEKLEYEN' : 
                     transaction.status === 'Approved' ? 'ONAYLI' : 
                     transaction.status === 'Purchased' ? 'ALINDI' : transaction.status}
                  </span>
                </div>
                <div className="flex items-center space-x-4">
                   <QrCode size={20} className="text-violet-500" />
                   <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">ID: {transaction.id} • TAKİP ANAHTARI: {transaction.publicTrackKey || 'ÜRETİLMEDİ'}</p>
                </div>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            {/* Finansal Detaylar */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                <div className="p-8 bg-violet-950/30 rounded-[35px] border border-violet-500/10 space-y-6">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> MİKTAR & BİRİM
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">TALEP EDİLEN:</span>
                            <span className="text-white font-black text-lg">{transaction.packageQuantity} ADET</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">BİRİM MALİYET:</span>
                            <span className="text-white font-black text-lg">₺{transaction.packageUnitPrice?.toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 flex flex-col justify-center space-y-4">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> MUHASEBE / MICRO KODU</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-5 rounded-2xl border border-violet-500/20 group cursor-pointer" title="Kopyalamak için tıkla" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-violet-300 tracking-wider uppercase">{transaction.microCode || '---'}</span>
                        {copied ? <CheckCircle2 size={16} className="text-green-500" /> : <Copy size={16} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />}
                    </div>
                </div>
                <div className="p-8 bg-white/5 rounded-[35px] border border-white/10 flex items-center justify-center space-x-6">
                   <div className="text-center">
                      <p className="text-[9px] font-black text-violet-400 uppercase tracking-widest mb-2">HIZLI TAKİP</p>
                      <img src={qrUrl} className="w-20 h-20 rounded-lg shadow-xl border border-white/20 p-1 bg-white" alt="QR" />
                   </div>
                   <div className="flex-1">
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-tighter leading-tight">MOBİL CİHAZLA TARATARAK DİJİTAL ASLINA ULAŞABİLİRSİNİZ.</p>
                   </div>
                </div>
            </div>

            {/* Mali Evraklar */}
            <div className={`p-10 rounded-[45px] border transition-all duration-700 ${transaction.status === 'Purchased' ? 'bg-emerald-600/5 border-emerald-500/30' : 'bg-violet-950/20 border-violet-500/10'}`}>
                <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-6">
                    <div className="flex items-center space-x-5">
                        <div className={`p-4 rounded-2xl ${transaction.status === 'Purchased' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-violet-500/20 text-violet-400'}`}>
                            <ReceiptText size={28} />
