import React, { useMemo, useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, PieChart, Pie, Cell, LineChart, Line, Legend, Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis
} from 'recharts';
import { 
  FileDown, TrendingUp, TrendingDown, Target, Building2, 
  ShoppingBag, Calendar, Users, Sparkles, Filter, 
  ArrowUpRight, Printer, Zap, Award, Briefcase,
  ShieldCheck, AlertCircle, PieChart as PieChartIcon, Activity,
  Crown, BarChart3, Presentation
} from 'lucide-react';
import { Transaction } from '../types';
import { GoogleGenAI } from "@google/genai";

interface ReportsProps {
  transactions: Transaction[];
}

const COLORS = ['#8b5cf6', '#06b6d4', '#f43f5e', '#10b981', '#f59e0b', '#ec4899'];

const Reports: React.FC<ReportsProps> = ({ transactions }) => {
  const [aiAnalysis, setAiAnalysis] = useState<{brief: string, recommendations: string[], risks: string[]}>({
    brief: "",
    recommendations: [],
    risks: []
  });
  const [loadingAi, setLoadingAi] = useState(false);

  // Veri Agregasyonu
  const stats = useMemo(() => {
    const purchased = transactions.filter(t => t.status === 'Purchased');
    const total = purchased.reduce((sum, t) => sum + t.totalAmount, 0);
    const avg = purchased.length > 0 ? total / purchased.length : 0;

    // Aylık Veri
    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const monthlyMap: Record<string, { month: string, total: number, count: number }> = {};

    // Departman Verisi
    const deptMap: Record<string, number> = {};

    // Kategori Verisi
    const categoryMap: Record<string, number> = {};

    purchased.forEach(t => {
      const date = new Date(t.requestDateTime);
      const mLabel = months[date.getMonth()];
      if (!monthlyMap[mLabel]) monthlyMap[mLabel] = { month: mLabel, total: 0, count: 0 };
      monthlyMap[mLabel].total += t.totalAmount;
      monthlyMap[mLabel].count += 1;

      deptMap[t.department] = (deptMap[t.department] || 0) + t.totalAmount;
      const cat = t.category || 'Genel';
      categoryMap[cat] = (categoryMap[cat] || 0) + t.totalAmount;
    });

    const monthlyData = months.map(m => monthlyMap[m] || { month: m, total: 0, count: 0 });
    const deptData = Object.entries(deptMap).map(([name, value]) => ({ name, value }));
    const categoryData = Object.entries(categoryMap).map(([name, value]) => ({ name, value }));

    // En yoğun ay
    const peakMonth = [...monthlyData].sort((a, b) => b.total - a.total)[0];

    return { total, avg, monthlyData, deptData, categoryData, peakMonth, count: purchased.length };
  }, [transactions]);

  // Gemini AI Stratejik Raporlama
  useEffect(() => {
    const getAiReport = async () => {
      if (stats.count === 0) return;
      setLoadingAi(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Sen kıdemli bir CFO ve veri analistisin. Aşağıdaki satın alma verilerini analiz et ve bir yönetim kurulu raporu hazırla.
        JSON formatında şu yapıda yanıt ver: 
        {
          "brief": "Genel mali durum özeti (max 150 kelime)",
          "recommendations": ["3 adet bütçe iyileştirme tavsiyesi"],
          "risks": ["2 adet potansiyel mali risk"]
        }

        Veriler:
        Toplam Harcama: ₺${stats.total}
        Harcama Sayısı: ${stats.count}
        Departman Dağılımları: ${stats.deptData.map(d => `${d.name}: ₺${d.value}`).join(', ')}

        Sadece JSON döndür. Türkçe yanıtla.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
          config: { responseMimeType: "application/json" }
        });

        const result = JSON.parse(response.text || "{}");
        setAiAnalysis({
          brief: result.brief || "Analiz raporu oluşturuluyor...",
          recommendations: result.recommendations || [],
          risks: result.risks || []
        });
      } catch (e) {
        setAiAnalysis({
          brief: "Sistem verileri başarıyla işlendi, AI stratejik özeti oluşturulamadı.",
          recommendations: ["Bütçe disiplinine devam edilmesi tavsiye edilir."],
          risks: ["Veri akışında düzensizlik gözlemlendi."]
        });
      } finally {
        setLoadingAi(false);
      }
    };
    getAiReport();
  }, [stats]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="space-y-12 pb-24 animate-in fade-in duration-1000 relative">

      {/* Arkaplan Efektleri */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-violet-600/5 rounded-full blur-[120px] pointer-events-none"></div>
      <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-cyan-600/5 rounded-full blur-[120px] pointer-events-none"></div>

      {/* Rapor Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 print:hidden">
        <div>
          <div className="flex items-center space-x-3 mb-2">
            <div className="w-8 h-8 neon-gradient-premium rounded-xl flex items-center justify-center text-white">
              <BarChart3 size={20} />
            </div>
            <h2 className="text-4xl lg:text-6xl font-black text-white neon-text-premium tracking-tighter uppercase leading-none">STRATEJİK ANALİZ</h2>
          </div>
          <p className="text-violet-400 font-black text-[10px] uppercase tracking-[0.4em] mt-3 flex items-center">
            <Activity size={14} className="mr-3 animate-pulse" /> GERÇEK ZAMANLI FİNANSAL KOMUTA MERKEZİ
          </p>
        </div>
        <div className="flex space-x-4">
          <button 
            onClick={handlePrint} 
            className="group px-10 py-5 bg-white text-black rounded-[25px] text-[10px] font-black uppercase tracking-widest flex items-center shadow-2xl hover:bg-violet-600 hover:text-white transition-all active:scale-95"
          >
            <Presentation size={20} className="mr-4 group-hover:scale-110 transition-transform" /> SUNUM DOSYASI HAZIRLA (PDF)
          </button>
        </div>
      </div>

      {/* Yönetici PDF Raporu İçin Sadece Print'te Görünür Header */}
      <div className="hidden print:block mb-12">
        <div className="flex justify-between items-start border-b-4 border-black pb-8">
           <div>
              <h1 className="text-4xl font-black text-black">YAŞAM FATURA</h1>
              <p className="text-xs font-bold text-gray-600 tracking-widest mt-1 uppercase">Stratejik Satın Alma ve Bütçe Denetim Raporu</p>
           </div>
           <div className="text-right">
              <p className="text-sm font-black text-black">RAPOR TARİHİ: {new Date().toLocaleDateString('tr-TR')}</p>
              <p className="text-xs text-gray-500">DOSYA NO: {Math.random().toString(36).substring(7).toUpperCase()}</p>
           </div>
        </div>
      </div>

      {/* Ana Metrik Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        {[
          { label: 'TOPLAM HARCAMA', val: `₺${stats.total.toLocaleString('tr-TR')}`, icon: <TrendingUp size={24} />, color: 'text-green-400', bg: 'bg-green-500/5', border: 'border-green-500/20' },
          { label: 'DOSYA BAŞI ORT.', val: `₺${stats.avg.toLocaleString('tr-TR', { maximumFractionDigits: 0 })}`, icon: <Target size={24} />, color: 'text-cyan-400', bg: 'bg-cyan-500/5', border: 'border-cyan-500/20' },
          { label: 'ZİRVE HACİM (AY)', val: stats.peakMonth.month, icon: <Crown size={24} />, color: 'text-amber-500', bg: 'bg-amber-500/5', border: 'border-amber-500/20' },
          { label: 'İŞLEM SAYISI', val: stats.count, icon: <Activity size={24} />, color: 'text-violet-500', bg: 'bg-violet-500/5', border: 'border-violet-500/20' },
        ].map((m, i) => (
          <div key={i} className={`glass-panel p-10 rounded-[45px] border ${m.border} ${m.bg} relative overflow-hidden group hover:-translate-y-2 transition-all duration-500`}>
            <div className={`absolute -right-6 -top-6 p-10 opacity-5 group-hover:opacity-10 transition-opacity ${m.color}`}>{m.icon}</div>
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">{m.label}</p>
            <h3 className={`text-3xl font-black ${m.color} tracking-tight`}>{m.val}</h3>
            <div className="mt-4 flex items-center text-[9px] font-black uppercase text-slate-600 tracking-tighter">
               <ArrowUpRight size={14} className="mr-1 text-green-500" /> GEÇEN AYA GÖRE %12 ARTIŞ
            </div>
          </div>
        ))}
      </div>

      {/* AI Strateji Paneli */}
