            <X size={32}/>
          </button>
          <img src={selectedImage} className="max-w-full max-h-[85vh] rounded-3xl shadow-[0_0_100px_rgba(139,92,246,0.3)] border border-white/10" alt="Detay Görsel" />
        </div>
      )}

      {/* Onay Detay Modalı */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-xl glass-panel p-10 rounded-[50px] border border-violet-500/20 relative shadow-2xl overflow-y-auto max-h-[90vh] custom-scroll">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-12">
                <div className="w-20 h-20 neon-gradient-premium rounded-[32px] flex items-center justify-center text-white shadow-xl">
                  <UserCheck size={40} />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-[11px] font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-8">
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 space-y-4">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">ONAY DURUMU VE TARİH</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase border shadow-lg ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'ONAYLANDI' : 'BEKLEMEDE'}</span>
                    </div>
                    {transaction.approvalFlow[selectedFlowDetail].decisionNote && (
                      <div className="mt-4 p-4 bg-violet-500/5 rounded-2xl border border-violet-500/10 italic text-xs text-slate-300">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote}"
