  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, 
  onBack, 
  onStatusChange, 
  onDelete,
  onUpdate,
  currentUserRole
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(transaction);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [selectedFlowDetail, setSelectedFlowDetail] = useState<number | null>(null);
  const [copied, setCopied] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');
  const [generalNoteInput, setGeneralNoteInput] = useState(transaction.generalNotes || '');
  const [analyzingJustification, setAnalyzingJustification] = useState(false);
  const [aiJustificationResult, setAiJustificationResult] = useState<string | null>(null);
  const [showAddApprover, setShowAddApprover] = useState(false);
  const [newApprover, setNewApprover] = useState({ role: '', name: '' });

  const fileInputRefs = useRef<{ [key: string]: HTMLInputElement | null }>({});
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedImage) setSelectedImage(null);
        else if (selectedFlowDetail !== null) setSelectedFlowDetail(null);
        else onBack();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onBack, selectedImage, selectedFlowDetail]);

  useEffect(() => {
    if (isEditing) {
      const newTotal = (editForm.packageQuantity || 0) * (editForm.packageUnitPrice || 0);
      if (newTotal !== editForm.totalAmount) {
        setEditForm(prev => ({ ...prev, totalAmount: newTotal }));
      }
    }
  }, [editForm.packageQuantity, editForm.packageUnitPrice, isEditing]);

  const allApproved = transaction.approvalFlow.every(f => f.status === 'Approved');

  const handleApprove = () => {
    onStatusChange(transaction.id, 'Approved');
    onBack();
  };

  const handlePurchase = () => {
    onStatusChange(transaction.id, 'Purchased');
    onBack();
  };

  const handleSuspend = () => {
    onUpdate(transaction.id, { 
      status: 'On Hold',
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Sistem',
        action: 'Askıya Alındı',
        details: 'Talep geçici olarak beklemeye alındı.'
      }, ...transaction.logs]
    });
    onBack();
  };

  const copyMicroCode = () => {
    if (!transaction.microCode) return;
    navigator.clipboard.writeText(transaction.microCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSave = () => {
    onUpdate(transaction.id, { ...editForm, generalNotes: generalNoteInput });
    setIsEditing(false);
  };

  const handleAddApprover = () => {
    if (!newApprover.role || !newApprover.name) return;
    const updatedFlow = [...transaction.approvalFlow, {
      role: newApprover.role,
      approverName: newApprover.name,
      status: 'Pending' as const
    }];
    onUpdate(transaction.id, {
      approvalFlow: updatedFlow,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Onay Mercii Eklendi',
        details: `${newApprover.role} (${newApprover.name}) sürece dahil edildi.`
      }, ...transaction.logs]
    });
    setNewApprover({ role: '', name: '' });
    setShowAddApprover(false);
  };

  const handleUpdateGeneralNotes = () => {
    onUpdate(transaction.id, { 
      generalNotes: generalNoteInput,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Not Güncellendi',
        details: 'Dosya genel süreç notları güncellendi.'
      }, ...transaction.logs]
    });
    alert('Süreç notları kaydedildi.');
  };

  const handleAiJustificationAnalysis = async () => {
    setAnalyzingJustification(true);
    const result = await analyzeJustification(transaction.productSetName, transaction.justification);
    setAiJustificationResult(result);
    setAnalyzingJustification(false);
  };

  const handleQuickApprove = (role: string) => {
    const updatedFlow = transaction.approvalFlow.map(f => 
      f.role === role ? { 
        ...f, 
        status: 'Approved' as const, 
        date: new Date().toLocaleString('tr-TR'), 
        decisionNote: decisionNote || 'Hızlı Dijital Onay' 
      } : f
    );

    const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      status: isNowFullyApproved ? 'Approved' : transaction.status,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Dijital Onay',
        details: `${role} adımı dijital imza ile onaylandı.`
      }, ...transaction.logs]
    });
    setDecisionNote('');
  };

  const handleProofUpload = (role: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert("Dosya boyutu 5MB limitini aşıyor.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = reader.result as string;
        const updatedFlow = transaction.approvalFlow.map(f => 
          f.role === role ? { 
            ...f, 
            proofUrl: base64Data, 
            status: 'Approved' as const, 
            date: f.date || new Date().toLocaleString('tr-TR'),
            decisionNote: f.decisionNote || 'İmzalı Kanıt Belgesi Yüklendi'
          } : f
        );

        const isNowFullyApproved = updatedFlow.every(f => f.status === 'Approved');

        onUpdate(transaction.id, { 
          approvalFlow: updatedFlow,
          status: isNowFullyApproved ? 'Approved' : transaction.status,
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'Kanıt Belgesi İşlendi',
            details: `${role} için imzalı belge kanıtı sisteme yüklendi/güncellendi.`
          }, ...transaction.logs]
        });
        setDecisionNote('');
      };
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string],
          logs: [{
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            user: 'Batuhan Yontuç',
            action: 'Fatura Eklendi',
            details: 'Dosyaya yeni mali evrak eklendi.'
          }, ...transaction.logs]
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (index: number) => {
    if (!window.confirm('Bu faturayı silmek istediğinizden emin misiniz?')) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(index, 1);
    onUpdate(transaction.id, { 
      invoices: currentInvoices,
      logs: [{
        id: Date.now().toString(),
        timestamp: new Date().toISOString(),
        user: 'Batuhan Yontuç',
        action: 'Fatura Silindi',
        details: 'Bir mali evrak sistemden kaldırıldı.'
      }, ...transaction.logs]
    });
  };

  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(transaction.id)}`;

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Gelişmiş Premium Lightbox Modalı */}
      {selectedImage && (
        <div 
          className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-[#020617]/95 backdrop-blur-[40px] animate-in fade-in duration-500"
          onClick={() => setSelectedImage(null)}
        >
          <div className="absolute top-10 right-10 flex items-center space-x-6 z-50">
            <button className="px-6 py-3 bg-white/10 backdrop-blur-xl rounded-2xl text-white font-black text-[10px] uppercase tracking-widest border border-white/20 hover:bg-white/20 transition-all shadow-2xl flex items-center">
              <Camera size={16} className="mr-3" /> BELGE ASLI
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); setSelectedImage(null); }} 
              className="p-4 text-white bg-rose-500/20 backdrop-blur-xl rounded-full hover:bg-rose-500 transition-all shadow-2xl border border-rose-500/30"
            >
              <X size={32}/>
            </button>
          </div>

          <div className="relative group max-w-5xl w-full" onClick={(e) => e.stopPropagation()}>
            <div className="absolute -inset-10 bg-violet-600/20 rounded-[100px] blur-[120px] opacity-40 group-hover:opacity-60 transition-opacity"></div>
            <img 
              src={selectedImage} 
              className="relative w-full h-auto max-h-[85vh] object-contain rounded-[40px] shadow-[0_0_100px_rgba(0,0,0,0.8)] border border-white/10 animate-in zoom-in-95 duration-500" 
              alt="Detay Görsel" 
            />
            <div className="absolute bottom-[-60px] left-0 right-0 text-center">
               <p className="text-[10px] font-black text-violet-400 uppercase tracking-[0.5em] opacity-60">BELGE GÖRÜNTÜLEME MODU • YAŞAM FATURA DİJİTAL ARŞİV</p>
            </div>
          </div>
        </div>
      )}

      {/* Onay Detay Modalı (Geliştirilmiş) */}
      {selectedFlowDetail !== null && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-xl animate-in fade-in">
          <div className="w-full max-w-xl glass-panel p-10 rounded-[50px] border border-violet-500/20 relative shadow-2xl overflow-y-auto max-h-[90vh] custom-scroll">
            <button onClick={() => setSelectedFlowDetail(null)} className="absolute top-8 right-8 p-3 text-violet-400 hover:bg-white/5 rounded-2xl"><X size={24} /></button>
            <div className="flex items-center space-x-6 mb-12">
                <div className="w-20 h-20 neon-gradient-premium rounded-[32px] flex items-center justify-center text-white shadow-xl">
                  <UserCheck size={40} />
                </div>
                <div>
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{transaction.approvalFlow[selectedFlowDetail].approverName}</h3>
                    <p className="text-[11px] font-black text-violet-500 uppercase tracking-widest opacity-60">{transaction.approvalFlow[selectedFlowDetail].role}</p>
                </div>
            </div>

            <div className="space-y-8">
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 space-y-4">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest">ONAY DURUMU VE TARİH</p>
                    <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-white">{transaction.approvalFlow[selectedFlowDetail].date || 'Bekleniyor...'}</span>
                        <span className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase border shadow-lg ${
                          transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'
                        }`}>{transaction.approvalFlow[selectedFlowDetail].status === 'Approved' ? 'ONAYLANDI' : 'BEKLEMEDE'}</span>
                    </div>
                    {transaction.approvalFlow[selectedFlowDetail].decisionNote && (
                      <div className="mt-4 p-4 bg-violet-500/5 rounded-2xl border border-violet-500/10 italic text-xs text-slate-300">
                        "{transaction.approvalFlow[selectedFlowDetail].decisionNote}"
                      </div>
                    )}
                </div>

                <div className="space-y-4">
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-[10px] font-black text-violet-500 uppercase tracking-widest flex items-center">
                      <FileCheck size={16} className="mr-3" /> İMZALI KANIT BELGESİ
                    </p>
                    {transaction.approvalFlow[selectedFlowDetail].proofUrl && (
                      <button 
                        onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail!].proofUrl!)}
                        className="text-[9px] font-black text-cyan-400 uppercase tracking-widest flex items-center hover:text-white transition-colors"
                      >
                        <Eye size={12} className="mr-2" /> TAM EKRAN GÖR
                      </button>
                    )}
                  </div>

                  {transaction.approvalFlow[selectedFlowDetail].proofUrl ? (
                    <div 
                      className="w-full h-80 rounded-[40px] overflow-hidden border border-violet-500/20 cursor-pointer relative group bg-black/40" 
                      onClick={() => setSelectedImage(transaction.approvalFlow[selectedFlowDetail!].proofUrl!)}
                    >
                      <img src={transaction.approvalFlow[selectedFlowDetail].proofUrl} className="w-full h-full object-cover transition-transform group-hover:scale-110 duration-700" alt="Proof" />
                      <div className="absolute inset-0 bg-violet-600/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity backdrop-blur-sm">
                        <div className="flex flex-col items-center">
                          <Maximize2 className="text-white mb-3" size={48} />
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">İNCELEMEK İÇİN TIKLA</span>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="w-full py-16 border-2 border-dashed border-violet-500/20 rounded-[40px] flex flex-col items-center justify-center text-slate-600 bg-violet-500/5">
                      <ImagePlus size={48} className="mb-4 opacity-20" />
                      <span className="text-[11px] font-black uppercase tracking-widest opacity-40">Henüz Belge Yüklenmedi</span>
                    </div>
                  )}

                  <button 
                    onClick={() => fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role]?.click()} 
                    className="w-full py-6 bg-violet-600/10 text-violet-400 rounded-3xl border border-violet-500/20 font-black text-[11px] uppercase tracking-widest hover:bg-violet-600 hover:text-white transition-all shadow-xl flex items-center justify-center"
                  >
                    <UploadCloud size={18} className="mr-3" /> {transaction.approvalFlow[selectedFlowDetail].proofUrl ? 'KANIT BELGESİNİ GÜNCELLE' : 'KANIT BELGESİ SEÇ'}
                  </button>
                  <input 
                    type="file" 
                    ref={el => { if (el) fileInputRefs.current[transaction.approvalFlow[selectedFlowDetail!].role] = el; }} 
                    className="hidden" 
                    accept="image/*" 
                    onChange={e => handleProofUpload(transaction.approvalFlow[selectedFlowDetail!].role, e)} 
                  />
                </div>
            </div>
          </div>
        </div>
      )}

      {/* Sol Ana Panel */}
      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-violet-400 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>LİSTEYE DÖN</span>
          </button>
          <div className="flex items-center space-x-3">
            {!isEditing ? (
              <button onClick={() => setIsEditing(true)} className="px-6 py-2 glass-panel rounded-xl text-[10px] font-black text-violet-400 uppercase tracking-widest border-violet-500/20 hover:border-violet-500/40 transition-all flex items-center">
                <Edit3 size={16} className="mr-2" /> DÜZENLE
              </button>
            ) : (
              <button onClick={handleSave} className="px-8 py-2 neon-gradient-premium text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg">KAYDET</button>
            )}
            <button onClick={() => window.confirm('Talebi silmek istiyor musunuz?') && onDelete(transaction.id)} className="p-3 text-rose-500/40 hover:text-rose-500 hover:bg-rose-500/5 rounded-xl transition-all"><Trash2 size={20} /></button>
          </div>
        </div>

        <div className="glass-panel rounded-[50px] border border-violet-500/10 overflow-hidden relative shadow-2xl">
          {transaction.photoUrl && (
            <div className="w-full h-64 md:h-96 relative group cursor-pointer overflow-hidden" onClick={() => setSelectedImage(transaction.photoUrl!)}>
               <img src={transaction.photoUrl} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-1000" alt="Ürün" />
               <div className="absolute inset-0 bg-gradient-to-t from-[#020617] to-transparent opacity-60"></div>
               <div className="absolute bottom-8 left-8 flex items-center space-x-4">
                  <div className="p-4 bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 text-white"><Maximize2 size={24} /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">ÜRÜN REFERANS GÖRSELİ</span>
               </div>
            </div>
          )}

          <div className="p-10 lg:p-14 border-b border-violet-500/10 bg-violet-950/20 relative">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8 relative z-10">
              <div className="flex-1">
                <div className="flex items-center flex-wrap gap-4 mb-4">
                  <h2 className="text-3xl lg:text-5xl font-black text-white neon-text-premium uppercase leading-tight tracking-tighter">
                    {isEditing ? <input className="bg-transparent border-b border-violet-500 outline-none w-full" value={editForm.productSetName} onChange={e => setEditForm({...editForm, productSetName: e.target.value})} /> : transaction.productSetName}
                  </h2>
                  <span className={`px-5 py-2 rounded-2xl text-[11px] font-black uppercase tracking-widest border shadow-lg ${
                    transaction.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                    transaction.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                    'bg-amber-500/10 text-amber-500 border-amber-500/20'
                  }`}>
                    {transaction.status === 'Pending' ? 'BEKLEYEN' : 
                     transaction.status === 'Approved' ? 'ONAYLI' : 
                     transaction.status === 'Purchased' ? 'ALINDI' : transaction.status}
                  </span>
                </div>
                <div className="flex items-center space-x-4">
                   <QrCode size={20} className="text-violet-500" />
                   <p className="text-[12px] text-violet-400 font-black uppercase tracking-[0.3em] opacity-60">ID: {transaction.id} • TAKİP ANAHTARI: {transaction.publicTrackKey || 'ÜRETİLMEDİ'}</p>
                </div>
              </div>
              <div className="lg:text-right">
                <p className="text-[10px] text-violet-600 font-black uppercase tracking-[0.3em] mb-2">TOPLAM BEDEL</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white neon-text-premium">₺{(isEditing ? editForm.totalAmount : transaction.totalAmount).toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">
            {/* Finansal Detaylar */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                <div className="p-8 bg-violet-950/30 rounded-[35px] border border-violet-500/10 space-y-6">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center">
                        <Package size={16} className="mr-3" /> MİKTAR & BİRİM
                    </h4>
                    <div className="space-y-4">
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">TALEP EDİLEN:</span>
                            <span className="text-white font-black text-lg">{transaction.packageQuantity} ADET</span>
                        </div>
                        <div className="flex justify-between items-center">
                            <span className="text-[11px] text-slate-500 font-bold">BİRİM MALİYET:</span>
                            <span className="text-white font-black text-lg">₺{transaction.packageUnitPrice?.toLocaleString('tr-TR')}</span>
                        </div>
                    </div>
                </div>
                <div className="p-8 bg-black/40 rounded-[35px] border border-violet-500/10 flex flex-col justify-center space-y-4">
                    <h4 className="text-[10px] font-black text-violet-400 uppercase tracking-widest flex items-center"><Hash size={16} className="mr-3" /> MUHASEBE / MICRO KODU</h4>
                    <div className="flex items-center justify-between bg-violet-900/10 p-5 rounded-2xl border border-violet-500/20 group cursor-pointer" title="Kopyalamak için tıkla" onClick={copyMicroCode}>
                        <span className="font-mono text-sm text-violet-300 tracking-wider uppercase">{transaction.microCode || '---'}</span>
                        {copied ? <CheckCircle2 size={16} className="text-green-500" /> : <Copy size={16} className="text-violet-600 opacity-40 group-hover:opacity-100 transition-all" />}
                    </div>
                </div>
                <div className="p-8 bg-white/5 rounded-[35px] border border-white/10 flex items-center justify-center space-x-6">
                   <div className="text-center">
                      <p className="text-[9px] font-black text-violet-400 uppercase tracking-widest mb-2">HIZLI TAKİP</p>
                      <img src={qrUrl} className="w-20 h-20 rounded-lg shadow-xl border border-white/20 p-1 bg-white" alt="QR" />
                   </div>
                   <div className="flex-1">
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-tighter leading-tight">MOBİL CİHAZLA TARATARAK DİJİTAL ASLINA ULAŞABİLİRSİNİZ.</p>
                   </div>
                </div>
            </div>

            {/* Mali Evraklar */}
            <div className={`p-10 rounded-[45px] border transition-all duration-700 ${transaction.status === 'Purchased' ? 'bg-emerald-600/5 border-emerald-500/30' : 'bg-violet-950/20 border-violet-500/10'}`}>
                <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-6">
                    <div className="flex items-center space-x-5">
                        <div className={`p-4 rounded-2xl ${transaction.status === 'Purchased' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-violet-500/20 text-violet-400'}`}>
                            <ReceiptText size={28} />
                        </div>
                        <div>
                            <h4 className="text-xl font-black text-white uppercase tracking-tighter">RESMİ MALİ EVRAKLAR</h4>
                            <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest">Sisteme işlenen fatura ve mali dökümanlar</p>
                        </div>
                    </div>
                    <button 
                        onClick={() => invoiceInputRef.current?.click()}
                        className="px-8 py-4 bg-white text-black rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-400 transition-all flex items-center shadow-lg justify-center"
                    >
                        <Camera size={18} className="mr-3" /> FATURA / EVRAK EKLE
                    </button>
                    <input type="file" ref={invoiceInputRef} className="hidden" onChange={handleInvoiceUpload} accept="image/*" />
                </div>

                <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6">
                    {transaction.invoices && transaction.invoices.map((inv, idx) => (
                        <div key={idx} className="group relative aspect-square rounded-[25px] overflow-hidden border border-white/10 shadow-xl cursor-pointer" onClick={() => setSelectedImage(inv)}>
                            <img src={inv} className="w-full h-full object-cover transition-transform group-hover:scale-110" alt="Fatura" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-3">
                                <button onClick={(e) => { e.stopPropagation(); setSelectedImage(inv); }} className="p-2 bg-white/10 rounded-full text-white hover:bg-white/20"><Maximize2 size={16} /></button>
                                <button onClick={(e) => { e.stopPropagation(); removeInvoice(idx); }} className="p-2 bg-rose-500/20 rounded-full text-rose-500 hover:bg-rose-500/40"><Trash2 size={16} /></button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

