import React, { useMemo, useState, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area, PieChart, Pie, Cell
} from 'recharts';
import { 
  TrendingUp, Target, Briefcase, Activity, Crown, BarChart3, Presentation, Zap, Sparkles, AlertCircle, Award
} from 'lucide-react';
import { Transaction } from '../types';
import { GoogleGenAI } from "@google/genai";

interface ReportsProps {
  transactions: Transaction[];
}

const COLORS = ['#dc2626', '#4b5563', '#991b1b', '#1f2937', '#f87171', '#374151'];

const Reports: React.FC<ReportsProps> = ({ transactions }) => {
  const [aiAnalysis, setAiAnalysis] = useState<{brief: string, recommendations: string[], risks: string[]}>({
    brief: "",
    recommendations: [],
    risks: []
  });
  const [loadingAi, setLoadingAi] = useState(false);

  const stats = useMemo(() => {
    const purchased = transactions.filter(t => t.status === 'Purchased');
    const total = purchased.reduce((sum, t) => sum + t.totalAmount, 0);
    const avg = purchased.length > 0 ? total / purchased.length : 0;

    const months = ["Oca", "Şub", "Mar", "Nis", "May", "Haz", "Tem", "Ağu", "Eyl", "Eki", "Kas", "Ara"];
    const monthlyMap: Record<string, { month: string, total: number, count: number }> = {};
    const deptMap: Record<string, number> = {};

    purchased.forEach(t => {
      const date = new Date(t.requestDateTime);
      const mLabel = months[date.getMonth()];
      if (!monthlyMap[mLabel]) monthlyMap[mLabel] = { month: mLabel, total: 0, count: 0 };
      monthlyMap[mLabel].total += t.totalAmount;
      monthlyMap[mLabel].count += 1;
      deptMap[t.department] = (deptMap[t.department] || 0) + t.totalAmount;
    });

    const monthlyData = months.map(m => monthlyMap[m] || { month: m, total: 0, count: 0 });
    const deptData = Object.entries(deptMap).map(([name, value]) => ({ name, value }));
    const peakMonth = [...monthlyData].sort((a, b) => b.total - a.total)[0];

    return { total, avg, monthlyData, deptData, peakMonth, count: purchased.length };
  }, [transactions]);

  useEffect(() => {
    const getAiReport = async () => {
      if (stats.count === 0) return;
      setLoadingAi(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `CFO Analizi: Harcama ₺${stats.total}, İşlem: ${stats.count}. Departman: ${stats.deptData.map(d => `${d.name}: ₺${d.value}`).join(',')}. JSON döndür: brief, recommendations[], risks[]. Türkçe.`;
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
          config: { responseMimeType: "application/json" }
        });
        const result = JSON.parse(response.text || "{}");
        setAiAnalysis(result);
      } catch (e) {
        setAiAnalysis({ brief: "Veri işlendi.", recommendations: ["Disiplin."], risks: ["Belirsizlik."] });
      } finally {
        setLoadingAi(false);
      }
    };
    getAiReport();
  }, [stats]);

  return (
    <div className="space-y-12 pb-24 relative">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 print:hidden">
        <div>
          <div className="flex items-center space-x-3 mb-2">
            <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white shadow-[0_0_15px_rgba(220,38,38,0.5)]">
              <BarChart3 size={20} />
            </div>
            <h2 className="text-4xl lg:text-5xl font-black text-white neon-text-red tracking-tighter uppercase leading-none">STRATEJİ ANALİZİ</h2>
          </div>
          <p className="text-gray-600 font-black text-[9px] uppercase tracking-[0.4em] mt-3">Elite Fiscal Intelligence Center</p>
        </div>
        <button onClick={() => window.print()} className="px-8 py-4 bg-white text-black rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all shadow-xl">
          <Presentation size={18} className="inline mr-2" /> PDF RAPOR ÜRET
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'TOPLAM HACİM', val: `₺${stats.total.toLocaleString('tr-TR')}`, color: 'text-red-600', icon: <TrendingUp size={24} /> },
          { label: 'İŞLEM BAŞI ORT.', val: `₺${stats.avg.toLocaleString('tr-TR', { maximumFractionDigits: 0 })}`, color: 'text-gray-400', icon: <Target size={24} /> },
          { label: 'ZİRVE DÖNEM', val: stats.peakMonth.month, color: 'text-red-800', icon: <Crown size={24} /> },
          { label: 'VERİ PUANI', val: '9.4', color: 'text-gray-200', icon: <Activity size={24} /> },
        ].map((m, i) => (
          <div key={i} className="glass-panel p-8 rounded-[25px] border-white/5 relative overflow-hidden group">
            <div className={`absolute -right-4 -top-4 opacity-5 ${m.color}`}>{m.icon}</div>
            <p className="text-[9px] font-black text-gray-600 uppercase tracking-widest mb-3">{m.label}</p>
            <h3 className={`text-3xl font-black ${m.color}`}>{m.val}</h3>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-1 space-y-10">
          <div className="glass-panel p-10 rounded-[40px] border-red-600/20 bg-red-600/5">
