import { INITIAL_ROLES } from '../constants';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [formData, setFormData] = useState({
    productSetName: '',
    supplierName: '',
    department: departments[0] || '',
    category: 'Genel Satın Alma',
    priority: 'Medium' as Priority,
    currency: 'TRY' as Currency,
    packageQuantity: 1,
    justification: '',
    generalNotes: '',
    microCode: '',
    photoUrl: '',
    totalAmount: 0
  });

  const [offers, setOffers] = useState<Offer[]>([
    { id: 'off-1', sourceName: '', price: 0, isChosen: true }
  ]);

  const [selectedRoles, setSelectedRoles] = useState<string[]>(INITIAL_ROLES.map(r => r.roleName));
  const [analyzing, setAnalyzing] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const chosenOffer = offers.find(o => o.isChosen) || offers[0];
    const total = formData.packageQuantity * (chosenOffer?.price || 0);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, offers]);

  const addOffer = () => {
    if (offers.length >= 5) return;
    setOffers([...offers, { id: `off-${Date.now()}`, sourceName: '', price: 0, isChosen: false }]);
  };

  const updateOffer = (id: string, updates: Partial<Offer>) => {
    setOffers(prev => prev.map(o => o.id === id ? { ...o, ...updates } : o));
  };

  const removeOffer = (id: string) => {
    if (offers.length === 1) return;
    setOffers(prev => {
      const newList = prev.filter(o => o.id !== id);
      if (prev.find(o => o.id === id)?.isChosen) {
        newList[0].isChosen = true;
      }
      return newList;
    });
  };

  const setChosenOffer = (id: string) => {
    setOffers(prev => prev.map(o => ({ ...o, isChosen: o.id === id })));
  };

  const cheapestOfferId = [...offers].sort((a, b) => a.price - b.price)[0]?.id;

  const inputClass = "w-full px-4 py-3 rounded-xl bg-[#0f0f0f] border border-white/5 focus:border-red-600/50 text-slate-200 outline-none transition-all text-sm shadow-inner";

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const chosenOffer = offers.find(o => o.isChosen);
    onSave({
      ...formData,
      unitPrice: chosenOffer?.price || 0,
      packageUnitPrice: chosenOffer?.price || 0,
      offers,
      supplierName: chosenOffer?.sourceName || formData.supplierName
    });
  };

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24">
      <div className="mb-10 flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-black text-white neon-text-red uppercase tracking-tighter">KARŞILAŞTIRMALI TALEP GİRİŞİ</h2>
          <p className="text-[10px] text-red-600 font-black uppercase tracking-[0.4em] mt-2">Pazar Analizi ve Tedarik Karşılaştırma Dosyası</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-10">

          {/* Ürün Bilgileri */}
          <div className="glass-panel p-10 rounded-[40px] border border-white/5 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">Talep Başlığı</label>
                <input required type="text" value={formData.productSetName} onChange={e => setFormData({...formData, productSetName: e.target.value})} placeholder="Örn: 10 Adet Gaming Monitör" className={inputClass} />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">Para Birimi</label>
                <select value={formData.currency} onChange={e => setFormData({...formData, currency: e.target.value as Currency})} className={inputClass}>
                  <option value="TRY">TRY (₺)</option><option value="USD">USD ($)</option><option value="EUR">EUR (€)</option>
                </select>
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                  <ShoppingCart size={16} className="mr-3 text-red-600" /> FİYAT KARŞILAŞTIRMALARI
                </h3>
                <button type="button" onClick={addOffer} className="px-4 py-2 bg-red-600/10 text-red-500 rounded-lg text-[9px] font-black uppercase border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                  <Plus size={14} className="inline mr-1" /> YENİ KAYNAK EKLE
                </button>
              </div>

              <div className="space-y-4">
                {offers.map((offer, idx) => (
                  <div key={offer.id} className={`p-6 rounded-3xl border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/30 shadow-[0_0_20px_rgba(220,38,38,0.05)]' : 'bg-[#0a0a0a] border-white/5'}`}>
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-6 items-center">
                      <div className="md:col-span-5 space-y-2">
                        <label className="text-[8px] font-black text-gray-600 uppercase">KAYNAK / MAĞAZA ADI</label>
                        <input required type="text" value={offer.sourceName} onChange={e => updateOffer(offer.id, {sourceName: e.target.value})} placeholder="Örn: Vatan, Amazon, Yerel Esnaf..." className={inputClass} />
                      </div>
                      <div className="md:col-span-3 space-y-2">
                        <label className="text-[8px] font-black text-gray-600 uppercase">BİRİM FİYAT</label>
                        <input required type="number" value={offer.price} onChange={e => updateOffer(offer.id, {price: parseFloat(e.target.value) || 0})} className={inputClass} />
                      </div>
                      <div className="md:col-span-4 flex items-center justify-end space-x-3 pt-4">
                        {offer.id === cheapestOfferId && (
                          <div className="flex items-center text-[9px] font-black text-green-500 uppercase bg-green-500/10 px-3 py-1.5 rounded-lg border border-green-500/20">
                            <BadgeCheck size={12} className="mr-1" /> EN UCUZ
                          </div>
                        )}
                        <button type="button" onClick={() => setChosenOffer(offer.id)} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase border transition-all ${offer.isChosen ? 'bg-red-600 text-white border-red-600' : 'bg-white/5 text-gray-500 border-white/5 hover:border-red-600/30'}`}>
                          {offer.isChosen ? 'SEÇİLDİ' : 'SEÇ'}
                        </button>
                        <button type="button" onClick={() => removeOffer(offer.id)} className="p-2 text-gray-700 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="glass-panel p-10 rounded-[40px] border border-white/5 space-y-6">
            <label className="text-xs font-black text-white uppercase tracking-widest flex items-center">
              <AlertTriangle size={18} className="mr-3 text-red-600" /> SATIN ALMA STRATEJİK GEREKÇESİ
            </label>
            <textarea required rows={5} value={formData.justification} onChange={e => setFormData({...formData, justification: e.target.value})} className={`${inputClass} resize-none leading-relaxed`} placeholder="Bu kaynaklar nasıl belirlendi? Neden bu ürün tercih edildi? Şehir içi ve online karşılaştırma özeti..." />
          </div>
        </div>

        <div className="space-y-8">
           <div className="glass-panel p-10 rounded-[40px] border border-red-600/10 bg-red-600/5 relative overflow-hidden">
              <div className="flex flex-col space-y-6">
                 <div>
                    <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest mb-1">TOPLAM TALEP BEDELİ</p>
                    <h3 className="text-5xl font-black text-white neon-text-red">₺{formData.totalAmount.toLocaleString('tr-TR')}</h3>
                 </div>
                 <div className="p-5 bg-black/40 rounded-2xl border border-white/5">
                    <p className="text-[9px] font-black text-red-500 uppercase mb-2">SEÇİLİ KAYNAK</p>
                    <p className="text-xs font-bold text-white uppercase tracking-widest">{offers.find(o => o.isChosen)?.sourceName || 'BELİRTİLMEDİ'}</p>
                 </div>
              </div>
           </div>

           <button type="submit" className="w-full py-8 neon-gradient-red text-white rounded-[35px] font-black shadow-2xl flex items-center justify-center space-x-4 uppercase tracking-[0.2em] text-sm hover:scale-[1.02] active:scale-95 transition-all">
             <Send size={22} />
             <span>ANALİZİ SİSTEME GÖNDER</span>
           </button>
        </div>
      </form>
    </div>
  );
};

export default NewRequest;

import React, { useState, useRef, useEffect } from 'react';
import { 
  ArrowLeft, CheckCircle2, XCircle, History, ShieldCheck, Trash2, Maximize2, Package, Copy, UserCheck, Info, X, Hash, Zap, Edit3, ImagePlus, PauseCircle, ShoppingBag, ReceiptText, Notebook, Sparkles, Loader2, QrCode, UserPlus, FileSignature, UploadCloud, FileCheck, Camera, Eye, 
  ArrowRight,
  BadgeCheck,
