} from 'lucide-react';
import { Transaction, Role, Offer } from '../types';
import { analyzeJustification } from '../services/geminiService';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiResult, setAiResult] = useState<string | null>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    });
  };

  const handleAiAnalysis = async () => {
    setAnalyzing(true);
    const comparisonText = transaction.offers.map(o => `${o.sourceName}: ${o.price} TL`).join(', ');
    const res = await analyzeJustification(transaction.productSetName, `Karşılaştırmalar: ${comparisonText}. Gerekçe: ${transaction.justification}`);
    setAiResult(res);
    setAnalyzing(false);
  };

  const cheapestOffer = [...(transaction.offers || [])].sort((a, b) => a.price - b.price)[0];

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 flex flex-col lg:flex-row gap-10 pb-24">

      {/* Lightbox Modalı */}
      {selectedImage && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/95 backdrop-blur-3xl" onClick={() => setSelectedImage(null)}>
          <img src={selectedImage} className="max-w-full max-h-[85vh] rounded-3xl border border-white/10 shadow-2xl" alt="Detay" />
        </div>
      )}

      <div className="flex-1 space-y-10">
        <div className="flex items-center justify-between px-2">
          <button onClick={onBack} className="flex items-center space-x-3 text-red-600 font-black text-xs uppercase tracking-widest group">
            <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
            <span>OPERASYON LİSTESİ</span>
          </button>
        </div>

        <div className="glass-panel rounded-[50px] border border-red-600/10 overflow-hidden shadow-2xl bg-[#0a0a0a]">
          <div className="p-10 lg:p-14 border-b border-red-600/10 bg-red-600/5">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8">
              <div>
                <h2 className="text-4xl lg:text-5xl font-black text-white neon-text-red uppercase tracking-tighter mb-4">{transaction.productSetName}</h2>
                <p className="text-[11px] text-gray-600 font-black uppercase tracking-[0.4em]">{transaction.department} • {transaction.id}</p>
              </div>
              <div className="text-right">
                <p className="text-[10px] text-red-700 font-black uppercase mb-1">TOPLAM ONAY BEDELİ</p>
                <h3 className="text-5xl lg:text-7xl font-black text-white">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              </div>
            </div>
          </div>

          <div className="p-10 lg:p-14 space-y-16">

            {/* Karşılaştırma Matrisi */}
            <div className="space-y-8">
              <div className="flex items-center justify-between">
                <h4 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                  <ShoppingCart size={20} className="mr-4 text-red-600" /> TEDARİK KARŞILAŞTIRMA MATRİSİ
                </h4>
                <button onClick={handleAiAnalysis} disabled={analyzing} className="text-[9px] font-black text-red-500 uppercase flex items-center space-x-2 hover:text-white transition-colors">
                  {analyzing ? <Loader2 className="animate-spin" size={14}/> : <Sparkles size={14}/>}
                  <span>AI MARKET ANALİZİ</span>
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                 {transaction.offers && transaction.offers.map((offer) => (
                   <div key={offer.id} className={`p-8 rounded-[35px] border transition-all relative group ${offer.isChosen ? 'bg-red-600/10 border-red-600/40 shadow-xl' : 'bg-white/5 border-white/5 opacity-60 hover:opacity-100'}`}>
                      {offer.id === cheapestOffer?.id && (
                        <div className="absolute -top-3 left-8 bg-green-500 text-white text-[8px] font-black px-3 py-1 rounded-full flex items-center shadow-lg">
                          <BadgeCheck size={10} className="mr-1" /> EN EKONOMİK OPSİYON
                        </div>
                      )}
                      {offer.isChosen && (
                        <div className="absolute top-4 right-4 text-red-500 animate-pulse"><CheckCircle2 size={24} /></div>
                      )}
                      <p className="text-[9px] font-black text-gray-500 uppercase mb-2">KAYNAK / MAĞAZA</p>
                      <h5 className="text-xl font-black text-white uppercase mb-6 truncate">{offer.sourceName}</h5>
                      <div className="flex items-end justify-between">
                        <div>
                          <p className="text-[9px] font-black text-gray-500 uppercase">FİYAT TEKLİFİ</p>
                          <p className="text-2xl font-black text-white">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                        <button 
                          onClick={() => handleSelectOffer(offer.id)}
                          className={`px-6 py-2 rounded-xl text-[9px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-white/10 text-gray-400 hover:bg-red-600 hover:text-white'}`}
                        >
                          {offer.isChosen ? 'SEÇİLDİ' : 'BU OPSİYONU SEÇ'}
                        </button>
                      </div>
                   </div>
                 ))}
              </div>

              {aiResult && (
                <div className="p-8 bg-red-600/5 border border-red-600/20 rounded-[35px] text-sm italic text-gray-300 animate-in fade-in duration-500">
                  <div className="flex items-center text-red-500 text-[10px] font-black uppercase mb-3"><Sparkles size={14} className="mr-2"/> AI ANALİST RAPORU</div>
                  "{aiResult}"
                </div>
              )}
            </div>

            {/* Dosya Detayları */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
               <div className="p-10 bg-white/5 rounded-[45px] border border-white/5 space-y-6">
                  <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center"><Notebook size={18} className="mr-3"/> STRATEJİK GEREKÇE</h4>
                  <p className="text-gray-300 text-sm leading-relaxed italic">"{transaction.justification}"</p>
               </div>
               <div className="p-10 bg-white/5 rounded-[45px] border border-white/5 space-y-6">
                  <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center"><UserCheck size={18} className="mr-3"/> TALEP SAHİBİ</h4>
                  <div className="flex items-center space-x-5">
                    <div className="w-14 h-14 bg-red-600 rounded-2xl flex items-center justify-center font-black text-white text-xl">{transaction.requesterName.charAt(0)}</div>
                    <div>
                      <p className="text-lg font-black text-white uppercase">{transaction.requesterName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{transaction.department}</p>
                    </div>
                  </div>
               </div>
            </div>
          </div>

          <div className="bg-red-950/20 p-12 border-t border-red-600/10 flex flex-wrap justify-center gap-6">
            <button 
              onClick={() => onStatusChange(transaction.id, 'Approved')} 
              className="px-16 py-6 neon-gradient-red text-white rounded-[30px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center"
            >
              <CheckCircle2 size={24} className="mr-4" /> DOSYAYI VE SEÇİLEN TEKLİFİ ONAYLA
            </button>
            <button 
              onClick={() => onStatusChange(transaction.id, 'Rejected')}
              className="px-10 py-6 bg-transparent border border-white/10 text-gray-600 rounded-[30px] font-black uppercase tracking-widest hover:border-red-600 hover:text-red-600 transition-all"
            >
              TALEBİ REDDET
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

