      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-8">

          <div className="glass-panel p-10 rounded-[40px] border border-white/5 space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-1">Ürün / Hizmet Tanımı</label>
                <input required type="text" value={formData.productSetName} onChange={e => setFormData({...formData, productSetName: e.target.value})} placeholder="Örn: Logitech M90 Mouse" className={inputClass} />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-1">Adet</label>
                <input required type="number" min="1" value={formData.packageQuantity} onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 1})} className={inputClass} />
              </div>
            </div>

            <div className="space-y-6">
              <div className="flex items-center justify-between border-b border-white/5 pb-4">
                <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                  <ShoppingCart size={16} className="mr-3 text-red-600" /> FİYAT ANALİZ TABLOSU
                </h3>
                <button type="button" onClick={addOffer} className="px-4 py-2 bg-red-600/10 text-red-500 rounded-lg text-[9px] font-black uppercase border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                  + YENİ KAYNAK EKLE
                </button>
              </div>

              <div className="space-y-4">
                {offers.map((offer, idx) => (
                  <div key={offer.id} className={`p-6 rounded-[30px] border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/30' : 'bg-[#0a0a0a] border-white/5'}`}>
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-4 items-end">
                      <div className="md:col-span-3 space-y-2">
                        <label className="text-[8px] font-black text-gray-700 uppercase">KAYNAK TİPİ</label>
                        <select value={offer.sourceType} onChange={e => updateOffer(offer.id, {sourceType: e.target.value as any})} className={inputClass}>
                          <option value="Online">Online Pazaryeri</option>
                          <option value="Local">Yerel Mağaza / Esnaf</option>
                        </select>
                      </div>
                      <div className="md:col-span-3 space-y-2">
                        <label className="text-[8px] font-black text-gray-700 uppercase">MAĞAZA / SATICI ADI</label>
                        <input required type="text" value={offer.sourceName} onChange={e => updateOffer(offer.id, {sourceName: e.target.value})} placeholder="Örn: Can Nalbur" className={inputClass} />
                      </div>
                      <div className="md:col-span-3 space-y-2">
                        <label className="text-[8px] font-black text-gray-700 uppercase">BİRİM FİYAT</label>
                        <input required type="number" step="0.01" value={offer.price} onChange={e => updateOffer(offer.id, {price: parseFloat(e.target.value) || 0})} className={inputClass} />
                      </div>
                      <div className="md:col-span-3 flex items-center justify-end space-x-2">
                        <button type="button" onClick={() => setChosenOffer(offer.id)} className={`flex-1 py-3 rounded-xl text-[9px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-600 border border-white/5'}`}>
                          {offer.isChosen ? 'SEÇİLDİ' : 'SEÇ'}
                        </button>
                        <button type="button" onClick={() => removeOffer(offer.id)} className="p-3 text-gray-800 hover:text-red-600 transition-colors"><Trash2 size={16}/></button>
                      </div>

                      <div className="md:col-span-12 mt-2">
                        <div className="relative">
                          {offer.sourceType === 'Online' ? <LinkIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-700" size={14} /> : <Store className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-700" size={14} />}
                          <input 
                            type="text" 
                            value={offer.url || ''} 
                            onChange={e => updateOffer(offer.id, {url: e.target.value})} 
                            placeholder={offer.sourceType === 'Online' ? "Ürün Linkini Yapıştırın (Hepsiburada, Amazon vb.)" : "Mağaza Adresi veya Bölge (Örn: Sanayi Sitesi, Şehir Merkezi)"} 
                            className={`${inputClass} pl-12 bg-black/20`}
                          />
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="glass-panel p-10 rounded-[40px] border border-white/5 space-y-4">
            <label className="text-xs font-black text-white uppercase tracking-widest flex items-center">
              <Info size={16} className="mr-3 text-red-600" /> ANALİZ ÖZETİ VE GEREKÇE
            </label>
            <textarea required rows={4} value={formData.justification} onChange={e => setFormData({...formData, justification: e.target.value})} className={`${inputClass} resize-none`} placeholder="Neden bu kaynaklar seçildi? Yerel mağaza avantajı nedir? (Örn: Can Nalbur'dan anında teslimat ve en uygun fiyat avantajıyla alım planlanmıştır.)" />
          </div>
        </div>

        <div className="space-y-6">
           <div className="glass-panel p-10 rounded-[40px] border-red-600/20 bg-red-600/5 sticky top-28">
              <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4">SEÇİLİ OPSİYON ÖZETİ</p>
              <div className="space-y-6">
                 <div>
                    <h3 className="text-4xl font-black text-white neon-text-red">₺{formData.totalAmount.toLocaleString('tr-TR')}</h3>
                    <p className="text-[10px] text-red-700 font-bold uppercase mt-1">TOPLAM ONAY BEDELİ</p>
                 </div>
                 <div className="p-6 bg-black/60 rounded-[25px] border border-white/5">
                    <p className="text-[8px] font-black text-gray-600 uppercase mb-2">TERCİH EDİLEN KAYNAK</p>
                    <div className="flex items-center space-x-3 text-white font-black uppercase text-xs">
                       {offers.find(o => o.isChosen)?.sourceType === 'Online' ? <Globe size={16} className="text-red-600"/> : <Store size={16} className="text-red-600"/>}
                       <span>{offers.find(o => o.isChosen)?.sourceName || 'MAĞAZA BELİRTİLMEDİ'}</span>
                    </div>
                 </div>
                 <button type="submit" className="w-full py-6 neon-gradient-red text-white rounded-2xl font-black shadow-2xl uppercase tracking-widest text-xs hover:scale-105 active:scale-95 transition-all">
                   ONAY DOSYASINI OLUŞTUR
                 </button>
              </div>
           </div>
        </div>
      </form>
    </div>
  );
};

