              </div>
            </div>

            <div className="space-y-8">
               <div className="glass-panel p-10 rounded-[45px] border-white/5 space-y-8">
                  <h4 className="text-[10px] font-black text-gray-500 uppercase tracking-widest flex items-center">
                    <Zap size={16} className="mr-3 text-red-600" /> TALEP ÖZETİ
                  </h4>
                  <div className="space-y-6">
                      <div className="p-6 bg-black/60 rounded-[25px] border border-white/5">
                        <p className="text-[8px] font-black text-gray-600 uppercase mb-2">SEÇİLEN ONAYCI SAYISI</p>
                        <p className="text-xl font-black text-white">{selectedApproverIds.length} YÖNETİCİ</p>
                      </div>
                      <div className="space-y-4">
                         <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">GEREKÇE (ZORUNLU)</label>
                         <textarea required value={formData.justification} onChange={e => setFormData({...formData, justification: e.target.value})} className="w-full bg-[#0a0a0a] border border-white/5 rounded-2xl p-4 text-xs text-white min-h-[100px] resize-none" placeholder="Bu alım neden seçilen yöneticilerin onayına sunuluyor?" />
                      </div>
                  </div>
               </div>

               <div className="flex flex-col space-y-4">
                  <button type="submit" disabled={selectedApproverIds.length === 0} className="w-full py-8 neon-gradient-red text-white rounded-[35px] font-black shadow-2xl flex items-center justify-center space-x-4 uppercase tracking-[0.2em] text-sm hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-30 disabled:cursor-not-allowed">
                    <Send size={22} />
                    <span>DOSYAYI GÖNDER</span>
                  </button>
                  <button type="button" onClick={() => setStep(1)} className="w-full py-4 text-gray-600 font-black uppercase text-[10px] tracking-widest flex items-center justify-center hover:text-white transition-colors">
                    <ChevronLeft size={16} className="mr-2" /> GERİ DÖN
                  </button>
               </div>
            </div>
          </div>
        )}
      </form>
    </div>
  );
};

