import React, { useState, useRef, useEffect } from 'react';
import { 
  Send, Globe, ShoppingCart, Trash2, BadgeCheck, Plus, Store, 
  Link as LinkIcon, Info, Camera, Image as ImageIcon, ChevronRight, 
  ChevronLeft, FileCheck, UserCheck, ShieldCheck, Zap, UserPlus, CheckCircle2
} from 'lucide-react';
import { Transaction, Currency, Priority, Offer } from '../types';
import { INITIAL_ROLES } from '../constants';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    productSetName: '',
    department: departments[0] || '',
    priority: 'Medium' as Priority,
    currency: 'TRY' as Currency,
    packageQuantity: 1,
    justification: '',
    microCode: '',
    totalAmount: 0,
    photoUrl: ''
  });

  // Seçili onaycıları tutan state (ID bazlı)
  const [selectedApproverIds, setSelectedApproverIds] = useState<string[]>(INITIAL_ROLES.slice(0, 2).map(r => r.id));

  const [offers, setOffers] = useState<Offer[]>([
    { id: 'off-1', sourceName: '', sourceType: 'Online', price: 0, isChosen: true, url: '' }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const chosenOffer = offers.find(o => o.isChosen) || offers[0];
    const total = formData.packageQuantity * (chosenOffer?.price || 0);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, offers]);

  const addOffer = () => {
    if (offers.length >= 6) return;
    setOffers([...offers, { id: `off-${Date.now()}`, sourceName: '', sourceType: 'Online', price: 0, isChosen: false, url: '' }]);
  };

  // Fix: Added removeOffer helper function to resolve "Cannot find name 'removeOffer'"
  const removeOffer = (id: string) => {
    if (offers.length <= 1) return;
    setOffers(prev => prev.filter(o => o.id !== id));
  };

  const updateOffer = (id: string, updates: Partial<Offer>) => {
    setOffers(prev => prev.map(o => o.id === id ? { ...o, ...updates } : o));
  };

  // Fix: Added setChosenOffer helper function to resolve "Cannot find name 'setChosenOffer'"
  const setChosenOffer = (id: string) => {
    setOffers(prev => prev.map(o => ({ ...o, isChosen: o.id === id })));
  };

  const toggleApprover = (id: string) => {
    setSelectedApproverIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, photoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const chosenOffer = offers.find(o => o.isChosen);

    // Seçilen onaycılara göre akış oluştur
    const customFlow = INITIAL_ROLES
      .filter(r => selectedApproverIds.includes(r.id))
      .map(r => ({
        role: r.roleName,
        status: 'Pending' as const,
        approverName: r.assignedName
      }));

    onSave({
      ...formData,
      unitPrice: chosenOffer?.price || 0,
      packageUnitPrice: chosenOffer?.price || 0,
      offers,
      supplierName: chosenOffer?.sourceName || '',
      approvalFlow: customFlow
    });
  };

  const inputClass = "w-full px-5 py-4 rounded-2xl bg-[#0f0f0f] border border-white/5 focus:border-red-600/50 text-slate-200 outline-none transition-all text-sm shadow-inner";

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700 pb-24">
      <div className="flex items-center justify-center mb-16 space-x-4">
        <div className={`flex items-center space-x-3 transition-all ${step === 1 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 1 ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]' : 'bg-white/5 text-gray-500'}`}>1</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white">TEKNİK ANALİZ</span>
        </div>
        <div className="w-12 h-[2px] bg-white/5"></div>
        <div className={`flex items-center space-x-3 transition-all ${step === 2 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 2 ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]' : 'bg-white/5 text-gray-500'}`}>2</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white">AKILLI ONAY AKIŞI</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-10">
        {step === 1 ? (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-10 rounded-[45px] border border-white/5 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-1">ÜRÜN / HİZMET ADI</label>
                    <input required type="text" value={formData.productSetName} onChange={e => setFormData({...formData, productSetName: e.target.value})} placeholder="Örn: Ofis Malzemeleri" className={inputClass} />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-1">TOPLAM ADET</label>
                    <input required type="number" min="1" value={formData.packageQuantity} onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 1})} className={inputClass} />
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center justify-between border-b border-white/5 pb-6">
                    <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                      <ShoppingCart size={20} className="mr-3 text-red-600" /> PAZAR ARAŞTIRMASI (TEKLİFLER)
                    </h3>
                    <button type="button" onClick={addOffer} className="px-5 py-2.5 bg-red-600/10 text-red-500 rounded-xl text-[10px] font-black uppercase border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                      + TEKLİF EKLE
                    </button>
                  </div>

                  <div className="space-y-4">
                    {offers.map((offer) => (
                      <div key={offer.id} className={`p-6 rounded-[35px] border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/30' : 'bg-[#0a0a0a] border-white/5'}`}>
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">KAYNAK</label>
                            <select value={offer.sourceType} onChange={e => updateOffer(offer.id, {sourceType: e.target.value as any})} className={inputClass}>
                              <option value="Online">Online Satıcı</option>
                              <option value="Local">Yerel Esnaf</option>
                            </select>
                          </div>
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">İSİM</label>
                            <input required type="text" value={offer.sourceName} onChange={updateOffer.bind(null, offer.id, {sourceName: offer.sourceName})} placeholder="Örn: Hepsiburada" className={inputClass} onChangeCapture={(e: any) => updateOffer(offer.id, {sourceName: e.target.value})} />
                          </div>
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">FİYAT</label>
                            <input required type="number" step="0.01" value={offer.price} onChange={(e) => updateOffer(offer.id, {price: parseFloat(e.target.value) || 0})} className={inputClass} />
                          </div>
                          <div className="md:col-span-3 flex items-center space-x-2">
                            <button type="button" onClick={() => setChosenOffer(offer.id)} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white shadow-lg' : 'bg-white/5 text-gray-600 border border-white/5'}`}>
                              {offer.isChosen ? 'SEÇİLİ' : 'SEÇ'}
                            </button>
                            <button type="button" onClick={() => removeOffer(offer.id)} className="p-4 text-gray-800 hover:text-red-600 transition-colors"><Trash2 size={18}/></button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="space-y-6">
               <div className="glass-panel p-10 rounded-[45px] border-red-600/20 bg-red-600/5">
                  <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6">ÖZET BÜTÇE</p>
                  <div className="space-y-8">
                    <div>
                        <h3 className="text-5xl font-black text-white neon-text-red">₺{formData.totalAmount.toLocaleString('tr-TR')}</h3>
                        <p className="text-[10px] text-red-700 font-bold uppercase mt-2">ALIM TUTARI</p>
                    </div>
                    <button type="button" onClick={() => setStep(2)} className="w-full py-6 bg-white text-black rounded-[25px] font-black shadow-2xl uppercase tracking-widest text-[11px] hover:bg-red-600 hover:text-white transition-all flex items-center justify-center group">
                      ONAYCILARI BELİRLE <ChevronRight size={18} className="ml-2 group-hover:translate-x-2 transition-transform" />
                    </button>
                  </div>
               </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-12 rounded-[50px] border border-white/5 space-y-12">
                <div className="space-y-8">
                    <h3 className="text-xs font-black text-white uppercase tracking-[0.2em] flex items-center border-b border-white/5 pb-4">
                      <UserPlus size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİNİ YAPILANDIR
                    </h3>
                    <p className="text-[10px] text-gray-500 uppercase tracking-widest leading-relaxed">Bu talep için kimlerin onayı gerekiyor? Lütfen aşağıdaki listeden seçim yapın.</p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {INITIAL_ROLES.map((role) => (
                        <div 
                          key={role.id} 
                          onClick={() => toggleApprover(role.id)}
                          className={`p-6 rounded-[30px] border transition-all cursor-pointer flex items-center justify-between group ${selectedApproverIds.includes(role.id) ? 'bg-red-600/10 border-red-600/40 shadow-xl' : 'bg-black/40 border-white/5 hover:border-white/20 opacity-50'}`}
                        >
                           <div className="flex items-center space-x-4">
                              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${selectedApproverIds.includes(role.id) ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-700'}`}>
                                 <UserCheck size={20} />
                              </div>
                              <div>
                                 <p className="text-[10px] font-black text-white uppercase">{role.roleName}</p>
                                 <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">{role.assignedName}</p>
                              </div>
                           </div>
                           {selectedApproverIds.includes(role.id) ? <CheckCircle2 size={20} className="text-red-500" /> : <div className="w-5 h-5 rounded-full border border-white/10"></div>}
                        </div>
                      ))}
                    </div>
                </div>

                <div className="space-y-8 border-t border-white/5 pt-8">
                    <h3 className="text-xs font-black text-white uppercase tracking-[0.2em] flex items-center">
                      <ImageIcon size={20} className="mr-3 text-red-600" /> GÖRSEL KANIT
                    </h3>
                    <div 
