import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, ShoppingCart, Globe, Store, ExternalLink, BadgeCheck, 
  Info, TrendingDown, Eye, FileText, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, MessageSquare, History, PenTool, ChevronRight
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState(false);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const proofInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    });
  };

  const executeApproval = (proofUrl?: string) => {
    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === currentUserRole && f.status === 'Pending') {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    });
    setShowApprovalModal(false);
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        executeApproval(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const cheapestOffer = [...(transaction.offers || [])].sort((a, b) => a.price - b.price)[0];
  const currentChosen = transaction.offers.find(o => o.isChosen);
  const userCanApprove = transaction.approvalFlow.some(f => f.role === currentUserRole && f.status === 'Pending');

  return (
    <div className="animate-in fade-in slide-in-from-right-4 duration-700 space-y-12 pb-24 relative">
      {/* Lightbox */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-8 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-full rounded-3xl shadow-2xl border border-white/10" alt="Full" />
           <button className="absolute top-10 right-10 p-4 text-white bg-white/5 rounded-full hover:bg-red-600 transition-all"><XCircle size={32}/></button>
        </div>
      )}

      {/* Onay Seçim Modalı */}
      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md">
           <div className="w-full max-w-lg glass-panel p-12 rounded-[50px] border border-red-600/30 space-y-8">
              <div className="text-center space-y-4">
                 <div className="w-20 h-20 bg-red-600 rounded-3xl flex items-center justify-center text-white mx-auto shadow-2xl">
                    <ShieldCheck size={40} />
                 </div>
                 <h3 className="text-2xl font-black text-white uppercase">ONAY METODUNU SEÇİN</h3>
                 <p className="text-gray-500 text-[10px] uppercase tracking-widest leading-relaxed">Bu alım için hangi onay tipini kullanmak istersiniz?</p>
              </div>

              <div className="grid grid-cols-1 gap-4">
                 <button 
                    onClick={() => { setIsSignedApproval(false); executeApproval(); }}
                    className="flex items-center justify-between p-6 bg-white/5 border border-white/5 rounded-3xl hover:border-red-600/50 hover:bg-red-600/5 transition-all group"
                 >
                    <div className="flex items-center space-x-5">
                       <div className="p-4 bg-black rounded-2xl text-gray-500 group-hover:text-red-500 transition-colors">
                          <MessageSquare size={24} />
                       </div>
                       <div className="text-left">
                          <p className="text-[11px] font-black text-white uppercase">HIZLI ONAY (SÖZLÜ)</p>
                          <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">Dijital sistem onayı basılır.</p>
                       </div>
                    </div>
                    <ChevronRight size={20} className="text-gray-800" />
                 </button>

                 <button 
                    onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }}
                    className="flex items-center justify-between p-6 bg-red-600/5 border border-red-600/20 rounded-3xl hover:border-red-600 hover:bg-red-600/10 transition-all group"
                 >
                    <div className="flex items-center space-x-5">
                       <div className="p-4 bg-red-600 rounded-2xl text-white shadow-lg">
                          <PenTool size={24} />
                       </div>
                       <div className="text-left">
                          <p className="text-[11px] font-black text-white uppercase">İMZALI FORM ONAYI</p>
                          <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">Formun fotoğrafını sisteme yükler.</p>
                       </div>
                    </div>
                    <Upload size={20} className="text-red-600" />
                 </button>
                 <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>

              <button onClick={() => setShowApprovalModal(false)} className="w-full py-4 text-[10px] font-black text-gray-600 uppercase tracking-widest hover:text-white transition-colors">VAZGEÇ</button>
           </div>
        </div>
      )}

      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center space-x-3 text-red-600 font-black text-xs uppercase tracking-widest group">
          <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
          <span>PANELİ KAPAT</span>
        </button>
        <div className="flex items-center space-x-4">
           <span className="text-[10px] text-gray-700 font-black uppercase tracking-[0.3em]">HİBRİT DENETİM SİSTEMİ v2.5</span>
        </div>
      </div>

      <div className="glass-panel rounded-[55px] border border-red-600/10 overflow-hidden shadow-2xl bg-[#0a0a0a]">
        <div className="p-10 lg:p-14 border-b border-red-600/10 bg-red-600/5">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-10">
            <div className="flex-1">
              <div className="flex items-center space-x-4 mb-4">
                <span className="px-4 py-1.5 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black border border-red-600/20">#{transaction.id}</span>
                <span className="text-[10px] text-gray-500 font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-4xl lg:text-7xl font-black text-white neon-text-red uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
            </div>
            <div className="lg:text-right">
              <p className="text-[10px] text-red-700 font-black uppercase mb-2">DOSYA BÜTÇESİ</p>
              <h3 className="text-6xl lg:text-8xl font-black text-white tracking-tighter">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>
        </div>

        <div className="p-10 lg:p-14 space-y-20">

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
             {/* Onay Zinciri ve Tip Görünümü */}
             <div className="lg:col-span-4 space-y-10">
                <div className="flex items-center justify-between border-b border-white/5 pb-4">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center">
                      <ShieldCheck size={18} className="mr-3 text-red-600" /> ONAY GEÇMİŞİ
                   </h4>
                   <History size={16} className="text-gray-800" />
                </div>
                <div className="space-y-6 relative">
                  <div className="absolute left-7 top-4 bottom-4 w-0.5 bg-red-600/20"></div>
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className={`flex items-center space-x-6 relative z-10 p-5 rounded-[30px] transition-all border ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/20 shadow-lg' : 'bg-black border-white/5 opacity-40'}`}>
                      <div 
                        className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-all cursor-pointer ${flow.status === 'Approved' ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-700'}`}
                        onClick={() => flow.proofUrl && setShowLightbox(flow.proofUrl)}
                      >
                         {flow.status === 'Approved' ? (
                            flow.type === 'Signed' ? <Signature size={24} /> : <MessageSquare size={24} />
                         ) : <UserCheck size={24} />}
                      </div>
                      <div className="flex-1">
                         <p className="text-[10px] font-black text-white uppercase">{flow.role}</p>
                         <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">{flow.approverName}</p>
                         {flow.date && <p className="text-[7px] text-red-900 font-mono mt-1">{new Date(flow.date).toLocaleString('tr-TR')}</p>}
                      </div>
                      {flow.type === 'Signed' && flow.proofUrl && (
                        <div className="flex flex-col items-center">
                           <BadgeCheck size={18} className="text-red-500 mb-1" />
                           <span className="text-[6px] font-black text-red-600 uppercase">BELGELİ</span>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-8 space-y-14">
                <div className="space-y-8">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center border-b border-white/5 pb-4">
                     <ShoppingCart size={20} className="mr-4 text-red-600" /> KARŞILAŞTIRMALI OPSİYONLAR
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-8 rounded-[40px] border transition-all relative group cursor-pointer ${offer.isChosen ? 'bg-red-600/10 border-red-600/40 shadow-2xl' : 'bg-white/5 border-white/5 opacity-40 hover:opacity-100'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.sourceType === 'Online' ? 'bg-blue-500/10 text-blue-400' : 'bg-amber-500/10 text-amber-400'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={22} /> : <Store size={22} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-500" />}
                           </div>
                           <h5 className="text-xl font-black text-white uppercase mb-1">{offer.sourceName}</h5>
                           <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                              <p className="text-3xl font-black text-white">₺{offer.price.toLocaleString('tr-TR')}</p>
                              {offer.url && <ExternalLink size={18} className="text-gray-700 hover:text-white" />}
                           </div>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                   <div className="p-10 bg-white/5 rounded-[45px] border border-white/5 space-y-6 h-fit">
                      <h4 className="text-[10px] font-black text-red-600 uppercase tracking-widest flex items-center"><Info size={16} className="mr-3" /> SATIN ALMA GEREKÇESİ</h4>
                      <p className="text-gray-400 text-xs leading-relaxed italic">"{transaction.justification || 'Gerekçe belirtilmemiş.'}"</p>
                   </div>
                   {transaction.photoUrl && (
                     <div 
                        className="group relative rounded-[45px] overflow-hidden border border-white/5 aspect-video cursor-pointer"
                        onClick={() => setShowLightbox(transaction.photoUrl || null)}
                     >
                        <img src={transaction.photoUrl} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-all duration-700" alt="Kanıt" />
                        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                           <Eye className="text-white" size={32} />
                        </div>
                        <div className="absolute top-6 right-6 px-4 py-2 bg-black/80 rounded-xl text-[9px] font-black text-white uppercase border border-white/10">TALEP GÖRSELİ</div>
                     </div>
                   )}
                </div>
             </div>
          </div>

          <div className="bg-red-950/20 p-12 rounded-[55px] border border-red-600/10 flex flex-wrap items-center justify-between gap-10">
             <div className="flex-1 min-w-[300px] space-y-2">
                <p className="text-[10px] font-black text-red-500 uppercase tracking-widest">SİSTEM OTORİTE PANELİ</p>
                <p className="text-gray-500 text-xs leading-relaxed">
                   {userCanApprove ? 'Bu talep şu an sizin onayınızı bekliyor. Onay metodunu seçerek süreci ilerletebilirsiniz.' : 'Bu dosya üzerindeki yetki işlemleriniz tamamlanmış veya yetkiniz bulunmamaktadır.'}
                </p>
             </div>
             <div className="flex gap-4">
                {userCanApprove && (
                   <button 
                     onClick={() => setShowApprovalModal(true)} 
                     className="px-16 py-8 neon-gradient-red text-white rounded-[35px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center"
                   >
                     <CheckCircle2 size={24} className="mr-4" /> DOSYAYI ONAYLA
                   </button>
                )}
                {currentUserRole === 'General Manager' && (
                   <button 
                     onClick={() => onStatusChange(transaction.id, 'Rejected')}
                     className="px-10 py-8 bg-transparent border border-white/10 text-gray-700 rounded-[35px] font-black uppercase tracking-widest hover:border-red-600 hover:text-red-600 transition-all"
                   >
                     REDDET
                   </button>
                )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Send, Globe, ShoppingCart, Trash2, BadgeCheck, Plus, Store, 
  Link as LinkIcon, Info, Camera, Image as ImageIcon, ChevronRight, 
  ChevronLeft, FileCheck, UserCheck, ShieldCheck, Zap, UserPlus, CheckCircle2
} from 'lucide-react';
import { Transaction, Currency, Priority, Offer } from '../types';
import { INITIAL_ROLES } from '../constants';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState({
    productSetName: '',
    department: departments[0] || '',
    priority: 'Medium' as Priority,
    currency: 'TRY' as Currency,
    packageQuantity: 1,
    justification: '',
    microCode: '',
    totalAmount: 0,
    photoUrl: ''
  });

  const [selectedApproverIds, setSelectedApproverIds] = useState<string[]>(INITIAL_ROLES.slice(0, 2).map(r => r.id));

  const [offers, setOffers] = useState<Offer[]>([
    { id: 'off-1', sourceName: '', sourceType: 'Online', price: 0, isChosen: true, url: '' }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const chosenOffer = offers.find(o => o.isChosen) || offers[0];
    const total = formData.packageQuantity * (chosenOffer?.price || 0);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, offers]);

  const addOffer = () => {
    if (offers.length >= 6) return;
    setOffers([...offers, { id: `off-${Date.now()}`, sourceName: '', sourceType: 'Online', price: 0, isChosen: false, url: '' }]);
  };

  const removeOffer = (id: string) => {
    if (offers.length <= 1) return;
    setOffers(prev => prev.filter(o => o.id !== id));
  };

  const updateOffer = (id: string, updates: Partial<Offer>) => {
    setOffers(prev => prev.map(o => o.id === id ? { ...o, ...updates } : o));
  };

  const setChosenOffer = (id: string) => {
    setOffers(prev => prev.map(o => ({ ...o, isChosen: o.id === id })));
  };

  const toggleApprover = (id: string) => {
    setSelectedApproverIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, photoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const chosenOffer = offers.find(o => o.isChosen);

    const customFlow = INITIAL_ROLES
      .filter(r => selectedApproverIds.includes(r.id))
      .map(r => ({
        role: r.roleName,
        status: 'Pending' as const,
        approverName: r.assignedName
      }));

    onSave({
      ...formData,
      unitPrice: chosenOffer?.price || 0,
      packageUnitPrice: chosenOffer?.price || 0,
      offers,
      supplierName: chosenOffer?.sourceName || '',
      approvalFlow: customFlow
    });
  };

  const inputClass = "w-full px-5 py-4 rounded-2xl bg-[#0f0f0f] border border-white/5 focus:border-red-600/50 text-slate-200 outline-none transition-all text-sm shadow-inner placeholder:text-gray-800";

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700 pb-24">
      <div className="flex items-center justify-center mb-16 space-x-4">
        <div className={`flex items-center space-x-3 transition-all ${step === 1 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 1 ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]' : 'bg-white/5 text-gray-500'}`}>1</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white">TEKNİK ANALİZ</span>
        </div>
        <div className="w-12 h-[2px] bg-white/5"></div>
        <div className={`flex items-center space-x-3 transition-all ${step === 2 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 2 ? 'bg-red-600 text-white shadow-[0_0_20px_rgba(220,38,38,0.4)]' : 'bg-white/5 text-gray-500'}`}>2</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-white">AKILLI ONAY AKIŞI</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-10">
        {step === 1 ? (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-10 rounded-[45px] border border-white/5 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-1">ÜRÜN / HİZMET ADI</label>
                    <input 
                      required 
                      type="text" 
                      value={formData.productSetName} 
                      onChange={e => setFormData({...formData, productSetName: e.target.value})} 
                      placeholder="Örn: Ofis Malzemeleri" 
                      className={inputClass} 
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-1">TOPLAM ADET</label>
                    <input 
                      required 
                      type="number" 
                      min="1" 
                      value={formData.packageQuantity} 
                      onChange={e => setFormData({...formData, packageQuantity: parseInt(e.target.value) || 0})} 
                      className={inputClass} 
                    />
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex items-center justify-between border-b border-white/5 pb-6">
                    <h3 className="text-xs font-black text-white uppercase tracking-widest flex items-center">
                      <ShoppingCart size={20} className="mr-3 text-red-600" /> PAZAR ARAŞTIRMASI (TEKLİFLER)
                    </h3>
                    <button type="button" onClick={addOffer} className="px-5 py-2.5 bg-red-600/10 text-red-500 rounded-xl text-[10px] font-black uppercase border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                      + TEKLİF EKLE
                    </button>
                  </div>

                  <div className="space-y-4">
                    {offers.map((offer) => (
                      <div key={offer.id} className={`p-6 rounded-[35px] border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/30' : 'bg-[#0a0a0a] border-white/5'}`}>
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">KAYNAK</label>
                            <select value={offer.sourceType} onChange={e => updateOffer(offer.id, {sourceType: e.target.value as any})} className={inputClass}>
                              <option value="Online">Online Satıcı</option>
                              <option value="Local">Yerel Esnaf</option>
                            </select>
                          </div>
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">İSİM</label>
                            <input 
                              required 
                              type="text" 
                              value={offer.sourceName} 
                              onChange={e => updateOffer(offer.id, {sourceName: e.target.value})} 
                              placeholder="Örn: Hepsiburada" 
                              className={inputClass} 
                            />
                          </div>
                          <div className="md:col-span-3 space-y-2">
                            <label className="text-[8px] font-black text-gray-700 uppercase">FİYAT</label>
                            <input 
                              required 
                              type="number" 
                              step="0.01" 
                              value={offer.price} 
                              onChange={e => updateOffer(offer.id, {price: parseFloat(e.target.value) || 0})} 
                              className={inputClass} 
                            />
                          </div>
                          <div className="md:col-span-3 flex items-center space-x-2">
                            <button type="button" onClick={() => setChosenOffer(offer.id)} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white shadow-lg' : 'bg-white/5 text-gray-600 border border-white/5'}`}>
                              {offer.isChosen ? 'SEÇİLİ' : 'SEÇ'}
                            </button>
                            <button type="button" onClick={() => removeOffer(offer.id)} className="p-4 text-gray-800 hover:text-red-600 transition-colors"><Trash2 size={18}/></button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="space-y-6">
               <div className="glass-panel p-10 rounded-[45px] border-red-600/20 bg-red-600/5">
                  <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6">ÖZET BÜTÇE</p>
                  <div className="space-y-8">
                    <div>
                        <h3 className="text-5xl font-black text-white neon-text-red">₺{formData.totalAmount.toLocaleString('tr-TR')}</h3>
                        <p className="text-[10px] text-red-700 font-bold uppercase mt-2">ALIM TUTARI</p>
                    </div>
                    <button type="button" onClick={() => setStep(2)} className="w-full py-6 bg-white text-black rounded-[25px] font-black shadow-2xl uppercase tracking-widest text-[11px] hover:bg-red-600 hover:text-white transition-all flex items-center justify-center group">
                      ONAYCILARI BELİRLE <ChevronRight size={18} className="ml-2 group-hover:translate-x-2 transition-transform" />
                    </button>
                  </div>
               </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-12 rounded-[50px] border border-white/5 space-y-12">
                <div className="space-y-8">
                    <h3 className="text-xs font-black text-white uppercase tracking-[0.2em] flex items-center border-b border-white/5 pb-4">
                      <UserPlus size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİNİ YAPILANDIR
                    </h3>
                    <p className="text-[10px] text-gray-500 uppercase tracking-widest leading-relaxed">Bu talep için kimlerin onayı gerekiyor? Lütfen aşağıdaki listeden seçim yapın.</p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {INITIAL_ROLES.map((role) => (
                        <div 
                          key={role.id} 
                          onClick={() => toggleApprover(role.id)}
                          className={`p-6 rounded-[30px] border transition-all cursor-pointer flex items-center justify-between group ${selectedApproverIds.includes(role.id) ? 'bg-red-600/10 border-red-600/40 shadow-xl' : 'bg-black/40 border-white/5 hover:border-white/20 opacity-50'}`}
                        >
                           <div className="flex items-center space-x-4">
                              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${selectedApproverIds.includes(role.id) ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-700'}`}>
                                 <UserCheck size={20} />
                              </div>
                              <div>
                                 <p className="text-[10px] font-black text-white uppercase">{role.roleName}</p>
                                 <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">{role.assignedName}</p>
                              </div>
                           </div>
                           {selectedApproverIds.includes(role.id) ? <CheckCircle2 size={20} className="text-red-500" /> : <div className="w-5 h-5 rounded-full border border-white/10"></div>}
                        </div>
                      ))}
                    </div>
                </div>

                <div className="space-y-8 border-t border-white/5 pt-8">
                    <h3 className="text-xs font-black text-white uppercase tracking-[0.2em] flex items-center">
                      <ImageIcon size={20} className="mr-3 text-red-600" /> GÖRSEL KANIT
                    </h3>
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className="w-full aspect-video rounded-[40px] border-2 border-dashed border-white/10 flex flex-col items-center justify-center cursor-pointer hover:border-red-600/40 hover:bg-red-600/5 transition-all relative overflow-hidden group"
                    >
                      {formData.photoUrl ? (
                        <img src={formData.photoUrl} className="w-full h-full object-cover rounded-[38px]" alt="Preview" />
                      ) : (
                        <>
                          <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center text-gray-600 mb-4 group-hover:text-red-500 transition-colors">
                            <Camera size={32} />
                          </div>
