                 >
                    <div className="flex items-center space-x-5">
                       <div className="p-4 bg-red-600 rounded-2xl text-white shadow-lg">
                          <Signature size={24} />
                       </div>
                       <div className="text-left">
                          <p className="text-[11px] font-black text-white uppercase">İMZALI FORM YÜKLE</p>
                          <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">Islak imzalı belgeyi sisteme işler.</p>
                       </div>
                    </div>
                    <Upload size={20} className="text-red-600" />
                 </button>
                 <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>

              <button onClick={() => setShowApprovalModal(null)} className="w-full py-4 text-[10px] font-black text-gray-600 uppercase tracking-widest hover:text-white transition-colors">VAZGEÇ</button>
           </div>
        </div>
      )}

      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center space-x-3 text-red-600 font-black text-xs uppercase tracking-widest group">
          <ArrowLeft size={18} className="group-hover:-translate-x-2 transition-transform" /> 
          <span>PANELİ KAPAT</span>
        </button>
        <div className="flex items-center space-x-4">
           <span className="text-[10px] text-gray-700 font-black uppercase tracking-[0.3em]">HİBRİT DENETİM SİSTEMİ v2.9</span>
        </div>
      </div>

      <div className="glass-panel rounded-[55px] border border-red-600/10 overflow-hidden shadow-2xl bg-[#0a0a0a]">
        <div className="p-10 lg:p-14 border-b border-red-600/10 bg-red-600/5">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-10">
            <div className="flex-1">
              <div className="flex items-center space-x-4 mb-4">
                <span className="px-4 py-1.5 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black border border-red-600/20">#{transaction.id}</span>
                <span className="text-[10px] text-gray-500 font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-4xl lg:text-7xl font-black text-white neon-text-red uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
            </div>
            <div className="lg:text-right">
              <p className="text-[10px] text-red-700 font-black uppercase mb-2">DOSYA BÜTÇESİ</p>
              <h3 className="text-6xl lg:text-8xl font-black text-white tracking-tighter">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>
        </div>

        <div className="p-10 lg:p-14 space-y-20">

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
             {/* Onay Zinciri ve Tip Görünümü */}
             <div className="lg:col-span-5 space-y-10">
                <div className="flex items-center justify-between border-b border-white/5 pb-4">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center">
                      <ShieldCheck size={18} className="mr-3 text-red-600" /> ONAY GEÇMİŞİ & YETKİLİLER
                   </h4>
                   <History size={16} className="text-gray-800" />
                </div>
                <div className="space-y-6 relative">
                  <div className="absolute left-7 top-4 bottom-4 w-0.5 bg-red-600/20"></div>
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className={`flex items-center space-x-6 relative z-10 p-5 rounded-[30px] transition-all border ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/10' : 'bg-black border-white/5 shadow-inner'}`}>
                      {/* Sol İkon (Onay Tipi) */}
                      <div 
                        className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-800'}`}
                      >
                         {flow.status === 'Approved' ? (
                            flow.type === 'Signed' ? <Signature size={24} /> : <Zap size={24} />
                         ) : <UserCheck size={24} />}
                      </div>

                      {/* Orta Bilgi Alanı */}
                      <div className="flex-1">
                         <div className="flex items-center space-x-2">
                           <p className="text-[10px] font-black text-white uppercase">{flow.role}</p>
                           {flow.type === 'Signed' && <BadgeCheck size={12} className="text-red-600" />}
                         </div>
                         <p className="text-[8px] text-gray-600 font-bold uppercase tracking-widest">{flow.approverName}</p>

                         {flow.status === 'Approved' ? (
                            <div className="flex items-center space-x-3 mt-1.5">
                               <p className="text-[7px] text-red-900 font-mono">{new Date(flow.date!).toLocaleTimeString('tr-TR')}</p>
                               <span className={`text-[7px] font-black px-2 py-0.5 rounded ${flow.type === 'Signed' ? 'bg-red-600/20 text-red-500' : 'bg-white/10 text-gray-500'}`}>
                                  {flow.type === 'Signed' ? 'İMZALI ONAY' : 'HIZLI ONAY'}
                               </span>
                            </div>
                         ) : (
                            <button 
                              onClick={() => setShowApprovalModal({ role: flow.role })}
                              className="mt-2 text-[8px] font-black text-red-500 uppercase hover:text-white transition-all flex items-center group/btn"
                            >
                               <Plus size={10} className="mr-1 group-hover/btn:rotate-90 transition-transform" /> VEKALETEN ONAYLA
                            </button>
                         )}
                      </div>

                      {/* Sağ Fotoğraf Alanı */}
                      <div className="flex flex-col items-center">
                        {flow.status === 'Approved' ? (
                          flow.proofUrl ? (
                            <div 
                              className="w-14 h-14 rounded-2xl overflow-hidden border-2 border-red-600/20 cursor-pointer hover:border-red-600 transition-all shadow-xl group/img" 
                              onClick={() => setShowLightbox(flow.proofUrl!)}
                            >
                               <img src={flow.proofUrl} className="w-full h-full object-cover opacity-60 group-hover/img:opacity-100" />
                               <div className="absolute inset-0 bg-red-600/20 flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity">
                                  <Eye size={16} className="text-white" />
                               </div>
                            </div>
                          ) : (
                            <button 
                              onClick={() => { setTargetRoleForLateProof(flow.role); lateProofInputRef.current?.click(); }}
                              className="w-14 h-14 rounded-2xl border-2 border-dashed border-white/10 flex flex-col items-center justify-center text-gray-700 hover:border-red-600/50 hover:bg-red-600/5 hover:text-red-600 transition-all group/upload"
                            >
                               <ImagePlus size={18} className="group-hover/upload:scale-110 transition-transform" />
                               <span className="text-[6px] font-black mt-1 uppercase">BELGE EKLE</span>
                            </button>
                          )
                        ) : (
                          <div className="w-14 h-14 rounded-2xl border border-white/5 bg-white/2 opacity-10 flex items-center justify-center">
                            <Camera size={16} />
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-14">
                <div className="space-y-8">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center border-b border-white/5 pb-4">
                     <ShoppingCart size={20} className="mr-4 text-red-600" /> SEÇİLEN TEKLİF VE OPSİYONLAR
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-8 rounded-[40px] border transition-all relative group cursor-pointer ${offer.isChosen ? 'bg-red-600/10 border-red-600/40 shadow-2xl scale-[1.02]' : 'bg-white/5 border-white/5 opacity-40 hover:opacity-100'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.sourceType === 'Online' ? 'bg-blue-500/10 text-blue-400' : 'bg-amber-500/10 text-amber-400'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={22} /> : <Store size={22} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-500 shadow-xl" />}
                           </div>
                           <h5 className="text-xl font-black text-white uppercase mb-1">{offer.sourceName}</h5>
                           <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                              <p className="text-3xl font-black text-white">₺{offer.price.toLocaleString('tr-TR')}</p>
                              {offer.url && <ExternalLink size={18} className="text-gray-700 hover:text-white" />}
                           </div>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                   <div className="p-10 bg-[#0f0f0f] rounded-[45px] border border-white/5 space-y-6 h-fit shadow-inner">
                      <h4 className="text-[10px] font-black text-red-600 uppercase tracking-widest flex items-center"><Info size={16} className="mr-3" /> SATIN ALMA GEREKÇESİ</h4>
                      <p className="text-gray-400 text-xs leading-relaxed italic">"{transaction.justification || 'Gerekçe belirtilmemiş.'}"</p>
                   </div>
                   {transaction.photoUrl && (
                     <div 
                        className="group relative rounded-[45px] overflow-hidden border border-white/5 aspect-video cursor-pointer"
                        onClick={() => setShowLightbox(transaction.photoUrl || null)}
                     >
                        <img src={transaction.photoUrl} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-all duration-700" alt="Kanıt" />
                        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40">
                           <Eye className="text-white" size={32} />
                        </div>
                        <div className="absolute top-6 right-6 px-4 py-2 bg-black/80 rounded-xl text-[9px] font-black text-white uppercase border border-white/10 backdrop-blur-md">TALEP GÖRSELİ</div>
                     </div>
                   )}
                </div>
             </div>
          </div>

          <div className="bg-red-950/20 p-12 rounded-[55px] border border-red-600/10 flex flex-wrap items-center justify-between gap-10">
             <div className="flex-1 min-w-[300px] space-y-2">
                <p className="text-[10px] font-black text-red-500 uppercase tracking-widest">DOSYA KONTROL MERKEZİ</p>
                <p className="text-gray-500 text-xs leading-relaxed">
                   Yöneticilerin adına vekaleten onay verebilir veya alımı nihai statüye kavuşturabilirsiniz. Tüm işlemler loglanmaktadır.
                </p>
             </div>
             <div className="flex gap-4">
                {transaction.status === 'Approved' && (
                   <button 
                     onClick={() => onStatusChange(transaction.id, 'Purchased')} 
                     className="px-16 py-8 neon-gradient-red text-white rounded-[35px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center"
                   >
                     <ShoppingCart size={24} className="mr-4" /> ALIMI TAMAMLA
                   </button>
                )}
                <button 
                   onClick={() => onStatusChange(transaction.id, 'Rejected')}
                   className="px-10 py-8 bg-transparent border border-white/10 text-gray-700 rounded-[35px] font-black uppercase tracking-widest hover:border-red-600 hover:text-red-600 transition-all"
                >
                   TALEBİ İPTAL ET
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo } from 'react';
import { Search } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedTransactionId) {
          setSelectedTransactionId(null);
        } else if (activeTab !== 'dashboard') {
          setActiveTab('dashboard');
        }
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];

    if (statusFilter) {
      list = list.filter(t => t.status === statusFilter);
    }

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q) ||
        (t.justification && t.justification.toLowerCase().includes(q))
      );
    }

    return list.sort((a, b) => 
      new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime()
    );
  }, [state.transactions, statusFilter, searchQuery]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
    setSearchQuery('');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Batuhan Yontuç',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || request.packageQuantity || 1,
      unitPrice: request.unitPrice || request.packageUnitPrice || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPrice: request.packageUnitPrice || 0,
      totalAmount: request.totalAmount || (request.packageQuantity || 1) * (request.packageUnitPrice || 0),
      description: request.description || '',
      justification: request.justification || '',
      generalNotes: request.generalNotes || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      publicTrackKey: request.publicTrackKey,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: request.logs || [],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} kodlu yeni talep oluşturuldu.`);

    setSearchQuery(''); 
    setStatusFilter('Pending');
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const statusMap: Record<string, string> = {
            'Purchased': 'Satın Alındı',
            'Approved': 'Bütçe Onaylandı',
            'Rejected': 'Talep İptal Edildi',
            'On Hold': 'Talep Ertelendi',
            'Pending': 'Beklemeye Alındı'
          };
          const actionText = statusMap[newStatus] || `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Güncelleme', `Kayıt #${id} yeni statüsü: ${newStatus}`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
        setSelectedTransactionId(null);
    }

    if (newStatus === 'Rejected' || newStatus === 'On Hold') {
        setSelectedTransactionId(null);
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          return updated;
        }
        return t;
      })
    }));
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    setActiveTab('transactions');
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} sistemden kaldırıldı.`);
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => { 
        setActiveTab(tab); 
        setSelectedTransactionId(null); 
        if (tab !== 'transactions') setStatusFilter(null); 
      }} 
      user={state.user} 
      onLogout={handleLogout}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
    >
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                </div>
                <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                  <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                  <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                  <button onClick={() => setStatusFilter('On Hold')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'On Hold' ? 'bg-gray-600 text-white shadow-xl' : 'text-gray-500 hover:bg-gray-500/10'}`}>ERTELENEN</button>
                </div>
              </div>

              {searchQuery && (
                <div className="flex items-center space-x-2 text-violet-400 text-sm font-bold uppercase tracking-widest">
                  <Search size={16} />
                  <span>"{searchQuery}" araması için {filteredTransactions.length} sonuç bulundu</span>
                  <button onClick={() => setSearchQuery('')} className="text-[10px] bg-violet-500/10 px-2 py-1 rounded-md hover:bg-violet-500/20">TEMİZLE</button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className={`cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group transition-all ${t.status === 'Rejected' ? 'grayscale opacity-60' : ''}`}>
                      <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                      <div className="flex justify-between items-start mb-8 relative z-10">
