import React, { useMemo, useState } from 'react';
import { 
  Clock, TrendingUp, ShieldAlert, Globe, Activity, Zap, 
  Calendar, Filter, ChevronDown, Database, Landmark, Layers
} from 'lucide-react';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

type TimeRange = 'all' | '24h' | '7d' | '30d' | '1y';

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const [timeRange, setTimeRange] = useState<TimeRange>('all');
  const [selectedDept, setSelectedDept] = useState<string | null>(null);

  const departments = useMemo(() => {
    return Array.from(new Set(transactions.map(t => t.department)));
  }, [transactions]);

  const filteredData = useMemo(() => {
    let data = [...transactions];
    const now = new Date().getTime();

    // Zaman Filtresi
    if (timeRange !== 'all') {
      const msMap = {
        '24h': 24 * 60 * 60 * 1000,
        '7d': 7 * 24 * 60 * 60 * 1000,
        '30d': 30 * 24 * 60 * 60 * 1000,
        '1y': 365 * 24 * 60 * 60 * 1000,
      };
      data = data.filter(t => (now - new Date(t.requestDateTime).getTime()) <= msMap[timeRange]);
    }

    // Departman Filtresi
    if (selectedDept) {
      data = data.filter(t => t.department === selectedDept);
    }

    return data;
  }, [transactions, timeRange, selectedDept]);

  const stats = useMemo(() => {
    const purchased = filteredData.filter(t => t.status === 'Purchased');
    const total = purchased.reduce((sum, t) => sum + t.totalAmount, 0);
    const critical = filteredData.filter(t => t.priority === 'Critical' && t.status === 'Pending').length;
    const pendingCount = filteredData.filter(t => t.status === 'Pending').length;

    // Geçmiş verilerle karşılaştırma simülasyonu (Verimlilik)
    const efficiency = purchased.length > 0 ? Math.min(98, 85 + (purchased.length * 0.5)) : 0;

    return { total, critical, pendingCount, efficiency };
  }, [filteredData]);

  const timeRangeLabels = {
    all: 'TÜM ARŞİV',
    '24h': 'SON 24 SAAT',
    '7d': 'SON 7 GÜN',
    '30d': 'SON 30 GÜN',
    '1y': 'SON 1 YIL'
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-1000">
      {/* Üst Başlık ve Global Filtreler */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-end gap-8">
        <div>
          <h2 className="text-4xl font-black text-white neon-text-red uppercase tracking-tighter">OPERASYONEL MERKEZ</h2>
