          <div className="flex items-center space-x-3 mt-2">
            <Database size={12} className="text-red-600" />
            <p className="text-gray-600 font-bold text-[10px] uppercase tracking-[0.4em]">
              Bütçe ve Kaynak Denetim Paneli <span className="text-red-900 mx-2">|</span> 
              <span className="text-red-500">{filteredData.length} Kayıt İnceleniyor</span>
            </p>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          {/* Zaman Penceresi Seçici */}
          <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5">
