              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`px-4 py-2 rounded-xl text-[9px] font-black transition-all ${
                  timeRange === range 
                    ? 'bg-red-600 text-white shadow-lg' 
                    : 'text-gray-500 hover:text-gray-300'
