              <Layers size={14} className="text-red-600" />
              <span>{selectedDept || 'TÜM BİRİMLER'}</span>
              <ChevronDown size={14} />
            </button>
            <div className="absolute right-0 top-full mt-2 w-64 bg-[#0a0a0a] border border-white/10 rounded-2xl p-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 shadow-2xl backdrop-blur-xl">
               <button onClick={() => setSelectedDept(null)} className="w-full text-left px-4 py-3 rounded-xl text-[9px] font-black text-gray-500 hover:bg-red-600 hover:text-white transition-all uppercase">TÜM BİRİMLER</button>
               {departments.map(dept => (
                 <button 
                  key={dept} 
                  onClick={() => setSelectedDept(dept)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[9px] font-black uppercase transition-all ${selectedDept === dept ? 'bg-red-600/20 text-red-500' : 'text-gray-500 hover:bg-white/5 hover:text-white'}`}
                 >
                   {dept}
                 </button>
               ))}
            </div>
          </div>
        </div>
      </div>

      {/* Ana İstatistik Kartları */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="glass-panel p-8 rounded-[35px] border-white/5 flex flex-col justify-between group hover:border-red-600/30 transition-all relative overflow-hidden">
          <div className="absolute -right-4 -bottom-4 text-red-600 opacity-5 group-hover:opacity-10 transition-opacity"><Landmark size={120} /></div>
