          </p>
          <div className="space-y-1">
            <h3 className="text-4xl font-black text-white group-hover:text-red-500 transition-colors">₺{stats.total.toLocaleString('tr-TR')}</h3>
            <p className="text-[8px] text-gray-700 font-bold uppercase">{timeRangeLabels[timeRange]} verisidir</p>
          </div>
        </div>

        <div className="glass-panel p-8 rounded-[35px] border-red-600/20 bg-red-600/5 flex flex-col justify-between relative overflow-hidden group">
          <div className="absolute -right-4 -top-4 text-red-600 opacity-5"><ShieldAlert size={100} /></div>
          <p className="text-[9px] font-black text-red-500 uppercase tracking-widest mb-6">KRİTİK GÖREVLER</p>
