            </div>
          </div>
        </div>

        <div className="glass-panel p-8 rounded-[35px] border-white/5 flex flex-col justify-between group cursor-pointer hover:bg-white/5" onClick={() => onFilterClick('Pending')}>
          <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-6">ONAY BEKLEYEN</p>
          <div className="flex items-end justify-between">
            <h3 className="text-4xl font-black text-white">{stats.pendingCount} <span className="text-lg opacity-40">DOSYA</span></h3>
            <Zap size={20} className="text-amber-500 mb-2" />
          </div>
        </div>

        <div className="glass-panel p-8 rounded-[35px] border-white/5 flex flex-col justify-between group relative overflow-hidden">
          <p className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-6">SİSTEM VERİMLİLİĞİ</p>
          <div className="space-y-4">
            <div className="flex items-end justify-between">
