              <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="cyber-card p-8 glass-panel rounded-[35px] cursor-pointer relative overflow-hidden group">
                  <div className={`absolute top-0 right-0 w-1.5 h-full transition-all duration-500 ${
                    t.priority === 'Critical' ? 'bg-red-600 shadow-[0_0_20px_rgba(220,38,38,0.6)]' : 
                    t.status === 'Purchased' ? 'bg-green-600' : 'bg-gray-800'
                  } group-hover:w-3`}></div>
                  <div className="flex justify-between items-start mb-6">
                    <span className="text-[8px] font-black text-gray-700 uppercase tracking-widest">KOD: {t.id}</span>
                    <span className={`px-3 py-1 rounded-lg text-[7px] font-black uppercase ${
                      t.priority === 'Critical' ? 'bg-red-600 text-white shadow-xl' : 'bg-white/5 text-gray-500'
