                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className={`w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl ${t.status === 'On Hold' ? 'grayscale' : ''}`}>{t.requesterName ? t.requesterName.charAt(0) : 'A'}</div>
