                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {transaction.extraItems.map((item) => (
                          <div key={item.id} className="flex items-center justify-between p-5 bg-white/5 rounded-2xl border border-white/5 group hover:border-red-600/30 transition-all">
                            <div className="flex items-center space-x-4">
                              <div className="p-3 bg-red-600/10 text-red-500 rounded-xl group-hover:bg-red-600 group-hover:text-white transition-all">
                                <Layers size={16} />
                              </div>
                              <span className="text-xs font-black text-white uppercase">{item.name}</span>
                            </div>
                            <span className="text-[10px] font-black text-red-600 bg-red-600/10 px-3 py-1 rounded-lg">{item.quantity} ADET</span>
                          </div>
                        ))}
                      </div>
                   </div>
                )}

                <div className="space-y-8">
                   <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center border-b border-white/5 pb-4">
                     <ShoppingCart size={20} className="mr-4 text-red-600" /> SEÇİLEN TEKLİF VE OPSİYONLAR
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-8 rounded-[40px] border transition-all relative group cursor-pointer ${offer.isChosen ? 'bg-red-600/10 border-red-600/40 shadow-2xl scale-[1.02]' : 'bg-white/5 border-white/5 opacity-40 hover:opacity-100'}`} onClick={() => transaction.status !== 'Rejected' && handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.sourceType === 'Online' ? 'bg-blue-500/10 text-blue-400' : 'bg-amber-500/10 text-amber-400'}`}>{offer.sourceType === 'Online' ? <Globe size={22} /> : <Store size={22} />}</div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-500 shadow-xl" />}
                           </div>
                           <h5 className="text-xl font-black text-white uppercase mb-1">{offer.sourceName}</h5>
                           <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                              <p className="text-3xl font-black text-white">₺{offer.price.toLocaleString('tr-TR')}</p>
                              {offer.url && <ExternalLink size={18} className="text-gray-700 hover:text-white" />}
                           </div>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                   <div className="p-10 bg-[#0f0f0f] rounded-[45px] border border-white/5 space-y-6 h-fit shadow-inner">
                      <h4 className="text-[10px] font-black text-red-600 uppercase tracking-widest flex items-center"><Info size={16} className="mr-3" /> SATIN ALMA GEREKÇESİ</h4>
                      <p className="text-gray-400 text-xs leading-relaxed italic">"{transaction.justification || 'Gerekçe belirtilmemiş.'}"</p>
                   </div>
                   {transaction.photoUrl && (
                     <div className="group relative rounded-[45px] overflow-hidden border border-white/5 aspect-video cursor-pointer" onClick={() => setShowLightbox(transaction.photoUrl || null)}>
                        <img src={transaction.photoUrl} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-all duration-700" alt="Kanıt" />
                        <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity bg-black/40"><Eye className="text-white" size={32} /></div>
                     </div>
                   )}
                </div>
             </div>
          </div>

          <div className="bg-red-950/20 p-12 rounded-[55px] border border-red-600/10 flex flex-wrap items-center justify-between gap-10">
             <div className="flex-1 min-w-[300px] space-y-2">
                <p className="text-[10px] font-black text-red-500 uppercase tracking-widest">DOSYA KONTROL MERKEZİ</p>
                <p className="text-gray-500 text-xs leading-relaxed">Yöneticilerin adına vekaleten onay verebilir, talebi erteleyebilir veya iptal edebilirsiniz.</p>
             </div>
             <div className="flex gap-4">
                {transaction.status === 'Approved' && (
                   <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className="px-16 py-8 neon-gradient-red text-white rounded-[35px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center"><ShoppingCart size={24} className="mr-4" /> ALIMI TAMAMLA</button>
                )}
                {transaction.status !== 'Rejected' && transaction.status !== 'Purchased' && (
                  <>
                    <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-10 py-8 bg-white/5 border border-white/10 text-gray-500 rounded-[35px] font-black uppercase tracking-widest hover:border-amber-500 hover:text-amber-500 transition-all flex items-center"><Clock size={20} className="mr-3" /> ERTELE</button>
                    <button onClick={() => onStatusChange(transaction.id, 'Rejected')} className="px-10 py-8 bg-transparent border border-white/10 text-gray-700 rounded-[35px] font-black uppercase tracking-widest hover:border-red-600 hover:text-red-600 transition-all flex items-center"><Ban size={20} className="mr-3" /> TALEBİ İPTAL ET</button>
                  </>
                )}
                {transaction.status === 'Rejected' && (
                   <button onClick={() => onStatusChange(transaction.id, 'Pending')} className="px-10 py-8 bg-red-600 text-white rounded-[35px] font-black uppercase tracking-widest">TALEBİ YENİDEN AÇ</button>
                )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

