                  ? 'bg-red-600/10 text-red-500 border border-red-600/20 shadow-[0_0_20px_rgba(220,38,38,0.1)]' 
                  : 'text-gray-600 hover:text-gray-300 hover:bg-white/5'
              }`}
            >
              <span className={`${activeTab === item.id ? 'text-red-500' : 'text-gray-700'}`}>{item.icon}</span>
              <span className="font-bold text-[10px] tracking-widest uppercase">{item.label}</span>
            </button>
