import React, { useMemo, useState } from 'react';
import { 
  Clock, TrendingUp, ShieldAlert, Globe, Activity, Zap, 
  Calendar, Filter, ChevronDown, Database, Landmark, Layers
} from 'lucide-react';
import { Transaction } from '../types';

interface DashboardProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onFilterClick: (status: string | null) => void;
}

type TimeRange = 'all' | '24h' | '7d' | '30d' | '1y';

const Dashboard: React.FC<DashboardProps> = ({ transactions, onSelectTransaction, onFilterClick }) => {
  const [timeRange, setTimeRange] = useState<TimeRange>('all');
  const [selectedDept, setSelectedDept] = useState<string | null>(null);

  const departments = useMemo(() => {
    return Array.from(new Set(transactions.map(t => t.department)));
  }, [transactions]);

  const filteredData = useMemo(() => {
    let data = [...transactions];
    const now = new Date().getTime();

    if (timeRange !== 'all') {
      const msMap = {
        '24h': 24 * 60 * 60 * 1000,
        '7d': 7 * 24 * 60 * 60 * 1000,
        '30d': 30 * 24 * 60 * 60 * 1000,
        '1y': 365 * 24 * 60 * 60 * 1000,
      };
      data = data.filter(t => (now - new Date(t.requestDateTime).getTime()) <= msMap[timeRange]);
    }

    if (selectedDept) {
      data = data.filter(t => t.department === selectedDept);
    }

    return data;
  }, [transactions, timeRange, selectedDept]);

  const stats = useMemo(() => {
    const purchased = filteredData.filter(t => t.status === 'Purchased');
    const total = purchased.reduce((sum, t) => sum + t.totalAmount, 0);
    const critical = filteredData.filter(t => t.priority === 'Critical' && t.status === 'Pending').length;
    const pendingCount = filteredData.filter(t => t.status === 'Pending').length;
    const efficiency = purchased.length > 0 ? Math.min(98, 85 + (purchased.length * 0.5)) : 0;

    return { total, critical, pendingCount, efficiency };
  }, [filteredData]);

  const timeRangeLabels = {
    all: 'TÜMÜ',
    '24h': '24S',
    '7d': '7G',
    '30d': '30G',
    '1y': '1Y'
  };

  return (
    <div className="space-y-6 lg:space-y-10 animate-in fade-in duration-1000">
      {/* Üst Başlık ve Global Filtreler */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-end gap-6 lg:gap-8">
        <div>
          <h2 className="text-2xl lg:text-4xl font-black text-white neon-text-red uppercase tracking-tighter">KOMUTA MERKEZİ</h2>
          <div className="flex items-center space-x-3 mt-1 lg:mt-2">
            <Database size={10} className="text-red-600" />
            <p className="text-gray-600 font-bold text-[8px] lg:text-[10px] uppercase tracking-[0.4em]">
              {filteredData.length} Aktif Kayıt
            </p>
          </div>
        </div>

        <div className="w-full lg:w-auto flex flex-col sm:flex-row items-center gap-4">
          <div className="w-full lg:w-auto flex bg-white/5 p-1 rounded-xl border border-white/5 overflow-x-auto no-scrollbar">
            {(Object.keys(timeRangeLabels) as TimeRange[]).map((range) => (
              <button
                key={range}
                onClick={() => setTimeRange(range)}
                className={`flex-1 sm:flex-none px-3 lg:px-4 py-2 rounded-lg lg:rounded-xl text-[9px] font-black transition-all ${
                  timeRange === range 
                    ? 'bg-red-600 text-white shadow-lg' 
                    : 'text-gray-500 hover:text-gray-300'
                }`}
              >
                {timeRangeLabels[range]}
              </button>
            ))}
          </div>

          <div className="w-full lg:w-auto relative group">
            <button className="w-full flex items-center justify-between lg:justify-start space-x-3 px-6 py-3.5 bg-[#0a0a0a] border border-white/10 rounded-2xl text-[9px] font-black text-gray-400 uppercase tracking-widest">
              <div className="flex items-center space-x-3">
                <Layers size={14} className="text-red-600" />
                <span>{selectedDept || 'TÜM BİRİMLER'}</span>
              </div>
              <ChevronDown size={14} />
            </button>
            <div className="absolute right-0 top-full mt-2 w-full lg:w-64 bg-[#0a0a0a] border border-white/10 rounded-2xl p-2 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all z-50 shadow-2xl backdrop-blur-xl">
               <button onClick={() => setSelectedDept(null)} className="w-full text-left px-4 py-3 rounded-xl text-[9px] font-black text-gray-500 hover:bg-red-600 hover:text-white transition-all uppercase">TÜM BİRİMLER</button>
               {departments.map(dept => (
                 <button 
                  key={dept} 
                  onClick={() => setSelectedDept(dept)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[9px] font-black uppercase transition-all ${selectedDept === dept ? 'bg-red-600/20 text-red-500' : 'text-gray-500 hover:bg-white/5 hover:text-white'}`}
                 >
                   {dept}
                 </button>
               ))}
            </div>
          </div>
        </div>
      </div>

      {/* Ana İstatistik Kartları */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 lg:gap-6">
        <div className="glass-panel p-6 lg:p-8 rounded-2xl lg:rounded-[35px] border-white/5 flex flex-col justify-between group relative overflow-hidden">
          <p className="text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4 lg:mb-6 flex items-center">
            <Activity size={12} className="mr-2 text-red-600" /> TOPLAM HARCAMA
          </p>
          <h3 className="text-2xl lg:text-4xl font-black text-white group-hover:text-red-500 transition-colors">₺{stats.total.toLocaleString('tr-TR')}</h3>
        </div>

        <div className="glass-panel p-6 lg:p-8 rounded-2xl lg:rounded-[35px] border-red-600/20 bg-red-600/5 flex flex-col justify-between relative overflow-hidden group">
          <p className="text-[8px] lg:text-[9px] font-black text-red-500 uppercase tracking-widest mb-4 lg:mb-6">KRİTİK GÖREVLER</p>
          <div className="flex items-center justify-between">
            <h3 className="text-2xl lg:text-4xl font-black text-white">{stats.critical}</h3>
            <ShieldAlert size={20} className="text-red-600" />
          </div>
        </div>

        <div className="glass-panel p-6 lg:p-8 rounded-2xl lg:rounded-[35px] border-white/5 flex flex-col justify-between group cursor-pointer hover:bg-white/5" onClick={() => onFilterClick('Pending')}>
          <p className="text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4 lg:mb-6">ONAY BEKLEYEN</p>
          <div className="flex items-end justify-between">
            <h3 className="text-2xl lg:text-4xl font-black text-white">{stats.pendingCount}</h3>
            <Zap size={20} className="text-amber-500 mb-1" />
          </div>
        </div>

        <div className="glass-panel p-6 lg:p-8 rounded-2xl lg:rounded-[35px] border-white/5 flex flex-col justify-between group relative overflow-hidden">
          <p className="text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4 lg:mb-6">SİSTEM VERİMLİLİĞİ</p>
          <div className="space-y-3 lg:space-y-4">
            <div className="flex items-end justify-between">
              <h3 className="text-2xl lg:text-4xl font-black text-white">%{stats.efficiency.toFixed(0)}</h3>
              <TrendingUp size={20} className="text-green-500 mb-1" />
            </div>
            <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden">
              <div 
                className="h-full bg-red-600 shadow-[0_0_15px_rgba(220,38,38,0.5)] transition-all duration-1000 ease-out" 
                style={{ width: `${stats.efficiency}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      {/* Dinamik Liste */}
      <div className="space-y-6 lg:space-y-8">
        <div className="flex items-center justify-between">
          <h3 className="text-[9px] lg:text-[10px] font-black text-white uppercase tracking-[0.4em] flex items-center">
            <Clock size={16} className="mr-3 text-red-600" /> SON İŞLEMLER
          </h3>
        </div>

        {filteredData.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-8">
            {filteredData.slice(0, 9).map(t => (
              <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="cyber-card p-6 lg:p-8 glass-panel rounded-2xl lg:rounded-[35px] cursor-pointer relative overflow-hidden group">
                  <div className={`absolute top-0 right-0 w-1 h-full transition-all duration-500 ${
                    t.priority === 'Critical' ? 'bg-red-600 shadow-[0_0_10px_rgba(220,38,38,0.6)]' : 
                    t.status === 'Purchased' ? 'bg-green-600' : 'bg-gray-800'
                  } group-hover:w-2`}></div>
                  <div className="flex justify-between items-start mb-4 lg:mb-6">
                    <span className="text-[7px] lg:text-[8px] font-black text-gray-700 uppercase tracking-widest">KOD: {t.id}</span>
                    <span className={`px-2 py-0.5 rounded text-[7px] font-black uppercase ${
                      t.priority === 'Critical' ? 'bg-red-600 text-white' : 'bg-white/5 text-gray-500'
                    }`}>{t.priority}</span>
                  </div>
                  <h4 className="text-base lg:text-xl font-black text-white uppercase truncate mb-1 group-hover:text-red-500 transition-colors leading-tight">{t.productSetName}</h4>
                  <div className="flex items-center space-x-2 mb-6 lg:mb-8">
                    <p className="text-[8px] lg:text-[9px] text-gray-600 font-bold uppercase tracking-widest">{t.department}</p>
                  </div>
                  <div className="flex justify-between items-end border-t border-white/5 pt-4 lg:pt-6">
                    <div className="space-y-1">
                      <p className="text-[7px] lg:text-[8px] text-gray-800 font-black uppercase">Tutar</p>
                      <p className="text-xl lg:text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                    </div>
                  </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="py-24 text-center glass-panel rounded-3xl border border-dashed border-white/10 opacity-30">
            <Filter size={48} className="mx-auto mb-4 text-gray-800" />
            <p className="text-[9px] font-black text-gray-600 uppercase tracking-widest">Veri bulunamadı</p>
          </div>
        )}
      </div>
    </div>
  );
};

