import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, ShoppingCart, Globe, Store, ExternalLink, BadgeCheck, 
  Info, Eye, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, Camera, ImagePlus,
  Ban, Clock, Package, RotateCcw, AlertCircle
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    });
  };

  const undoApproval = (roleName: string) => {
    if (!confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz?`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending'
    });
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role && f.status === 'Pending') {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    });
    setShowApprovalModal(null);
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        executeApproval(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => {
          if (f.role === targetRoleForLateProof) {
            return { ...f, proofUrl: reader.result as string, type: 'Signed' as const };
          }
          return f;
        });
        onUpdate(transaction.id, { approvalFlow: newFlow });
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  return (
    <div className="animate-in fade-in duration-700 space-y-8 pb-24">

      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-8 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-full rounded-2xl shadow-2xl border border-white/10" alt="Full" />
           <button className="absolute top-10 right-10 p-4 text-white bg-red-600 rounded-full"><XCircle size={32}/></button>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 lg:p-14 rounded-[40px] border-red-600/30 space-y-8 animate-in zoom-in">
              <div className="text-center space-y-3">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-2xl font-black text-[var(--text-main)] uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[var(--text-muted)] text-[10px] uppercase tracking-widest">Lütfen bir onay türü seçin</p>
              </div>

              <div className="grid grid-cols-1 gap-4">
                 <button 
                    onClick={() => { setIsSignedApproval(false); executeApproval(); }}
                    className="flex items-center justify-between p-6 bg-[var(--bg-input)] border border-[var(--border-grey)] rounded-3xl hover:border-red-600/50 transition-all group"
                 >
                    <div className="flex items-center space-x-5">
                       <Zap size={24} className="text-red-600" />
                       <div className="text-left">
                          <p className="text-[11px] font-black text-[var(--text-main)] uppercase">HIZLI ONAY</p>
                          <p className="text-[8px] text-[var(--text-muted)] font-bold uppercase">Dijital imza ile onay basılır.</p>
                       </div>
                    </div>
                    <ChevronRight size={18} className="text-[var(--text-muted)]" />
                 </button>

                 <button 
                    onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }}
                    className="flex items-center justify-between p-6 bg-red-600/5 border border-red-600/20 rounded-3xl hover:bg-red-600/10 transition-all group"
                 >
                    <div className="flex items-center space-x-5">
                       <Signature size={24} className="text-red-600" />
                       <div className="text-left">
                          <p className="text-[11px] font-black text-[var(--text-main)] uppercase">ISLAK İMZA YÜKLE</p>
                          <p className="text-[8px] text-[var(--text-muted)] font-bold uppercase">Belge taraması eklenir.</p>
                       </div>
                    </div>
                    <Upload size={18} className="text-red-600" />
                 </button>
                 <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-4 text-[10px] font-black text-[var(--text-muted)] hover:text-[var(--text-main)] uppercase tracking-widest">VAZGEÇ</button>
           </div>
        </div>
      )}

      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center space-x-3 text-red-600 font-black text-xs uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> 
          <span>PANELİ KAPAT</span>
        </button>
        <div className="flex items-center space-x-4">
           {transaction.productUrl && (
             <a href={transaction.productUrl} target="_blank" rel="noopener noreferrer" className="flex items-center space-x-2 px-6 py-3 bg-red-600 text-white rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-red-500 transition-all">
                <ExternalLink size={14} />
                <span>ÜRÜNÜ GÖR</span>
             </a>
           )}
        </div>
      </div>

      <div className={`glass-panel rounded-[40px] overflow-hidden ${transaction.status === 'Rejected' ? 'opacity-60 grayscale' : ''}`}>
        <div className="p-8 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/50">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-8">
            <div className="flex-1">
              <div className="flex items-center space-x-3 mb-4">
                <span className="px-3 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black border border-red-600/20">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
            </div>
            <div className="lg:text-right">
              <p className="text-[10px] text-red-600 font-black uppercase mb-1">TOPLAM BÜTÇE</p>
              <h3 className="text-4xl lg:text-6xl font-black text-[var(--text-main)] tracking-tighter">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>
        </div>

        <div className="p-8 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                   <h4 className="text-[10px] font-black text-[var(--text-main)] uppercase tracking-widest flex items-center">
                      <ShieldCheck size={18} className="mr-3 text-red-600" /> ONAY ZİNCİRİ
                   </h4>
                   <History size={16} className="text-[var(--text-muted)]" />
                </div>
                <div className="space-y-4">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className={`flex items-center space-x-5 p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/20' : 'bg-[var(--bg-input)] border-[var(--border-grey)]'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-md' : 'bg-[var(--bg-deep)] text-[var(--text-muted)]'}`}>
                         {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                      </div>

                      <div className="flex-1">
                         <div className="flex items-center space-x-2">
                           <p className="text-[10px] font-black text-[var(--text-main)] uppercase">{flow.role}</p>
                           {flow.status === 'Approved' && (
                             <button 
                               onClick={() => undoApproval(flow.role)}
                               className="p-1 text-red-600 hover:bg-red-600 hover:text-white rounded-md transition-all group"
                               title="Onayı Geri Al"
                             >
                               <RotateCcw size={12} className="group-hover:rotate-[-180deg] transition-transform duration-500" />
                             </button>
                           )}
                         </div>
                         <p className="text-[9px] text-[var(--text-muted)] font-bold uppercase">{flow.approverName}</p>

                         {flow.status === 'Approved' ? (
                            <p className="text-[8px] text-red-600 font-bold mt-1 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')} - {flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL'}</p>
                         ) : transaction.status !== 'Rejected' && (
                            <button onClick={() => setShowApprovalModal({ role: flow.role })} className="mt-2 text-[8px] font-black text-red-600 uppercase flex items-center hover:underline">
                               VEKALETEN ONAYLA
                            </button>
                         )}
                      </div>

                      {flow.status === 'Approved' && flow.proofUrl && (
                        <div className="w-12 h-12 rounded-xl overflow-hidden cursor-pointer border border-red-600/20" onClick={() => setShowLightbox(flow.proofUrl!)}>
                           <img src={flow.proofUrl} className="w-full h-full object-cover" />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[10px] font-black text-[var(--text-main)] uppercase tracking-widest border-b border-[var(--border-grey)] pb-4">SEÇİLEN TEKLİF</h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-3xl border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/40 shadow-lg' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-40'}`} onClick={() => transaction.status !== 'Rejected' && handleSelectOffer(offer.id)}>
                           <div className="flex justify-between mb-4">
                              <div className="p-2 bg-[var(--bg-deep)] rounded-xl text-red-600">{offer.sourceType === 'Online' ? <Globe size={20} /> : <Store size={20} />}</div>
                              {offer.isChosen && <CheckCircle2 size={20} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-[var(--text-main)] uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-2xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="p-8 bg-[var(--bg-input)] rounded-3xl border border-[var(--border-grey)]">
                   <h4 className="text-[9px] font-black text-red-600 uppercase tracking-widest mb-4 flex items-center"><Info size={14} className="mr-2" /> GEREKÇE</h4>
                   <p className="text-[var(--text-muted)] text-xs italic">"{transaction.justification || 'Belirtilmedi.'}"</p>
                </div>
             </div>
          </div>

