import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, PlusCircle, Settings, LogOut, ShoppingBag,
  Bell, Search, Moon, Sun, BarChart3, Archive as ArchiveIcon
} from 'lucide-react';
import { User } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  user: User | null;
  onLogout: () => void;
  searchQuery: string;
  setSearchQuery: (setQuery: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, user, onLogout, searchQuery, setSearchQuery }) => {
  const [theme, setTheme] = useState<'dark' | 'light'>(
    (localStorage.getItem('theme') as any) || 'dark'
  );

  useEffect(() => {
    if (theme === 'light') {
      document.body.classList.add('light-mode');
    } else {
      document.body.classList.remove('light-mode');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const menuItems = [
    { id: 'dashboard', label: 'Komuta', icon: <LayoutDashboard size={20} /> },
    { id: 'new-request', label: 'Yeni', icon: <PlusCircle size={20} /> },
    { id: 'transactions', label: 'İşlem', icon: <ShoppingBag size={20} /> },
    { id: 'archive', label: 'Arşiv', icon: <ArchiveIcon size={20} /> },
    { id: 'reports', label: 'Rapor', icon: <BarChart3 size={20} /> },
    { id: 'settings', label: 'Ayarlar', icon: <Settings size={20} /> },
  ];

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[var(--bg-deep)]">
      {/* Sidebar */}
      <aside className="hidden lg:flex w-72 bg-[var(--bg-panel)] border-r border-[var(--border-grey)] flex-col z-20 shadow-xl">
