            src="https://i.ibb.co/LhY00n5/yasam-logo.png" 
            alt="Yaşam Hastanesi Logo" 
            className="w-48 object-contain mb-2 brightness-110 drop-shadow-[0_0_10px_rgba(220,38,38,0.2)]"
            onError={(e) => {
              // Fallback if image fails to load
              e.currentTarget.src = "https://www.tekirdagyasam.com/images/logo.png";
            }}
          />
          <p className="text-[7px] text-red-600 uppercase tracking-[0.5em] font-black opacity-80 mt-1">SATIN ALMA SİSTEMİ</p>
        </div>

        <nav className="flex-1 px-6 space-y-2 mt-6">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-4 px-5 py-4 rounded-xl transition-all duration-300 ${
                activeTab === item.id 
                  ? 'bg-red-600/10 text-red-600 border border-red-600/20' 
                  : 'text-[var(--text-muted)] hover:text-[var(--text-main)] hover:bg-[var(--border-grey)]'
              }`}
            >
              <span>{item.icon}</span>
              <span className="font-bold text-[10px] tracking-widest uppercase">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-8 border-t border-[var(--border-grey)]">
          <div className="flex items-center space-x-4 p-4 bg-[var(--bg-input)] rounded-2xl border border-[var(--border-grey)] mb-6">
            <div className="w-10 h-10 bg-red-600 rounded-lg flex items-center justify-center font-black text-white shadow-lg">
              {user?.name.charAt(0)}
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-xs font-black text-[var(--text-main)] truncate">{user?.name}</p>
              <p className="text-[8px] text-[var(--text-muted)] font-bold truncate uppercase">{user?.role}</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center space-x-3 px-5 py-3 text-red-600 hover:bg-red-600/5 rounded-xl transition-all">
            <LogOut size={16} />
            <span className="text-[9px] font-black uppercase tracking-widest">ÇIKIŞ YAP</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 border-b border-[var(--border-grey)] flex items-center justify-between px-6 lg:px-10 bg-[var(--bg-panel)] sticky top-0 z-30">
          <div className="flex lg:hidden items-center mr-4">
             <img src="https://i.ibb.co/LhY00n5/yasam-logo.png" alt="Yaşam Logo" className="h-8 object-contain" />
          </div>

          <div className="flex items-center flex-1 max-w-xl">
            <div className="relative w-full group">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-[var(--text-muted)]" size={16} />
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Evrak, tedarikçi veya bütçe ara..." 
                className="w-full rounded-xl py-2.5 pl-14 pr-4 text-xs transition-all outline-none"
              />
            </div>
          </div>

          <div className="flex items-center space-x-6 ml-6">
            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className="p-3 rounded-xl bg-[var(--bg-input)] border border-[var(--border-grey)] text-[var(--text-muted)] hover:text-red-600 transition-all shadow-sm"
