            </button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-10 custom-scroll bg-[var(--bg-deep)] pb-24 lg:pb-10">
            <div className="max-w-7xl mx-auto">
                {children}
            </div>
        </section>

        {/* Mobile Nav */}
        <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-[var(--bg-panel)] border-t border-[var(--border-grey)] px-2 py-3 flex justify-around items-center z-50 shadow-2xl">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`flex flex-col items-center p-2 rounded-xl ${activeTab === item.id ? 'text-red-600' : 'text-[var(--text-muted)]'}`}
            >
              {item.icon}
              <span className="text-[7px] font-black uppercase mt-1">{item.label}</span>
            </button>
          ))}
        </nav>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState } from 'react';
import { Lock, User as UserIcon, Loader2, Wallet2, AlertCircle } from 'lucide-react';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (loading) return;
    setLoading(true);
    setTimeout(() => {
      if (username === 'admin' && password === '1234') {
        onLogin({ username: 'admin', role: 'General Manager', name: 'Batuhan Yontuç' });
      } else {
        setError('KİMLİK DOĞRULANAMADI.');
        setLoading(false);
      }
    }, 1200);
  };

  return (
    <div className="min-h-screen bg-[#050505] flex items-center justify-center p-6 relative overflow-hidden">
      <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_center,rgba(220,38,38,0.08)_0%,transparent_70%)]"></div>

      <div className="w-full max-w-lg glass-panel rounded-[40px] border-red-600/10 shadow-[0_0_100px_rgba(0,0,0,0.8)] overflow-hidden relative z-10">
        <div className="p-12 md:p-16">
          <div className="text-center mb-14">
            <div className="inline-flex items-center justify-center w-full mb-8">
              <img 
                src="https://i.ibb.co/LhY00n5/yasam-logo.png" 
                alt="Yaşam Hastanesi Logo" 
                className="h-24 md:h-32 object-contain drop-shadow-[0_0_20px_rgba(220,38,38,0.4)]"
              />
            </div>
            <h1 className="text-4xl font-black text-white neon-text-red tracking-tight uppercase leading-none">YAŞAM FATURA</h1>
            <p className="text-red-700 font-bold uppercase tracking-[0.4em] text-[9px] mt-4">Enterprise Operational Access</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-red-600/10 border border-red-600/20 p-4 rounded-xl flex items-center space-x-3 text-red-500 text-[10px] font-black animate-pulse">
                <AlertCircle size={16} />
                <span>{error}</span>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Sistem Kimliği</label>
              <div className="relative">
                <UserIcon className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-700" size={18} />
                <input required type="text" value={username} onChange={e => setUsername(e.target.value)} placeholder="Yönetici Kimliği" className="w-full rounded-xl py-4 pl-14 pr-6 text-sm bg-white/5 border-white/5" />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Güvenlik Anahtarı</label>
              <div className="relative">
                <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-700" size={18} />
                <input required type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="••••" className="w-full rounded-xl py-4 pl-14 pr-6 text-sm bg-white/5 border-white/5" />
              </div>
            </div>

            <button type="submit" disabled={loading} className="w-full py-5 bg-red-600 text-white rounded-xl font-black uppercase tracking-[0.2em] text-[11px] shadow-[0_15px_30px_rgba(220,38,38,0.2)] hover:bg-red-500 active:scale-95 transition-all flex items-center justify-center space-x-3 mt-10">
              {loading ? <Loader2 className="animate-spin" size={20} /> : <span>SİSTEME GİRİŞ YAP</span>}
            </button>
