                              >
                                <ImagePlus size={10} /> <span>İMZA EKLE</span>
                              </button>
                            )}
                         </div>
                         <p className="text-[9px] text-[var(--text-muted)] font-bold uppercase">{flow.approverName}</p>

                         {flow.status === 'Approved' ? (
                            <p className="text-[8px] text-red-600 font-bold mt-1 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')} - {flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL ONAY'}</p>
                         ) : transaction.status !== 'Rejected' && (
                            <button onClick={() => setShowApprovalModal({ role: flow.role })} className="mt-2 text-[8px] font-black text-red-600 uppercase flex items-center hover:underline">
                               VEKALETEN ONAYLA
                            </button>
                         )}
                      </div>

                      {flow.status === 'Approved' && flow.proofUrl && (
                        <div className="w-12 h-12 rounded-xl overflow-hidden cursor-pointer border border-red-600/20 group relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
