                              <ExternalLink size={12} />
                           </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                {/* Paket İçeriği */}
                {transaction.extraItems && transaction.extraItems.length > 0 && (
                  <div className="space-y-6">
                    <h4 className="text-[10px] font-black text-[var(--text-main)] uppercase tracking-widest border-b border-[var(--border-grey)] pb-4 flex items-center">
