                    </h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {transaction.extraItems.map(item => (
                        <div key={item.id} className="flex items-center justify-between p-4 bg-[var(--bg-input)] rounded-2xl border border-[var(--border-grey)]">
                          <span className="text-[10px] font-bold text-[var(--text-main)] uppercase">{item.name}</span>
                          <span className="text-[10px] font-black text-red-600">{item.quantity} ADET</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                <div className="space-y-6">
                   <h4 className="text-[10px] font-black text-[var(--text-main)] uppercase tracking-widest border-b border-[var(--border-grey)] pb-4">SEÇİLEN TEKLİF</h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-3xl border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/40 shadow-lg' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-40'}`} onClick={() => transaction.status !== 'Rejected' && handleSelectOffer(offer.id)}>
