import React, { useState, useMemo } from 'react';
import { 
  Archive, Filter, Calendar, ChevronLeft, ChevronRight, 
  Search, ArrowUpRight, Download, FileText, CheckCircle2, 
  Clock, XCircle, MoreVertical, LayoutGrid, List, Database,
  AlertTriangle, Trash2
} from 'lucide-react';
import { Transaction } from '../types';

interface ArchiveProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
}

const ArchiveView: React.FC<ArchiveProps> = ({ transactions, onSelectTransaction, onStatusChange }) => {
  const currentYearNum = new Date().getFullYear();
  const endYearNum = 2030;

  const [selectedYear, setSelectedYear] = useState<string>(currentYearNum.toString());
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [viewType, setViewType] = useState<'grid' | 'list'>('list');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const years = useMemo(() => {
    const yearsFromData = new Set<string>(transactions.map(t => new Date(t.requestDateTime).getFullYear().toString()));
    for (let y = 2024; y <= endYearNum; y++) {
      yearsFromData.add(y.toString());
    }
    return Array.from(yearsFromData).sort((a, b) => b.localeCompare(a));
  }, [transactions]);

  const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];

  const filteredData = useMemo(() => {
    return transactions.filter(t => {
      const date = new Date(t.requestDateTime);
      const y = date.getFullYear().toString();
      const m = (date.getMonth() + 1).toString();
      const yearMatch = y === selectedYear;
      const monthMatch = selectedMonth ? m === selectedMonth : true;
      return yearMatch && monthMatch;
    }).sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [transactions, selectedYear, selectedMonth]);

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(start, start + itemsPerPage);
  }, [filteredData, currentPage]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  const totalSpend = useMemo(() => {
    return filteredData
      .filter(t => t.status === 'Purchased')
      .reduce((sum, t) => sum + t.totalAmount, 0);
  }, [filteredData]);

  const handleCancelTransaction = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Bu dosyayı arşivden iptal durumuna çekmek istediğinize emin misiniz? Bu işlem geri alınamaz.")) {
      onStatusChange(id, 'Rejected');
    }
  };

  return (
    <div className="space-y-6 lg:space-y-10 animate-in fade-in duration-700 pb-20">
      {/* Arşiv Başlığı ve Özet */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-6 lg:gap-8">
        <div className="space-y-2">
          <div className="flex items-center space-x-3">
             <div className="p-2 lg:p-3 bg-red-600 rounded-xl lg:rounded-2xl text-white shadow-2xl">
               <Archive size={20} />
             </div>
             <h2 className="text-2xl lg:text-4xl font-black text-white neon-text-red uppercase tracking-tighter">SİSTEM ARŞİVİ</h2>
          </div>
          <p className="text-gray-600 font-bold text-[8px] lg:text-[10px] uppercase tracking-[0.4em] ml-1">Kayıtlı Tüm Operasyonlar</p>
        </div>

        <div className="w-full lg:w-auto flex items-center justify-between lg:justify-start space-x-6 lg:space-x-10 glass-panel px-6 lg:px-10 py-4 lg:py-6 rounded-2xl lg:rounded-3xl border-white/5">
           <div>
              <p className="text-[8px] lg:text-[9px] font-black text-gray-500 uppercase mb-1">Dönem Harcaması</p>
              <p className="text-lg lg:text-2xl font-black text-white">₺{totalSpend.toLocaleString('tr-TR')}</p>
           </div>
           <div className="w-px h-8 lg:h-10 bg-white/10"></div>
           <div>
              <p className="text-[8px] lg:text-[9px] font-black text-gray-500 uppercase mb-1">Dosya Adedi</p>
              <p className="text-lg lg:text-2xl font-black text-red-500">{filteredData.length}</p>
           </div>
        </div>
      </div>

      {/* Kontrol ve Filtre Barı */}
      <div className="flex flex-col xl:flex-row gap-4 lg:gap-6">
        <div className="flex-1 flex flex-col gap-4">
           <div className="flex bg-white/5 p-1 rounded-xl lg:rounded-2xl border border-white/5 overflow-x-auto no-scrollbar whitespace-nowrap">
              {years.map(y => (
                <button 
                  key={y} 
                  onClick={() => { setSelectedYear(y); setCurrentPage(1); }}
                  className={`px-4 lg:px-6 py-2 rounded-lg lg:rounded-xl text-[9px] lg:text-[10px] font-black transition-all ${selectedYear === y ? 'bg-red-600 text-white shadow-lg' : 'text-gray-600 hover:text-gray-300'}`}
                >
                  {y}
                </button>
              ))}
           </div>

           <div className="flex bg-white/5 p-1 rounded-xl border border-white/5 overflow-x-auto no-scrollbar whitespace-nowrap">
              <button 
                onClick={() => { setSelectedMonth(null); setCurrentPage(1); }}
                className={`px-3 lg:px-4 py-2 rounded-lg text-[8px] lg:text-[9px] font-black uppercase transition-all ${!selectedMonth ? 'bg-white/10 text-white' : 'text-gray-700 hover:text-gray-400'}`}
              >
                TÜMÜ
              </button>
              {months.map((m, idx) => (
                <button 
                  key={m} 
                  onClick={() => { setSelectedMonth((idx + 1).toString()); setCurrentPage(1); }}
                  className={`px-3 lg:px-4 py-2 rounded-lg text-[8px] lg:text-[9px] font-black uppercase transition-all ${selectedMonth === (idx + 1).toString() ? 'bg-red-600/20 text-red-500' : 'text-gray-700 hover:text-gray-400'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        <div className="flex items-center justify-between lg:justify-end space-x-3">
           <div className="flex bg-white/5 p-1 rounded-xl border border-white/5">
              <button onClick={() => setViewType('list')} className={`p-2 rounded-lg transition-all ${viewType === 'list' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-700 hover:text-gray-400'}`}>
                <List size={16} />
              </button>
              <button onClick={() => setViewType('grid')} className={`p-2 rounded-lg transition-all ${viewType === 'grid' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-700 hover:text-gray-400'}`}>
                <LayoutGrid size={16} />
              </button>
           </div>
           <button className="p-3 bg-white/5 border border-white/10 rounded-xl text-gray-600 hover:text-white transition-all">
              <Download size={16} />
           </button>
        </div>
      </div>

      <div className="space-y-4 lg:space-y-6">
        {paginatedData.length > 0 ? (
          viewType === 'list' ? (
            <div className="glass-panel rounded-2xl lg:rounded-[40px] border-white/5 overflow-x-auto no-scrollbar">
               <table className="w-full text-left border-collapse min-w-[600px]">
                  <thead className="bg-white/2 border-b border-white/5">
                     <tr>
                        <th className="px-6 lg:px-8 py-4 lg:py-6 text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest">DURUM / TARİH</th>
                        <th className="px-6 lg:px-8 py-4 lg:py-6 text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest">DOSYA & TEDARİKÇİ</th>
                        <th className="px-6 lg:px-8 py-4 lg:py-6 text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest text-right">NET TUTAR</th>
                        <th className="px-6 lg:px-8 py-4 lg:py-6 text-[8px] lg:text-[9px] font-black text-gray-500 uppercase tracking-widest text-center">İŞLEM</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                     {paginatedData.map(t => (
                       <tr key={t.id} onClick={() => onSelectTransaction(t.id)} className="group hover:bg-red-600/[0.02] cursor-pointer transition-all">
                          <td className="px-6 lg:px-8 py-4 lg:py-6">
                             <div className="flex items-center space-x-4">
                                <div className={`w-1.5 h-8 lg:h-10 rounded-full ${
                                  t.status === 'Purchased' ? 'bg-green-600 shadow-[0_0_10px_rgba(22,163,74,0.4)]' :
                                  t.status === 'Approved' ? 'bg-cyan-600 shadow-[0_0_10px_rgba(8,145,178,0.4)]' :
                                  t.status === 'Rejected' ? 'bg-red-600' : 'bg-gray-800'
                                }`}></div>
                                <div>
                                   <p className="text-[9px] lg:text-[10px] font-black text-white uppercase">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                                   <p className="text-[7px] lg:text-[8px] text-gray-700 font-bold uppercase">{t.status}</p>
                                </div>
                             </div>
                          </td>
                          <td className="px-6 lg:px-8 py-4 lg:py-6">
                             <p className="text-xs lg:text-sm font-black text-white uppercase group-hover:text-red-500 transition-colors">{t.productSetName}</p>
                             <p className="text-[8px] lg:text-[9px] text-gray-600 font-bold uppercase tracking-widest">{t.supplierName || '...'}</p>
                          </td>
                          <td className="px-6 lg:px-8 py-4 lg:py-6 text-right">
                             <p className="text-base lg:text-lg font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                          </td>
                          <td className="px-6 lg:px-8 py-4 lg:py-6 text-center">
                             {t.status !== 'Rejected' && (
                               <button 
                                onClick={(e) => handleCancelTransaction(e, t.id)}
                                className="p-2 text-gray-700 hover:text-red-600 transition-colors"
                                title="Dosyayı İptal Et"
                               >
                                 <XCircle size={18} />
                               </button>
                             )}
                          </td>
                       </tr>
                     ))}
                  </tbody>
               </table>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 lg:gap-6">
               {paginatedData.map(t => (
                 <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="glass-panel p-6 lg:p-8 rounded-2xl lg:rounded-[35px] border-white/5 hover:border-red-600/30 transition-all cursor-pointer group relative overflow-hidden">
                    <div className="flex justify-between items-start mb-4 lg:mb-6">
                       <span className="text-[7px] lg:text-[8px] font-black text-gray-700 uppercase tracking-widest">ID: {t.id}</span>
                       <div className="flex items-center space-x-2">
                          {t.status !== 'Rejected' && (
                            <button onClick={(e) => handleCancelTransaction(e, t.id)} className="text-gray-700 hover:text-red-600 p-1">
                               <Trash2 size={14} />
                            </button>
                          )}
                          <div className={`p-1.5 rounded-full ${t.status === 'Purchased' ? 'bg-green-600' : 'bg-gray-800'}`}></div>
                       </div>
                    </div>
                    <h4 className="text-base lg:text-lg font-black text-white uppercase truncate mb-1 group-hover:text-red-500 transition-colors">{t.productSetName}</h4>
                    <p className="text-[8px] lg:text-[9px] text-gray-600 font-bold uppercase mb-6 lg:mb-8">{t.department}</p>
                    <div className="flex justify-between items-end">
                       <div>
                          <p className="text-[7px] lg:text-[8px] font-black text-gray-800 uppercase mb-1">Tutar</p>
                          <p className="text-lg lg:text-xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       </div>
                       <p className="text-[7px] lg:text-[8px] text-gray-700 font-mono italic">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                    </div>
                 </div>
               ))}
            </div>
          )
        ) : (
          <div className="py-24 lg:py-40 text-center glass-panel rounded-3xl lg:rounded-[50px] border border-dashed border-white/10">
             <Database size={48} className="mx-auto mb-4 lg:mb-6 text-gray-900" />
             <p className="text-[9px] lg:text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Veri Kaydı Bulunmuyor</p>
          </div>
        )}

        {totalPages > 1 && (
          <div className="flex items-center justify-center space-x-4 lg:space-x-6 pt-6 lg:pt-10">
             <button 
              onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
              disabled={currentPage === 1}
              className="p-3 lg:p-4 glass-panel rounded-xl border-white/5 text-gray-500 disabled:opacity-20 hover:text-red-500 transition-all"
             >
                <ChevronLeft size={16} />
             </button>
             <div className="flex items-center space-x-2 lg:space-x-3">
                <span className="text-[10px] lg:text-xs font-black text-white">{currentPage}</span>
                <span className="text-[10px] lg:text-xs font-black text-gray-800">/</span>
                <span className="text-[10px] lg:text-xs font-black text-gray-800">{totalPages}</span>
             </div>
             <button 
              onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
              disabled={currentPage === totalPages}
              className="p-3 lg:p-4 glass-panel rounded-xl border-white/5 text-gray-500 disabled:opacity-20 hover:text-red-500 transition-all"
             >
                <ChevronRight size={16} />
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ArchiveView;

import React, { useState, useEffect, useMemo } from 'react';
import { Search } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, RoleDefinition, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  useEffect(() => {
    const handleGlobalEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        if (selectedTransactionId) {
          setSelectedTransactionId(null);
        } else if (activeTab !== 'dashboard') {
          setActiveTab('dashboard');
        }
      }
    };
    window.addEventListener('keydown', handleGlobalEsc);
    return () => window.removeEventListener('keydown', handleGlobalEsc);
  }, [selectedTransactionId, activeTab]);

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];

    if (statusFilter) {
      list = list.filter(t => t.status === statusFilter);
    }

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q) ||
        (t.justification && t.justification.toLowerCase().includes(q))
      );
    }

    return list.sort((a, b) => 
      new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime()
    );
  }, [state.transactions, statusFilter, searchQuery]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
    setSearchQuery('');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Batuhan Yontuç',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || request.packageQuantity || 1,
      unitPrice: request.unitPrice || request.packageUnitPrice || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPrice: request.packageUnitPrice || 0,
      totalAmount: request.totalAmount || (request.packageQuantity || 1) * (request.packageUnitPrice || 0),
      description: request.description || '',
      justification: request.justification || '',
      generalNotes: request.generalNotes || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl, 
      publicTrackKey: request.publicTrackKey,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: request.logs || [],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} kodlu yeni talep oluşturuldu.`);

    setSearchQuery(''); 
    setStatusFilter('Pending');
    setActiveTab('transactions');
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const statusMap: Record<string, string> = {
            'Purchased': 'Satın Alındı',
            'Approved': 'Bütçe Onaylandı',
            'Rejected': 'Talep İptal Edildi',
            'On Hold': 'Talep Ertelendi',
            'Pending': 'Beklemeye Alındı'
          };
          const actionText = statusMap[newStatus] || `Durum: ${newStatus}`;
          const newLog = { id: `log-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Statü Güncelleme', details: actionText };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));
    addSystemLog('PURCHASE', 'Durum Güncelleme', `Kayıt #${id} yeni statüsü: ${newStatus}`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
        setSelectedTransactionId(null);
    }

    if (newStatus === 'Rejected' || newStatus === 'On Hold') {
        setSelectedTransactionId(null);
        setActiveTab('transactions');
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          return updated;
        }
        return t;
      })
    }));
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    setActiveTab('transactions');
    addSystemLog('PURCHASE', 'Kayıt Silindi', `Kayıt #${id} sistemden kaldırıldı.`);
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={(tab) => { 
        setActiveTab(tab); 
        setSelectedTransactionId(null); 
        if (tab !== 'transactions') setStatusFilter(null); 
      }} 
      user={state.user} 
      onLogout={handleLogout}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
    >
      {selectedTransaction ? (
        <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
      ) : (
        <>
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onStatusChange={handleStatusChange} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-700">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                </div>
                <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                  <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                  <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                  <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                  <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                  <button onClick={() => setStatusFilter('On Hold')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'On Hold' ? 'bg-gray-600 text-white shadow-xl' : 'text-gray-500 hover:bg-gray-500/10'}`}>ERTELENEN</button>
                </div>
              </div>

              {searchQuery && (
                <div className="flex items-center space-x-2 text-violet-400 text-sm font-bold uppercase tracking-widest">
                  <Search size={16} />
                  <span>"{searchQuery}" araması için {filteredTransactions.length} sonuç bulundu</span>
                  <button onClick={() => setSearchQuery('')} className="text-[10px] bg-violet-500/10 px-2 py-1 rounded-md hover:bg-violet-500/20">TEMİZLE</button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.length > 0 ? (
                  filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className={`cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group transition-all ${t.status === 'Rejected' ? 'grayscale opacity-60' : ''}`}>
                      <div className="absolute -right-4 -top-4 w-32 h-32 bg-violet-500/5 rounded-full blur-3xl group-hover:bg-violet-500/10 transition-all"></div>
                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className={`w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl ${t.status === 'On Hold' ? 'grayscale' : ''}`}>{t.requesterName ? t.requesterName.charAt(0) : 'A'}</div>
                        <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${
                          t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                          t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                          t.status === 'On Hold' ? 'bg-gray-500/10 text-gray-400 border-gray-500/20' :
                          t.status === 'Rejected' ? 'bg-red-500/10 text-red-400 border-red-500/20' :
                          'bg-violet-500/10 text-violet-400 border-violet-500/20'
                        }`}>{
                          t.status === 'Pending' ? 'BEKLEYEN' : 
                          t.status === 'Approved' ? 'ONAYLI' : 
                          t.status === 'Purchased' ? 'ALINDI' : 
                          t.status === 'On Hold' ? 'ERTELENDİ' :
                          t.status === 'Rejected' ? 'İPTAL' : t.status
                        }</span>
                      </div>
                      <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                      <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-1">{t.department} • {t.supplierName}</p>
                      <p className="text-[9px] text-slate-500 font-mono mb-10">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')} {new Date(t.requestDateTime).toLocaleTimeString('tr-TR', {hour: '2-digit', minute:'2-digit'})}</p>
                      <div className="flex justify-between items-end border-t border-violet-500/10 pt-8">
                         <div>
                            <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                            <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="col-span-full py-24 text-center glass-panel rounded-[40px] border border-dashed border-violet-500/20 opacity-50">
                    <Search size={48} className="mx-auto mb-4 text-violet-900" />
                    <p className="text-sm font-black text-violet-500 uppercase tracking-widest">Kayıt Bulunamadı</p>
                    <p className="text-xs text-slate-500 mt-2 italic">Arama kriterlerinizi değiştirip tekrar deneyin.</p>
                  </div>
                )}
              </div>
            </div>
          )}
          {activeTab === 'settings' && <Settings 
            roles={state.roles} 
            setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} 
            departments={state.departments} 
            setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} 
            user={state.user} 
            onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} 
            systemLogs={state.systemLogs} 
            transactions={state.transactions} 
            searchQuery={searchQuery}
            onSelectTransaction={(id) => { setSelectedTransactionId(id); }}
            onShowAll={() => { setActiveTab('transactions'); }}
            onBack={() => setActiveTab('dashboard')} 
          />}
        </>
      )}
    </Layout>
  );
};

