                   <p className="text-[var(--text-muted)] text-xs italic">"{transaction.justification || 'Belirtilmedi.'}"</p>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-10 rounded-[40px] border border-red-600/10 flex flex-wrap items-center justify-between gap-6">
             <div className="flex-1 min-w-[200px] space-y-1">
                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest flex items-center">
                  <AlertCircle size={14} className="mr-2" /> OPERASYONEL EYLEMLER
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase">Talep durumunu buradan yönetebilirsiniz.</p>
             </div>
             <div className="flex flex-wrap gap-3">
                {transaction.status === 'Approved' && (
                   <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className="px-8 py-4 bg-red-600 text-white rounded-2xl font-black uppercase text-[10px] hover:bg-red-500 transition-all shadow-xl">SATIN ALIMI BİTİR</button>
                )}
                {transaction.status !== 'Rejected' && transaction.status !== 'Purchased' && (
                  <>
                    <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-6 py-4 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-2xl font-black uppercase text-[10px] hover:bg-white hover:text-black transition-all">ERTELE</button>
                    <button onClick={() => onStatusChange(transaction.id, 'Rejected')} className="px-6 py-4 border border-red-900/50 text-red-700 rounded-2xl font-black uppercase text-[10px] hover:bg-red-700 hover:text-white transition-all">İPTAL ET</button>
                  </>
                )}
                {transaction.status === 'Purchased' && (
                   <button onClick={() => onStatusChange(transaction.id, 'Approved')} className="px-6 py-4 border border-red-900/50 text-red-700 rounded-2xl font-black uppercase text-[10px] hover:bg-red-700 hover:text-white transition-all">SATIN ALIMI İPTAL ET (GERİ ÇEK)</button>
                )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

