               <span className="text-[7px] text-red-600 uppercase tracking-[0.3em] font-black">v2 Premium Edition</span>
            </div>
          </div>
        </div>

        <nav className="flex-1 px-6 space-y-1.5 mt-2">
          {menuItems.map((item) => (
