            <span>SİSTEMDEN AYRIL</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-24 border-b border-[var(--border-grey)] flex items-center justify-between px-6 lg:px-12 bg-[var(--bg-panel)]/80 backdrop-blur-3xl sticky top-0 z-30">
          <div className="flex lg:hidden items-center mr-4">
             <img src={LOGO_URL} alt="Yaşam Logo" className="h-10 object-contain" />
          </div>

          <div className="flex items-center flex-1 max-w-2xl">
            <div className="relative w-full group">
              <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-[var(--text-muted)] group-focus-within:text-red-600 transition-colors" size={18} />
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Evrak, tedarikçi veya bütçe kodu ile arayın..." 
                className="w-full rounded-2xl py-4 pl-16 pr-6 text-xs transition-all outline-none border-transparent focus:bg-[var(--bg-deep)]"
              />
            </div>
          </div>

          <div className="flex items-center space-x-4 ml-8">
            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className="p-3.5 rounded-2xl bg-[var(--bg-input)] border border-[var(--border-grey)] text-[var(--text-muted)] hover:text-red-600 hover:border-red-600/40 transition-all shadow-sm"
              title="Görünüm Modu"
            >
              {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button className="relative p-3.5 rounded-2xl bg-[var(--bg-input)] border border-[var(--border-grey)] text-[var(--text-muted)] hover:text-red-600 transition-all">
              <Bell size={20} />
              <span className="absolute top-3.5 right-3.5 w-2.5 h-2.5 bg-red-600 rounded-full border-2 border-[var(--bg-panel)] pulse-effect"></span>
            </button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-12 custom-scroll bg-[var(--bg-deep)] pb-32 lg:pb-12">
            <div className="max-w-7xl mx-auto">
                {children}
            </div>
        </section>

        {/* Mobile Nav */}
        <nav className="lg:hidden fixed bottom-0 left-0 w-full bg-[var(--bg-panel)]/95 backdrop-blur-2xl border-t border-[var(--border-grey)] px-2 py-4 flex justify-around items-center z-50 shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`flex flex-col items-center p-2 rounded-xl transition-all ${activeTab === item.id ? 'text-red-600 scale-110' : 'text-[var(--text-muted)] opacity-60'}`}
            >
              {item.icon}
              <span className="text-[7px] font-black uppercase mt-1.5 tracking-tighter">{item.label}</span>
            </button>
          ))}
        </nav>
      </main>
    </div>
  );
};

export default Layout;

