import React, { useState, useMemo } from 'react';
import { 
  Archive, Filter, Calendar, ChevronLeft, ChevronRight, 
  Search, ArrowUpRight, Download, FileText, CheckCircle2, 
  Clock, XCircle, MoreVertical, LayoutGrid, List, Database,
  AlertTriangle, Trash2
} from 'lucide-react';
import { Transaction } from '../types';

interface ArchiveProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
}

const ArchiveView: React.FC<ArchiveProps> = ({ transactions, onSelectTransaction, onStatusChange, onDelete }) => {
  const currentYearNum = new Date().getFullYear();
  const endYearNum = 2030;

  const [selectedYear, setSelectedYear] = useState<string>(currentYearNum.toString());
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [viewType, setViewType] = useState<'grid' | 'list'>('list');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const years = useMemo(() => {
    const yearsFromData = new Set<string>(transactions.map(t => new Date(t.requestDateTime).getFullYear().toString()));
    for (let y = 2024; y <= endYearNum; y++) {
      yearsFromData.add(y.toString());
    }
    return Array.from(yearsFromData).sort((a, b) => b.localeCompare(a));
  }, [transactions]);

  const months = ["Ocak", "Şubat", "Mart", "Nisan", "Mayıs", "Haziran", "Temmuz", "Ağustos", "Eylül", "Ekim", "Kasım", "Aralık"];

  const filteredData = useMemo(() => {
    return transactions.filter(t => {
      const date = new Date(t.requestDateTime);
      const y = date.getFullYear().toString();
      const m = (date.getMonth() + 1).toString();
      const yearMatch = y === selectedYear;
      const monthMatch = selectedMonth ? m === selectedMonth : true;
      return yearMatch && monthMatch;
    }).sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [transactions, selectedYear, selectedMonth]);

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filteredData.slice(start, start + itemsPerPage);
  }, [filteredData, currentPage]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  const totalSpend = useMemo(() => {
    return filteredData
      .filter(t => t.status === 'Purchased')
      .reduce((sum, t) => sum + t.totalAmount, 0);
  }, [filteredData]);

  const handleDeleteTransaction = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("DİKKAT! Bu dosya arşivden ve tüm sistemden KALICI olarak silinecek. Onaylıyor musunuz?")) {
      onDelete(id);
    }
  };

  return (
    <div className="space-y-6 lg:space-y-10 animate-in fade-in duration-700 pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-6 lg:gap-8">
        <div className="space-y-2">
          <div className="flex items-center space-x-3">
             <div className="p-3 bg-red-600 rounded-2xl text-white shadow-2xl">
               <Archive size={20} />
             </div>
             <h2 className="text-2xl lg:text-4xl font-black text-white neon-text-red uppercase tracking-tighter">SİSTEM ARŞİVİ</h2>
          </div>
          <p className="text-gray-600 font-bold text-[10px] uppercase tracking-[0.4em] ml-1">Kayıtlı Tüm Operasyonlar</p>
        </div>

        <div className="w-full lg:w-auto flex items-center justify-between lg:justify-start space-x-10 glass-panel px-10 py-6 rounded-3xl border-white/5">
           <div>
              <p className="text-[9px] font-black text-gray-500 uppercase mb-1">Dönem Harcaması</p>
              <p className="text-2xl font-black text-white">₺{totalSpend.toLocaleString('tr-TR')}</p>
           </div>
           <div className="w-px h-10 bg-white/10"></div>
           <div>
              <p className="text-[9px] font-black text-gray-500 uppercase mb-1">Dosya Adedi</p>
              <p className="text-2xl font-black text-red-500">{filteredData.length}</p>
           </div>
        </div>
      </div>

      <div className="flex flex-col xl:flex-row gap-6">
        <div className="flex-1 flex flex-col gap-4">
           <div className="flex bg-white/5 p-1 rounded-2xl border border-white/5 overflow-x-auto no-scrollbar whitespace-nowrap">
              {years.map(y => (
                <button 
                  key={y} 
                  onClick={() => { setSelectedYear(y); setCurrentPage(1); }}
                  className={`px-6 py-2 rounded-xl text-[10px] font-black transition-all ${selectedYear === y ? 'bg-red-600 text-white shadow-lg' : 'text-gray-600 hover:text-gray-300'}`}
                >
                  {y}
                </button>
              ))}
           </div>
           <div className="flex bg-white/5 p-1 rounded-xl border border-white/5 overflow-x-auto no-scrollbar whitespace-nowrap">
              <button 
                onClick={() => { setSelectedMonth(null); setCurrentPage(1); }}
                className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${!selectedMonth ? 'bg-white/10 text-white' : 'text-gray-700 hover:text-gray-400'}`}
              >
                TÜMÜ
              </button>
              {months.map((m, idx) => (
                <button 
                  key={m} 
                  onClick={() => { setSelectedMonth((idx + 1).toString()); setCurrentPage(1); }}
                  className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${selectedMonth === (idx + 1).toString() ? 'bg-red-600/20 text-red-500' : 'text-gray-700 hover:text-gray-400'}`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>
        <div className="flex items-center space-x-3">
           <div className="flex bg-white/5 p-1 rounded-xl border border-white/5">
              <button onClick={() => setViewType('list')} className={`p-2 rounded-lg transition-all ${viewType === 'list' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-700 hover:text-gray-400'}`}>
                <List size={16} />
              </button>
              <button onClick={() => setViewType('grid')} className={`p-2 rounded-lg transition-all ${viewType === 'grid' ? 'bg-red-600 text-white shadow-lg' : 'text-gray-700 hover:text-gray-400'}`}>
                <LayoutGrid size={16} />
              </button>
           </div>
        </div>
      </div>

      <div className="space-y-6">
        {paginatedData.length > 0 ? (
          viewType === 'list' ? (
            <div className="glass-panel rounded-[40px] border-white/5 overflow-x-auto no-scrollbar">
               <table className="w-full text-left border-collapse min-w-[600px]">
                  <thead className="bg-white/2 border-b border-white/5">
                     <tr>
                        <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase tracking-widest">DURUM / TARİH</th>
                        <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase tracking-widest">DOSYA & TEDARİKÇİ</th>
                        <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase tracking-widest text-right">NET TUTAR</th>
                        <th className="px-8 py-6 text-[9px] font-black text-gray-500 uppercase tracking-widest text-center">EYLEM</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                     {paginatedData.map(t => (
                       <tr key={t.id} onClick={() => onSelectTransaction(t.id)} className="group hover:bg-red-600/[0.02] cursor-pointer transition-all">
                          <td className="px-8 py-6">
                             <div className="flex items-center space-x-4">
                                <div className={`w-1.5 h-10 rounded-full ${
                                  t.status === 'Purchased' ? 'bg-green-600 shadow-[0_0_10px_rgba(22,163,74,0.4)]' :
                                  t.status === 'Approved' ? 'bg-cyan-600 shadow-[0_0_10px_rgba(8,145,178,0.4)]' :
                                  'bg-gray-800'
                                }`}></div>
                                <div>
                                   <p className="text-[10px] font-black text-white uppercase">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                                   <p className="text-[8px] text-gray-700 font-bold uppercase">{t.status}</p>
                                </div>
                             </div>
                          </td>
                          <td className="px-8 py-6">
                             <p className="text-sm font-black text-white uppercase group-hover:text-red-500 transition-colors">{t.productSetName}</p>
                             <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest">{t.supplierName}</p>
                          </td>
                          <td className="px-8 py-6 text-right font-black text-lg text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</td>
                          <td className="px-8 py-6 text-center">
                             <button onClick={(e) => handleDeleteTransaction(e, t.id)} className="p-3 text-gray-800 hover:text-red-600 hover:bg-red-600/5 rounded-xl transition-all">
                               <Trash2 size={18} />
                             </button>
                          </td>
                       </tr>
                     ))}
                  </tbody>
               </table>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
               {paginatedData.map(t => (
                 <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="glass-panel p-8 rounded-[35px] border-white/5 hover:border-red-600/30 transition-all cursor-pointer group relative overflow-hidden">
                    <div className="flex justify-between items-start mb-6">
                       <span className="text-[8px] font-black text-gray-700 uppercase tracking-widest">ID: {t.id}</span>
                       <button onClick={(e) => handleDeleteTransaction(e, t.id)} className="text-gray-800 hover:text-red-600 p-2 bg-white/5 rounded-lg">
                          <Trash2 size={14} />
                       </button>
                    </div>
                    <h4 className="text-lg font-black text-white uppercase truncate mb-1 group-hover:text-red-500 transition-colors">{t.productSetName}</h4>
                    <p className="text-[9px] text-gray-600 font-bold uppercase mb-8">{t.department}</p>
                    <div className="flex justify-between items-end">
                       <p className="text-xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       <p className="text-[8px] text-gray-700 font-mono italic">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</p>
                    </div>
                 </div>
               ))}
            </div>
          )
        ) : (
          <div className="py-40 text-center glass-panel rounded-[50px] border border-dashed border-white/10 opacity-30">
             <Database size={48} className="mx-auto mb-6 text-gray-900" />
             <p className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Arşiv Verisi Bulunmuyor</p>
          </div>
        )}

        {totalPages > 1 && (
          <div className="flex items-center justify-center space-x-6 pt-10">
             <button onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))} disabled={currentPage === 1} className="p-4 glass-panel rounded-xl text-gray-500 disabled:opacity-20 hover:text-red-500 transition-all"><ChevronLeft size={16} /></button>
             <div className="text-xs font-black text-white">{currentPage} / {totalPages}</div>
             <button onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))} disabled={currentPage === totalPages} className="p-4 glass-panel rounded-xl text-gray-500 disabled:opacity-20 hover:text-red-500 transition-all"><ChevronRight size={16} /></button>
          </div>
        )}
      </div>
    </div>
  );
};

