                            <button type="button" onClick={() => setChosenOffer(offer.id)} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white shadow-lg' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
