                   <div className="space-y-2 max-h-64 overflow-y-auto custom-scroll pr-2">
                     {transaction.logs.map(log => (
                       <div key={log.id} className="p-4 bg-black/20 rounded-2xl border border-white/5 flex justify-between items-center hover:bg-black/30 transition-all">
