                          <div className="text-right">
                            <span className="text-[8px] font-mono text-gray-700 block">{new Date(log.timestamp).toLocaleDateString('tr-TR')}</span>
                            <span className="text-[8px] font-mono text-gray-700 block">{new Date(log.timestamp).toLocaleTimeString('tr-TR')}</span>
                          </div>
                       </div>
                     ))}
                   </div>
                </div>
             </div>
          </div>

          {/* Operational Status */}
          <div className="bg-red-600/5 p-10 rounded-[40px] border border-red-600/10 flex flex-wrap items-center justify-between gap-6">
             <div className="flex-1 min-w-[200px] space-y-1">
                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest flex items-center"><AlertCircle size={14} className="mr-2" /> OPERASYONEL DURUM</p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase">Talep statüsünü buradan manuel değiştirebilirsiniz.</p>
             </div>
             <div className="flex flex-wrap gap-3">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`px-8 py-4 ${transaction.status === 'Purchased' ? 'bg-green-600' : 'bg-red-600'} text-white rounded-2xl font-black uppercase text-[10px] shadow-xl hover:bg-red-500 transition-all`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALIM TAMAMLANDI' : 'SATIN ALIMI BİTİR'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-6 py-4 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-2xl font-black uppercase text-[10px] hover:bg-white hover:text-black transition-all">ERTELE</button>
                <button onClick={() => onStatusChange(transaction.id, 'Rejected')} className="px-6 py-4 border border-red-900 text-red-700 rounded-2xl font-black uppercase text-[10px] hover:bg-red-700 hover:text-white transition-all">DOSYAYI İPTAL ET</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

