      {/* Approval Modal */}
      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-6 sm:p-10 rounded-[35px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Yetki bazlı onaylama işlemi</p>
              </div>
              <textarea 
                value={decisionNote}
                onChange={e => setDecisionNote(e.target.value)}
                placeholder="Varsa notunuz..."
                className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-sm text-white min-h-[100px]"
              />
              <div className="grid grid-cols-1 gap-3">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="flex items-center justify-between p-4 bg-red-600 text-white rounded-2xl font-bold uppercase text-[11px] shadow-lg">
                   HIZLI DİJİTAL ONAY <Zap size={18} />
                </button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="flex items-center justify-between p-4 bg-white/5 border border-white/10 text-white rounded-2xl font-bold uppercase text-[11px]">
                   ISLAK İMZA YÜKLE <Signature size={18} />
                </button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      {/* Header Controls */}
