           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-4 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[10px] uppercase">
