                      <div className="flex items-center space-x-4">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${flow.status === 'Approved' ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                           {flow.status === 'Approved' ? <BadgeCheck size={20} /> : <UserCheck size={20} />}
