                        <div className="flex-1 min-w-0">
                           <div className="flex items-center justify-between">
                              <p className="text-[9px] font-black text-white uppercase truncate">{flow.role}</p>
                              {flow.status === 'Approved' ? (
                                <button onClick={() => undoApproval(flow.role)} className="p-1.5 text-red-600 bg-white/5 rounded-lg">
                                   <RotateCcw size={14} />
                                </button>
                              ) : (
                                <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-2 py-1 bg-red-600 text-white rounded-lg text-[7px] font-black uppercase">ONAY</button>
                              )}
                           </div>
                           <p className="text-[8px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                        </div>
                        {flow.status === 'Approved' && flow.proofUrl && (
                          <div className="w-10 h-10 rounded-lg overflow-hidden border border-red-600/20" onClick={() => setShowLightbox(flow.proofUrl!)}>
                             <img src={flow.proofUrl} className="w-full h-full object-cover" />
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-10">
                {/* Offers */}
                <div className="space-y-4">
                   <h4 className="text-[9px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-3">TEKLİFLER</h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-4 rounded-2xl border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/40' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-center mb-2">
                              <p className="text-[11px] font-black text-white uppercase truncate">{offer.sourceName}</p>
                              {offer.isChosen && <CheckCircle2 size={16} className="text-red-600" />}
                           </div>
                           <p className="text-lg font-black text-red-600">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                {/* Documents - Scrollable for Mobile */}
                <div className="space-y-4">
                   <div className="flex items-center justify-between">
                      <h4 className="text-[9px] font-black text-[var(--text-main)] uppercase tracking-[0.2em]">BELGELER</h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-3 py-2 bg-red-600 text-white rounded-lg text-[8px] font-black uppercase">DOSYA EKLE</button>
                   </div>
                   <div className="flex space-x-3 overflow-x-auto pb-2 no-scrollbar">
                      {transaction.invoices?.map((inv, idx) => (
                         <div key={idx} className="relative min-w-[80px] h-20 rounded-xl overflow-hidden border border-white/5 flex-shrink-0">
                            <img src={inv} className="w-full h-full object-cover" />
                            <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                               <button onClick={() => removeInvoice(idx)} className="p-1.5 bg-red-600 text-white rounded-lg"><Trash2 size={12}/></button>
                            </div>
                         </div>
                      ))}
                      {(!transaction.invoices || transaction.invoices.length === 0) && (
                        <div className="w-full h-20 bg-white/5 rounded-xl border border-dashed border-white/10 flex items-center justify-center">
                           <p className="text-[8px] text-gray-600 font-black uppercase">Belge Yok</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="p-6 bg-[var(--bg-input)] rounded-2xl border border-[var(--border-grey)]">
                   <p className="text-[8px] font-black text-red-600 uppercase tracking-widest mb-2 flex items-center"><Info size={12} className="mr-2" /> GEREKÇE</p>
                   <p className="text-[var(--text-muted)] text-[10px] italic leading-relaxed">"{transaction.justification}"</p>
                </div>
             </div>
          </div>

          {/* Action Footer - Sticky style on mobile? */}
          <div className="bg-red-600/5 p-6 rounded-[25px] border border-red-600/10 flex flex-col sm:flex-row items-center gap-6">
             <div className="flex flex-wrap justify-center gap-2 w-full">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className="flex-1 min-w-[140px] py-4 bg-red-600 text-white rounded-xl font-black uppercase text-[10px] shadow-lg">SATIN ALIMI BİTİR</button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="flex-1 min-w-[140px] py-4 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-xl font-black uppercase text-[10px]">ERTELE</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

