import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi/Teklif değiştirildi: ${chosen?.sourceName}`);
  };

  const undoApproval = (roleName: string) => {
    if (!confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya 'Bekliyor' durumuna düşecek ve bu adımın tüm verileri (not, imza vb.) sıfırlanacaktır.`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending'
    }, `${roleName} onayı yönetici tarafından GERİ ÇEKİLDİ.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} onayı verildi. ${decisionNote ? `Not: ${decisionNote}` : ''}`);

    setShowApprovalModal(null);
    setDecisionNote('');
    setIsSignedApproval(false);
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        executeApproval(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const openLateProofPicker = (role: string) => {
    setTargetRoleForLateProof(role);
    setTimeout(() => {
      lateProofInputRef.current?.click();
    }, 100);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => {
          if (f.role === targetRoleForLateProof) {
            return { 
              ...f, 
              proofUrl: reader.result as string, 
              type: 'Signed' as const,
              status: 'Approved' as const,
              date: f.date || new Date().toISOString() 
            };
          }
          return f;
        });
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} onayı için görsel kanıt güncellendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string] 
        }, `Yeni fatura eklendi.`);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const removeInvoice = (idx: number) => {
    if (!confirm("Belge silinsin mi?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Fatura silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {/* Lightbox */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" alt="Full" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {/* Print View */}
      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">
                    Kapat
                 </button>
              </div>
              <div className="p-4 sm:p-10">
                <OfficialForm transaction={transaction} />
              </div>
           </div>
        </div>
      )}

      {/* Approval Modal */}
      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-6 sm:p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Karar notunuzu ekleyebilirsiniz</p>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">KARAR NOTU</label>
                <textarea 
                  value={decisionNote}
                  onChange={e => setDecisionNote(e.target.value)}
                  placeholder="Bu onay/red ile ilgili notunuzu yazın..."
                  className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none shadow-inner focus:border-red-600/50"
                />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="flex items-center justify-between p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">
                   HIZLI DİJİTAL ONAY <Zap size={20} />
                </button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="flex items-center justify-between p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">
                   ISLAK İMZA YÜKLE <Signature size={20} />
                </button>
                <input type="file" id="sig-input" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      {/* Header Controls */}
      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button onClick={() => { if(confirm('Bu dosya silinsin mi?')) onDelete(transaction.id); }} className="p-3 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10">
              <Trash2 size={20} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg">
              <Printer size={16} className="text-red-600" />
              <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black border border-red-600/20">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">İSTENEN BİRİM/KİŞİ: {transaction.usageLocation || 'Belirtilmemiş'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 flex flex-col items-center lg:items-end justify-center">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA BEDELİ</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

             {/* ONAY ZİNCİRİ - SOL KOLON */}
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY SÜRECİ & KANITLAR
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        {/* TEXT TABANLI GERİ ÇEK BUTONU */}
                                        <button 
                                          onClick={() => undoApproval(flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button onClick={() => openLateProofPicker(flow.role)} className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all">
                                           <ImagePlus size={16} />
                                        </button>
                                     </>
                                   ) : (
                                     <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-red-500 transition-all">ONAYLA</button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                             {flow.status === 'Approved' && (
                                <div className="flex items-center space-x-2 mt-1">
                                   <span className="text-[8px] font-black text-red-600 uppercase tracking-tighter">{flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL ONAY'}</span>
                                   <span className="text-[8px] text-gray-600">•</span>
                                   <span className="text-[8px] font-black text-gray-600 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')}</span>
                                </div>
                             )}
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity">
                                  <Eye size={16} className="text-white" />
                               </div>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Karar Notu Balonu */}
                      {flow.status === 'Approved' && flow.decisionNote && (
                        <div className="ml-16 p-4 bg-white/5 border border-white/10 rounded-2xl relative animate-in slide-in-from-top-2">
                           <div className="absolute -top-2 left-6 w-3 h-3 bg-[var(--bg-input)] border-t border-l border-white/10 rotate-45"></div>
                           <div className="flex items-start space-x-3">
                              <MessageSquare size={14} className="text-red-600 mt-0.5 shrink-0" />
                              <p className="text-[10px] text-[var(--text-muted)] italic leading-relaxed">"{flow.decisionNote}"</p>
                           </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             {/* TEKLİFLER VE BELGELER - SAĞ KOLON */}
             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> TEDARİKÇİ & TEKLİFLER
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all cursor-pointer group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE & DOSYA HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg hover:bg-red-500 transition-all">
                        DOSYA YÜKLE
                      </button>
                   </div>

                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices && transaction.invoices.length > 0 ? (
                        transaction.invoices.map((inv, idx) => (
                           <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 transition-all cursor-pointer">
                              <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                                 <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 transition-transform"><Eye size={18} /></button>
                                 <button onClick={() => removeInvoice(idx)} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 transition-transform"><Trash2 size={18} /></button>
                              </div>
                           </div>
                        ))
                      ) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-600" />
                           <p className="text-[10px] font-black uppercase text-gray-500">Henüz belge eklenmedi</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="p-8 bg-[var(--bg-input)] rounded-[35px] border border-[var(--border-grey)]">
                   <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.3em] mb-4 flex items-center"><Info size={16} className="mr-3" /> TALEP GEREKÇESİ</p>
                   <p className="text-[var(--text-muted)] text-[11px] italic leading-relaxed">"{transaction.justification}"</p>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1">Dosyayı nihai statüsüne çekin.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`flex-1 sm:flex-none px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white' : 'bg-red-600 text-white hover:bg-red-500'}`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALIM TAMAMLANDI' : 'SATIN ALIMI BİTİR'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="flex-1 sm:flex-none px-8 py-5 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-[25px] font-black uppercase text-[11px] hover:bg-white hover:text-black transition-all">ERTELE</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi/Teklif değiştirildi: ${chosen?.sourceName}`);
  };

  const undoApproval = (roleName: string) => {
    if (!confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya 'Bekliyor' durumuna düşecek ve bu adımın tüm verileri (not, imza vb.) sıfırlanacaktır.`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending'
    }, `${roleName} onayı yönetici tarafından GERİ ÇEKİLDİ.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} onayı verildi. ${decisionNote ? `Not: ${decisionNote}` : ''}`);

    setShowApprovalModal(null);
    setDecisionNote('');
    setIsSignedApproval(false);
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        executeApproval(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const openLateProofPicker = (role: string) => {
    setTargetRoleForLateProof(role);
    setTimeout(() => {
      lateProofInputRef.current?.click();
    }, 100);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => {
          if (f.role === targetRoleForLateProof) {
            return { 
              ...f, 
              proofUrl: reader.result as string, 
              type: 'Signed' as const,
              status: 'Approved' as const,
              date: f.date || new Date().toISOString() 
            };
          }
          return f;
        });
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} onayı için görsel kanıt güncellendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string] 
        }, `Yeni fatura eklendi.`);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const removeInvoice = (idx: number) => {
    if (!confirm("Belge silinsin mi?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Fatura silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {/* Lightbox */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" alt="Full" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {/* Print View */}
      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">
                    Kapat
                 </button>
              </div>
              <div className="p-4 sm:p-10">
                <OfficialForm transaction={transaction} />
              </div>
           </div>
        </div>
      )}

      {/* Approval Modal */}
      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-6 sm:p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Karar notunuzu ekleyebilirsiniz</p>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">KARAR NOTU</label>
                <textarea 
                  value={decisionNote}
                  onChange={e => setDecisionNote(e.target.value)}
                  placeholder="Bu onay/red ile ilgili notunuzu yazın..."
                  className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none shadow-inner focus:border-red-600/50"
                />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="flex items-center justify-between p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">
                   HIZLI DİJİTAL ONAY <Zap size={20} />
                </button>
