export default TransactionDetail;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, ChevronRight, ChevronLeft, UserPlus, CheckCircle2,
  Package, ListPlus, ExternalLink, Sparkles, Loader2, Globe, Store,
  MapPin, Building2, Edit3
} from 'lucide-react';
import { Transaction, Currency, Priority, Offer, ExtraItem } from '../types';
import { INITIAL_ROLES } from '../constants';
import { analyzeJustification } from '../services/geminiService';

interface NewRequestProps {
  onSave: (transaction: Partial<Transaction>) => void;
  departments: string[];
  onAddDepartment: (name: string) => void;
  onBack?: () => void;
}

const NewRequest: React.FC<NewRequestProps> = ({ onSave, departments, onAddDepartment, onBack }) => {
  const [step, setStep] = useState(1);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiFeedback, setAiFeedback] = useState<string | null>(null);
  const [otherDeptName, setOtherDeptName] = useState('');

  const [formData, setFormData] = useState({
    productSetName: '',
    department: departments[0] || '',
    usageLocation: '', 
    priority: 'Medium' as Priority,
    currency: 'TRY' as Currency,
    packageQuantity: 1,
    justification: '',
    microCode: '',
    totalAmount: 0,
    photoUrl: '',
    productUrl: '' 
  });

  const [extraItems, setExtraItems] = useState<ExtraItem[]>([]);
  const [selectedApproverIds, setSelectedApproverIds] = useState<string[]>(INITIAL_ROLES.slice(0, 2).map(r => r.id));

  const [offers, setOffers] = useState<Offer[]>([
    { id: 'off-1', sourceName: '', sourceType: 'Online', price: 0, isChosen: true, url: '' }
  ]);

  useEffect(() => {
    const chosenOffer = offers.find(o => o.isChosen) || offers[0];
    const total = formData.packageQuantity * (chosenOffer?.price || 0);
    setFormData(prev => ({ ...prev, totalAmount: total }));
  }, [formData.packageQuantity, offers]);

  const handleAiAnalysis = async () => {
    if (!formData.justification || formData.justification.length < 10) {
      alert("Analiz için daha detaylı bir gerekçe yazmalısınız.");
      return;
    }
    setAnalyzing(true);
    const feedback = await analyzeJustification(formData.productSetName, formData.justification);
    setAiFeedback(feedback);
    setAnalyzing(false);
  };

  const addExtraItem = () => {
    setExtraItems([...extraItems, { id: `item-${Date.now()}`, name: '', quantity: 1 }]);
  };

  const removeExtraItem = (id: string) => {
    setExtraItems(extraItems.filter(item => item.id !== id));
  };

  const updateExtraItem = (id: string, updates: Partial<ExtraItem>) => {
    setExtraItems(extraItems.map(item => item.id === id ? { ...item, ...updates } : item));
  };

  const addOffer = () => {
    if (offers.length >= 6) return;
    setOffers([...offers, { id: `off-${Date.now()}`, sourceName: '', sourceType: 'Online', price: 0, isChosen: false, url: '' }]);
  };

  const removeOffer = (id: string) => {
    if (offers.length <= 1) return;
    setOffers(prev => prev.filter(o => o.id !== id));
  };

  const updateOffer = (id: string, updates: Partial<Offer>) => {
    setOffers(prev => prev.map(o => o.id === id ? { ...o, ...updates } : o));
  };

  const setChosenOffer = (id: string) => {
    setOffers(prev => prev.map(o => ({ ...o, isChosen: o.id === id })));
  };

  const toggleApprover = (id: string) => {
    setSelectedApproverIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleSubmit = () => {
    let finalDepartment = formData.department;
    if (formData.department === 'DIĞER' && otherDeptName.trim()) {
      finalDepartment = otherDeptName.trim().toUpperCase();
      onAddDepartment(finalDepartment);
    }

    const chosenOffer = offers.find(o => o.isChosen);
    const customFlow = INITIAL_ROLES
      .filter(r => selectedApproverIds.includes(r.id))
      .map(r => ({
        role: r.roleName,
        status: 'Pending' as const,
        approverName: r.assignedName
      }));

    onSave({
      ...formData,
      department: finalDepartment,
      unitPrice: chosenOffer?.price || 0,
      packageUnitPrice: chosenOffer?.price || 0,
      offers,
      extraItems, 
      supplierName: chosenOffer?.sourceName || '',
      approvalFlow: customFlow
    });
  };

  const inputClass = "w-full px-5 py-4 rounded-2xl bg-[var(--bg-input)] border border-[var(--border-grey)] focus:border-red-600/50 text-[var(--text-main)] outline-none transition-all text-sm shadow-inner placeholder:text-gray-500";

  return (
    <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700 pb-24">

      <div className="flex items-center justify-center mb-16 space-x-4">
        <div className={`flex items-center space-x-3 transition-all ${step === 1 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 1 ? 'bg-red-600 text-white shadow-lg' : 'bg-[var(--bg-input)] text-gray-500'}`}>1</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-[var(--text-main)]">TEKNİK ANALİZ</span>
        </div>
        <div className="w-12 h-[2px] bg-[var(--border-grey)]"></div>
        <div className={`flex items-center space-x-3 transition-all ${step === 2 ? 'opacity-100 scale-110' : 'opacity-40'}`}>
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${step === 2 ? 'bg-red-600 text-white shadow-lg' : 'bg-[var(--bg-input)] text-gray-500'}`}>2</div>
          <span className="text-[10px] font-black uppercase tracking-[0.2em] text-[var(--text-main)]">ONAY AKIŞI</span>
        </div>
      </div>

      <div className="space-y-10">
        {step === 1 ? (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-10 rounded-[45px] border-[var(--border-grey)] space-y-8">

                {/* Birim Seçimi ve Diğer Opsiyonu */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] ml-1 flex items-center">
                      <Building2 size={14} className="mr-2 text-red-600" /> TALEP EDEN BİRİM
                    </label>
                    <div className="space-y-3">
                      <select 
                        value={formData.department} 
                        onChange={e => setFormData({...formData, department: e.target.value})}
                        className={inputClass}
                      >
                        {departments.map(d => <option key={d} value={d}>{d}</option>)}
                        <option value="DIĞER">DİĞER...</option>
                      </select>

                      {formData.department === 'DIĞER' && (
                        <div className="relative animate-in slide-in-from-top-2 duration-300">
                          <Edit3 size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-red-600" />
                          <input 
                            required
                            type="text" 
                            value={otherDeptName} 
                            onChange={e => setOtherDeptName(e.target.value)}
                            placeholder="Yeni Birim Adını Yazın..." 
                            className={`${inputClass} !pl-12 !border-red-600/30 bg-red-600/5`}
                          />
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] ml-1 flex items-center">
                      <MapPin size={14} className="mr-2 text-red-600" /> HANGİ BİRİM/KİŞİ İÇİN?
                    </label>
                    <input 
                      required 
                      type="text" 
                      value={formData.usageLocation} 
                      onChange={e => setFormData({...formData, usageLocation: e.target.value})} 
                      placeholder="Örn: Kardiyoloji / Dr. Ahmet" 
                      className={inputClass} 
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">ANA ÜRÜN / SET ADI</label>
                    <input 
                      required 
                      type="text" 
                      value={formData.productSetName} 
                      onChange={e => setFormData({...formData, productSetName: e.target.value})} 
                      placeholder="Örn: Godox Işık Seti" 
                      className={inputClass} 
                    />
                  </div>
                  <div className="space-y-3">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">TOPLAM SET ADEDİ</label>
                    <input 
                      required 
                      type="number" 
                      min="1" 
                      value={formData.packageQuantity} 
                      onChange={e => setFormData({...formData, packageQuantity: Math.max(1, parseInt(e.target.value) || 0)})} 
                      className={inputClass} 
                    />
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-[10px] font-black text-gray-500 uppercase tracking-[0.2em] ml-1 flex items-center">
                    <ExternalLink size={14} className="mr-2 text-red-600" /> ÜRÜN REFERANS LİNKİ
                  </label>
                  <input 
                    type="url" 
                    value={formData.productUrl} 
                    onChange={e => setFormData({...formData, productUrl: e.target.value})} 
                    placeholder="https://www.hepsiburada.com/urun-detay" 
                    className={inputClass} 
                  />
                </div>

                <div className="space-y-6 pt-4">
                  <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                    <h3 className="text-xs font-black text-[var(--text-main)] uppercase tracking-widest flex items-center">
                      <Package size={20} className="mr-3 text-red-600" /> PAKET İÇERİĞİ / ALT ÜRÜNLER
                    </h3>
                    <button type="button" onClick={addExtraItem} className="flex items-center space-x-2 px-4 py-2 bg-[var(--bg-input)] text-[var(--text-main)] rounded-xl text-[10px] font-black uppercase border border-[var(--border-grey)] hover:border-red-600 transition-all">
                      <ListPlus size={14} /> <span>MADDE EKLE</span>
                    </button>
                  </div>

                  <div className="space-y-3">
                    {extraItems.map((item) => (
                      <div key={item.id} className="flex items-center space-x-3 group animate-in slide-in-from-right-2 duration-300">
                        <input 
                          type="text" 
                          value={item.name} 
                          onChange={e => updateExtraItem(item.id, {name: e.target.value})} 
                          placeholder="Ürün adı (Örn: Mikrofon Standı)" 
                          className={`${inputClass} !py-3`} 
                        />
                        <input 
                          type="number" 
                          min="1"
                          value={item.quantity} 
                          onChange={e => updateExtraItem(item.id, {quantity: Math.max(1, parseInt(e.target.value) || 1)})}
                          className={`${inputClass} !py-3 w-24 text-center`} 
                        />
                        <button onClick={() => removeExtraItem(item.id)} className="p-3 text-gray-500 hover:text-red-600 transition-colors">
                          <Trash2 size={18} />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="space-y-6 pt-6">
                  <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-6">
                    <h3 className="text-xs font-black text-[var(--text-main)] uppercase tracking-widest flex items-center">
                      <Sparkles size={20} className="mr-3 text-red-600" /> PAZAR ARAŞTIRMASI (FİYAT TEKLİFLERİ)
                    </h3>
                    <button type="button" onClick={addOffer} className="px-5 py-2.5 bg-red-600/10 text-red-600 rounded-xl text-[10px] font-black uppercase border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                      + TEKLİF EKLE
                    </button>
                  </div>

                  <div className="space-y-4">
                    {offers.map((offer) => (
                      <div key={offer.id} className={`p-6 rounded-[35px] border transition-all ${offer.isChosen ? 'bg-red-600/5 border-red-600/30 shadow-lg' : 'bg-[var(--bg-input)] border-[var(--border-grey)]'}`}>
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-5 items-end">
                          <div className="md:col-span-4 space-y-2">
                            <label className="text-[8px] font-black text-gray-500 uppercase">TEKLİF TÜRÜ & FİRMA</label>
                            <div className="flex bg-[var(--bg-deep)] p-1 rounded-xl border border-[var(--border-grey)] mb-2">
                               <button 
                                 type="button"
                                 onClick={() => updateOffer(offer.id, {sourceType: 'Online'})}
                                 className={`flex-1 flex items-center justify-center space-x-2 py-2 rounded-lg text-[8px] font-black transition-all ${offer.sourceType === 'Online' ? 'bg-red-600 text-white shadow-md' : 'text-gray-500'}`}
                               >
                                  <Globe size={12} /> <span>ONLINE</span>
                               </button>
                               <button 
                                 type="button"
                                 onClick={() => updateOffer(offer.id, {sourceType: 'Local'})}
                                 className={`flex-1 flex items-center justify-center space-x-2 py-2 rounded-lg text-[8px] font-black transition-all ${offer.sourceType === 'Local' ? 'bg-red-600 text-white shadow-md' : 'text-gray-500'}`}
                               >
                                  <Store size={12} /> <span>YEREL ESNAF</span>
                               </button>
                            </div>
                            <input 
                              required 
                              type="text" 
                              value={offer.sourceName} 
                              onChange={e => updateOffer(offer.id, {sourceName: e.target.value})} 
                              placeholder="Firma adı..." 
                              className={inputClass} 
                            />
                          </div>
                          <div className="md:col-span-4 space-y-2">
                            <label className="text-[8px] font-black text-gray-500 uppercase">BİRİM FİYAT (TL)</label>
                            <input 
                              required 
                              type="number" 
                              step="0.01" 
                              value={offer.price} 
                              onChange={e => updateOffer(offer.id, {price: parseFloat(e.target.value) || 0})} 
                              className={inputClass} 
                            />
                          </div>
                          <div className="md:col-span-4 flex items-center space-x-2">
                            <button type="button" onClick={() => setChosenOffer(offer.id)} className={`flex-1 py-4 rounded-2xl text-[10px] font-black uppercase transition-all ${offer.isChosen ? 'bg-red-600 text-white shadow-lg' : 'bg-[var(--bg-input)] text-gray-500'}`}>
                              {offer.isChosen ? 'SEÇİLİ' : 'SEÇ'}
                            </button>
                            <button type="button" onClick={() => removeOffer(offer.id)} className="p-4 text-gray-500 hover:text-red-600 transition-colors"><Trash2 size={18}/></button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="space-y-6">
               <div className="glass-panel p-10 rounded-[45px] border-red-600/20 bg-red-600/5">
                  <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-6">ÖZET ANALİZ</p>
                  <div className="space-y-8">
                    <div>
                        <h3 className="text-5xl font-black text-[var(--text-main)]">₺{formData.totalAmount.toLocaleString('tr-TR')}</h3>
                        <p className="text-[10px] text-red-700 font-bold uppercase mt-2">TAHMİNİ TOPLAM TUTAR</p>
                    </div>
                    <button type="button" onClick={() => setStep(2)} className="w-full py-6 bg-red-600 text-white rounded-[25px] font-black shadow-2xl uppercase tracking-widest text-[11px] hover:bg-red-500 transition-all flex items-center justify-center group">
                      ONAYCILARI BELİRLE <ChevronRight size={18} className="ml-2 group-hover:translate-x-1 transition-transform" />
                    </button>
                  </div>
               </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            <div className="lg:col-span-2 space-y-8">
              <div className="glass-panel p-12 rounded-[50px] border-[var(--border-grey)] space-y-12">
                <div className="space-y-8">
                    <h3 className="text-xs font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center border-b border-[var(--border-grey)] pb-4">
                      <UserPlus size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {INITIAL_ROLES.map((role) => (
                        <div 
                          key={role.id} 
                          onClick={() => toggleApprover(role.id)}
                          className={`p-6 rounded-[30px] border transition-all cursor-pointer flex items-center justify-between group ${selectedApproverIds.includes(role.id) ? 'bg-red-600/10 border-red-600/40 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`}
                        >
                           <div className="flex items-center space-x-4">
                              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${selectedApproverIds.includes(role.id) ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
                                 <UserPlus size={20} />
                              </div>
                              <div>
                                 <p className="text-[10px] font-black text-[var(--text-main)] uppercase">{role.roleName}</p>
                                 <p className="text-[8px] text-[var(--text-muted)] font-bold uppercase tracking-widest">{role.assignedName}</p>
                              </div>
                           </div>
                           {selectedApproverIds.includes(role.id) ? <CheckCircle2 size={20} className="text-red-500" /> : <div className="w-5 h-5 rounded-full border border-[var(--border-grey)]"></div>}
                        </div>
                      ))}
                    </div>
                </div>

                <div className="space-y-6">
                     <div className="flex items-center justify-between">
                        <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest">TALEP GEREKÇESİ</label>
                        <button 
                          onClick={handleAiAnalysis}
                          disabled={analyzing}
                          className="flex items-center space-x-2 text-[10px] font-black text-red-600 uppercase hover:underline disabled:opacity-50"
                        >
                          {analyzing ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                          <span>AI ANALİZİ AL</span>
                        </button>
                     </div>
                     <textarea 
                       required 
                       value={formData.justification} 
                       onChange={e => setFormData({...formData, justification: e.target.value})} 
                       className="w-full bg-[var(--bg-input)] border border-[var(--border-grey)] rounded-2xl p-6 text-sm text-[var(--text-main)] min-h-[150px] resize-none outline-none shadow-inner" 
                       placeholder="Bu ürünün alımı neden gerekli?" 
                     />
                     {aiFeedback && (
                       <div className="p-5 bg-red-600/5 border border-red-600/10 rounded-2xl animate-in slide-in-from-top-2">
                          <p className="text-[9px] font-black text-red-600 uppercase mb-2 flex items-center"><Sparkles size={12} className="mr-2" /> AI GERİ BİLDİRİMİ</p>
                          <p className="text-xs text-[var(--text-muted)] italic leading-relaxed">"{aiFeedback}"</p>
                       </div>
                     )}
                </div>
              </div>
            </div>

            <div className="space-y-8">
               <div className="glass-panel p-10 rounded-[45px] border-red-600/20 bg-red-600/5 space-y-6 text-center">
                  <div className="w-16 h-16 bg-red-600 rounded-3xl flex items-center justify-center text-white mx-auto shadow-xl">
                     <CheckCircle2 size={32} />
                  </div>
                  <h4 className="text-lg font-black text-[var(--text-main)] uppercase tracking-tighter">TALEP HAZIR</h4>
                  <button 
                    onClick={handleSubmit}
                    className="w-full py-8 bg-red-600 text-white rounded-[30px] font-black uppercase tracking-widest text-xs hover:scale-[1.02] active:scale-95 transition-all shadow-2xl"
                  >
                     KAYDET VE ONAYA GÖNDER
                  </button>
               </div>
               <button onClick={() => setStep(1)} className="w-full py-4 text-gray-500 font-black uppercase text-[9px] tracking-[0.3em] flex items-center justify-center hover:text-[var(--text-main)] transition-colors">
                  <ChevronLeft size={16} className="mr-2" /> GERİ DÖN
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default NewRequest;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi/Teklif değiştirildi: ${chosen?.sourceName}`);
  };

  const undoApproval = (roleName: string) => {
    if (!confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya 'Bekliyor' durumuna düşecek ve bu adımın tüm verileri (not, imza vb.) sıfırlanacaktır.`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending'
    }, `${roleName} onayı yönetici tarafından GERİ ÇEKİLDİ.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} onayı verildi. ${decisionNote ? `Not: ${decisionNote}` : ''}`);

    setShowApprovalModal(null);
    setDecisionNote('');
    setIsSignedApproval(false);
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        executeApproval(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const openLateProofPicker = (role: string) => {
    setTargetRoleForLateProof(role);
    setTimeout(() => {
      lateProofInputRef.current?.click();
    }, 100);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => {
          if (f.role === targetRoleForLateProof) {
            return { 
              ...f, 
              proofUrl: reader.result as string, 
              type: 'Signed' as const,
              status: 'Approved' as const,
              date: f.date || new Date().toISOString() 
            };
          }
          return f;
        });
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} onayı için görsel kanıt güncellendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { 
          invoices: [...currentInvoices, reader.result as string] 
        }, `Yeni fatura eklendi.`);
      };
      reader.readAsDataURL(file);
      e.target.value = '';
    }
  };

  const removeInvoice = (idx: number) => {
    if (!confirm("Belge silinsin mi?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Fatura silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {/* Lightbox */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" alt="Full" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {/* Print View */}
      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">
                    Kapat
                 </button>
              </div>
              <div className="p-4 sm:p-10">
                <OfficialForm transaction={transaction} />
              </div>
           </div>
        </div>
      )}

      {/* Approval Modal */}
      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-6 sm:p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Karar notunuzu ekleyebilirsiniz</p>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest ml-1">KARAR NOTU</label>
                <textarea 
                  value={decisionNote}
                  onChange={e => setDecisionNote(e.target.value)}
                  placeholder="Bu onay/red ile ilgili notunuzu yazın..."
                  className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none shadow-inner focus:border-red-600/50"
                />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="flex items-center justify-between p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">
                   HIZLI DİJİTAL ONAY <Zap size={20} />
                </button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="flex items-center justify-between p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">
                   ISLAK İMZA YÜKLE <Signature size={20} />
                </button>
                <input type="file" id="sig-input" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      {/* Header Controls */}
      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button onClick={() => { if(confirm('Bu dosya silinsin mi?')) onDelete(transaction.id); }} className="p-3 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10">
              <Trash2 size={20} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg">
              <Printer size={16} className="text-red-600" />
              <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black border border-red-600/20">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">İSTENEN BİRİM/KİŞİ: {transaction.usageLocation || 'Belirtilmemiş'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 flex flex-col items-center lg:items-end justify-center">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA BEDELİ</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

             {/* ONAY ZİNCİRİ - SOL KOLON */}
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY SÜRECİ & KANITLAR
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        {/* TEXT TABANLI GERİ ÇEK BUTONU */}
                                        <button 
                                          onClick={() => undoApproval(flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button onClick={() => openLateProofPicker(flow.role)} className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all">
                                           <ImagePlus size={16} />
                                        </button>
                                     </>
                                   ) : (
                                     <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg hover:bg-red-500 transition-all">ONAYLA</button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                             {flow.status === 'Approved' && (
                                <div className="flex items-center space-x-2 mt-1">
                                   <span className="text-[8px] font-black text-red-600 uppercase tracking-tighter">{flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL ONAY'}</span>
                                   <span className="text-[8px] text-gray-600">•</span>
                                   <span className="text-[8px] font-black text-gray-600 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')}</span>
                                </div>
                             )}
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity">
                                  <Eye size={16} className="text-white" />
                               </div>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Karar Notu Balonu */}
                      {flow.status === 'Approved' && flow.decisionNote && (
                        <div className="ml-16 p-4 bg-white/5 border border-white/10 rounded-2xl relative animate-in slide-in-from-top-2">
                           <div className="absolute -top-2 left-6 w-3 h-3 bg-[var(--bg-input)] border-t border-l border-white/10 rotate-45"></div>
                           <div className="flex items-start space-x-3">
                              <MessageSquare size={14} className="text-red-600 mt-0.5 shrink-0" />
                              <p className="text-[10px] text-[var(--text-muted)] italic leading-relaxed">"{flow.decisionNote}"</p>
                           </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             {/* TEKLİFLER VE BELGELER - SAĞ KOLON */}
             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> TEDARİKÇİ & TEKLİFLER
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all cursor-pointer group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE & DOSYA HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-lg hover:bg-red-500 transition-all">
                        DOSYA YÜKLE
                      </button>
                   </div>

                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices && transaction.invoices.length > 0 ? (
                        transaction.invoices.map((inv, idx) => (
                           <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 transition-all cursor-pointer">
                              <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                                 <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 transition-transform"><Eye size={18} /></button>
                                 <button onClick={() => removeInvoice(idx)} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 transition-transform"><Trash2 size={18} /></button>
                              </div>
                           </div>
                        ))
                      ) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-600" />
                           <p className="text-[10px] font-black uppercase text-gray-500">Henüz belge eklenmedi</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="p-8 bg-[var(--bg-input)] rounded-[35px] border border-[var(--border-grey)]">
                   <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.3em] mb-4 flex items-center"><Info size={16} className="mr-3" /> TALEP GEREKÇESİ</p>
                   <p className="text-[var(--text-muted)] text-[11px] italic leading-relaxed">"{transaction.justification}"</p>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1">Dosyayı nihai statüsüne çekin.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`flex-1 sm:flex-none px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white' : 'bg-red-600 text-white hover:bg-red-500'}`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALIM TAMAMLANDI' : 'SATIN ALIMI BİTİR'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="flex-1 sm:flex-none px-8 py-5 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-[25px] font-black uppercase text-[11px] hover:bg-white hover:text-black transition-all">ERTELE</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo } from 'react';
import { Search, Heart, Trash2 } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi v2 Premium aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Durum çeviri haritası
  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  useEffect(() => {
    setIsTransitioning(true);
    const timer = setTimeout(() => {
      setIsTransitioning(false);
    }, 1000);
    return () => clearTimeout(timer);
  }, [activeTab, selectedTransactionId]);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  };

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    const trx = state.transactions.find(t => t.id === id);
    if (!trx) return;

    const actionText = statusLabels[newStatus] || newStatus;

    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const newLog = { 
            id: `log-${Date.now()}`, 
            timestamp: new Date().toISOString(), 
            user: state.user?.name || 'Sistem', 
            action: 'Statü Güncelleme', 
            details: `${statusLabels[t.status]} -> ${actionText}` 
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      })
    }));

    addSystemLog('PURCHASE', 'Statü Değişimi', `#${id} nolu dosya ${actionText} durumuna çekildi.`);

    if (newStatus === 'Purchased' || newStatus === 'Approved') {
        setStatusFilter(newStatus);
        setActiveTab('transactions');
        setSelectedTransactionId(null);
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (logMessage) {
            const newLog = { 
              id: `log-${Date.now()}`, 
              timestamp: new Date().toISOString(), 
              user: state.user?.name || 'Sistem', 
              action: 'Veri Müdahalesi', 
              details: logMessage 
            };
            updated.logs = [newLog, ...updated.logs];
          }
          return updated;
        }
        return t;
      })
    }));
    if (logMessage) addSystemLog('PURCHASE', 'Müdahale', `#${id}: ${logMessage}`);
  };

  const deleteTransaction = (id: string) => {
    const trx = state.transactions.find(t => t.id === id);
    setState(prev => ({ ...prev, transactions: prev.transactions.filter(t => t.id !== id) }));
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Veri İmhası', `#${id} (${trx?.productSetName}) sistemden kalıcı olarak silindi.`);
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `Kullanıcı girişi: ${user.name}`);
  };

  const handleLogout = () => {
    addSystemLog('AUTH', 'Oturum Kapatıldı', `Kullanıcı çıkışı: ${state.user?.name}`);
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
    setStatusFilter(null);
    setSearchQuery('');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTransaction: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Batuhan Yontuç',
      requestDateTime: request.requestDateTime || new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || request.packageQuantity || 1,
      unitPrice: request.unitPrice || request.packageUnitPrice || 0,
      packageQuantity: request.packageQuantity || 1,
      packageUnitPrice: request.packageUnitPrice || 0,
      totalAmount: request.totalAmount || (request.packageQuantity || 1) * (request.packageUnitPrice || 0),
      description: request.description || '',
      justification: request.justification || '',
      generalNotes: request.generalNotes || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl, 
      publicTrackKey: request.publicTrackKey,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: [{ id: 'init', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep sisteme kaydedildi.' }],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTransaction, ...prev.transactions] }));
    addSystemLog('PURCHASE', 'Talep Başlatıldı', `${newTransaction.id} nolu yeni talep oluşturuldu.`);
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) ||
        t.supplierName.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        t.microCode.toLowerCase().includes(q)
      );
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={handleLogin} />;

  const selectedTransaction = state.transactions.find(t => t.id === selectedTransactionId);

  return (
    <>
      {isTransitioning && (
        <div className="heart-overlay-container">
          <div className="relative w-32 h-32 flex items-center justify-center">
             <Heart className="absolute text-red-600/10 w-full h-full" strokeWidth={1} />
             <div className="absolute bottom-0 left-0 w-full overflow-hidden animate-heart-fill">
                <Heart className="text-red-600 fill-red-600 w-32 h-32" strokeWidth={0} />
             </div>
          </div>
        </div>
      )}

      <Layout 
        activeTab={activeTab} 
        setActiveTab={(tab) => { 
          setActiveTab(tab); 
          setSelectedTransactionId(null); 
          if (tab !== 'transactions') setStatusFilter(null); 
        }} 
        user={state.user} 
        onLogout={handleLogout}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      >
        {selectedTransaction ? (
          <TransactionDetail transaction={selectedTransaction} onBack={() => setSelectedTransactionId(null)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} onUpdate={handleUpdate} currentUserRole={state.user.role} />
        ) : (
          <>
            {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onFilterClick={(status) => { setStatusFilter(status); setActiveTab('transactions'); }} />}
            {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(name) => setState(prev => ({ ...prev, departments: [...prev.departments, name] }))} onBack={() => setActiveTab('dashboard')} />}
            {activeTab === 'reports' && <Reports transactions={state.transactions} />}
            {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
            {activeTab === 'transactions' && (
              <div className="space-y-12 animate-in fade-in duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                  <div>
                      <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                      <p className="text-violet-400 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? `${statusLabels[statusFilter] || statusFilter} Durumundaki Kayıtlar` : 'Tüm Satın Alma Dosyaları'}</p>
                  </div>
                  <div className="flex flex-wrap bg-violet-950/20 p-2 rounded-2xl border border-violet-500/10 gap-1">
                    <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-violet-600 text-white shadow-xl neon-glow-violet' : 'text-violet-500 hover:bg-violet-500/10'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                    <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl neon-glow-cyan' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLANDI</button>
                    <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl neon-glow-green' : 'text-green-500 hover:bg-green-500/10'}`}>SATIN ALINDI</button>
                    <button onClick={() => setStatusFilter('On Hold')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'On Hold' ? 'bg-gray-600 text-white shadow-xl' : 'text-gray-500 hover:bg-gray-500/10'}`}>ERTELENEN</button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className={`cyber-card glass-panel p-10 rounded-[45px] border border-violet-500/10 cursor-pointer relative overflow-hidden group transition-all ${t.status === 'Rejected' ? 'grayscale opacity-60' : ''}`}>
                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className={`w-16 h-16 neon-gradient-premium rounded-2xl flex items-center justify-center font-black text-white shadow-xl text-xl ${t.status === 'On Hold' ? 'grayscale' : ''}`}>{t.requesterName ? t.requesterName.charAt(0) : 'A'}</div>
                        <div className="flex flex-col items-end space-y-2">
                          <span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase border ${
                            t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                            t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                            'bg-violet-500/10 text-violet-400 border-violet-500/20'
                          }`}>{statusLabels[t.status] || t.status}</span>

                          {/* Hızlı Silme/İptal Butonu */}
                          <button 
                            onClick={(e) => {
                              e.stopPropagation();
                              if(confirm('Bu talebi iptal etmek ve sistemden silmek istediğinize emin misiniz?')) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-2 bg-red-600/10 text-red-600 rounded-lg border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-lg"
                            title="Talebi İptal Et / Sil"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>
                      <h3 className="text-2xl font-black text-white uppercase truncate mb-1 group-hover:neon-text-premium transition-all">{t.productSetName}</h3>
                      <p className="text-[10px] text-violet-500 font-bold uppercase tracking-widest opacity-60 mb-1">{t.department} • {t.supplierName}</p>
                      <div className="flex justify-between items-end border-t border-violet-500/10 pt-8 mt-4">
                         <div>
                            <p className="text-[9px] text-violet-700 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                            <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-violet-500">#{t.id}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(prev => ({ ...prev, roles: r }))} departments={state.departments} setDepartments={(d) => setState(prev => ({ ...prev, departments: d }))} user={state.user} onUpdateUser={(n) => setState(prev => ({ ...prev, user: { ...prev.user!, name: n } }))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={(id) => setSelectedTransactionId(id)} />}
          </>
        )}
      </Layout>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, PlusCircle, Settings, LogOut, ShoppingBag,
  Bell, Search, Moon, Sun, BarChart3, Archive as ArchiveIcon,
  ShieldCheck, Menu, X
} from 'lucide-react';
import { User } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  user: User | null;
  onLogout: () => void;
  searchQuery: string;
  setSearchQuery: (setQuery: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, user, onLogout, searchQuery, setSearchQuery }) => {
  const [theme, setTheme] = useState<'dark' | 'light'>(
    (localStorage.getItem('theme') as any) || 'dark'
  );
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    if (theme === 'light') {
      document.body.classList.add('light-mode');
    } else {
      document.body.classList.remove('light-mode');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const menuItems = [
    { id: 'dashboard', label: 'Komuta', icon: <LayoutDashboard size={20} /> },
    { id: 'new-request', label: 'Yeni', icon: <PlusCircle size={24} /> },
    { id: 'transactions', label: 'Süreç', icon: <ShoppingBag size={20} /> },
