        <div className="p-8 border-t border-[var(--border-grey)]">
          <button onClick={onLogout} className="w-full flex items-center justify-center space-x-3 px-5 py-4 text-red-600 border border-red-600/20 rounded-2xl font-black text-[9px] uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all">
            <LogOut size={16} />
            <span>ÇIKIŞ YAP</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 lg:h-24 border-b border-[var(--border-grey)] flex items-center justify-between px-4 lg:px-12 bg-[var(--bg-panel)]/80 backdrop-blur-3xl sticky top-0 z-30">
          <div className="flex lg:hidden items-center">
             <img src={LOGO_URL} alt="Yaşam Logo" className="h-8 object-contain" />
          </div>

          <div className="flex items-center flex-1 max-w-lg mx-4 lg:mx-0">
            <div className="relative w-full group">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[var(--text-muted)] group-focus-within:text-red-600 transition-colors" size={16} />
              <input 
                type="text" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Evrak Ara..." 
                className="w-full rounded-xl py-3 pl-12 pr-4 text-xs bg-[var(--bg-input)]"
              />
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <button 
              onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}
              className="p-3 rounded-xl bg-[var(--bg-input)] border border-[var(--border-grey)] text-[var(--text-muted)] hover:border-red-600 transition-colors"
            >
              {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
