  const LOGO_URL = "https://www.tekirdagyasam.com/wp-content/uploads/2021/05/yasam-logo-1.png";

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[var(--bg-deep)]">
