        <nav className="flex-1 px-6 space-y-2 mt-2">
          {menuItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-4 px-5 py-4 rounded-2xl transition-all duration-300 ${
                activeTab === item.id 
                  ? 'bg-red-600 text-white shadow-lg' 
                  : 'text-[var(--text-muted)] hover:text-[var(--text-main)] hover:bg-white/5'
              }`}
            >
              <span>{item.icon}</span>
              <span className="font-bold text-[10px] tracking-widest uppercase">{item.label}</span>
            </button>
          ))}
          <button
              onClick={() => setActiveTab('settings')}
              className={`w-full flex items-center space-x-4 px-5 py-4 rounded-2xl transition-all ${
                activeTab === 'settings' ? 'bg-red-600 text-white shadow-lg' : 'text-[var(--text-muted)] hover:text-[var(--text-main)]'
              }`}
            >
              <Settings size={20} />
              <span className="font-bold text-[10px] tracking-widest uppercase">Ayarlar</span>
            </button>
