    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Package, Image as ImageIcon } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi v2 Premium aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTransitioning, setIsTransitioning] = useState(false);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  useEffect(() => {
    setIsTransitioning(true);
    const timer = setTimeout(() => {
      setIsTransitioning(false);
    }, 800);
    return () => clearTimeout(timer);
  }, [activeTab, selectedTransactionId]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  }, [state.user]);

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => {
      const updatedTransactions = prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = statusLabels[newStatus] || newStatus;
          const newLog = { 
            id: `log-${Date.now()}`, 
            timestamp: new Date().toISOString(), 
            user: prev.user?.name || 'Sistem', 
            action: 'Durum Değişikliği', 
            details: `${statusLabels[t.status]} -> ${actionText}` 
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      });
      return { ...prev, transactions: updatedTransactions };
    });

    addSystemLog('PURCHASE', 'Statü Güncellendi', `#${id} dosyası ${statusLabels[newStatus]} statüsüne çekildi.`);
    if (newStatus === 'Purchased') {
      setStatusFilter('Purchased');
      setActiveTab('transactions');
      setSelectedTransactionId(null);
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => {
      const updatedTransactions = prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (logMessage) {
            const newLog = { 
              id: `log-${Date.now()}`, 
              timestamp: new Date().toISOString(), 
              user: prev.user?.name || 'Sistem', 
              action: 'Güncelleme', 
              details: logMessage 
            };
            updated.logs = [newLog, ...updated.logs];
          }
          return updated;
        }
        return t;
      });
      return { ...prev, transactions: updatedTransactions };
    });
  };

  const deleteTransaction = (id: string) => {
    setState(prev => ({ 
      ...prev, 
      transactions: prev.transactions.filter(t => t.id !== id) 
    }));
    if (selectedTransactionId === id) setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Talep İptali', `#${id} nolu kayıt sistemden kaldırıldı.`);
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `${user.name} giriş yaptı.`);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTrx: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: [{ id: 'init', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep girildi.' }],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) || 
        t.id.toLowerCase().includes(q)
      );
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <>
      {isTransitioning && (
        <div className="heart-overlay-container">
          <div className="relative w-32 h-32 flex items-center justify-center">
             <Heart className="absolute text-red-600/10 w-full h-full" strokeWidth={1} />
             <div className="absolute bottom-0 left-0 w-full overflow-hidden animate-heart-fill">
                <Heart className="text-red-600 fill-red-600 w-32 h-32" strokeWidth={0} />
             </div>
          </div>
        </div>
      )}

      <Layout 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} 
        user={state.user} 
        onLogout={handleLogout}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      >
        {selectedTransactionId ? (
          <TransactionDetail 
            transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
            onBack={() => setSelectedTransactionId(null)} 
            onStatusChange={handleStatusChange} 
            onDelete={deleteTransaction} 
            onUpdate={handleUpdate} 
            currentUserRole={state.user.role} 
          />
        ) : (
          <>
            {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={(s) => { setStatusFilter(s); setActiveTab('transactions'); }} />}
            {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} onBack={() => setActiveTab('dashboard')} />}
            {activeTab === 'transactions' && (
              <div className="space-y-12 animate-in fade-in duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                  <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                  </div>
                  <div className="flex flex-wrap bg-white/5 p-2 rounded-2xl border border-white/5 gap-1">
                    <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-red-600 text-white' : 'text-gray-500 hover:bg-white/5'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                    <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                    <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white' : 'text-green-500 hover:bg-green-500/10'}`}>ALINDI</button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group">
                      <div className="flex justify-between items-start mb-6 relative z-10">
                        <div className="flex flex-col items-center">
                           <span className="text-[8px] font-black text-gray-500 uppercase mb-2 tracking-tighter flex items-center">
                             <CalendarDays size={10} className="mr-1 text-red-600" />
                             {new Date(t.requestDateTime).toLocaleDateString('tr-TR')}
                           </span>
                           <div className="w-16 h-16 bg-red-600/10 rounded-2xl flex items-center justify-center font-black text-white shadow-xl overflow-hidden border border-white/5">
                             {t.photoUrl ? (
                               <img src={t.photoUrl} alt={t.productSetName} className="w-full h-full object-cover" />
                             ) : (
                               <div className="w-full h-full bg-gradient-to-br from-red-600 to-red-900 flex items-center justify-center text-2xl">
                                  {t.requesterName.charAt(0)}
                               </div>
                             )}
                           </div>
                        </div>

                        <div className="flex flex-col items-end space-y-3">
                          <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase border ${
                            t.status === 'Purchased' ? 'bg-green-500/10 text-green-400 border-green-500/20' : 
                            t.status === 'Approved' ? 'bg-cyan-500/10 text-cyan-400 border-cyan-500/20' :
                            'bg-red-600/10 text-red-400 border-red-600/20'
                          }`}>{statusLabels[t.status]}</span>

                          <button 
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              if(window.confirm('DİKKAT! Bu işlem geri alınamaz. Bu talebi silmek istediğinize emin misiniz?')) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-3 bg-red-600/10 text-red-600 rounded-xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-lg active:scale-90"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>

                      <h3 className="text-xl font-black text-white uppercase truncate mb-1 group-hover:text-red-600 transition-all">{t.productSetName}</h3>
                      <p className="text-[9px] text-gray-500 font-bold uppercase tracking-widest mb-1">{t.department}</p>

                      <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-4">
                         <div>
                            <p className="text-[8px] text-red-900 font-black uppercase tracking-widest mb-1">Dosya Bedeli</p>
                            <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[9px] font-mono text-gray-700 tracking-tighter">#{t.id}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {activeTab === 'reports' && <Reports transactions={state.transactions} />}
            {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
            {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
          </>
        )}
      </Layout>
    </>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi Değiştirildi: ${chosen?.sourceName}`);
  };

  /**
   * Onay Geri Çekme Fonksiyonu - KESİN FIX
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`DİKKAT: ${roleName} onayını geri çekmek üzeresiniz. Bu işlem onay verilerini temizleyecek ve dosyayı 'BEKLİYOR' statüsüne çekecektir. Devam edilsin mi?`)) return;

    // Onay akışını güncelle
    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    // Parent component'e güncellemeyi gönder
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya bekleme listesine alındı.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} tarafından onay verildi.`);

    setShowApprovalModal(null);
    setDecisionNote('');
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => executeApproval(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { invoices: [...currentInvoices, reader.result as string] }, `Dosyaya yeni belge eklendi.`);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (e: React.MouseEvent, idx: number) => {
    e.preventDefault();
    e.stopPropagation();
    if (!window.confirm("Bu belgeyi sistemden kalıcı olarak silmek istiyor musunuz?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Belge kullanıcı tarafından silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">Kapat</button>
              </div>
              <div className="p-4 sm:p-10"><OfficialForm transaction={transaction} /></div>
           </div>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Süreci ilerletmek için onay verin</p>
              </div>
              <textarea 
                value={decisionNote}
                onChange={e => setDecisionNote(e.target.value)}
                placeholder="Notunuzu ekleyebilirsiniz..."
                className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none"
              />
              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500">HIZLI ONAY <Zap size={16} className="inline ml-2"/></button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={(e) => {
        const file = e.target.files?.[0];
        if (file && targetRoleForLateProof) {
          const reader = new FileReader();
          reader.onloadend = () => {
            const newFlow = transaction.approvalFlow.map(f => (f.role === targetRoleForLateProof ? { ...f, proofUrl: reader.result as string, type: 'Signed' as const, status: 'Approved' as const, date: f.date || new Date().toISOString() } : f));
            onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi güncellendi.`);
            setTargetRoleForLateProof(null);
          };
          reader.readAsDataURL(file);
        }
      }} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button onClick={() => { if(window.confirm('Dosyayı silmek istediğinize emin misiniz?')) onDelete(transaction.id); }} className="p-3 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90"><Trash2 size={20} /></button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg"><Printer size={16} className="text-red-600" /><span>RESMİ FORM</span></button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Belirtilmedi'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">TOPLAM BEDEL</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">{statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY SÜRECİ & KANITLAR
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        <button 
                                          onClick={(e) => undoApproval(e, flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 active:scale-95 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button onClick={() => { setTargetRoleForLateProof(flow.role); setTimeout(() => lateProofInputRef.current?.click(), 100); }} className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all">
                                           <ImagePlus size={16} />
                                        </button>
                                     </>
                                   ) : (
                                     <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg active:scale-95 transition-all">ONAYLA</button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                             {flow.status === 'Approved' && (
                                <div className="flex items-center space-x-2 mt-1">
                                   <span className="text-[8px] font-black text-red-600 uppercase tracking-tighter">{flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL ONAY'}</span>
                                   <span className="text-[8px] text-gray-600">•</span>
                                   <span className="text-[8px] font-black text-gray-600 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')}</span>
                                </div>
                             )}
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity"><Eye size={16} className="text-white" /></div>
                            </div>
                          )}
                        </div>
                      </div>
                      {flow.status === 'Approved' && flow.decisionNote && (
                        <div className="ml-16 p-4 bg-white/5 border border-white/10 rounded-2xl relative animate-in slide-in-from-top-2">
                           <div className="absolute -top-2 left-6 w-3 h-3 bg-[var(--bg-input)] border-t border-l border-white/10 rotate-45"></div>
                           <div className="flex items-start space-x-3">
                              <MessageSquare size={14} className="text-red-600 mt-0.5 shrink-0" />
                              <p className="text-[10px] text-[var(--text-muted)] italic leading-relaxed">"{flow.decisionNote}"</p>
                           </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> SEÇİLEN TEDARİKÇİ
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all cursor-pointer group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase active:scale-95 transition-all">BELGE YÜKLE</button>
                </div>
                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices?.length ? transaction.invoices.map((inv, idx) => (
                         <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 cursor-pointer">
                            <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                               <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110"><Eye size={18} /></button>
                               <button onClick={(e) => removeInvoice(e, idx)} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110"><Trash2 size={18} /></button>
                            </div>
                         </div>
                      )) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-900" /><p className="text-[10px] font-black uppercase text-gray-500">BELGE BULUNMUYOR</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="p-8 bg-[var(--bg-input)] rounded-[35px] border border-[var(--border-grey)]">
                   <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.3em] mb-4 flex items-center"><Info size={16} className="mr-3" /> TALEP GEREKÇESİ</p>
                   <p className="text-[var(--text-muted)] text-[11px] italic leading-relaxed">"{transaction.justification}"</p>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1">Dosya sonucunu nihai aşamaya taşıyın.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white' : 'bg-red-600 text-white hover:bg-red-500'}`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALINDI' : 'SATIN ALIMI TAMAMLA'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-8 py-5 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-[25px] font-black uppercase text-[11px] active:scale-95 transition-all">ERTELENSİN</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    user: null,
    transactions: MOCK_TRANSACTIONS,
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: [
      { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'Süreç Yönetim Sistemi v2 Premium aktif edildi.' }
    ]
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTransitioning, setIsTransitioning] = useState(false);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  useEffect(() => {
    setIsTransitioning(true);
    const timer = setTimeout(() => {
      setIsTransitioning(false);
    }, 800);
    return () => clearTimeout(timer);
  }, [activeTab, selectedTransactionId]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  }, [state.user]);

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => {
      const updatedTransactions = prev.transactions.map(t => {
        if (t.id === id) {
          const actionText = statusLabels[newStatus] || newStatus;
          const newLog = { 
            id: `log-${Date.now()}`, 
            timestamp: new Date().toISOString(), 
            user: prev.user?.name || 'Sistem', 
            action: 'Durum Değişikliği', 
            details: `${statusLabels[t.status]} -> ${actionText}` 
          };
          return { ...t, status: newStatus, logs: [newLog, ...t.logs] };
        }
        return t;
      });
      return { ...prev, transactions: updatedTransactions };
    });

    addSystemLog('PURCHASE', 'Statü Güncellendi', `#${id} dosyası ${statusLabels[newStatus]} statüsüne çekildi.`);
    if (newStatus === 'Purchased') {
      setStatusFilter('Purchased');
      setActiveTab('transactions');
      setSelectedTransactionId(null);
    }
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => {
      const updatedTransactions = prev.transactions.map(t => {
        if (t.id === id) {
          const updated = { ...t, ...updates };
          if (logMessage) {
            const newLog = { 
              id: `log-${Date.now()}`, 
              timestamp: new Date().toISOString(), 
              user: prev.user?.name || 'Sistem', 
              action: 'Güncelleme', 
              details: logMessage 
            };
            updated.logs = [newLog, ...updated.logs];
          }
          return updated;
        }
        return t;
      });
      return { ...prev, transactions: updatedTransactions };
    });
  };

  const deleteTransaction = (id: string) => {
    setState(prev => {
      const isSelected = selectedTransactionId === id;
      if (isSelected) setSelectedTransactionId(null);
      return { 
        ...prev, 
        transactions: prev.transactions.filter(t => t.id !== id) 
      };
    });
    addSystemLog('PURCHASE', 'Kayıt İmhası', `#${id} nolu kayıt sistemden kalıcı olarak silindi.`);
  };

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, user }));
    addSystemLog('AUTH', 'Oturum Açıldı', `${user.name} giriş yaptı.`);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, user: null }));
    setActiveTab('dashboard');
  };

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTrx: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: [{ id: 'init', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep girildi.' }],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => 
        t.productSetName.toLowerCase().includes(q) || 
        t.id.toLowerCase().includes(q)
      );
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <>
      {isTransitioning && (
        <div className="heart-overlay-container">
          <div className="relative w-32 h-32 flex items-center justify-center">
             <Heart className="absolute text-red-600/10 w-full h-full" strokeWidth={1} />
             <div className="absolute bottom-0 left-0 w-full overflow-hidden animate-heart-fill">
                <Heart className="text-red-600 fill-red-600 w-32 h-32" strokeWidth={0} />
             </div>
          </div>
        </div>
      )}

      <Layout 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} 
        user={state.user} 
        onLogout={handleLogout}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      >
        {selectedTransactionId ? (
          <TransactionDetail 
            transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
            onBack={() => setSelectedTransactionId(null)} 
            onStatusChange={handleStatusChange} 
            onDelete={deleteTransaction} 
            onUpdate={handleUpdate} 
            currentUserRole={state.user.role} 
          />
        ) : (
          <>
            {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={(s) => { setStatusFilter(s); setActiveTab('transactions'); }} />}
            {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} onBack={() => setActiveTab('dashboard')} />}
            {activeTab === 'transactions' && (
              <div className="space-y-12 animate-in fade-in duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                  <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                  </div>
                  <div className="flex flex-wrap bg-white/5 p-2 rounded-2xl border border-white/5 gap-1">
                    <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                    <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                    <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white' : 'text-green-500 hover:bg-green-500/10'}`}>ALINDI</button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id} 
                      onClick={() => setSelectedTransactionId(t.id)} 
                      className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group transition-all"
                    >
                      <div className="flex justify-between items-start mb-6 relative z-10">
                        {/* Sol Üst: Tarih ve Ürün Görseli */}
                        <div className="flex flex-col">
                           <div className="flex items-center space-x-1 mb-2">
                             <CalendarDays size={11} className="text-red-600" />
                             <span className="text-[9px] font-black text-gray-500 uppercase tracking-tighter">
                               {new Date(t.requestDateTime).toLocaleDateString('tr-TR')}
                             </span>
                           </div>
                           <div className="w-20 h-20 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500">
                             {t.photoUrl ? (
                               <img src={t.photoUrl} alt={t.productSetName} className="w-full h-full object-cover" />
                             ) : (
                               <div className="flex flex-col items-center">
                                  <ImageIcon size={24} className="text-red-600/40 mb-1" />
                                  <span className="text-xl font-black text-red-600">{t.requesterName.charAt(0)}</span>
                               </div>
                             )}
                           </div>
                        </div>

                        {/* Sağ Üst: Durum ve Silme */}
                        <div className="flex flex-col items-end space-y-3">
                          <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border tracking-widest ${
                            t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20 shadow-[0_0_15px_rgba(22,163,74,0.2)]' : 
                            t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20 shadow-[0_0_15px_rgba(8,145,178,0.2)]' :
                            'bg-red-600/10 text-red-400 border-red-600/20'
                          }`}>{statusLabels[t.status]}</span>

                          <button 
                            type="button"
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              if(window.confirm('BU İŞLEM GERİ ALINAMAZ! Bu talebi kalıcı olarak silip/iptal etmek istediğinize emin misiniz?')) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-3.5 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90"
                            title="Talebi İptal Et / Sil"
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      </div>

                      {/* Bilgiler */}
                      <div className="space-y-1">
                        <h3 className="text-xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors duration-300">{t.productSetName}</h3>
                        <p className="text-[10px] text-gray-500 font-bold uppercase tracking-[0.2em]">{t.department}</p>
                      </div>

                      <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                         <div className="space-y-0.5">
                            <p className="text-[9px] text-red-950 font-black uppercase tracking-widest opacity-60">DOSYA TUTARI</p>
                            <p className="text-2xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <div className="text-right">
                            <p className="text-[9px] font-mono text-gray-700 font-bold uppercase tracking-widest">#{t.id}</p>
                         </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {activeTab === 'reports' && <Reports transactions={state.transactions} />}
            {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
            {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
          </>
        )}
      </Layout>
    </>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi Değiştirildi: ${chosen?.sourceName}`);
  };

  /**
   * Onay Geri Çekme Fonksiyonu - KESİN FIX
   * Statüleri temizler ve dosyayı BEKLİYOR moduna geri döndürür.
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`DİKKAT: ${roleName} onayını geri çekmek üzeresiniz. Onay verileri silinecek ve süreç 'BEKLİYOR' statüsüne dönecektir. Onaylıyor musunuz?`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya yeniden incelemeye alındı.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} tarafından onay verildi.`);

    setShowApprovalModal(null);
    setDecisionNote('');
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => executeApproval(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { invoices: [...currentInvoices, reader.result as string] }, `Dosyaya yeni belge eklendi.`);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (e: React.MouseEvent, idx: number) => {
    e.preventDefault();
    e.stopPropagation();
    if (!window.confirm("Bu belgeyi sistemden kalıcı olarak silmek istiyor musunuz?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Belge kullanıcı tarafından silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">Kapat</button>
              </div>
              <div className="p-4 sm:p-10"><OfficialForm transaction={transaction} /></div>
           </div>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Süreci ilerletmek için onay verin</p>
              </div>
              <textarea 
                value={decisionNote}
                onChange={e => setDecisionNote(e.target.value)}
                placeholder="Notunuzu ekleyebilirsiniz..."
                className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none focus:border-red-600/50"
              />
              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">HIZLI ONAY <Zap size={16} className="inline ml-2"/></button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={(e) => {
        const file = e.target.files?.[0];
        if (file && targetRoleForLateProof) {
          const reader = new FileReader();
          reader.onloadend = () => {
            const newFlow = transaction.approvalFlow.map(f => (f.role === targetRoleForLateProof ? { ...f, proofUrl: reader.result as string, type: 'Signed' as const, status: 'Approved' as const, date: f.date || new Date().toISOString() } : f));
            onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi güncellendi.`);
            setTargetRoleForLateProof(null);
          };
          reader.readAsDataURL(file);
        }
      }} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button 
             onClick={() => { if(window.confirm('BU KAYDI TAMAMEN SİLMEK İSTİYOR MUSUNUZ? Bu işlem geri alınamaz.')) onDelete(transaction.id); }} 
             className="p-3 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90 shadow-md hover:bg-red-600 hover:text-white transition-all"
           >
              <Trash2 size={20} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg hover:border-red-600 transition-all">
              <Printer size={16} className="text-red-600" />
              <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Belirtilmedi'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">TOPLAM BEDEL</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">DURUM: {statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY SÜRECİ & KANITLAR
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        <button 
                                          onClick={(e) => undoApproval(e, flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 active:scale-95 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button onClick={() => { setTargetRoleForLateProof(flow.role); setTimeout(() => lateProofInputRef.current?.click(), 100); }} className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all shadow-sm">
                                           <ImagePlus size={16} />
                                        </button>
                                     </>
                                   ) : (
                                     <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg active:scale-95 transition-all">ONAYLA</button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                             {flow.status === 'Approved' && (
                                <div className="flex items-center space-x-2 mt-1">
                                   <span className="text-[8px] font-black text-red-600 uppercase tracking-tighter">{flow.type === 'Signed' ? 'ISLAK İMZALI' : 'DİJİTAL ONAY'}</span>
                                   <span className="text-[8px] text-gray-600">•</span>
                                   <span className="text-[8px] font-black text-gray-600 uppercase">{new Date(flow.date!).toLocaleDateString('tr-TR')}</span>
                                </div>
                             )}
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity"><Eye size={16} className="text-white" /></div>
                            </div>
                          )}
                        </div>
                      </div>
                      {flow.status === 'Approved' && flow.decisionNote && (
                        <div className="ml-16 p-4 bg-white/5 border border-white/10 rounded-2xl relative animate-in slide-in-from-top-2">
                           <div className="absolute -top-2 left-6 w-3 h-3 bg-[var(--bg-input)] border-t border-l border-white/10 rotate-45"></div>
                           <div className="flex items-start space-x-3">
                              <MessageSquare size={14} className="text-red-600 mt-0.5 shrink-0" />
                              <p className="text-[10px] text-[var(--text-muted)] italic leading-relaxed">"{flow.decisionNote}"</p>
                           </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> SEÇİLEN TEDARİKÇİ
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all cursor-pointer group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase active:scale-95 transition-all hover:bg-red-500 shadow-md">BELGE YÜKLE</button>
                </div>
                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices?.length ? transaction.invoices.map((inv, idx) => (
                         <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 cursor-pointer transition-all">
                            <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                               <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 shadow-lg"><Eye size={18} /></button>
                               <button onClick={(e) => removeInvoice(e, idx)} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 shadow-lg"><Trash2 size={18} /></button>
                            </div>
                         </div>
                      )) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-900" /><p className="text-[10px] font-black uppercase text-gray-500 tracking-widest">BELGE BULUNMUYOR</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="p-8 bg-[var(--bg-input)] rounded-[35px] border border-[var(--border-grey)]">
                   <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.3em] mb-4 flex items-center"><Info size={16} className="mr-3" /> TALEP GEREKÇESİ</p>
                   <p className="text-[var(--text-muted)] text-[11px] italic leading-relaxed">"{transaction.justification}"</p>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM GÜNCELLE
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1 tracking-wider font-bold">Dosya sonucunu nihai aşamaya taşıyın.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white shadow-[0_0_20px_rgba(22,163,74,0.3)]' : 'bg-red-600 text-white hover:bg-red-500'}`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALINDI' : 'SATIN ALIMI TAMAMLA'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-8 py-5 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-[25px] font-black uppercase text-[11px] active:scale-95 transition-all hover:bg-white/5">ERTELENSİN</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import { Transaction, RoleDefinition } from './types';

export const INITIAL_ROLES: RoleDefinition[] = [
  { id: '1', roleName: "IT Manager", assignedName: "Murat Bilgin" },
  { id: '2', roleName: "CFO", assignedName: "Selin Aksoy" },
  { id: '3', roleName: "Coordinator", assignedName: "Caner Yıldız" },
  { id: '4', roleName: "General Manager", assignedName: "Batuhan Yontuç" }
];

export const INITIAL_DEPARTMENTS = [
  "Bilgi İşlem",
  "Pazarlama",
  "Finans",
  "Lojistik",
  "İnsan Kaynakları",
  "Teknik Servis",
  "Satınalma"
];

// Varsayılan veriler boşaltıldı
export const MOCK_TRANSACTIONS: Transaction[] = [];

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  // LocalStorage'dan veriyi yükle veya boş başlat
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('yasam_app_state');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        return {
          ...parsed,
          user: null // Giriş her seferinde yapılsın güvenlik için
        };
      } catch (e) {
        console.error("State loading error", e);
      }
    }
    return {
      user: null,
      transactions: MOCK_TRANSACTIONS,
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [
        { id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Başlatıldı', details: 'Sistem belleği aktif edildi.' }
      ]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTransitioning, setIsTransitioning] = useState(false);

  // State değiştikçe localStorage'a kaydet (Persistence)
  useEffect(() => {
    const { user, ...rest } = state;
    localStorage.setItem('yasam_app_state', JSON.stringify(rest));
  }, [state]);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  useEffect(() => {
    setIsTransitioning(true);
    const timer = setTimeout(() => setIsTransitioning(false), 800);
    return () => clearTimeout(timer);
  }, [activeTab, selectedTransactionId]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  }, [state.user]);

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => {
      const updated = prev.transactions.map(t => {
        if (t.id === id) {
          return { ...t, status: newStatus };
        }
        return t;
      });
      return { ...prev, transactions: updated };
    });
    addSystemLog('PURCHASE', 'Durum Güncellendi', `${id} dosyası ${statusLabels[newStatus]} yapıldı.`);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => {
      const updated = prev.transactions.map(t => (t.id === id ? { ...t, ...updates } : t));
      return { ...prev, transactions: updated };
    });
    if (logMessage) addSystemLog('PURCHASE', 'Bilgi Güncelleme', `${id}: ${logMessage}`);
  };

  const deleteTransaction = (id: string) => {
    setState(prev => {
      const filtered = prev.transactions.filter(t => t.id !== id);
      return { ...prev, transactions: filtered };
    });
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt Silindi', `${id} nolu talep imha edildi.`);
  };

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => setState(prev => ({ ...prev, user: null }));

  const handleNewRequest = (request: Partial<Transaction>) => {
    const approvalFlow = state.roles.map(r => ({
      role: r.roleName,
      status: 'Pending' as const,
      approverName: r.assignedName
    }));

    const newTrx: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: [{ id: 'init', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep oluşturuldu.' }],
      approvalFlow: request.approvalFlow || approvalFlow
    };

    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <>
      {isTransitioning && (
        <div className="heart-overlay-container">
          <div className="relative w-32 h-32 flex items-center justify-center">
             <Heart className="absolute text-red-600/10 w-full h-full" strokeWidth={1} />
             <div className="absolute bottom-0 left-0 w-full overflow-hidden animate-heart-fill">
                <Heart className="text-red-600 fill-red-600 w-32 h-32" strokeWidth={0} />
             </div>
          </div>
        </div>
      )}

      <Layout 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} 
        user={state.user} 
        onLogout={handleLogout}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      >
        {selectedTransactionId ? (
          <TransactionDetail 
            transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
            onBack={() => setSelectedTransactionId(null)} 
            onStatusChange={handleStatusChange} 
            onDelete={deleteTransaction} 
            onUpdate={handleUpdate} 
            currentUserRole={state.user.role} 
          />
        ) : (
          <>
            {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={(s) => { setStatusFilter(s); setActiveTab('transactions'); }} />}
            {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} onBack={() => setActiveTab('dashboard')} />}
            {activeTab === 'transactions' && (
              <div className="space-y-12 animate-in fade-in duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                  <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                  </div>
                  <div className="flex flex-wrap bg-white/5 p-2 rounded-2xl border border-white/5 gap-1">
                    <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                    <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                    <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl' : 'text-green-500 hover:bg-green-500/10'}`}>ALINDI</button>
                  </div>
                </div>

                {filteredTransactions.length === 0 ? (
                  <div className="py-32 text-center glass-panel rounded-[50px] border-dashed border-white/10 opacity-30">
                    <ImageIcon size={64} className="mx-auto mb-6 text-gray-800" />
                    <p className="text-sm font-black uppercase tracking-[0.4em]">Henüz bir talep bulunmuyor</p>
                    <button onClick={() => setActiveTab('new-request')} className="mt-8 px-8 py-4 bg-red-600 text-white rounded-2xl font-black uppercase text-[10px] shadow-2xl opacity-100">YENİ TALEP OLUŞTUR</button>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                    {filteredTransactions.map((t) => (
                      <div 
                        key={t.id} 
                        onClick={() => setSelectedTransactionId(t.id)} 
                        className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group transition-all"
                      >
                        <div className="flex justify-between items-start mb-6 relative z-10">
                          <div className="flex flex-col">
                             <div className="flex items-center space-x-1 mb-3">
                               <CalendarDays size={12} className="text-red-600" />
                               <span className="text-[10px] font-black text-gray-500 uppercase tracking-tighter">
                                 {new Date(t.requestDateTime).toLocaleDateString('tr-TR')}
                               </span>
                             </div>
                             <div className="w-24 h-24 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500 relative">
                               {t.photoUrl ? (
                                 <img src={t.photoUrl} alt={t.productSetName} className="w-full h-full object-cover" />
                               ) : (
                                 <div className="flex flex-col items-center">
                                    <ImageIcon size={28} className="text-red-600/30 mb-1" />
                                    <span className="text-2xl font-black text-red-600">{t.requesterName.charAt(0)}</span>
                                 </div>
                               )}
                             </div>
                          </div>

                          <div className="flex flex-col items-end space-y-3">
                            <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border tracking-widest ${
                              t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20 shadow-[0_0_15px_rgba(22,163,74,0.2)]' : 
                              t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20 shadow-[0_0_15px_rgba(8,145,178,0.2)]' :
                              'bg-red-600/10 text-red-400 border-red-600/20'
                            }`}>{statusLabels[t.status]}</span>

                            <button 
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                if(window.confirm('DİKKAT! Bu işlem geri alınamaz. Bu talebi kalıcı olarak silmek istediğinize emin misiniz?')) {
                                  deleteTransaction(t.id);
                                }
                              }}
                              className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90"
                              title="Sil"
                            >
                              <Trash2 size={20} />
                            </button>
                          </div>
                        </div>

                        <div className="space-y-1">
                          <h3 className="text-2xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors duration-300">{t.productSetName}</h3>
                          <p className="text-[11px] text-gray-500 font-bold uppercase tracking-[0.2em]">{t.department}</p>
                        </div>

                        <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                           <div className="space-y-1">
                              <p className="text-[10px] text-red-950 font-black uppercase tracking-widest opacity-60">TOPLAM TUTAR</p>
                              <p className="text-3xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                           </div>
                           <div className="text-right">
                              <p className="text-[10px] font-mono text-gray-700 font-bold uppercase tracking-widest">#{t.id}</p>
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
            {activeTab === 'reports' && <Reports transactions={state.transactions} />}
            {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
            {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
          </>
        )}
      </Layout>
    </>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi Değiştirildi: ${chosen?.sourceName}`);
  };

  /**
   * Onay Geri Çekme Fonksiyonu - KESİN FIX
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`DİKKAT: ${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya 'BEKLİYOR' durumuna geri alınacaktır.`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    // Dosyayı BEKLİYOR moduna çek ve flow'u güncelle
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya yeniden incelemeye alındı.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} tarafından onay verildi.`);

    setShowApprovalModal(null);
    setDecisionNote('');
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => executeApproval(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { invoices: [...currentInvoices, reader.result as string] }, `Belge eklendi.`);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (e: React.MouseEvent, idx: number) => {
    e.preventDefault();
    e.stopPropagation();
    if (!window.confirm("Bu belgeyi silmek istediğinize emin misiniz?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Belge silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">Kapat</button>
              </div>
              <div className="p-4 sm:p-10"><OfficialForm transaction={transaction} /></div>
           </div>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Onay notu veya açıklama ekleyin</p>
              </div>
              <textarea 
                value={decisionNote}
                onChange={e => setDecisionNote(e.target.value)}
                placeholder="Notunuz..."
                className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none"
              />
              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">DİJİTAL ONAY <Zap size={16} className="inline ml-2"/></button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={handleSignedFile} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={(e) => {
        const file = e.target.files?.[0];
        if (file && targetRoleForLateProof) {
          const reader = new FileReader();
          reader.onloadend = () => {
            const newFlow = transaction.approvalFlow.map(f => (f.role === targetRoleForLateProof ? { ...f, proofUrl: reader.result as string, type: 'Signed' as const, status: 'Approved' as const, date: f.date || new Date().toISOString() } : f));
            onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi güncellendi.`);
            setTargetRoleForLateProof(null);
          };
          reader.readAsDataURL(file);
        }
      }} />
      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleInvoiceUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button 
             onClick={(e) => { 
                e.preventDefault();
                e.stopPropagation();
                if(window.confirm('BU KAYDI TAMAMEN SİLMEK İSTİYOR MUSUNUZ?')) onDelete(transaction.id); 
             }} 
             className="p-4 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90 shadow-md hover:bg-red-600 hover:text-white transition-all"
           >
              <Trash2 size={24} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg hover:border-red-600 transition-all">
              <Printer size={16} className="text-red-600" />
              <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Yok'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right min-w-[200px]">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA TUTARI</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">DURUM: {statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        <button 
                                          onClick={(e) => undoApproval(e, flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 active:scale-95 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button onClick={() => { setTargetRoleForLateProof(flow.role); setTimeout(() => lateProofInputRef.current?.click(), 100); }} className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all">
                                           <ImagePlus size={16} />
                                        </button>
                                     </>
                                   ) : (
                                     <button onClick={() => setShowApprovalModal({ role: flow.role })} className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg active:scale-95 transition-all">ONAYLA</button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity"><Eye size={16} className="text-white" /></div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> SEÇİLEN TEDARİKÇİ
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all cursor-pointer group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`} onClick={() => handleSelectOffer(offer.id)}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-600'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase active:scale-95 transition-all hover:bg-red-500 shadow-md">BELGE YÜKLE</button>
                </div>
                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices?.length ? transaction.invoices.map((inv, idx) => (
                         <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 cursor-pointer transition-all">
                            <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                               <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 shadow-lg"><Eye size={18} /></button>
                               <button onClick={(e) => removeInvoice(e, idx)} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 shadow-lg"><Trash2 size={18} /></button>
                            </div>
                         </div>
                      )) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-900" /><p className="text-[10px] font-black uppercase text-gray-500 tracking-widest">Belge Yok</p>
                        </div>
                      )}
                   </div>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM GÜNCELLE
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1 tracking-wider font-bold">Dosya sonucunu nihai aşamaya taşıyın.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button onClick={() => onStatusChange(transaction.id, 'Purchased')} className={`px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white shadow-[0_0_20px_rgba(22,163,74,0.3)]' : 'bg-red-600 text-white hover:bg-red-500'}`}>
                   {transaction.status === 'Purchased' ? 'SATIN ALINDI' : 'SATIN ALIMI TAMAMLA'}
                </button>
                <button onClick={() => onStatusChange(transaction.id, 'On Hold')} className="px-8 py-5 border border-[var(--border-grey)] text-[var(--text-muted)] rounded-[25px] font-black uppercase text-[11px] active:scale-95 transition-all hover:bg-white/5">ERTELENSİN</button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus, AlertTriangle } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  // Verileri LocalStorage'dan yükle
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('yasam_app_v2_data');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // "Macbook Pro M3" gibi eski cache verilerini temizle (isteğe bağlı güvenlik filtresi)
        const cleanTransactions = (parsed.transactions || []).filter((t: any) => !t.productSetName.includes("Macbook Pro M3"));
        return {
          ...parsed,
          transactions: cleanTransactions,
          user: null // Güvenlik için her girişte login istenir
        };
      } catch (e) {
        console.error("Yükleme hatası:", e);
      }
    }
    return {
      user: null,
      transactions: [], // Temiz başlangıç
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'V2 Premium sürüm aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Veri değiştikçe kaydet
  useEffect(() => {
    const { user, ...persistentData } = state;
    localStorage.setItem('yasam_app_v2_data', JSON.stringify(persistentData));
  }, [state]);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    const newLog: SystemLog = {
      id: `SL-${Date.now()}`,
      timestamp: new Date().toISOString(),
      user: state.user?.name || 'Ziyaretçi',
      module,
      action,
      details
    };
    setState(prev => ({ ...prev, systemLogs: [newLog, ...prev.systemLogs] }));
  }, [state.user]);

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, status: newStatus } : t)
    }));
    addSystemLog('PURCHASE', 'Durum Değişti', `${id} statüsü ${statusLabels[newStatus]} oldu.`);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
    if (logMessage) addSystemLog('PURCHASE', 'Güncelleme', `${id}: ${logMessage}`);
  };

  // SİLME FONKSİYONU - KESİN ÇÖZÜM
  const deleteTransaction = (id: string) => {
    setState(prev => {
      const newList = prev.transactions.filter(t => t.id !== id);
      return { ...prev, transactions: newList };
    });
    if (selectedTransactionId === id) setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt Silindi', `${id} dosyası kalıcı olarak kaldırıldı.`);
  };

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => setState(prev => ({ ...prev, user: null }));

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTrx: Transaction = {
      id: `TRX-${Math.floor(Math.random() * 9000) + 1000}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      productUrl: request.productUrl,
      extraItems: request.extraItems || [],
      offers: request.offers || [],
      logs: [{ id: 'init', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Başlangıç', details: 'Talep girişi yapıldı.' }],
      approvalFlow: request.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
    };
    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <>
      {isTransitioning && (
        <div className="heart-overlay-container"><div className="relative w-32 h-32 flex items-center justify-center"><Heart className="absolute text-red-600/10 w-full h-full" strokeWidth={1} /><div className="absolute bottom-0 left-0 w-full overflow-hidden animate-heart-fill"><Heart className="text-red-600 fill-red-600 w-32 h-32" strokeWidth={0} /></div></div></div>
      )}

      <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={handleLogout} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
        {selectedTransactionId ? (
          <TransactionDetail 
            transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
            onBack={() => setSelectedTransactionId(null)} 
            onStatusChange={handleStatusChange} 
            onDelete={deleteTransaction} 
            onUpdate={handleUpdate} 
            currentUserRole={state.user.role} 
          />
        ) : (
          <>
            {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={(s) => { setStatusFilter(s); setActiveTab('transactions'); }} />}
            {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} onBack={() => setActiveTab('dashboard')} />}
            {activeTab === 'transactions' && (
              <div className="space-y-12 animate-in fade-in duration-700">
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                  <div>
                    <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                    <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                  </div>
                  <div className="flex flex-wrap bg-white/5 p-2 rounded-2xl border border-white/5 gap-1">
                    <button onClick={() => setStatusFilter(null)} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!statusFilter ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}>TÜMÜ</button>
                    <button onClick={() => setStatusFilter('Pending')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Pending' ? 'bg-amber-600 text-white shadow-xl' : 'text-amber-500 hover:bg-amber-500/10'}`}>BEKLEYEN</button>
                    <button onClick={() => setStatusFilter('Approved')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Approved' ? 'bg-cyan-600 text-white shadow-xl' : 'text-cyan-500 hover:bg-cyan-500/10'}`}>ONAYLI</button>
                    <button onClick={() => setStatusFilter('Purchased')} className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${statusFilter === 'Purchased' ? 'bg-green-600 text-white shadow-xl' : 'text-green-500 hover:bg-green-500/10'}`}>ALINDI</button>
                  </div>
                </div>

                {filteredTransactions.length === 0 ? (
                  <div className="py-32 text-center glass-panel rounded-[50px] border-dashed border-white/10 opacity-30">
                    <ImageIcon size={64} className="mx-auto mb-6 text-gray-800" />
                    <p className="text-sm font-black uppercase tracking-[0.4em]">Henüz bir talep bulunmuyor</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                    {filteredTransactions.map((t) => (
                      <div 
                        key={t.id} 
                        onClick={() => setSelectedTransactionId(t.id)} 
                        className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group transition-all hover:border-red-600/30"
                      >
                        {/* KART ÜST KISIM: Tarih (En Üstte) ve Görsel */}
                        <div className="flex justify-between items-start mb-6 relative z-10">
                          <div className="flex flex-col space-y-3">
                             {/* TARİH (İstediğiniz yer: Sol üst en tepede) */}
                             <div className="flex items-center space-x-1.5">
                               <CalendarDays size={13} className="text-red-600" />
                               <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">
                                 {new Date(t.requestDateTime).toLocaleDateString('tr-TR')}
                               </span>
                             </div>

                             {/* GÖRSEL (Tarihin altında) */}
                             <div className="w-24 h-24 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500">
                               {t.photoUrl ? (
                                 <img src={t.photoUrl} alt={t.productSetName} className="w-full h-full object-cover" />
                               ) : (
                                 <div className="flex flex-col items-center">
                                    <ImageIcon size={28} className="text-red-600/30 mb-1" />
                                    <span className="text-2xl font-black text-red-600">{t.requesterName.charAt(0)}</span>
                                 </div>
                               )}
                             </div>
                          </div>

                          {/* SAĞ ÜST: Statü ve Silme Butonu */}
                          <div className="flex flex-col items-end space-y-4">
                            <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border tracking-widest ${
                              t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20' : 
                              t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20' :
                              'bg-red-600/10 text-red-400 border-red-600/20'
                            }`}>{statusLabels[t.status]}</span>

                            <button 
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation(); // Kart tıklamasını engellemek için KRİTİK
                                if(window.confirm('DİKKAT! Bu işlem geri alınamaz. Bu kaydı silmek istediğinize emin misiniz?')) {
                                  deleteTransaction(t.id);
                                }
                              }}
                              className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90"
                              title="Sil"
                            >
                              <Trash2 size={22} />
                            </button>
                          </div>
                        </div>

                        <div className="space-y-1">
                          <h3 className="text-2xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors duration-300">{t.productSetName}</h3>
                          <p className="text-[11px] text-gray-500 font-bold uppercase tracking-[0.2em]">{t.department}</p>
                        </div>

                        <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                           <div className="space-y-1">
                              <p className="text-[10px] text-red-950 font-black uppercase tracking-widest opacity-60">TOPLAM TUTAR</p>
                              <p className="text-3xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                           </div>
                           <p className="text-[10px] font-mono text-gray-700 font-bold uppercase">#{t.id}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
            {activeTab === 'reports' && <Reports transactions={state.transactions} />}
            {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
            {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
          </>
        )}
      </Layout>
    </>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  Upload, History, ChevronRight, ImagePlus,
  RotateCcw, AlertCircle, Printer, Package, Trash2, MessageSquare,
  FileText, Paperclip, Eye, Download, MapPin
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  const handleSelectOffer = (offerId: string) => {
    const updatedOffers = transaction.offers.map(o => ({ ...o, isChosen: o.id === offerId }));
    const chosen = updatedOffers.find(o => o.id === offerId);
    onUpdate(transaction.id, { 
      offers: updatedOffers, 
      totalAmount: (transaction.packageQuantity || 1) * (chosen?.price || 0),
      supplierName: chosen?.sourceName || ''
    }, `Tedarikçi Değiştirildi: ${chosen?.sourceName}`);
  };

  /**
   * ONARILAN GERİ ÇEKME FONKSİYONU
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`DİKKAT: ${roleName} onayını geri çekmek istediğinize emin misiniz? Onay verileri temizlenecek ve süreç 'BEKLİYOR' durumuna dönecektir.`)) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya yeniden inceleme moduna alındı.`);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === showApprovalModal.role) {
        return {
          ...f,
          status: 'Approved' as const,
          date: new Date().toISOString(),
          type: isSignedApproval ? 'Signed' : 'Normal',
          proofUrl: proofUrl || f.proofUrl,
          decisionNote: decisionNote || undefined
        };
      }
      return f;
    });

    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: allApproved ? 'Approved' : transaction.status
    }, `${showApprovalModal.role} tarafından onay verildi.`);

    setShowApprovalModal(null);
    setDecisionNote('');
  };

  const handleSignedFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => executeApproval(reader.result as string);
      reader.readAsDataURL(file);
    }
  };

  const handleInvoiceUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const currentInvoices = transaction.invoices || [];
        onUpdate(transaction.id, { invoices: [...currentInvoices, reader.result as string] }, `Dosyaya belge eklendi.`);
      };
      reader.readAsDataURL(file);
    }
  };

  const removeInvoice = (e: React.MouseEvent, idx: number) => {
    e.preventDefault();
    e.stopPropagation();
    if (!window.confirm("Bu belgeyi silmek istediğinize emin misiniz?")) return;
    const currentInvoices = [...(transaction.invoices || [])];
    currentInvoices.splice(idx, 1);
    onUpdate(transaction.id, { invoices: currentInvoices }, "Belge silindi.");
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showPrintView && (
        <div className="fixed inset-0 z-[250] bg-black/90 flex flex-col items-center overflow-y-auto p-4 lg:p-10 no-print">
           <div className="w-full max-w-[215mm] bg-white rounded-xl shadow-2xl relative mb-20">
              <div className="sticky top-0 right-0 flex justify-end p-4 bg-white/90 backdrop-blur border-b z-10 space-x-2 no-print">
                 <button onClick={() => window.print()} className="px-5 py-2.5 bg-red-600 text-white rounded-lg text-xs font-black uppercase flex items-center space-x-2">
                    <Printer size={16} /> <span>Yazdır</span>
                 </button>
                 <button onClick={() => setShowPrintView(false)} className="px-5 py-2.5 bg-gray-100 text-gray-800 rounded-lg text-xs font-black uppercase">Kapat</button>
              </div>
              <div className="p-4 sm:p-10"><OfficialForm transaction={transaction} /></div>
           </div>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Onay notu veya açıklama ekleyin</p>
              </div>
              <textarea 
                value={decisionNote}
