                        const file = e.target.files?.[0];
                        if (file) {
                          const reader = new FileReader();
                          reader.onloadend = () => {
                            const current = transaction.invoices || [];
                            onUpdate(transaction.id, { invoices: [...current, reader.result as string] }, "Yeni belge eklendi.");
