import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const STORAGE_KEY = 'yasam_enterprise_v3_final';

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // Filtrele: Sadece Macbook olmayanları al
        const cleanTrx = (parsed.transactions || []).filter((t: any) => 
          !t.productSetName.toLowerCase().includes("macbook")
        );
        return { ...parsed, transactions: cleanTrx, user: null };
      } catch (e) { console.error(e); }
    }
    return {
      user: null,
      transactions: [],
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'V3 Stabil Çekirdek Aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Veri Kaydı
  useEffect(() => {
    const { user, ...persistent } = state;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(persistent));
  }, [state]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    setState(prev => ({
      ...prev,
      systemLogs: [{ id: `SL-${Date.now()}`, timestamp: new Date().toISOString(), user: prev.user?.name || 'Ziyaretçi', module, action, details }, ...prev.systemLogs].slice(0, 100)
    }));
  }, []);

  const handleStatusChange = (id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, status: newStatus } : t)
    }));
    addSystemLog('PURCHASE', 'Statü Güncellendi', `${id} dosyası ${newStatus} yapıldı.`);
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t)
    }));
    if (logMessage) addSystemLog('PURCHASE', 'Bilgi Güncelleme', `${id}: ${logMessage}`);
  };

  // KESİN SİLME FONKSİYONU
  const deleteTransaction = (id: string) => {
    setState(prev => {
      const filtered = prev.transactions.filter(t => t.id !== id);
      return { ...prev, transactions: filtered };
    });
    // Eğer detay sayfasındaysak kapat
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt İmha', `${id} nolu talep sistemden kalıcı olarak silindi.`);
  };

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => setState(prev => ({ ...prev, user: null }));

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTrx: Transaction = {
      id: `TRX-${Math.floor(1000 + Math.random() * 9000)}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      offers: request.offers || [],
      extraItems: request.extraItems || [],
      logs: [{ id: '1', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep girişi sağlandı.' }],
      approvalFlow: request.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
    };
    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={handleLogout} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
      {selectedTransactionId ? (
        <TransactionDetail 
          transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
          onBack={() => setSelectedTransactionId(null)} 
          onStatusChange={handleStatusChange} 
          onDelete={deleteTransaction} 
          onUpdate={handleUpdate} 
          currentUserRole={state.user.role} 
        />
      ) : (
        <div className="space-y-12">
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={setStatusFilter} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                  <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                </div>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 gap-1">
                  {['TÜMÜ', 'Pending', 'Approved', 'Purchased'].map((s) => (
                    <button 
                      key={s} 
                      onClick={() => setStatusFilter(s === 'TÜMÜ' ? null : s as any)}
                      className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                        (s === 'TÜMÜ' && !statusFilter) || statusFilter === s ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'
                      }`}
                    >
                      {s === 'TÜMÜ' ? 'TÜMÜ' : statusLabels[s]}
                    </button>
                  ))}
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="py-40 text-center glass-panel rounded-[50px] border border-dashed border-white/10 opacity-30">
                  <ImageIcon size={64} className="mx-auto mb-6 text-gray-800" />
                  <p className="text-[10px] font-black uppercase tracking-[0.4em]">VERİ YOK</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id} 
                      onClick={() => setSelectedTransactionId(t.id)} 
                      className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group hover:border-red-600/40 transition-all"
                    >
                      <div className="flex justify-between items-start mb-6 relative z-10">
                        <div className="flex flex-col space-y-4">
                           {/* TARİH ÜSTTE */}
                           <div className="flex items-center space-x-2">
                             <CalendarDays size={14} className="text-red-600" />
                             <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</span>
                           </div>
                           {/* GÖRSEL ALTTA */}
                           <div className="w-24 h-24 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500">
                             {t.photoUrl ? <img src={t.photoUrl} className="w-full h-full object-cover" /> : <span className="text-2xl text-red-600">{t.requesterName.charAt(0)}</span>}
                           </div>
                        </div>

                        <div className="flex flex-col items-end space-y-4">
                          <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${
                            t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20' : 
                            t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20' : 'bg-red-600/10 text-red-400 border-red-600/20'
                          }`}>{statusLabels[t.status]}</span>

                          {/* SİLME BUTONU - EVENT BUBBLING FIX */}
                          <button 
                            type="button" 
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              if (e.nativeEvent) e.nativeEvent.stopImmediatePropagation();
                              if(window.confirm(`DİKKAT! ${t.productSetName} kaydını sistemden KALICI olarak silmek istiyor musunuz?`)) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90"
                            title="Kaydı Sil"
                          >
                            <Trash2 size={24} />
                          </button>
                        </div>
                      </div>

                      <h3 className="text-2xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors">{t.productSetName}</h3>
                      <p className="text-[11px] text-gray-500 font-bold uppercase tracking-widest">{t.department}</p>

                      <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                         <div>
                            <p className="text-[10px] text-red-950 font-black uppercase tracking-widest opacity-60">TUTAR</p>
                            <p className="text-3xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-gray-700 font-bold uppercase tracking-widest">#{t.id}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  ImagePlus, Trash2, Printer, MessageSquare, FileText, Paperclip, Eye, MapPin,
  AlertCircle
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  /**
   * GERİ ÇEKME - TÜM VERİLERİ SIFIRLAR VE STATÜYÜ BEKLİYOR YAPAR
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`DİKKAT: ${roleName} onayını geri çekmek istediğinize emin misiniz? Süreç 'BEKLİYOR' aşamasına geri dönecektir.`)) return;

    const newFlow = transaction.approvalFlow.map(f => (
      f.role === roleName ? { 
        ...f, 
        status: 'Pending' as const, 
        date: undefined, 
        type: undefined, 
        proofUrl: undefined, 
        decisionNote: undefined 
      } : f
    ));

    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi.`);
  };

  /**
   * GÖRSEL YÜKLEME TETİKLEME - ASENKRON FIX
   */
  const triggerLateProof = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();
    setTargetRoleForLateProof(roleName);
    // State'in yerleşmesi için milisaniyelik gecikme ile input'u aç
    setTimeout(() => {
      if (lateProofInputRef.current) lateProofInputRef.current.click();
    }, 100);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => (
          f.role === targetRoleForLateProof ? { 
            ...f, 
            proofUrl: reader.result as string, 
            type: 'Signed' as const, 
            status: 'Approved' as const, 
            date: f.date || new Date().toISOString() 
          } : f
        ));
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi başarıyla işlendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;
    const newFlow = transaction.approvalFlow.map(f => (
      f.role === showApprovalModal.role ? {
        ...f,
        status: 'Approved' as const,
        date: new Date().toISOString(),
        type: isSignedApproval ? 'Signed' : 'Normal',
        proofUrl: proofUrl || f.proofUrl,
        decisionNote: decisionNote || undefined
      } : f
    ));
    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { approvalFlow: newFlow, status: allApproved ? 'Approved' : transaction.status }, `${showApprovalModal.role} tarafından onay verildi.`);
    setShowApprovalModal(null);
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Onay notu veya açıklama ekleyin</p>
              </div>
              <textarea value={decisionNote} onChange={e => setDecisionNote(e.target.value)} placeholder="Açıklama (isteğe bağlı)..." className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none" />
              <div className="grid grid-cols-1 gap-4">
                <button onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">DİJİTAL ONAY <Zap size={16} className="inline ml-2"/></button>
                <button onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => executeApproval(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} />
              </div>
              <button onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase tracking-widest">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button 
             type="button"
             onClick={(e) => { 
                e.preventDefault(); e.stopPropagation();
                if(window.confirm('BU KAYDI TAMAMEN SİLMEK İSTİYOR MUSUNUZ?')) {
                  onDelete(transaction.id);
                }
             }} 
             className="p-4 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90 shadow-md hover:bg-red-600 hover:text-white transition-all"
           >
              <Trash2 size={24} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg hover:border-red-600 transition-all">
              <Printer size={16} className="text-red-600" /> <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Bilgisi Yok'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right min-w-[200px]">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA TUTARI</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">DURUM: {statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        <button 
                                          type="button" 
                                          onClick={(e) => undoApproval(e, flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 active:scale-95 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button 
                                          type="button" 
                                          onClick={(e) => triggerLateProof(e, flow.role)} 
                                          className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all shadow-sm"
                                        >
                                           <ImagePlus size={20} />
                                        </button>
                                     </>
                                   ) : (
                                     <button 
                                       type="button" 
                                       onClick={() => setShowApprovalModal({ role: flow.role })} 
                                       className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg active:scale-95 transition-all"
                                     >
                                       ONAYLA
                                     </button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity"><Eye size={16} className="text-white" /></div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> SEÇİLEN TEDARİKÇİ
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE HAVUZU
                      </h4>
                      <button onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-md hover:bg-red-500 transition-all">YENİ BELGE EKLE</button>
                      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          const reader = new FileReader();
                          reader.onloadend = () => {
                            const current = transaction.invoices || [];
                            onUpdate(transaction.id, { invoices: [...current, reader.result as string] }, "Dosyaya yeni bir belge eklendi.");
                          };
                          reader.readAsDataURL(file);
                        }
                      }} />
                   </div>
                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices?.length ? transaction.invoices.map((inv, idx) => (
                         <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 cursor-pointer transition-all">
                            <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                               <button onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 shadow-lg"><Eye size={18} /></button>
                               <button onClick={(e) => {
                                 e.stopPropagation();
                                 if(window.confirm('Belgeyi silmek istediğinize emin misiniz?')) {
                                   const current = [...(transaction.invoices || [])];
                                   current.splice(idx, 1);
                                   onUpdate(transaction.id, { invoices: current }, "Dosyadaki bir belge silindi.");
                                 }
                               }} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 shadow-lg"><Trash2 size={18} /></button>
                            </div>
                         </div>
                      )) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-900" /><p className="text-[10px] font-black uppercase text-gray-500 tracking-widest">Belge Havuzu Boş</p>
                        </div>
                      )}
                   </div>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM GÜNCELLE
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1 tracking-wider font-bold">İşlemin sonucunu buradan yönetin.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button 
                  onClick={() => onStatusChange(transaction.id, 'Purchased')} 
                  className={`px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white shadow-[0_0_20px_rgba(22,163,74,0.3)]' : 'bg-red-600 text-white hover:bg-red-500'}`}
                >
                   {transaction.status === 'Purchased' ? 'SATIN ALINDI' : 'SATIN ALIMI TAMAMLA'}
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const STORAGE_KEY = 'yasam_enterprise_v3_final';

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const cleanTrx = (parsed.transactions || []).filter((t: any) => 
          !t.productSetName.toLowerCase().includes("macbook")
        );
        return { ...parsed, transactions: cleanTrx, user: null };
      } catch (e) { console.error(e); }
    }
    return {
      user: null,
      transactions: [],
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'V3 Stabil Çekirdek Aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const { user, ...persistent } = state;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(persistent));
  }, [state]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    setState(prev => ({
      ...prev,
      systemLogs: [{ id: `SL-${Date.now()}`, timestamp: new Date().toISOString(), user: prev.user?.name || 'Ziyaretçi', module, action, details }, ...prev.systemLogs].slice(0, 100)
    }));
  }, []);

  const handleStatusChange = useCallback((id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, status: newStatus } : t)
    }));
    addSystemLog('PURCHASE', 'Statü Güncellendi', `${id} dosyası ${newStatus} yapıldı.`);
  }, [addSystemLog]);

  const handleUpdate = useCallback((id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => {
      const updatedTransactions = prev.transactions.map(t => t.id === id ? { ...t, ...updates } : t);
      return { ...prev, transactions: updatedTransactions };
    });
    if (logMessage) addSystemLog('PURCHASE', 'Bilgi Güncelleme', `${id}: ${logMessage}`);
  }, [addSystemLog]);

  const deleteTransaction = useCallback((id: string) => {
    setState(prev => {
      const filtered = prev.transactions.filter(t => t.id !== id);
      return { ...prev, transactions: filtered };
    });
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt İmha', `${id} nolu talep sistemden kalıcı olarak silindi.`);
  }, [addSystemLog]);

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => setState(prev => ({ ...prev, user: null }));

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTrx: Transaction = {
      id: `TRX-${Math.floor(1000 + Math.random() * 9000)}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      offers: request.offers || [],
      extraItems: request.extraItems || [],
      logs: [{ id: '1', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep girişi sağlandı.' }],
      approvalFlow: request.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
    };
    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={handleLogout} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
      {selectedTransactionId ? (
        <TransactionDetail 
          transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
          onBack={() => setSelectedTransactionId(null)} 
          onStatusChange={handleStatusChange} 
          onDelete={deleteTransaction} 
          onUpdate={handleUpdate} 
          currentUserRole={state.user.role} 
        />
      ) : (
        <div className="space-y-12">
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={setStatusFilter} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                  <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                </div>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 gap-1">
                  {['TÜMÜ', 'Pending', 'Approved', 'Purchased'].map((s) => (
                    <button 
                      key={s} 
                      onClick={() => setStatusFilter(s === 'TÜMÜ' ? null : s as any)}
                      className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                        (s === 'TÜMÜ' && !statusFilter) || statusFilter === s ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'
                      }`}
                    >
                      {s === 'TÜMÜ' ? 'TÜMÜ' : statusLabels[s]}
                    </button>
                  ))}
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="py-40 text-center glass-panel rounded-[50px] border border-dashed border-white/10 opacity-30">
                  <ImageIcon size={64} className="mx-auto mb-6 text-gray-800" />
                  <p className="text-[10px] font-black uppercase tracking-[0.4em]">VERİ YOK</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id} 
                      onClick={() => setSelectedTransactionId(t.id)} 
                      className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group hover:border-red-600/40 transition-all"
                    >
                      <div className="flex justify-between items-start mb-6 relative z-10">
                        <div className="flex flex-col space-y-4">
                           <div className="flex items-center space-x-2">
                             <CalendarDays size={14} className="text-red-600" />
                             <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</span>
                           </div>
                           <div className="w-24 h-24 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500">
                             {t.photoUrl ? <img src={t.photoUrl} className="w-full h-full object-cover" /> : <span className="text-2xl text-red-600">{t.requesterName.charAt(0)}</span>}
                           </div>
                        </div>

                        <div className="flex flex-col items-end space-y-4">
                          <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${
                            t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20' : 
                            t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20' : 'bg-red-600/10 text-red-400 border-red-600/20'
                          }`}>{statusLabels[t.status]}</span>

                          <button 
                            type="button" 
                            onClick={(e) => {
                              // KRİTİK: Hem stopPropagation hem de Native StopImmediatePropagation kullanılarak olay tamamen donduruldu.
                              e.preventDefault();
                              e.stopPropagation();
                              if (e.nativeEvent) e.nativeEvent.stopImmediatePropagation();

                              if(window.confirm(`DİKKAT! ${t.productSetName} kaydını KALICI olarak silmek istiyor musunuz?`)) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90 relative z-[100]"
                          >
                            <Trash2 size={24} />
                          </button>
                        </div>
                      </div>

                      <h3 className="text-2xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors">{t.productSetName}</h3>
                      <p className="text-[11px] text-gray-500 font-bold uppercase tracking-widest">{t.department}</p>

                      <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                         <div>
                            <p className="text-[10px] text-red-950 font-black uppercase tracking-widest opacity-60">TUTAR</p>
                            <p className="text-3xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-gray-700 font-bold uppercase tracking-widest">#{t.id}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  ImagePlus, Trash2, Printer, MessageSquare, FileText, Paperclip, Eye, MapPin,
  AlertCircle
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  /**
   * GERİ ÇEKME (UNDO) - KESİN ÇÖZÜM
   * Parent bileşendeki onUpdate'i kullanarak state'i doğrudan günceller.
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya 'BEKLİYOR' durumuna geri alınacaktır.`)) return;

    // Yeni onay akışını oluştur (ilgili rolü sıfırla)
    const newFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    // Parent'a güncelleme gönder (Statü mutlaka Pending olmalı)
    onUpdate(transaction.id, { 
      approvalFlow: newFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya yeniden incelemeye alındı.`);
  };

  /**
   * GEÇ BELGE YÜKLEME - REF GÜVENLİĞİ
   */
  const triggerLateProof = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();
    setTargetRoleForLateProof(roleName);
    // State güncellemesinin tamamlanması için küçük bir timeout
    setTimeout(() => {
      if (lateProofInputRef.current) {
        lateProofInputRef.current.click();
      }
    }, 150);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => (
          f.role === targetRoleForLateProof ? { 
            ...f, 
            proofUrl: reader.result as string, 
            type: 'Signed' as const, 
            status: 'Approved' as const, 
            date: f.date || new Date().toISOString() 
          } : f
        ));
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi sisteme işlendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
    }
    // Aynı dosyayı tekrar seçebilmek için input'u sıfırla
    e.target.value = '';
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;
    const newFlow = transaction.approvalFlow.map(f => (
      f.role === showApprovalModal.role ? {
        ...f,
        status: 'Approved' as const,
        date: new Date().toISOString(),
        type: isSignedApproval ? 'Signed' : 'Normal',
        proofUrl: proofUrl || f.proofUrl,
        decisionNote: decisionNote || undefined
      } : f
    ));
    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow, 
      status: allApproved ? 'Approved' : transaction.status 
    }, `${showApprovalModal.role} onay verdi.`);
    setShowApprovalModal(null);
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {/* Lightbox ve Modallar aynen kalacak */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Onay notu veya açıklama ekleyin</p>
              </div>
              <textarea value={decisionNote} onChange={e => setDecisionNote(e.target.value)} placeholder="Açıklama (isteğe bağlı)..." className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none focus:border-red-600/50" />
              <div className="grid grid-cols-1 gap-4">
                <button type="button" onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">DİJİTAL ONAY <Zap size={16} className="inline ml-2"/></button>
                <button type="button" onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => executeApproval(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} />
              </div>
              <button type="button" onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase tracking-widest">VAZGEÇ</button>
           </div>
        </div>
      )}

      {/* KRİTİK: Hidden Inputlar */}
      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button 
             type="button"
             onClick={(e) => { 
                e.preventDefault(); e.stopPropagation();
                if(window.confirm('BU KAYDI TAMAMEN SİLMEK İSTİYOR MUSUNUZ?')) {
                  onDelete(transaction.id);
                }
             }} 
             className="p-4 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90 shadow-md hover:bg-red-600 hover:text-white transition-all"
           >
              <Trash2 size={24} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg hover:border-red-600 transition-all">
              <Printer size={16} className="text-red-600" /> <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Bilgisi Yok'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right min-w-[200px]">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA TUTARI</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">DURUM: {statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
                             {flow.status === 'Approved' ? <BadgeCheck size={24} /> : <UserCheck size={24} />}
                          </div>
                          <div className="flex-1 min-w-0">
                             <div className="flex items-center justify-between mb-1">
                                <p className="text-[11px] font-black text-white uppercase truncate">{flow.role}</p>
                                <div className="flex items-center space-x-3">
                                   {flow.status === 'Approved' ? (
                                     <>
                                        <button 
                                          type="button" 
                                          onClick={(e) => undoApproval(e, flow.role)} 
                                          className="text-[9px] font-black text-red-600 hover:text-red-400 uppercase tracking-tighter border-b border-red-600/50 pb-0.5 active:scale-95 transition-all"
                                        >
                                           GERİ ÇEK
                                        </button>
                                        <button 
                                          type="button" 
                                          onClick={(e) => triggerLateProof(e, flow.role)} 
                                          className="p-2 text-cyan-500 bg-white/5 rounded-xl hover:bg-cyan-600 hover:text-white transition-all shadow-sm"
                                        >
                                           <ImagePlus size={20} />
                                        </button>
                                     </>
                                   ) : (
                                     <button 
                                       type="button" 
                                       onClick={() => setShowApprovalModal({ role: flow.role })} 
                                       className="px-4 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg active:scale-95 transition-all"
                                     >
                                       ONAYLA
                                     </button>
                                   )}
                                </div>
                             </div>
                             <p className="text-[10px] text-[var(--text-muted)] font-bold uppercase truncate">{flow.approverName}</p>
                          </div>
                          {flow.status === 'Approved' && flow.proofUrl && (
                            <div className="w-14 h-14 rounded-xl overflow-hidden border border-red-600/30 cursor-pointer group/img relative" onClick={() => setShowLightbox(flow.proofUrl!)}>
                               <img src={flow.proofUrl} className="w-full h-full object-cover" />
                               <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 flex items-center justify-center transition-opacity"><Eye size={16} className="text-white" /></div>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-7 space-y-12">
                <div className="space-y-6">
                   <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                      <ExternalLink size={18} className="mr-3 text-red-600" /> SEÇİLEN TEDARİKÇİ
                   </h4>
                   <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {transaction.offers.map((offer) => (
                        <div key={offer.id} className={`p-6 rounded-[30px] border transition-all group ${offer.isChosen ? 'bg-red-600/5 border-red-600/50 shadow-xl' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-50'}`}>
                           <div className="flex justify-between items-start mb-6">
                              <div className={`p-3 rounded-2xl ${offer.isChosen ? 'bg-red-600 text-white' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
                                 {offer.sourceType === 'Online' ? <Globe size={24} /> : <Store size={24} />}
                              </div>
                              {offer.isChosen && <CheckCircle2 size={24} className="text-red-600" />}
                           </div>
                           <h5 className="text-lg font-black text-white uppercase truncate">{offer.sourceName}</h5>
                           <p className="text-3xl font-black text-red-600 mt-2">₺{offer.price.toLocaleString('tr-TR')}</p>
                        </div>
                      ))}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-[var(--border-grey)] pb-4">
                      <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] flex items-center">
                        <FileText size={18} className="mr-3 text-red-600" /> BELGE HAVUZU
                      </h4>
                      <button type="button" onClick={() => invoiceInputRef.current?.click()} className="px-5 py-2.5 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-md hover:bg-red-500 transition-all">YENİ BELGE EKLE</button>
                      <input type="file" ref={invoiceInputRef} className="hidden" accept="image/*,application/pdf" onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          const reader = new FileReader();
                          reader.onloadend = () => {
                            const current = transaction.invoices || [];
                            onUpdate(transaction.id, { invoices: [...current, reader.result as string] }, "Dosyaya yeni bir belge eklendi.");
                          };
                          reader.readAsDataURL(file);
                        }
                      }} />
                   </div>
                   <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
                      {transaction.invoices?.length ? transaction.invoices.map((inv, idx) => (
                         <div key={idx} className="group relative aspect-square glass-panel rounded-2xl border-white/5 overflow-hidden border hover:border-red-600/30 cursor-pointer transition-all">
                            <img src={inv} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-all" />
                            <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center space-x-2 transition-all">
                               <button type="button" onClick={() => setShowLightbox(inv)} className="p-2.5 bg-white text-black rounded-xl hover:scale-110 shadow-lg"><Eye size={18} /></button>
                               <button type="button" onClick={(e) => {
                                 e.stopPropagation();
                                 if(window.confirm('Belgeyi silmek istediğinize emin misiniz?')) {
                                   const current = [...(transaction.invoices || [])];
                                   current.splice(idx, 1);
                                   onUpdate(transaction.id, { invoices: current }, "Dosyadaki bir belge silindi.");
                                 }
                               }} className="p-2.5 bg-red-600 text-white rounded-xl hover:scale-110 shadow-lg"><Trash2 size={18} /></button>
                            </div>
                         </div>
                      )) : (
                        <div className="col-span-full py-12 flex flex-col items-center justify-center glass-panel rounded-[30px] border border-dashed border-white/10 opacity-30">
                           <Paperclip size={36} className="mb-4 text-gray-900" /><p className="text-[10px] font-black uppercase text-gray-500 tracking-widest">Belge Havuzu Boş</p>
                        </div>
                      )}
                   </div>
                </div>
             </div>
          </div>

          <div className="bg-red-600/5 p-8 lg:p-12 rounded-[50px] border border-red-600/15 flex flex-col sm:flex-row items-center justify-between gap-8">
             <div className="text-center sm:text-left">
                <p className="text-[11px] font-black text-red-600 uppercase tracking-widest flex items-center justify-center sm:justify-start">
                   <AlertCircle size={18} className="mr-2" /> OPERASYONEL DURUM GÜNCELLE
                </p>
                <p className="text-[var(--text-muted)] text-[10px] uppercase mt-1 tracking-wider font-bold">İşlemin sonucunu buradan yönetin.</p>
             </div>
             <div className="flex flex-wrap justify-center gap-3 w-full sm:w-auto">
                <button 
                  type="button"
                  onClick={() => onStatusChange(transaction.id, 'Purchased')} 
                  className={`px-10 py-5 rounded-[25px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white shadow-[0_0_20px_rgba(22,163,74,0.3)]' : 'bg-red-600 text-white hover:bg-red-500'}`}
                >
                   {transaction.status === 'Purchased' ? 'SATIN ALINDI' : 'SATIN ALIMI TAMAMLA'}
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { MOCK_TRANSACTIONS, INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const App: React.FC = () => {
  const STORAGE_KEY = 'yasam_enterprise_v3_final';

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        const cleanTrx = (parsed.transactions || []).filter((t: any) => 
          !t.productSetName.toLowerCase().includes("macbook")
        );
        return { ...parsed, transactions: cleanTrx, user: null };
      } catch (e) { console.error(e); }
    }
    return {
      user: null,
      transactions: [],
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Sistem Başlatıldı', details: 'V3 Stabil Çekirdek Aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const { user, ...persistent } = state;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(persistent));
  }, [state]);

  const addSystemLog = useCallback((module: SystemLog['module'], action: string, details: string) => {
    setState(prev => ({
      ...prev,
      systemLogs: [{ id: `SL-${Date.now()}`, timestamp: new Date().toISOString(), user: prev.user?.name || 'Ziyaretçi', module, action, details }, ...prev.systemLogs].slice(0, 100)
    }));
  }, []);

  const handleStatusChange = useCallback((id: string, newStatus: Transaction['status']) => {
    setState(prev => ({
      ...prev,
      transactions: prev.transactions.map(t => t.id === id ? { ...t, status: newStatus } : t)
    }));
    addSystemLog('PURCHASE', 'Statü Güncellendi', `${id} dosyası ${newStatus} yapıldı.`);
  }, [addSystemLog]);

  // GÜNCELLEME - DERİN KOPYALAMA (DEEP COPY) İLE REFERANS TAZELEME
  const handleUpdate = useCallback((id: string, updates: Partial<Transaction>, logMessage?: string) => {
    setState(prev => {
      // Mevcut listeyi derin kopyalayarak referansları tazele
      const newTransactions = prev.transactions.map(t => {
        if (t.id === id) {
          // Güncellemeyi uygula ve yeni bir obje referansı döndür
          return { ...t, ...updates };
        }
        return t;
      });
      return { ...prev, transactions: newTransactions };
    });
    if (logMessage) addSystemLog('PURCHASE', 'Kayıt Güncelleme', `${id}: ${logMessage}`);
  }, [addSystemLog]);

  // SİLME - KESİN ÇÖZÜM
  const deleteTransaction = useCallback((id: string) => {
    setState(prev => {
      const filtered = prev.transactions.filter(t => t.id !== id);
      return { ...prev, transactions: filtered };
    });
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt Silindi', `${id} nolu dosya imha edildi.`);
  }, [addSystemLog]);

  const handleLogin = (user: User) => setState(prev => ({ ...prev, user }));
  const handleLogout = () => setState(prev => ({ ...prev, user: null }));

  const handleNewRequest = (request: Partial<Transaction>) => {
    const newTrx: Transaction = {
      id: `TRX-${Math.floor(1000 + Math.random() * 9000)}`,
      productSetName: request.productSetName || '',
      supplierName: request.supplierName || '',
      department: request.department || '',
      usageLocation: request.usageLocation || '',
      requesterName: state.user?.name || 'Admin',
      requestDateTime: new Date().toISOString(),
      currency: request.currency || 'TRY',
      priority: request.priority || 'Medium',
      category: request.category || 'Genel',
      quantity: request.quantity || 1,
      unitPrice: request.unitPrice || 0,
      totalAmount: request.totalAmount || 0,
      description: request.description || '',
      justification: request.justification || '',
      microCode: request.microCode || '',
      status: 'Pending',
      photoUrl: request.photoUrl,
      offers: request.offers || [],
      extraItems: request.extraItems || [],
      logs: [{ id: '1', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Oluşturma', details: 'Talep girişi sağlandı.' }],
      approvalFlow: request.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
    };
    setState(prev => ({ ...prev, transactions: [newTrx, ...prev.transactions] }));
    setActiveTab('transactions');
    setStatusFilter('Pending');
  };

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  if (!state.user) return <Login onLogin={handleLogin} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={handleLogout} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
      {selectedTransactionId ? (
        <TransactionDetail 
          transaction={state.transactions.find(t => t.id === selectedTransactionId)!} 
          onBack={() => setSelectedTransactionId(null)} 
          onStatusChange={handleStatusChange} 
          onDelete={deleteTransaction} 
          onUpdate={handleUpdate} 
          currentUserRole={state.user.role} 
        />
      ) : (
        <div className="space-y-12">
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={setStatusFilter} />}
          {activeTab === 'new-request' && <NewRequest onSave={handleNewRequest} departments={state.departments} onAddDepartment={(n) => setState(p => ({ ...p, departments: [...p.departments, n] }))} />}
          {activeTab === 'transactions' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                <div>
                  <h2 className="text-5xl font-black text-white neon-text-premium tracking-tighter uppercase">SÜREÇ YÖNETİMİ</h2>
                  <p className="text-red-600 font-bold text-xs uppercase tracking-widest mt-2">{statusFilter ? statusLabels[statusFilter] : 'TÜM TALEPLER'}</p>
                </div>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5 gap-1">
                  {['TÜMÜ', 'Pending', 'Approved', 'Purchased'].map((s) => (
                    <button 
                      key={s} 
                      onClick={() => setStatusFilter(s === 'TÜMÜ' ? null : s as any)}
                      className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                        (s === 'TÜMÜ' && !statusFilter) || statusFilter === s ? 'bg-red-600 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'
                      }`}
                    >
                      {s === 'TÜMÜ' ? 'TÜMÜ' : statusLabels[s]}
                    </button>
                  ))}
                </div>
              </div>

              {filteredTransactions.length === 0 ? (
                <div className="py-40 text-center glass-panel rounded-[50px] border border-dashed border-white/10 opacity-30">
                  <ImageIcon size={64} className="mx-auto mb-6 text-gray-800" />
                  <p className="text-[10px] font-black uppercase tracking-[0.4em]">KAYIT BULUNAMADI</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                  {filteredTransactions.map((t) => (
                    <div 
                      key={t.id} 
                      onClick={() => setSelectedTransactionId(t.id)} 
                      className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 cursor-pointer relative overflow-hidden group hover:border-red-600/40 transition-all"
                    >
                      <div className="flex justify-between items-start mb-6 relative z-10">
                        <div className="flex flex-col space-y-4">
                           <div className="flex items-center space-x-2">
                             <CalendarDays size={14} className="text-red-600" />
                             <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</span>
                           </div>
                           <div className="w-24 h-24 bg-gradient-to-br from-red-600/20 to-black rounded-3xl flex items-center justify-center font-black text-white shadow-2xl overflow-hidden border border-white/10 group-hover:scale-105 transition-transform duration-500">
                             {t.photoUrl ? <img src={t.photoUrl} className="w-full h-full object-cover" /> : <span className="text-2xl text-red-600">{t.requesterName.charAt(0)}</span>}
                           </div>
                        </div>

                        <div className="flex flex-col items-end space-y-4">
                          <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase border ${
                            t.status === 'Purchased' ? 'bg-green-600/10 text-green-400 border-green-600/20' : 
                            t.status === 'Approved' ? 'bg-cyan-600/10 text-cyan-400 border-cyan-600/20' : 'bg-red-600/10 text-red-400 border-red-600/20'
                          }`}>{statusLabels[t.status]}</span>

                          {/* SİLME BUTONU - EVENT BUBBLING KESİN DURDURMA */}
                          <button 
                            type="button" 
                            onClick={(e) => {
                              e.preventDefault();
                              e.stopPropagation();
                              if (e.nativeEvent) e.nativeEvent.stopImmediatePropagation();

                              if(window.confirm(`DİKKAT! "${t.productSetName}" kaydını tamamen silmek istiyor musunuz?`)) {
                                deleteTransaction(t.id);
                              }
                            }}
                            className="p-5 bg-red-600/20 text-red-600 rounded-2xl border border-red-600/30 hover:bg-red-600 hover:text-white transition-all shadow-xl active:scale-90 relative z-[50]"
                          >
                            <Trash2 size={24} />
                          </button>
                        </div>
                      </div>

                      <h3 className="text-2xl font-black text-white uppercase truncate group-hover:text-red-600 transition-colors">{t.productSetName}</h3>
                      <p className="text-[11px] text-gray-500 font-bold uppercase tracking-widest">{t.department}</p>

                      <div className="flex justify-between items-end border-t border-white/5 pt-6 mt-6">
                         <div>
                            <p className="text-[10px] text-red-950 font-black uppercase tracking-widest opacity-60">TUTAR</p>
                            <p className="text-3xl font-black text-white tracking-tighter">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                         </div>
                         <p className="text-[10px] font-mono text-gray-700 font-bold uppercase tracking-widest">#{t.id}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={handleStatusChange} onDelete={deleteTransaction} />}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => setState(p => ({...p, roles: r}))} departments={state.departments} setDepartments={(d) => setState(p => ({...p, departments: d}))} user={state.user} onUpdateUser={(n) => setState(p => ({...p, user: {...p.user!, name: n}}))} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef, useCallback } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  Info, UserCheck, ShieldCheck, Signature, XCircle, Zap,
  ImagePlus, Trash2, Printer, MessageSquare, FileText, Paperclip, Eye, MapPin,
  AlertCircle
} from 'lucide-react';
import { Transaction, Role } from '../types';
import OfficialForm from './OfficialForm';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [targetRoleForLateProof, setTargetRoleForLateProof] = useState<string | null>(null);
  const [showPrintView, setShowPrintView] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const statusLabels: Record<string, string> = {
    'Pending': 'BEKLİYOR',
    'Approved': 'ONAYLANDI',
    'Purchased': 'SATIN ALINDI',
    'Rejected': 'REDDEDİLDİ',
    'On Hold': 'ERTELENDİ'
  };

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);
  const invoiceInputRef = useRef<HTMLInputElement>(null);

  /**
   * GERİ ÇEKME (UNDO) - KESİN VE SENKRON ÇÖZÜM
   */
  const undoApproval = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();

    if (!window.confirm(`${roleName} onayını geri çekmek istediğinize emin misiniz? Dosya "BEKLİYOR" durumuna geri dönecektir.`)) return;

    // Mevcut akışı al ve ilgili rolün verilerini SIFIRLA
    const updatedFlow = transaction.approvalFlow.map(f => {
      if (f.role === roleName) {
        return {
          ...f,
          status: 'Pending' as const,
          date: undefined,
          type: undefined,
          proofUrl: undefined,
          decisionNote: undefined
        };
      }
      return f;
    });

    // Ana tabloyu anında güncelle (Dosya statüsü PENDING zorlanmalı)
    onUpdate(transaction.id, { 
      approvalFlow: updatedFlow,
      status: 'Pending' 
    }, `${roleName} onayı geri çekildi. Dosya statüsü "BEKLİYOR" yapıldı.`);
  };

  /**
   * GÖRSEL KANIT YÜKLEME (LATE PROOF)
   */
  const triggerLateProof = (e: React.MouseEvent, roleName: string) => {
    e.preventDefault();
    e.stopPropagation();
    setTargetRoleForLateProof(roleName);
    setTimeout(() => {
      if (lateProofInputRef.current) lateProofInputRef.current.click();
    }, 100);
  };

  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && targetRoleForLateProof) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const newFlow = transaction.approvalFlow.map(f => (
          f.role === targetRoleForLateProof ? { 
            ...f, 
            proofUrl: reader.result as string, 
            type: 'Signed' as const, 
            status: 'Approved' as const, 
            date: f.date || new Date().toISOString() 
          } : f
        ));
        onUpdate(transaction.id, { approvalFlow: newFlow }, `${targetRoleForLateProof} belgesi yüklendi.`);
        setTargetRoleForLateProof(null);
      };
      reader.readAsDataURL(file);
    }
    e.target.value = ''; // Aynı dosyayı tekrar seçebilmek için
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;
    const newFlow = transaction.approvalFlow.map(f => (
      f.role === showApprovalModal.role ? {
        ...f,
        status: 'Approved' as const,
        date: new Date().toISOString(),
        type: isSignedApproval ? 'Signed' : 'Normal',
        proofUrl: proofUrl || f.proofUrl,
        decisionNote: decisionNote || undefined
      } : f
    ));
    const allApproved = newFlow.every(f => f.status === 'Approved');
    onUpdate(transaction.id, { 
      approvalFlow: newFlow, 
      status: allApproved ? 'Approved' : transaction.status 
    }, `${showApprovalModal.role} tarafından onay verildi.`);
    setShowApprovalModal(null);
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <div className="w-16 h-16 bg-red-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-xl mb-4">
                    <ShieldCheck size={32} />
                 </div>
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Onay açıklaması yazın</p>
              </div>
              <textarea value={decisionNote} onChange={e => setDecisionNote(e.target.value)} placeholder="Not..." className="w-full p-4 bg-[var(--bg-deep)] border border-[var(--border-grey)] rounded-2xl text-xs text-white min-h-[100px] outline-none" />
              <div className="grid grid-cols-1 gap-4">
                <button type="button" onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">DİJİTAL ONAY <Zap size={16} className="inline ml-2"/></button>
                <button type="button" onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => executeApproval(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} />
              </div>
              <button type="button" onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase tracking-widest">VAZGEÇ</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />

      <div className="flex items-center justify-between gap-4">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <div className="flex items-center space-x-2">
           <button 
             type="button"
             onClick={(e) => { 
                e.preventDefault(); e.stopPropagation();
                if(window.confirm('BU KAYDI TAMAMEN SİLECEKSİNİZ. EMİN MİSİNİZ?')) {
                  onDelete(transaction.id);
                }
             }} 
             className="p-4 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 active:scale-90 shadow-md hover:bg-red-600 hover:text-white transition-all"
           >
              <Trash2 size={24} />
           </button>
           <button onClick={() => setShowPrintView(true)} className="flex items-center space-x-2 px-6 py-3 bg-[var(--bg-panel)] text-[var(--text-main)] border border-[var(--border-grey)] rounded-xl font-black text-[11px] uppercase shadow-lg hover:border-red-600 transition-all">
              <Printer size={16} className="text-red-600" /> <span>RESMİ FORM</span>
           </button>
        </div>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden border-white/5">
        <div className="p-6 lg:p-12 border-b border-[var(--border-grey)] bg-[var(--bg-input)]/30">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <span className="px-2 py-1 bg-red-600/10 text-red-600 rounded-lg text-[10px] font-black">#{transaction.id}</span>
                <span className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-widest">{transaction.department}</span>
              </div>
              <h2 className="text-3xl lg:text-5xl font-black text-[var(--text-main)] uppercase tracking-tighter leading-tight">{transaction.productSetName}</h2>
              <div className="flex items-center space-x-2">
                 <MapPin size={14} className="text-red-600" />
                 <p className="text-[11px] text-white font-black uppercase tracking-tighter">{transaction.usageLocation || 'Konum Bildirilmedi'}</p>
              </div>
            </div>
            <div className="p-6 bg-[var(--bg-deep)] rounded-3xl border border-white/5 text-center lg:text-right min-w-[200px]">
              <p className="text-[10px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA TUTARI</p>
              <h3 className="text-4xl font-black text-[var(--text-main)]">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[9px] text-gray-600 font-black mt-2 uppercase tracking-widest">DURUM: {statusLabels[transaction.status]}</p>
            </div>
          </div>
        </div>

        <div className="p-6 lg:p-12 space-y-16">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-5 space-y-8">
                <h4 className="text-[11px] font-black text-[var(--text-main)] uppercase tracking-[0.2em] border-b border-[var(--border-grey)] pb-4 flex items-center">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ (GERİ ÇEKİLEBİLİR)
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className="space-y-3">
                      <div className={`p-5 rounded-3xl border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/25 shadow-lg shadow-red-600/5' : 'bg-[var(--bg-input)] border-[var(--border-grey)] opacity-60'}`}>
                        <div className="flex items-center space-x-5">
                          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-[var(--bg-deep)] text-gray-500'}`}>
