import React, { useState, useEffect, useMemo, useCallback, useReducer } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus, ArrowUpRight, AlertCircle } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const STORAGE_KEY = 'YASAM_V8_ATOMIC_STABLE';

type Action = 
  | { type: 'SET_USER', user: User | null }
  | { type: 'ADD_TRANSACTION', transaction: Transaction }
  | { type: 'UPDATE_TRANSACTION', id: string, updates: any }
  | { type: 'REVOKE_APPROVAL', id: string, roleName: string } // ÖZEL ATOMIK AKSIYON
  | { type: 'DELETE_TRANSACTION', id: string }
  | { type: 'ADD_SYSTEM_LOG', log: SystemLog }
  | { type: 'SET_ROLES', roles: any[] }
  | { type: 'SET_DEPTS', depts: string[] };

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'SET_USER': return { ...state, user: action.user };
    case 'ADD_TRANSACTION': return { ...state, transactions: [action.transaction, ...state.transactions] };

    case 'DELETE_TRANSACTION': {
      const filtered = state.transactions.filter(t => t.id !== action.id);
      console.log("Atomic Delete Applied:", action.id);
      return { ...state, transactions: [...filtered] };
    }

    case 'UPDATE_TRANSACTION': {
      const updated = state.transactions.map(t => 
        t.id === action.id ? { ...t, ...action.updates, lastUpdated: Date.now() } : t
      );
      return { ...state, transactions: [...updated] };
    }

    case 'REVOKE_APPROVAL': {
      // KRITIK: Geri çekme mantığı reducer içinde atomik olarak yapılır
      const updatedTransactions = state.transactions.map(t => {
        if (t.id === action.id) {
          const newFlow = t.approvalFlow.map(f => {
            if (f.role === action.roleName) {
              return {
                ...f,
                status: 'Pending' as const,
                date: undefined,
                proofUrl: undefined,
                decisionNote: undefined,
                type: undefined
              };
            }
            return f;
          });
          return { ...t, approvalFlow: newFlow, status: 'Pending', lastUpdated: Date.now() };
        }
        return t;
      });
      console.log("Atomic Revoke Applied for:", action.roleName);
      return { ...state, transactions: updatedTransactions };
    }

    case 'ADD_SYSTEM_LOG': return { ...state, systemLogs: [action.log, ...state.systemLogs].slice(0, 100) };
    case 'SET_ROLES': return { ...state, roles: action.roles };
    case 'SET_DEPTS': return { ...state, departments: action.depts };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(reducer, {
    user: null,
    transactions: [],
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: []
  }, () => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
       try {
         const parsed = JSON.parse(saved);
         return { ...parsed, user: null };
       } catch (e) { console.error("Data Parse Error"); }
    }
    return {
      user: null,
      transactions: [],
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Başlatıldı', details: 'V8 Atomic Engine aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const { user, ...persistent } = state;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(persistent));
  }, [state]);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    dispatch({ type: 'ADD_SYSTEM_LOG', log: { id: `SL-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Ziyaretçi', module, action, details } });
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    dispatch({ type: 'UPDATE_TRANSACTION', id, updates });
    if (logMessage) addSystemLog('PURCHASE', 'Güncelleme', `${id}: ${logMessage}`);
  };

  const handleRevoke = (id: string, roleName: string) => {
    dispatch({ type: 'REVOKE_APPROVAL', id, roleName });
    addSystemLog('PURCHASE', 'Onay Geri Çekildi', `${id}: ${roleName} onayı sıfırlandı.`);
  };

  const deleteTransaction = (id: string) => {
    dispatch({ type: 'DELETE_TRANSACTION', id });
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt Silindi', `${id} dosyası imha edildi.`);
  };

  const selectedTransaction = useMemo(() => 
    state.transactions.find(t => t.id === selectedTransactionId),
    [state.transactions, selectedTransactionId]
  );

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={(user) => dispatch({ type: 'SET_USER', user })} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={() => dispatch({ type: 'SET_USER', user: null })} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
      {selectedTransaction ? (
        <TransactionDetail 
          key={selectedTransaction.id + selectedTransaction.lastUpdated} 
          transaction={selectedTransaction} 
          onBack={() => setSelectedTransactionId(null)} 
          onStatusChange={(id, status) => handleUpdate(id, { status })} 
          onDelete={deleteTransaction} 
          onUpdate={handleUpdate}
          onRevoke={handleRevoke}
          currentUserRole={state.user.role} 
        />
      ) : (
        <div className="space-y-12 pb-24">
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={setStatusFilter} />}
          {activeTab === 'new-request' && <NewRequest onSave={(req) => {
            const newTrx: Transaction = {
              id: `TRX-${Math.floor(1000 + Math.random() * 9000)}`,
              lastUpdated: Date.now(),
              productSetName: req.productSetName || '',
              supplierName: req.supplierName || '',
              department: req.department || '',
              usageLocation: req.usageLocation || '',
              requesterName: state.user?.name || 'Admin',
              requestDateTime: new Date().toISOString(),
              currency: req.currency || 'TRY',
              priority: req.priority || 'Medium',
              category: req.category || 'Genel',
              quantity: req.quantity || 1,
              unitPrice: req.unitPrice || 0,
              totalAmount: req.totalAmount || 0,
              description: req.description || '',
              justification: req.justification || '',
              microCode: req.microCode || '',
              status: 'Pending',
              offers: req.offers || [],
              extraItems: req.extraItems || [],
              logs: [{ id: '1', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Giriş', details: 'Talep oluşturuldu.' }],
              approvalFlow: req.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
            };
            dispatch({ type: 'ADD_TRANSACTION', transaction: newTrx });
            setActiveTab('transactions');
            setStatusFilter('Pending');
          }} departments={state.departments} onAddDepartment={(n) => dispatch({ type: 'SET_DEPTS', depts: [...state.departments, n] })} />}

          {activeTab === 'transactions' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.map(t => (
                  <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 relative group hover:border-red-600/40 transition-all shadow-2xl cursor-pointer">
                    <div className="flex justify-between items-start mb-6">
                       <div className="space-y-4">
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</span>
                          <div className="w-16 h-16 bg-red-600/10 rounded-2xl flex items-center justify-center font-black text-red-600 border border-red-600/20">{t.requesterName.charAt(0)}</div>
                       </div>
                       <button onClick={(e) => { e.stopPropagation(); if(confirm('SİLMEK İSTEDİĞİNİZDEN EMİN MİSİNİZ?')) deleteTransaction(t.id); }} className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                          <Trash2 size={24} />
                       </button>
                    </div>
                    <h3 className="text-xl font-black text-white uppercase truncate mb-2">{t.productSetName}</h3>
                    <p className="text-[10px] text-gray-500 font-bold uppercase mb-6">{t.department}</p>
                    <div className="flex justify-between items-end border-t border-white/5 pt-6">
                       <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase ${t.status === 'Purchased' ? 'bg-green-600/10 text-green-400' : 'bg-red-600/10 text-red-400'}`}>{t.status}</span>
                    </div>
                  </div>
                ))}
             </div>
          )}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={(id, s) => handleUpdate(id, {status: s})} onDelete={deleteTransaction} />}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => dispatch({ type: 'SET_ROLES', roles: r })} departments={state.departments} setDepartments={(d) => dispatch({ type: 'SET_DEPTS', depts: d })} user={state.user} onUpdateUser={(n) => dispatch({ type: 'SET_USER', user: {...state.user!, name: n} })} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  ArrowLeft, CheckCircle2, Globe, Store, ExternalLink, BadgeCheck, 
  UserCheck, ShieldCheck, Signature, XCircle, Zap,
  ImagePlus, Trash2, Undo2, AlertCircle, FilePlus
} from 'lucide-react';
import { Transaction, Role } from '../types';

interface TransactionDetailProps {
  transaction: Transaction;
  onBack: () => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<Transaction>, logMessage?: string) => void;
  onRevoke: (id: string, roleName: string) => void; // Yeni prop
  currentUserRole: Role;
}

const TransactionDetail: React.FC<TransactionDetailProps> = ({ 
  transaction, onBack, onStatusChange, onDelete, onUpdate, onRevoke, currentUserRole
}) => {
  const [showLightbox, setShowLightbox] = useState<string | null>(null);
  const [showApprovalModal, setShowApprovalModal] = useState<{ role: string } | null>(null);
  const [lateProofRole, setLateProofRole] = useState<string | null>(null);
  const [isSignedApproval, setIsSignedApproval] = useState(false);
  const [decisionNote, setDecisionNote] = useState('');

  const proofInputRef = useRef<HTMLInputElement>(null);
  const lateProofInputRef = useRef<HTMLInputElement>(null);

  /**
   * ÇİFT DOĞRULAMALI GERİ ÇEKME
   */
  const handleRevokeWithVerify = (roleName: string) => {
    const code = prompt(`DİKKAT! ${roleName} onayını geri çekmek süreci "BEKLEMEDE" durumuna getirecektir.\n\nOnaylıyorsanız lütfen "IPTAL" yazınız:`);
    if (code === 'IPTAL') {
      onRevoke(transaction.id, roleName);
    } else if (code !== null) {
      alert("Hatalı kod girdiniz. İşlem iptal edildi.");
    }
  };

  /**
   * SONRADAN İMZA EKLEME
   */
  const handleLateProofUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !lateProofRole) return;

    const reader = new FileReader();
    reader.onloadend = () => {
      const updatedFlow = transaction.approvalFlow.map(f => (
        f.role === lateProofRole ? { ...f, proofUrl: reader.result as string, type: 'Signed' as const } : f
      ));
      onUpdate(transaction.id, { approvalFlow: [...updatedFlow] }, `${lateProofRole} onayı için ıslak imza belgesi eklendi.`);
      setLateProofRole(null);
    };
    reader.readAsDataURL(file);
  };

  const executeApproval = (proofUrl?: string) => {
    if (!showApprovalModal) return;

    const newFlow = transaction.approvalFlow.map(f => (
      f.role === showApprovalModal.role ? {
        ...f,
        status: 'Approved' as const,
        date: new Date().toISOString(),
        type: isSignedApproval ? 'Signed' : 'Normal',
        proofUrl: proofUrl || f.proofUrl,
        decisionNote: decisionNote || undefined
      } : f
    ));

    const allApproved = newFlow.every(f => f.status === 'Approved');

    onUpdate(transaction.id, { 
      approvalFlow: [...newFlow], 
      status: allApproved ? 'Approved' : transaction.status 
    }, `${showApprovalModal.role} onayı kaydedildi.`);

    setShowApprovalModal(null);
    setDecisionNote('');
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6 pb-24">
      {/* Lightbox & Modals */}
      {showLightbox && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-3xl" onClick={() => setShowLightbox(null)}>
           <img src={showLightbox} className="max-w-full max-h-[85vh] rounded-xl object-contain shadow-2xl border border-white/10" />
           <button className="absolute top-6 right-6 p-3 text-white bg-red-600 rounded-full shadow-lg"><XCircle size={28}/></button>
        </div>
      )}

      {showApprovalModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
           <div className="w-full max-w-lg glass-panel p-10 rounded-[40px] border-red-600/30 space-y-6 animate-in zoom-in">
              <div className="text-center space-y-2">
                 <ShieldCheck size={48} className="text-red-600 mx-auto mb-4" />
                 <h3 className="text-xl font-black text-white uppercase tracking-tighter">{showApprovalModal.role} ONAYI</h3>
                 <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Lütfen bir onay tipi seçin</p>
              </div>
              <textarea value={decisionNote} onChange={e => setDecisionNote(e.target.value)} placeholder="Onay notu (isteğe bağlı)..." className="w-full p-4 bg-black/50 border border-white/10 rounded-2xl text-xs text-white min-h-[100px] outline-none" />
              <div className="grid grid-cols-1 gap-4">
                <button type="button" onClick={() => { setIsSignedApproval(false); executeApproval(); }} className="p-5 bg-red-600 text-white rounded-2xl font-black uppercase text-[11px] shadow-xl hover:bg-red-500 transition-all">SÖZLÜ / DİJİTAL ONAY <Zap size={16} className="inline ml-2"/></button>
                <button type="button" onClick={() => { setIsSignedApproval(true); proofInputRef.current?.click(); }} className="p-5 bg-white/5 border border-white/10 text-white rounded-2xl font-black uppercase text-[11px] hover:bg-white/10 transition-all">ISLAK İMZA/BELGE YÜKLE <Signature size={16} className="inline ml-2"/></button>
                <input type="file" ref={proofInputRef} className="hidden" accept="image/*" onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => executeApproval(reader.result as string);
                    reader.readAsDataURL(file);
                  }
                }} />
              </div>
              <button type="button" onClick={() => setShowApprovalModal(null)} className="w-full py-2 text-[10px] font-black text-gray-500 uppercase tracking-widest">KAPAT</button>
           </div>
        </div>
      )}

      <input type="file" ref={lateProofInputRef} className="hidden" accept="image/*" onChange={handleLateProofUpload} />

      <div className="flex items-center justify-between">
        <button onClick={onBack} className="flex items-center space-x-2 text-red-600 font-black text-[11px] uppercase group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> <span>PANELE DÖN</span>
        </button>
        <button 
           onClick={() => { if(confirm('KALICI OLARAK SİLMEK İSTİYOR MUSUNUZ?')) onDelete(transaction.id); }}
           className="p-4 bg-red-600/10 text-red-600 rounded-xl border border-red-600/10 hover:bg-red-600 hover:text-white transition-all shadow-md active:scale-90"
        >
           <Trash2 size={24} />
        </button>
      </div>

      <div className="glass-panel rounded-[35px] overflow-hidden border-white/5 shadow-2xl">
        <div className="p-12 border-b border-white/5 bg-white/2">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6">
            <div className="space-y-3">
              <span className="text-[10px] font-black text-red-600 uppercase tracking-widest">DOSYA NO: #{transaction.id}</span>
              <h2 className="text-4xl lg:text-5xl font-black text-white uppercase tracking-tighter leading-none">{transaction.productSetName}</h2>
              <p className="text-[11px] text-gray-500 font-bold uppercase tracking-[0.2em]">{transaction.department}</p>
            </div>
            <div className="p-8 bg-black/40 rounded-3xl border border-white/5 text-center lg:text-right shadow-2xl min-w-[220px]">
              <p className="text-[9px] text-red-600 font-black uppercase tracking-widest mb-1">DOSYA TUTARI</p>
              <h3 className="text-4xl font-black text-white">₺{transaction.totalAmount.toLocaleString('tr-TR')}</h3>
              <p className="text-[8px] text-gray-700 font-black mt-2 uppercase tracking-[0.3em]">{transaction.status}</p>
            </div>
          </div>
        </div>

        <div className="p-12">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
             <div className="lg:col-span-7 space-y-8">
                <h4 className="text-[10px] font-black text-white uppercase tracking-[0.3em] flex items-center border-b border-white/5 pb-4">
                   <ShieldCheck size={20} className="mr-3 text-red-600" /> ONAY ZİNCİRİ VE YETKİLER
                </h4>
                <div className="space-y-6">
                  {transaction.approvalFlow.map((flow, idx) => (
                    <div key={idx} className={`p-6 rounded-[30px] border transition-all ${flow.status === 'Approved' ? 'bg-red-600/5 border-red-600/30 shadow-lg' : 'bg-white/2 border-white/5'}`}>
                      <div className="flex items-center space-x-6">
                        <div 
                          className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${flow.status === 'Approved' ? 'bg-red-600 text-white shadow-xl' : 'bg-black/40 text-gray-500'} ${flow.proofUrl ? 'cursor-pointer' : ''}`} 
                          onClick={() => flow.proofUrl && setShowLightbox(flow.proofUrl)}
                        >
                           {flow.status === 'Approved' ? <BadgeCheck size={32} /> : <UserCheck size={32} />}
                        </div>
                        <div className="flex-1 min-w-0">
                           <div className="flex items-center justify-between mb-1">
                              <p className="text-sm font-black text-white uppercase truncate">{flow.role}</p>
                              <div className="flex items-center space-x-2">
                                 {flow.status === 'Approved' ? (
                                    <div className="flex items-center space-x-2">
                                       {!flow.proofUrl && (
                                          <button 
                                            onClick={() => { setLateProofRole(flow.role); lateProofInputRef.current?.click(); }}
                                            className="px-3 py-2 bg-blue-600/10 text-blue-500 rounded-xl text-[9px] font-black uppercase hover:bg-blue-600 hover:text-white transition-all shadow-sm"
                                          >
                                             <FilePlus size={12} className="inline mr-1" /> BELGE EKLE
                                          </button>
                                       )}
                                       <button 
                                          onClick={() => handleRevokeWithVerify(flow.role)} 
                                          className="px-3 py-2 bg-red-600/10 text-red-600 rounded-xl text-[9px] font-black uppercase hover:bg-red-600 hover:text-white transition-all shadow-sm active:scale-95"
                                       >
                                          <Undo2 size={12} className="inline mr-1" /> GERİ ÇEK
                                       </button>
                                    </div>
                                 ) : (
                                   <button 
                                     onClick={() => setShowApprovalModal({ role: flow.role })} 
                                     className="px-6 py-3 bg-red-600 text-white rounded-xl text-[10px] font-black uppercase shadow-lg active:scale-95 transition-all"
                                   >
                                     ONAY VER
                                   </button>
                                 )}
                              </div>
                           </div>
                           <p className="text-[10px] text-gray-500 font-bold uppercase truncate tracking-widest">{flow.approverName}</p>
                           <div className="flex items-center mt-2 space-x-3">
                              <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${flow.status === 'Approved' ? (flow.type === 'Signed' ? 'bg-green-600 text-white' : 'bg-red-600/20 text-red-400') : 'bg-gray-800 text-gray-500'}`}>
                                 {flow.status === 'Approved' ? (flow.type === 'Signed' ? 'BELGELİ ONAY' : 'SÖZLÜ ONAY') : 'BEKLİYOR'}
                              </span>
                              {flow.date && <span className="text-[8px] text-gray-600 font-mono italic">{new Date(flow.date).toLocaleString('tr-TR')}</span>}
                           </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
             </div>

             <div className="lg:col-span-5 space-y-12">
                <div className="bg-red-600/5 p-8 rounded-[40px] border border-red-600/15 text-center space-y-6">
                   <AlertCircle size={32} className="text-red-600 mx-auto" />
                   <div className="space-y-2">
                      <p className="text-[11px] font-black text-red-600 uppercase tracking-[0.2em]">FİNALİZASYON</p>
                      <p className="text-[9px] text-gray-500 uppercase font-bold">İşlem kapandıysa aşağıyı onaylayın.</p>
                   </div>
                   <button 
                      onClick={() => onStatusChange(transaction.id, 'Purchased')} 
                      className={`w-full py-6 rounded-[30px] font-black uppercase text-[11px] shadow-2xl active:scale-95 transition-all ${transaction.status === 'Purchased' ? 'bg-green-600 text-white' : 'bg-red-600 text-white hover:bg-red-500'}`}
                    >
                      {transaction.status === 'Purchased' ? 'OPERASYON TAMAMLANDI' : 'SATIN ALINDI OLARAK KAPAT'}
                   </button>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TransactionDetail;

import React, { useState, useMemo } from 'react';
import { 
  Archive, Filter, Calendar, ChevronLeft, ChevronRight, 
  Search, ArrowUpRight, Download, FileText, CheckCircle2, 
  Clock, XCircle, MoreVertical, LayoutGrid, List, Database,
  AlertTriangle, Trash2
} from 'lucide-react';
import { Transaction } from '../types';

interface ArchiveProps {
  transactions: Transaction[];
  onSelectTransaction: (id: string) => void;
  onStatusChange: (id: string, newStatus: Transaction['status']) => void;
  onDelete: (id: string) => void;
}

const ArchiveView: React.FC<ArchiveProps> = ({ transactions, onSelectTransaction, onStatusChange, onDelete }) => {
  const currentYearNum = new Date().getFullYear();
  const [selectedYear, setSelectedYear] = useState<string>(currentYearNum.toString());
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 12;

  const years = useMemo(() => {
    const yearsFromData = new Set<string>(transactions.map(t => new Date(t.requestDateTime).getFullYear().toString()));
    for (let y = 2024; y <= 2030; y++) yearsFromData.add(y.toString());
    return Array.from(yearsFromData).sort((a, b) => b.localeCompare(a));
  }, [transactions]);

  const filteredData = useMemo(() => {
    return transactions.filter(t => {
      const date = new Date(t.requestDateTime);
      return date.getFullYear().toString() === selectedYear;
    }).sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [transactions, selectedYear]);

  const totalPages = Math.ceil(filteredData.length / itemsPerPage);
  const paginatedData = filteredData.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Bu kayıt arşivden KALICI olarak silinecektir. Devam edilsin mi?")) {
      onDelete(id);
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 pb-20">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-8">
        <div>
          <h2 className="text-4xl font-black text-white neon-text-red uppercase tracking-tighter leading-none">KURUMSAL ARŞİV</h2>
          <p className="text-gray-600 font-bold text-[10px] uppercase tracking-[0.4em] mt-3">Sistem Kayıtları Veritabanı</p>
        </div>
        <div className="flex bg-white/5 p-1 rounded-2xl border border-white/5">
          {years.map(y => (
            <button key={y} onClick={() => { setSelectedYear(y); setCurrentPage(1); }} className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${selectedYear === y ? 'bg-red-600 text-white' : 'text-gray-600 hover:text-white'}`}>{y}</button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {paginatedData.map(t => (
          <div key={t.id} onClick={() => onSelectTransaction(t.id)} className="glass-panel p-8 rounded-[40px] border-white/5 hover:border-red-600/30 transition-all cursor-pointer group shadow-xl relative overflow-hidden">
             <div className="flex justify-between items-start mb-6">
                <span className="text-[8px] font-black text-gray-700 uppercase">#{t.id}</span>
                <button onClick={(e) => handleDelete(e, t.id)} className="text-gray-800 hover:text-red-600 p-2 relative z-20"><Trash2 size={16} /></button>
             </div>
             <h4 className="text-lg font-black text-white uppercase truncate mb-1 group-hover:text-red-500 transition-colors">{t.productSetName}</h4>
             <p className="text-[9px] text-gray-600 font-bold uppercase">{t.department}</p>
             <div className="mt-8 pt-4 border-t border-white/5 flex justify-between items-end">
                <p className="text-xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                <p className={`text-[8px] font-black uppercase ${t.status === 'Purchased' ? 'text-green-600' : 'text-gray-700'}`}>{t.status}</p>
             </div>
          </div>
        ))}
      </div>

      {paginatedData.length === 0 && (
         <div className="py-40 text-center opacity-20"><Database size={48} className="mx-auto mb-4" /><p className="font-black text-xs uppercase tracking-[0.4em]">Kayit Bulunamadi</p></div>
      )}

      {totalPages > 1 && (
        <div className="flex justify-center space-x-4 pt-10">
          <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} className="p-4 glass-panel rounded-xl"><ChevronLeft size={16}/></button>
          <div className="flex items-center px-6 text-xs font-black text-white">{currentPage} / {totalPages}</div>
          <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} className="p-4 glass-panel rounded-xl"><ChevronRight size={16}/></button>
        </div>
      )}
    </div>
  );
};

