import React, { useState, useEffect, useMemo, useCallback, useReducer } from 'react';
import { Search, Heart, Trash2, CalendarDays, Image as ImageIcon, Plus, ArrowUpRight, AlertCircle } from 'lucide-react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewRequest from './components/NewRequest';
import TransactionDetail from './components/TransactionDetail';
import ArchiveView from './components/Archive';
import Settings from './components/Settings';
import Reports from './components/Reports';
import Login from './components/Login';
import { AppState, Transaction, User, SystemLog } from './types';
import { INITIAL_ROLES, INITIAL_DEPARTMENTS } from './constants';

const STORAGE_KEY = 'YASAM_V8_ATOMIC_STABLE';

type Action = 
  | { type: 'SET_USER', user: User | null }
  | { type: 'ADD_TRANSACTION', transaction: Transaction }
  | { type: 'UPDATE_TRANSACTION', id: string, updates: any }
  | { type: 'REVOKE_APPROVAL', id: string, roleName: string, reason: string } 
  | { type: 'DELETE_TRANSACTION', id: string }
  | { type: 'ADD_SYSTEM_LOG', log: SystemLog }
  | { type: 'SET_ROLES', roles: any[] }
  | { type: 'SET_DEPTS', depts: string[] };

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'SET_USER': return { ...state, user: action.user };
    case 'ADD_TRANSACTION': return { ...state, transactions: [action.transaction, ...state.transactions] };

    case 'DELETE_TRANSACTION': {
      const filtered = state.transactions.filter(t => t.id !== action.id);
      return { ...state, transactions: [...filtered] };
    }

    case 'UPDATE_TRANSACTION': {
      const updated = state.transactions.map(t => 
        t.id === action.id ? { ...t, ...action.updates, lastUpdated: Date.now() } : t
      );
      return { ...state, transactions: [...updated] };
    }

    case 'REVOKE_APPROVAL': {
      const updatedTransactions: Transaction[] = state.transactions.map(t => {
        if (t.id === action.id) {
          const newFlow = t.approvalFlow.map(f => {
            if (f.role === action.roleName) {
              return {
                ...f,
                status: 'Pending' as const,
                date: undefined,
                proofUrl: undefined,
                decisionNote: undefined,
                type: undefined,
                lastRevokeReason: action.reason, // Sebebi buraya mühürle
                lastRevokeDate: new Date().toISOString()
              };
            }
            return f;
          });

          const newLog = {
            id: `L-${Date.now()}`,
            timestamp: new Date().toISOString(),
            user: state.user?.name || 'Sistem',
            action: 'ONAY GERİ ÇEKİLDİ',
            details: `${action.roleName} onayı geri çekildi. GEREKÇE: ${action.reason}`
          };

          return { 
            ...t, 
            approvalFlow: newFlow, 
            status: 'Pending' as const, 
            lastUpdated: Date.now(),
            logs: [newLog, ...t.logs]
          };
        }
        return t;
      });
      return { ...state, transactions: updatedTransactions };
    }

    case 'ADD_SYSTEM_LOG': return { ...state, systemLogs: [action.log, ...state.systemLogs].slice(0, 100) };
    case 'SET_ROLES': return { ...state, roles: action.roles };
    case 'SET_DEPTS': return { ...state, departments: action.depts };
    default: return state;
  }
}

const App: React.FC = () => {
  const [state, dispatch] = useReducer(reducer, {
    user: null,
    transactions: [],
    roles: INITIAL_ROLES,
    departments: INITIAL_DEPARTMENTS,
    systemLogs: []
  }, () => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
       try {
         const parsed = JSON.parse(saved);
         return { ...parsed, user: null };
       } catch (e) { console.error("Data Parse Error"); }
    }
    return {
      user: null,
      transactions: [],
      roles: INITIAL_ROLES,
      departments: INITIAL_DEPARTMENTS,
      systemLogs: [{ id: '1', timestamp: new Date().toISOString(), user: 'Sistem', module: 'AUTH', action: 'Başlatıldı', details: 'V8 Atomic Engine aktif.' }]
    };
  });

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedTransactionId, setSelectedTransactionId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const { user, ...persistent } = state;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(persistent));
  }, [state]);

  const addSystemLog = (module: SystemLog['module'], action: string, details: string) => {
    dispatch({ type: 'ADD_SYSTEM_LOG', log: { id: `SL-${Date.now()}`, timestamp: new Date().toISOString(), user: state.user?.name || 'Ziyaretçi', module, action, details } });
  };

  const handleUpdate = (id: string, updates: Partial<Transaction>, logMessage?: string) => {
    dispatch({ type: 'UPDATE_TRANSACTION', id, updates });
    if (logMessage) addSystemLog('PURCHASE', 'Güncelleme', `${id}: ${logMessage}`);
  };

  const handleRevoke = (id: string, roleName: string, reason: string) => {
    dispatch({ type: 'REVOKE_APPROVAL', id, roleName, reason });
    addSystemLog('PURCHASE', 'Onay Geri Çekildi', `${id}: ${roleName} onayı sıfırlandı. Neden: ${reason}`);
  };

  const deleteTransaction = (id: string) => {
    dispatch({ type: 'DELETE_TRANSACTION', id });
    setSelectedTransactionId(null);
    addSystemLog('PURCHASE', 'Kayıt Silindi', `${id} dosyası imha edildi.`);
  };

  const selectedTransaction = useMemo(() => 
    state.transactions.find(t => t.id === selectedTransactionId),
    [state.transactions, selectedTransactionId]
  );

  const filteredTransactions = useMemo(() => {
    let list = [...state.transactions];
    if (statusFilter) list = list.filter(t => t.status === statusFilter);
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      list = list.filter(t => t.productSetName.toLowerCase().includes(q) || t.id.toLowerCase().includes(q));
    }
    return list.sort((a, b) => new Date(b.requestDateTime).getTime() - new Date(a.requestDateTime).getTime());
  }, [state.transactions, statusFilter, searchQuery]);

  if (!state.user) return <Login onLogin={(user) => dispatch({ type: 'SET_USER', user })} />;

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => { setActiveTab(tab); setSelectedTransactionId(null); }} user={state.user} onLogout={() => dispatch({ type: 'SET_USER', user: null })} searchQuery={searchQuery} setSearchQuery={setSearchQuery}>
      {selectedTransaction ? (
        <TransactionDetail 
          key={selectedTransaction.id + selectedTransaction.lastUpdated} 
          transaction={selectedTransaction} 
          onBack={() => setSelectedTransactionId(null)} 
          onStatusChange={(id, status) => handleUpdate(id, { status })} 
          onDelete={deleteTransaction} 
          onUpdate={handleUpdate}
          onRevoke={handleRevoke}
          currentUserRole={state.user.role} 
        />
      ) : (
        <div className="space-y-12 pb-24">
          {activeTab === 'dashboard' && <Dashboard transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onFilterClick={setStatusFilter} />}
          {activeTab === 'new-request' && <NewRequest onSave={(req) => {
            const newTrx: Transaction = {
              id: `TRX-${Math.floor(1000 + Math.random() * 9000)}`,
              lastUpdated: Date.now(),
              productSetName: req.productSetName || '',
              supplierName: req.supplierName || '',
              department: req.department || '',
              usageLocation: req.usageLocation || '',
              requesterName: state.user?.name || 'Admin',
              requestDateTime: new Date().toISOString(),
              currency: req.currency || 'TRY',
              priority: req.priority || 'Medium',
              category: req.category || 'Genel',
              quantity: req.quantity || 1,
              unitPrice: req.unitPrice || 0,
              totalAmount: req.totalAmount || 0,
              description: req.description || '',
              justification: req.justification || '',
              microCode: req.microCode || '',
              status: 'Pending',
              offers: req.offers || [],
              extraItems: req.extraItems || [],
              logs: [{ id: '1', timestamp: new Date().toISOString(), user: state.user?.name || 'Sistem', action: 'Giriş', details: 'Talep oluşturuldu.' }],
              approvalFlow: req.approvalFlow || state.roles.map(r => ({ role: r.roleName, status: 'Pending', approverName: r.assignedName }))
            };
            dispatch({ type: 'ADD_TRANSACTION', transaction: newTrx });
            setActiveTab('transactions');
            setStatusFilter('Pending');
          }} departments={state.departments} onAddDepartment={(n) => dispatch({ type: 'SET_DEPTS', depts: [...state.departments, n] })} />}

          {activeTab === 'transactions' && (
             <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {filteredTransactions.map(t => (
                  <div key={t.id} onClick={() => setSelectedTransactionId(t.id)} className="cyber-card glass-panel p-8 rounded-[40px] border border-white/5 relative group hover:border-red-600/40 transition-all shadow-2xl cursor-pointer">
                    <div className="flex justify-between items-start mb-6">
                       <div className="space-y-4">
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{new Date(t.requestDateTime).toLocaleDateString('tr-TR')}</span>
                          <div className="w-16 h-16 bg-red-600/10 rounded-2xl flex items-center justify-center font-black text-red-600 border border-red-600/20">{t.requesterName.charAt(0)}</div>
                       </div>
                       <button onClick={(e) => { e.stopPropagation(); if(confirm('SİLMEK İSTEDİĞİNİZDEN EMİN MİSİNİZ?')) deleteTransaction(t.id); }} className="p-4 bg-red-600/10 text-red-600 rounded-2xl border border-red-600/20 hover:bg-red-600 hover:text-white transition-all">
                          <Trash2 size={24} />
                       </button>
                    </div>
                    <h3 className="text-xl font-black text-white uppercase truncate mb-2">{t.productSetName}</h3>
                    <p className="text-[10px] text-gray-500 font-bold uppercase mb-6">{t.department}</p>
                    <div className="flex justify-between items-end border-t border-white/5 pt-6">
                       <p className="text-2xl font-black text-white">₺{t.totalAmount.toLocaleString('tr-TR')}</p>
                       <span className={`px-3 py-1.5 rounded-xl text-[9px] font-black uppercase ${t.status === 'Purchased' ? 'bg-green-600/10 text-green-400' : 'bg-red-600/10 text-red-400'}`}>{t.status}</span>
                    </div>
                  </div>
                ))}
             </div>
          )}
          {activeTab === 'reports' && <Reports transactions={state.transactions} />}
          {activeTab === 'archive' && <ArchiveView transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} onStatusChange={(id, s) => handleUpdate(id, {status: s})} onDelete={deleteTransaction} />}
          {activeTab === 'settings' && <Settings roles={state.roles} setRoles={(r) => dispatch({ type: 'SET_ROLES', roles: r })} departments={state.departments} setDepartments={(d) => dispatch({ type: 'SET_DEPTS', depts: d })} user={state.user} onUpdateUser={(n) => dispatch({ type: 'SET_USER', user: {...state.user!, name: n} })} systemLogs={state.systemLogs} transactions={state.transactions} onSelectTransaction={setSelectedTransactionId} />}
        </div>
      )}
    </Layout>
  );
};

