  { s: 'NMNA023187', ip: '136', m: 'LBP251DW', l: 'GÜZELLİK MERKEZİ', sc: '1031' },
  { s: '34X36824', ip: '143', m: 'iR1643i', l: 'İNSAN KAYNAKLARI YENİ', sc: '1032' }, 
  { s: 'NMNA020231', ip: '-', m: 'LBP251DW', l: 'İNSAN KAYNAKLARI(yedek)', sc: '1033' }, 
  { s: 'NMNA020234', ip: 'USB', m: 'LBP251DW', l: 'İŞİTME TESTİ (ODİO)', sc: '1034' },
  { s: 'NMNA023180', ip: 'USB', m: 'LBP251DW', l: 'HASTA HAKLARI YAPRAK', sc: '1035' },
  { s: '34X36821', ip: '135', m: 'iR1643i', l: 'OZLSGRTOSS', sc: '1036' },
  { s: 'NQGA077960', ip: '157', m: 'LBP223DW', l: 'OZLSGRT2', sc: '1037' },
  { s: 'NMNA023495', ip: 'USB', m: 'LBP251DW', l: 'KALİTE ODASI', sc: '1038' }, 
  { s: '34M25642', ip: '160', m: 'MF645C', l: 'Sağlık Turizmi', sc: '1039' }, 
  { s: 'JA4B8254', ip: 'USB', m: 'DR-C230', l: 'OZLSGRT-DIDEM', sc: '1040' }
];

export const Settings: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>({ brands: [], models: [], suppliers: [], tonerModels: [], brandImages: {}, modelImages: {}, appUrl: '' });
  const [printers, setPrinters] = useState<PrinterType[]>([]);
  const [loading, setLoading] = useState(true);

  const [showImportConfirm, setShowImportConfirm] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [isFixingCodes, setIsFixingCodes] = useState(false);
  const [isSavingUrl, setIsSavingUrl] = useState(false);

  const [newBrand, setNewBrand] = useState('');
  const [newBrandImage, setNewBrandImage] = useState('');
  const [newModel, setNewModel] = useState('');
  const [newModelImage, setNewModelImage] = useState('');
  const [newSupplier, setNewSupplier] = useState('');
  const [newTonerModel, setNewTonerModel] = useState('');
  const [whatsappNumber, setWhatsappNumber] = useState('');
  const [appUrl, setAppUrl] = useState('');

  const [editModal, setEditModal] = useState<{ type: ConfigType, oldVal: string, newVal: string, newImage?: string } | null>(null);
  const [deleteModal, setDeleteModal] = useState<{ type: ConfigType, val: string } | null>(null);

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    setLoading(true);
    const c = await StorageService.getConfig();
    const p = await StorageService.getPrinters();
    setConfig(c);
    setWhatsappNumber(c.whatsappNumber || '');
    setAppUrl(c.appUrl || '');
    setPrinters(p);
    setLoading(false);
  };

  const handleSaveAppUrl = async () => {
    const trimmedUrl = appUrl.trim();
    if (!trimmedUrl) {
        alert('Lütfen geçerli bir URL giriniz.');
        return;
    }

    setIsSavingUrl(true);
    try {
        const updatedConfig = { ...config, appUrl: trimmedUrl };
        await StorageService.saveConfig(updatedConfig);
        setConfig(updatedConfig);
        alert('Uygulama URL adresi başarıyla kaydedildi.');
        loadData();
    } catch (e) {
        alert('Kaydetme sırasında bir hata oluştu.');
    } finally {
        setIsSavingUrl(false);
    }
  };

  const handleInitialImport = async () => {
    setShowImportConfirm(false);
    setIsImporting(true);
    try {
        let count = 0;
        for (const item of INITIAL_PRINTER_DATA) {
            const isUsb = item.ip === 'USB' || item.ip === '-' || item.ip === '' || item.ip === null;
            const connectionType = isUsb ? 'USB' : 'Network';
            let ipAddress = '';
            if (!isUsb) { ipAddress = item.ip.length <= 3 ? `192.168.1.${item.ip}` : item.ip; }
            const newPrinter: PrinterType = {
                id: '',
                serialNumber: item.s,
                shortCode: item.sc,
                brand: 'Canon',
                model: item.m,
                location: item.l,
                floor: 'Giriş/Poliklinik',
                lastCounter: 0,
                lastTonerDate: new Date().toISOString(),
                compatibleToner: '',
                connectionType,
                ipAddress,
                supplier: 'Anahtar Bilgisayar',
                status: 'ACTIVE',
                connectedUsers: [],
                monthlyRentalCost: 0
            };
            await StorageService.addPrinter(newPrinter);
            count++;
            setImportProgress(count);
            await new Promise(resolve => setTimeout(resolve, 30));
        }
        await loadData();
        alert(`Toplam ${count} adet yazıcı sisteme kaydedildi.`);
    } catch (e) { alert('İçe aktarma hatası.'); } finally { setIsImporting(false); }
  };

  const handleFixCodes = async () => {
    if (!confirm("Eksik kodlar otomatik tamamlanacak?")) return;
    setIsFixingCodes(true);
    try {
      const count = await StorageService.fixMissingShortCodes();
      await loadData();
      alert(`Onarım tamamlandı. ${count} ünite güncellendi.`);
    } catch (e) { alert("Hata oluştu."); } finally { setIsFixingCodes(false); }
  };

  const handleAddItem = async (e: React.FormEvent, type: ConfigType, value: string, setter: (s: string) => void, imageValue?: string, imageSetter?: (s: string) => void) => {
    e.preventDefault();
    const val = value.trim();
    if (val && !config[type].includes(val)) {
      let updated = { ...config, [type]: [...config[type], val] };
      if (imageValue && (type === 'brands' || type === 'models')) {
         const imgMapKey = type === 'brands' ? 'brandImages' : 'modelImages';
         updated = { ...updated, [imgMapKey]: { ...(updated[imgMapKey as keyof SystemConfig] as Record<string, string>), [val]: imageValue.trim() } };
      }
      await StorageService.saveConfig(updated);
      setConfig(updated);
      setter('');
      if (imageSetter) imageSetter('');
    }
  };

  const openEdit = (type: ConfigType, oldVal: string) => {
    let currentImage = '';
    if (type === 'brands') currentImage = config.brandImages?.[oldVal] || '';
    if (type === 'models') currentImage = config.modelImages?.[oldVal] || '';
    setEditModal({ type, oldVal, newVal: oldVal, newImage: currentImage });
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editModal || !editModal.newVal.trim()) return;
    const { type, oldVal, newVal, newImage } = editModal;
    const trimmedNewVal = newVal.trim();
    const updatedList = config[type].map(item => item === oldVal ? trimmedNewVal : item);
    let updatedConfig = { ...config, [type]: updatedList };

    if (type === 'brands' || type === 'models') {
        const mapKey = type === 'brands' ? 'brandImages' : 'modelImages';
        const currentMap = { ...(updatedConfig[mapKey] || {}) };
        if (oldVal !== trimmedNewVal) delete currentMap[oldVal];
        if (newImage) currentMap[trimmedNewVal] = newImage.trim();
        else delete currentMap[trimmedNewVal];
        updatedConfig = { ...updatedConfig, [mapKey]: currentMap };
    }

    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);

    if (oldVal !== trimmedNewVal) {
        for (const p of printers) {
            let changed = false;
            let newP = { ...p };
            if (type === 'brands' && p.brand === oldVal) { newP.brand = trimmedNewVal; changed = true; }
            if (type === 'models' && p.model === oldVal) { newP.model = trimmedNewVal; changed = true; }
            if (type === 'suppliers' && p.supplier === oldVal) { newP.supplier = trimmedNewVal; changed = true; }
            if (type === 'tonerModels' && p.compatibleToner === oldVal) { newP.compatibleToner = trimmedNewVal; changed = true; }
            if (changed) await StorageService.updatePrinter(newP);
        }
        await loadData();
    }
    setEditModal(null);
  };

  const openDelete = (type: ConfigType, val: string) => setDeleteModal({ type, val });

  const handleDelete = async () => {
    if (!deleteModal) return;
    const { type, val } = deleteModal;
    const updatedList = config[type].filter(item => item !== val);
    let updatedConfig = { ...config, [type]: updatedList };
    if (type === 'brands' && updatedConfig.brandImages) {
        const newImages = {...updatedConfig.brandImages};
        delete newImages[val];
        updatedConfig.brandImages = newImages;
    }
    if (type === 'models' && updatedConfig.modelImages) {
        const newImages = {...updatedConfig.modelImages};
        delete newImages[val];
        updatedConfig.modelImages = newImages;
    }
    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    setDeleteModal(null);
  };

  const handleSaveWhatsapp = async () => {
    const updatedConfig = { ...config, whatsappNumber: whatsappNumber };
    await StorageService.saveConfig(updatedConfig);
    setConfig(updatedConfig);
    alert('Numara kaydedildi.');
  };

  const renderList = (type: ConfigType, items: string[]) => (
    <div className="space-y-2 max-h-64 overflow-y-auto pr-1 custom-scrollbar">
      {items.map((item, idx) => (
        <div key={`${item}-${idx}`} className="flex justify-between items-center p-3 bg-zinc-50 dark:bg-zinc-900 rounded-xl border border-zinc-100 dark:border-zinc-800 group hover:shadow-sm transition-all">
          <div className="flex items-center gap-3 min-w-0">
              {(type === 'brands' || type === 'models') && (
                  <div className="w-10 h-10 rounded-lg bg-white dark:bg-zinc-800 border border-zinc-100 dark:border-zinc-700 flex items-center justify-center overflow-hidden shrink-0">
                      {(type === 'brands' ? config.brandImages?.[item] : config.modelImages?.[item]) ? (
                          <img src={type === 'brands' ? config.brandImages?.[item] : config.modelImages?.[item]} alt={item} className="w-full h-full object-contain p-1" />
                      ) : (
                          <Printer size={16} className="text-zinc-300 dark:text-zinc-600" />
                      )}
                  </div>
              )}
              {type === 'tonerModels' && <div className="p-2 bg-orange-50 dark:bg-orange-950/40 text-orange-500 rounded-lg shrink-0"><Droplet size={16}/></div>}
              {type === 'suppliers' && <div className="p-2 bg-blue-50 dark:bg-blue-950/40 text-blue-500 rounded-lg shrink-0"><Truck size={16}/></div>}
              <span className="font-black text-xs text-zinc-700 dark:text-zinc-200 uppercase truncate">{item}</span>
          </div>
          <div className="flex gap-2 shrink-0">
              <button type="button" onClick={() => openEdit(type, item)} className="p-2 bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400 rounded-lg active:scale-90 transition-all"><Edit2 size={16} /></button>
              <button type="button" onClick={() => openDelete(type, item)} className="p-2 bg-red-50 text-red-600 dark:bg-red-950/30 dark:text-red-400 rounded-lg active:scale-90 transition-all"><Trash2 size={16} /></button>
          </div>
        </div>
      ))}
      {items.length === 0 && <p className="text-[10px] text-zinc-400 text-center py-6 font-bold uppercase italic tracking-widest">Kayıt Bulunmuyor</p>}
    </div>
  );

  if (loading) return <LoadingScreen message="Sistem ayarları yükleniyor..." />;

  return (
    <div className="space-y-8 pb-32 animate-in fade-in duration-700">
      <div className="bg-white dark:bg-zinc-950 p-6 rounded-[2.5rem] shadow-xl border border-zinc-100 dark:border-zinc-900 flex justify-between items-center">
        <div className="flex items-center gap-4">
            <div className="p-3 bg-emerald-500/10 text-emerald-500 rounded-2xl"><Save size={28}/></div>
            <h2 className="text-2xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">Sistem Konfigürasyonu</h2>
        </div>
        <button onClick={loadData} className="p-3 bg-zinc-100 dark:bg-zinc-800 text-zinc-500 rounded-2xl hover:text-emerald-500 transition-all active:rotate-180"><RefreshCw size={24} /></button>
      </div>

      {/* URL VE WHATSAPP PANELI */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900 space-y-6">
              <h3 className="text-sm font-black text-zinc-900 dark:text-white uppercase tracking-[0.2em] flex items-center gap-3"><Globe size={20} className="text-blue-500" /> Uygulama URL Adresi</h3>
              <div className="flex gap-3">
                  <input type="text" placeholder="https://..." className="flex-1 p-5 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl font-bold text-sm" value={appUrl} onChange={e => setAppUrl(e.target.value)} />
                  <button onClick={handleSaveAppUrl} className="bg-blue-600 text-white px-8 rounded-3xl font-black text-[10px] uppercase shadow-lg shadow-blue-500/20 active:scale-95 transition-all">Kaydet</button>
              </div>
          </div>
          <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900 space-y-6">
              <h3 className="text-sm font-black text-zinc-900 dark:text-white uppercase tracking-[0.2em] flex items-center gap-3"><MessageCircle size={20} className="text-emerald-500" /> WhatsApp Bildirim Hattı</h3>
              <div className="flex gap-3">
                  <input type="tel" placeholder="905xxxxxxxxx" className="flex-1 p-5 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl font-bold text-sm" value={whatsappNumber} onChange={e => setWhatsappNumber(e.target.value)} />
                  <button onClick={handleSaveWhatsapp} className="bg-emerald-600 text-white px-8 rounded-3xl font-black text-[10px] uppercase shadow-lg shadow-emerald-500/20 active:scale-95 transition-all">Kaydet</button>
              </div>
          </div>
      </div>

      {/* ANA TANIMLAMALAR GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

        {/* TONER MODELLERİ (YENİ EKLENDİ) */}
        <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900">
          <h3 className="text-sm font-black text-zinc-900 dark:text-white mb-6 uppercase tracking-[0.2em] flex items-center gap-3"><Droplet size={20} className="text-orange-500" /> Toner & Mürekkep Modelleri</h3>
          <form onSubmit={(e) => handleAddItem(e, 'tonerModels', newTonerModel, setNewTonerModel)} className="mb-6 flex gap-2">
              <input required type="text" placeholder="Örn: CRG-052, 259X..." className="flex-1 p-4 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl font-black text-xs uppercase" value={newTonerModel} onChange={e => setNewTonerModel(e.target.value)} />
              <button type="submit" className="bg-orange-600 text-white p-4 rounded-2xl shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
          </form>
          {renderList('tonerModels', config.tonerModels)}
        </div>

        {/* MARKALAR */}
        <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900">
          <h3 className="text-sm font-black text-zinc-900 dark:text-white mb-6 uppercase tracking-[0.2em] flex items-center gap-3"><Tag size={20} className="text-emerald-500" /> Marka Havuzu</h3>
          <form onSubmit={(e) => handleAddItem(e, 'brands', newBrand, setNewBrand, newBrandImage, setNewBrandImage)} className="mb-6 space-y-3">
              <div className="flex gap-2">
                <input required type="text" placeholder="Marka İsmi" className="flex-1 p-4 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl font-black text-xs uppercase" value={newBrand} onChange={e => setNewBrand(e.target.value)} />
                <button type="submit" className="bg-emerald-600 text-white p-4 rounded-2xl shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
              </div>
              <input type="url" placeholder="Logo Görsel URL" className="w-full p-2 bg-zinc-100 dark:bg-zinc-800 rounded-xl text-[10px] font-bold" value={newBrandImage} onChange={e => setNewBrandImage(e.target.value)} />
          </form>
          {renderList('brands', config.brands)}
        </div>

        {/* CİHAZ MODELLERİ */}
        <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900">
          <h3 className="text-sm font-black text-zinc-900 dark:text-white mb-6 uppercase tracking-[0.2em] flex items-center gap-3"><Box size={20} className="text-blue-500" /> Cihaz Modelleri</h3>
          <form onSubmit={(e) => handleAddItem(e, 'models', newModel, setNewModel, newModelImage, setNewModelImage)} className="mb-6 space-y-3">
              <div className="flex gap-2">
                <input required type="text" placeholder="Model Kodu" className="flex-1 p-4 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl font-black text-xs uppercase" value={newModel} onChange={e => setNewModel(e.target.value)} />
                <button type="submit" className="bg-blue-600 text-white p-4 rounded-2xl shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
              </div>
              <input type="url" placeholder="Cihaz Görsel URL" className="w-full p-2 bg-zinc-100 dark:bg-zinc-800 rounded-xl text-[10px] font-bold" value={newModelImage} onChange={e => setNewModelImage(e.target.value)} />
          </form>
          {renderList('models', config.models)}
        </div>

        {/* TEDARİKÇİLER */}
        <div className="bg-white dark:bg-zinc-950 p-8 rounded-[3rem] shadow-xl border border-zinc-100 dark:border-zinc-900">
          <h3 className="text-sm font-black text-zinc-900 dark:text-white mb-6 uppercase tracking-[0.2em] flex items-center gap-3"><Truck size={20} className="text-purple-500" /> Tedarikçiler & Servisler</h3>
          <form onSubmit={(e) => handleAddItem(e, 'suppliers', newSupplier, setNewSupplier)} className="mb-6 flex gap-2">
              <input required type="text" placeholder="Şirket İsmi" className="flex-1 p-4 bg-zinc-50 dark:bg-zinc-900 border-2 border-zinc-100 dark:border-zinc-800 rounded-2xl font-black text-xs uppercase" value={newSupplier} onChange={e => setNewSupplier(e.target.value)} />
              <button type="submit" className="bg-purple-600 text-white p-4 rounded-2xl shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
          </form>
          {renderList('suppliers', config.suppliers)}
        </div>

      </div>

      {/* ARAÇLAR PANELI */}
      <div className="bg-zinc-900 p-10 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-10 opacity-10"><Database size={200}/></div>
          <div className="relative z-10">
              <h3 className="text-2xl font-black uppercase tracking-tighter mb-4">Sistem Bakım Araçları</h3>
              <p className="text-zinc-400 text-sm mb-8 max-w-xl italic">"Toplu veri onarımı ve ilk kurulum araçları sadece yönetici onayı ile kullanılmalıdır. Bu işlemler veritabanında kalıcı değişiklikler yapar."</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <button onClick={() => setShowImportConfirm(true)} className="p-6 bg-white/10 hover:bg-white/20 rounded-3xl border border-white/10 transition-all flex items-center justify-between group">
                      <div>
                          <p className="text-[10px] font-black uppercase tracking-widest text-emerald-400 mb-1">DATA IMPORT</p>
                          <p className="text-lg font-black uppercase leading-none">Hazır Cihaz Listesi</p>
                      </div>
                      <ArrowRight className="group-hover:translate-x-2 transition-transform" />
                  </button>
                  <button onClick={handleFixCodes} disabled={isFixingCodes} className="p-6 bg-blue-600/20 hover:bg-blue-600/30 rounded-3xl border border-blue-500/30 transition-all flex items-center justify-between group">
                      <div>
                          <p className="text-[10px] font-black uppercase tracking-widest text-blue-400 mb-1">ID RECOVERY</p>
                          <p className="text-lg font-black uppercase leading-none">{isFixingCodes ? 'Onarılıyor...' : 'Hızlı Kod Onarımı'}</p>
                      </div>
                      {isFixingCodes ? <Loader2 className="animate-spin" /> : <RefreshCw className="group-hover:rotate-180 transition-transform duration-500" />}
                  </button>
              </div>
          </div>
      </div>

      {/* MODALLAR */}
      {editModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white dark:bg-zinc-950 rounded-[3rem] w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 border border-zinc-100 dark:border-zinc-900">
             <div className="p-8 border-b border-zinc-100 dark:border-zinc-900 flex justify-between items-center bg-zinc-50/50 dark:bg-zinc-900/50">
                 <h3 className="font-black text-xl uppercase tracking-tighter">Kayıt Düzenle</h3>
                 <button onClick={() => setEditModal(null)} className="p-2 text-zinc-400 hover:text-red-500 transition-colors"><X size={24}/></button>
             </div>
             <form onSubmit={handleUpdate} className="p-8 space-y-6">
                <div className="space-y-2">
                    <label className="text-[10px] font-black text-zinc-400 uppercase ml-2 tracking-widest">YENİ DEĞER</label>
                    <input required type="text" className="w-full p-5 border-2 border-zinc-100 dark:border-zinc-800 rounded-3xl bg-zinc-50 dark:bg-zinc-900 font-black text-sm uppercase" value={editModal.newVal} onChange={e => setEditModal({...editModal, newVal: e.target.value})} />
                </div>
                {(editModal.type === 'brands' || editModal.type === 'models') && (
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-zinc-400 uppercase ml-2 tracking-widest">GÖRSEL URL</label>
                        <input type="url" className="w-full p-3 border border-zinc-100 dark:border-zinc-800 rounded-2xl bg-zinc-50 dark:bg-zinc-900 text-xs font-bold" value={editModal.newImage || ''} onChange={e => setEditModal({...editModal, newImage: e.target.value})} />
                     </div>
                )}
                <div className="flex gap-3 pt-4">
                    <button type="button" onClick={() => setEditModal(null)} className="flex-1 py-5 bg-zinc-100 dark:bg-zinc-800 text-zinc-500 rounded-2xl font-black text-[10px] uppercase">İptal</button>
                    <button type="submit" className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg shadow-blue-500/20">Güncelle</button>
                </div>
             </form>
          </div>
        </div>
      )}

      {deleteModal && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-white dark:bg-zinc-950 rounded-[3rem] p-10 text-center max-w-sm w-full shadow-2xl border border-zinc-100 dark:border-zinc-900">
              <div className="w-20 h-20 bg-red-100 dark:bg-red-950/30 text-red-600 rounded-full flex items-center justify-center mx-auto mb-6"><Trash2 size={40} /></div>
              <p className="font-black text-lg text-zinc-900 dark:text-white uppercase mb-2">"{deleteModal.val}" Silinsin mi?</p>
              <p className="text-zinc-500 text-xs mb-8">Bu değerle eşleşen cihazlardaki veriler de etkilenecektir.</p>
              <div className="grid grid-cols-2 gap-4">
                  <button onClick={() => setDeleteModal(null)} className="py-5 bg-zinc-100 dark:bg-zinc-800 text-zinc-500 rounded-2xl font-black text-[10px] uppercase">VAZGEÇ</button>
                  <button onClick={handleDelete} className="py-5 bg-red-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl">EVET, SİL</button>
              </div>
           </div>
        </div>
      )}

      {showImportConfirm && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-md z-[200] flex items-center justify-center p-6 animate-in fade-in duration-300">
            <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] border border-zinc-100 dark:border-zinc-900 max-w-sm w-full text-center space-y-6">
                <div className="w-20 h-20 bg-emerald-100 dark:bg-emerald-950/40 text-emerald-600 rounded-full flex items-center justify-center mx-auto"><AlertTriangle size={40}/></div>
                <div>
                    <h3 className="text-xl font-black text-zinc-900 dark:text-white uppercase tracking-tighter">İçe Aktarma Onayı</h3>
                    <p className="text-zinc-500 text-xs mt-3 leading-relaxed">40 adet önceden tanımlı Canon yazıcı ve lokasyon verisi sisteme eklenecektir. Mevcut verileriniz silinmez.</p>
                </div>
                <div className="flex gap-4">
                    <button onClick={() => setShowImportConfirm(false)} className="flex-1 py-5 bg-zinc-100 dark:bg-zinc-800 text-zinc-500 rounded-2xl font-black text-[10px] uppercase">VAZGEÇ</button>
                    <button onClick={handleInitialImport} className="flex-1 py-5 bg-emerald-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl shadow-emerald-500/20">VERİLERİ YÜKLE</button>
                </div>
            </div>
        </div>
      )}

      {isImporting && (
           <div className="fixed inset-0 bg-black/95 z-[300] flex items-center justify-center p-10 text-center animate-in fade-in">
              <div className="space-y-8 w-full max-w-md">
                  <div className="relative inline-block">
                    <Loader2 size={120} className="text-emerald-500 animate-spin opacity-20" strokeWidth={1} />
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Printer size={48} className="text-emerald-500" />
                    </div>
                  </div>
                  <div className="space-y-2">
                      <p className="text-white font-black text-2xl uppercase tracking-tighter">CİHAZLAR YÜKLENİYOR...</p>
                      <p className="text-emerald-500 font-mono text-4xl font-black">{Math.round((importProgress / INITIAL_PRINTER_DATA.length) * 100)}%</p>
                  </div>
                  <div className="w-full bg-zinc-800 h-2 rounded-full overflow-hidden border border-white/5">
                      <div className="bg-emerald-500 h-full transition-all duration-300 shadow-[0_0_15px_#10b981]" style={{ width: `${(importProgress / INITIAL_PRINTER_DATA.length) * 100}%` }}></div>
                  </div>
                  <p className="text-zinc-500 text-[10px] font-bold uppercase tracking-[0.4em]">Lütfen tarayıcıyı kapatmayın</p>
              </div>
           </div>
      )}
    </div>
  );
};
